package com.ascent.climb.data.i18n

/**
 * Deutsche Quiz-Texte (629 Fragen / 3.954 Einträge).
 * Schlüssel identisch zu PackEnQuiz.kt; Zahlen, Dosierungen und Skalen bleiben unverändert.
 */

internal val PACK_DE_QUIZ: Map<String, String> = mapOf(

    // ---------- l1 Gefahren verstehen ----------
    "q.l1#0.p" to "Welche der folgenden Gefahren ist eine objektive Gefahr?",
    "q.l1#0.o0" to "Steinschlag und Eislawinen",
    "q.l1#0.o1" to "Ein Beurteilungsfehler",
    "q.l1#0.o2" to "Erschöpfung der Kräfte",
    "q.l1#0.o3" to "Konkurrenzdenken",
    "q.l1#0.e" to "Objektive Gefahren sind Umweltfaktoren, die sich durch Können oder Haltung nicht ändern: Steinschlag, Eisabbruch, Lawinen, Wetter, Gletscherspalten. Die anderen drei sind subjektive Gefahren, die Training und Selbstdisziplin beherrschen können.",

    "q.l1#1.p" to "Wie verändern sich Lufttemperatur und Sauerstoffpartialdruck mit steigender Höhe?",
    "q.l1#1.o0" to "Die Temperatur steigt, der Sauerstoffpartialdruck sinkt",
    "q.l1#1.o1" to "Die Temperatur sinkt um etwa 6,5 °C pro 1.000 m, der Sauerstoffpartialdruck sinkt mit",
    "q.l1#1.o2" to "Beide bleiben unverändert",
    "q.l1#1.o3" to "Die Temperatur sinkt, der Sauerstoffpartialdruck steigt",
    "q.l1#1.e" to "Pro 1.000 m Höhengewinn kühlt die Luft um rund 6,5 °C ab, während Luftdruck und Sauerstoffpartialdruck im gleichen Maß fallen. Deshalb treten Höhenkrankheit und Unterkühlung gemeinsam auf.",

    "q.l1#2.p" to "Welche Aussage über die Rolle von Training ist richtig?",
    "q.l1#2.o0" to "Gutes Training beseitigt alle objektiven Gefahren",
    "q.l1#2.o1" to "Training senkt subjektive Gefahren, kann objektive aber nicht beseitigen",
    "q.l1#2.o2" to "Objektive Gefahren sind reine Glückssache",
    "q.l1#2.o3" to "Wer fit genug ist, ist nicht gefährdet",
    "q.l1#2.e" to "Technisches Training verbessert Beurteilung und Reaktion, doch Steinschlag, Lawinen und Wetter verschwinden nicht, weil man erfahren ist. Der richtige Umgang mit objektiven Gefahren ist, sie zu umgehen und sich einen Ausweg offen zu halten.",

    "q.l1#3.p" to "Warum betonen Bergsteiger Reservern mehr als das Reparieren vor Ort?",
    "q.l1#3.o0" to "Weil eine Reserve die Gipfelquote erhöht",
    "q.l1#3.o1" to "Weil eine Reserve früh in der Unfallkette wirkt, während Reparieren am letzten Glied ansetzt",
    "q.l1#3.o2" to "Weil eine Reserve Geld spart",
    "q.l1#3.o3" to "Weil die Regeln eine Reserve verlangen",
    "q.l1#3.e" to "Reserven haben viele Formen: Zeit, Kraft, Vorräte, ein Wetterfenster. Gemeinsam ist ihnen, dass man den Spielraum schafft, solange man noch wählen kann. Reparieren beginnt immer erst, nachdem etwas schiefgegangen ist – dann bleiben wenige Optionen.",

    "q.l1#4.p" to "Woran erkennt man das Niveau einer Seilschaft am besten?",
    "q.l1#4.o0" to "An der höchsten erreichten Höhe eines Mitglieds",
    "q.l1#4.o1" to "An der Zahl der Touren pro Jahr",
    "q.l1#4.o2" to "Daran, ob sie sich rechtzeitig zurückziehen kann und das Risiko tragbar bleibt",
    "q.l1#4.o3" to "Am Gesamtwert der Ausrüstung",
    "q.l1#4.e" to "Gipfelrekorde belegen nur, dass etwas einmal funktioniert hat; die Fähigkeit zum Rückzug belegt Kontrolle. In der Höhe kommt die nächste Chance immer wieder, ein schwerer Unfall nicht. Was Teams wirklich unterscheidet, ist die Qualität ihrer Entscheidungen unter ungünstigen Bedingungen.",

    "q.l1#5.p" to "Die chinesischen Bergsteigerregeln beschränken das Bergsteigen auf „selbstständige Gipfel“. Wie ist ein selbstständiger Gipfel auf der Karte definiert?",
    "q.l1#5.o0" to "Jeder Bergstock über 5.000 m",
    "q.l1#5.o1" to "Ein Bergstock, der von einer geschlossenen Höhenlinie umschlossen wird",
    "q.l1#5.o2" to "Ein Bergstock mit sichtbarem Gletscher",
    "q.l1#5.o3" to "Ein Bergstock, den noch niemand bestiegen hat",
    "q.l1#5.e" to "Auf der topografischen Karte erscheint ein selbstständiger Gipfel als geschlossene Höhenlinie: Der Berg fällt nach allen Seiten ab. Die Definition trennt „Bergsteigen“ vom „Hinaufgehen auf irgendeine hohe Stelle“ und bildet die Grundlage für Verwaltung und Zählung.",

    "q.l1#6.p" to "Welches Muster zeigt sich in Unfallauswertungen am häufigsten?",
    "q.l1#6.o0" to "Fast jeder Unfall beruht auf einem einzigen großen Fehler",
    "q.l1#6.o1" to "Schwere Unfälle sind meist mehrere kleine Fehler, die sich stapeln",
    "q.l1#6.o2" to "Unfälle haben nichts mit Erfahrung zu tun",
    "q.l1#6.o3" to "Materialversagen ist die Hauptursache",
    "q.l1#6.e" to "Ein typischer Unfall ist eine Kette: eine zu optimistische Routenwahl, dann Zeitverzug, dann vereinfachte Sicherung, um Zeit zu sparen, dann Ermüdung, die die Bewegung verschlechtert. Durchtrennt man ein einziges Glied, geschieht der Unfall nicht – genau deshalb ist die Reserve besser als die Reparatur.",

    "q.l1#7.p" to "【Mehrfachauswahl】Welche der folgenden Punkte sind objektive Gefahren im Bergsteigen?",
    "q.l1#7.o0" to "Steinschlag und Eisabbruch",
    "q.l1#7.o1" to "Lawinen",
    "q.l1#7.o2" to "Plötzlicher Wetterumschwung",
    "q.l1#7.o3" to "Gletscherspalten",
    "q.l1#7.o4" to "Konkurrenzdenken",
    "q.l1#7.e" to "Die ersten vier ändern sich nicht mit Können oder Haltung – sie sind Eigenschaften der Umwelt. Gegen objektive Gefahren kann man nur umgehen, den Zeitpunkt wählen und sich einen Ausweg offen halten. Subjektive Gefahren – Fehlbeurteilung, mangelnde Vorbereitung, Vergleich mit anderen – sind der Teil, den Training tatsächlich senken kann.",

    "q.l1#8.p" to "Was sollten Sie vor einer Hochtour zuerst klären?",
    "q.l1#8.o0" to "Kondition, Ausrüstung, Zeitplan und Versicherung",
    "q.l1#8.o1" to "Den Ruf der Partner, die Bekanntheit des Gipfels, die Marken der Ausrüstung",
    "q.l1#8.o2" to "Fotos, Video und den Social-Media-Plan",
    "q.l1#8.o3" to "Die Vorhersage, Flüge und Hotels",
    "q.l1#8.e" to "Die Kondition entscheidet, ob Sie es schaffen; die Ausrüstung entscheidet, ob Sie schlechtes Wetter überstehen; Zeitplan und Versicherung entscheiden, ob im Ernstfall Hilfe existiert. Alle drei liegen vor dem Aufbruch vollständig in Ihrer Hand – deshalb gibt es keine Ausrede, wenn sie fehlen.",

    "q.l1#9.p" to "Warum geraten auch erfahrene Bergsteiger noch in Notlagen?",
    "q.l1#9.o0" to "Weil Erfahrung allmählich hebt, was man als normales Risiko akzeptiert",
    "q.l1#9.o1" to "Weil Erfahrene schwierigere Routen wählen",
    "q.l1#9.o2" to "Weil Erfahrung nichts mit Sicherheit zu tun hat",
    "q.l1#9.o3" to "Weil Erfahrene schneller ermüden",
    "q.l1#9.e" to "Das nennt man Risikonormalisierung: Hat man dieselben Bedingungen viele Male sicher durchquert, stuft man sie unbewusst als „sicher“ ein und weitet den Maßstab Stück für Stück. Je erfahrener Sie sind, desto mehr brauchen Sie ausdrückliche Regeln – etwa eine Umkehrzeit –, die Ihr Urteil im Zaum halten.",

    // ---------- l2 Steigeisen und Eispickel ----------
    "q.l2#0.p" to "Wofür wird ein Eispickel des Typs T (technisch) vor allem verwendet?",
    "q.l2#0.o0" to "Zum Spazieren auf flachen Schneehängen",
    "q.l2#0.o1" to "Für steile Eisflächen und technisches Klettern",
    "q.l2#0.o2" to "Nur zum Fotografieren",
    "q.l2#0.o3" to "Nur zum Zelten im Schnee",
    "q.l2#0.e" to "Ein Schaft des Typs T darf ins Eis geschlagen werden und Zug aufnehmen, was zu steilem Eis passt. Ein Schaft des Typs B ist schwächer: Er ist für Gehen und Selbstbremsung ausgelegt und darf nicht als technischer Fixpunkt dienen.",

    "q.l2#1.p" to "Welche Steigeisenklasse passt zu einem voll steifen B3-Schuh?",
    "q.l2#1.o0" to "C1, reine Riemenbindung",
    "q.l2#1.o1" to "C2, Riemen vorn und Kipphebel hinten",
    "q.l2#1.o2" to "C3, reine Kippbindung",
    "q.l2#1.o3" to "Jede Klasse ist geeignet",
    "q.l2#1.e" to "Ein B3-Schuh hat vordere und hintere Wulst, und ein C3-Steigeisen mit Vollkippbindung ist die sicherste Paarung. B1 mit C1, B2 mit C2 und B3 mit C3 ist die Grundregel der Kombination.",

    "q.l2#2.p" to "Was passiert, wenn Sie C3-Steigeisen mit Vollkippbindung an einen weichen Wanderschuh montieren?",
    "q.l2#2.o0" to "Kein Problem, und das Anlegen geht schneller",
    "q.l2#2.o1" to "Der Schuh verformt sich unter Last, die Kipphebel verlieren Halt und das Steigeisen kann abspringen – eine gefährliche Kombination",
    "q.l2#2.o2" to "Sie gehen schneller",
    "q.l2#2.o3" to "Es sieht nur unschön aus",
    "q.l2#2.e" to "Vollkippbindungen brauchen einen steifen Schuh, der seine Form hält. Am weichen Schuh biegt sich dieser durch, die Kipphebel greifen nicht mehr und das Steigeisen kann am Steilhang abgehen. Das ist eine eindeutig gefährliche Fehlpaarung.",

    "q.l2#3.p" to "Die Länge des Eispickels wird meist nach Körpergröße gewählt. Was wird für etwa 173–180 cm empfohlen?",
    "q.l2#3.o0" to "50 cm",
    "q.l2#3.o1" to "55 cm",
    "q.l2#3.o2" to "60 cm",
    "q.l2#3.o3" to "70 cm",
    "q.l2#3.e" to "Eine gängige Orientierung: unter etwa 157 cm 50 cm; 157–170 cm 55 cm; 173–180 cm 60 cm; über 183 cm 65–70 cm. Nur die richtige Länge erlaubt es, die Haue bei der Selbstbremsung wirksam in den Schnee zu drücken.",

    "q.l2#4.p" to "Was ist beim Kauf von Steigeisen die grundlegendste und wichtigste Anforderung?",
    "q.l2#4.o0" to "So leicht wie möglich",
    "q.l2#4.o1" to "Sie müssen zum Schuh passen, idealerweise 12-zackig aus Stahl mit Antistollplatten",
    "q.l2#4.o2" to "Die Farbe sollte zur übrigen Ausrüstung passen",
    "q.l2#4.o3" to "Mehr Zacken sind immer besser – 20 oder mehr",
    "q.l2#4.e" to "Ein Steigeisen ist nur so gut wie seine Verbindung zum Schuh. Mehr Zacken sind nicht automatisch besser; Passform und Antistollplatten (die verhindern, dass sich Schnee darunter ballt) entscheiden. Schlechte Passform ist der klassische Weg, am Steilhang ein Steigeisen zu verlieren.",

    "q.l2#5.p" to "【Szenario】Für einen technischen Gipfeltag in der Höhe mit Steigeisen, Pickel, Reserve-Isolationsschicht, Essen, Wasser und Notfallset – welches Netto-Rucksackvolumen wird empfohlen?",
    "q.l2#5.o0" to "15–25 Liter",
    "q.l2#5.o1" to "35–50 Liter",
    "q.l2#5.o2" to "60–75 Liter",
    "q.l2#5.o3" to "90 Liter oder mehr",
    "q.l2#5.e" to "Für „eigene Technik + Reserve-Isolation + Notfallset“ sind 35–50 Liter der übliche Bereich, idealerweise mit eigenem Steigeisenfach.\nDoch das Volumen ist nicht fest: Auf einem viel begangenen Schneehang, bei stabiler Wetterlage und Gruppenaustrüstung bei der Trägerchaft können 15–25 Liter für den Gipfeltag völlig ausreichen; wer Zelt oder Seile selbst trägt, braucht mehr.\nDer Maßstab ist immer das, was Sie tatsächlich tragen müssen – keine allgemeine Zahl.",

    "q.l2#6.p" to "Wozu dient die Fangschlinge am Eispickel vor allem?",
    "q.l2#6.o0" to "Zur Zierde und zur Erkennung der Seilschaft",
    "q.l2#6.o1" to "Damit Sie den Pickel nicht verlieren und ihn nach einem Rutsch noch kontrollieren können",
    "q.l2#6.o2" to "Um Gewicht zu addieren, damit der Pickel fester drückt",
    "q.l2#6.o3" to "Um den Pickel am Rucksack aufzuhängen",
    "q.l2#6.e" to "Die Schlinge zählt im Moment des Rutschens: Verlässt der Pickel die Hand, ist das einzige Bremsmittel weg. Die Schlinge hält ihn auch bei heftiger Bewegung bei Ihnen – deshalb bestehen so viele Lehrbücher auf ihrem Gebrauch.",

    "q.l2#7.p" to "【Mehrfachauswahl】Welche Faktoren zählen bei der Wahl der Steigeisen?",
    "q.l2#7.o0" to "Wie sie am Schuh befestigt werden (Riemen / Halbkipp / Vollkipp)",
    "q.l2#7.o1" to "Ob Zahl und Form der Zacken zum Gelände passen",
    "q.l2#7.o2" to "Ob sie Antistollplatten haben",
    "q.l2#7.o3" to "Die Zuverlässigkeit von Bindungen und Riemen",
    "q.l2#7.o4" to "Ob die Farbe zum Rucksack passt",
    "q.l2#7.e" to "Alle vier zählen. Die Befestigung entscheidet, ob sie überhaupt halten, die Zackenform entscheidet über die Eignung fürs Gelände (Frontzacken für steiles Eis, Flachzacken für flachen Schnee), die Platten entscheiden über Schneeballen darunter, die Bindungen darüber, ob sie dranbleiben.",

    "q.l2#8.p" to "Warum prüft man Riemen und Bindungen der Steigeisen vor jedem Aufbruch?",
    "q.l2#8.o0" to "Um die Ausrüstung ordentlich zu halten",
    "q.l2#8.o1" to "Weil ein abspringendes Steigeisen am Steilhang eine unmittelbare Lebensgefahr ist",
    "q.l2#8.o2" to "Weil Riemen altern und ihre Farbe ändern",
    "q.l2#8.o3" to "Weil die Disziplin der Gruppe es verlangt",
    "q.l2#8.e" to "Steigeisen versagen gern im ungünstigsten Moment: an der Steilwand, beim Queren, beim ersten belasteten Schritt. Verliert ein Fuß den Halt, verschiebt sich der Körperschwerpunkt sofort. Die Prüfung kostet fast nichts, die Folge steht in keinem Verhältnis dazu.",

    "q.l2#9.p" to "Welche Aussage zur Form der Eispickelhaue ist richtig?",
    "q.l2#9.o0" to "Alle Haue sind gerade",
    "q.l2#9.o1" to "Eine gebogene Haue dringt leichter ins Eis ein und löst sich seltener, daher ist sie bei technischen Eisgeräten üblich",
    "q.l2#9.o2" to "Eine gebogene Haue ist nur zum Gehen im Schnee",
    "q.l2#9.o3" to "Die Haubenform hat nichts mit dem Einsatzzweck zu tun",
    "q.l2#9.e" to "Ein langer Bergpickel hat meist eine nach unten gebogene Haue: Sie greift beim Schwung oder bei der Selbstbremsung und zieht sich nicht leicht heraus. Eisgeräte haben schärfere, steilere Haue für schnelles Setzen und leichtes Herausziehen in steilem Eis. Der Zweck bestimmt die Form.",

    // ---------- l3 Stiefel, Brillen, Kleidung ----------
    "q.l3#0.p" to "Was ist der Hauptvorteil von Doppelschuhen gegenüber Einschuhmodellen?",
    "q.l3#0.o0" to "Leichter",
    "q.l3#0.o1" to "Wärmer, und der Innenschuh lässt sich zum Trocknen herausnehmen",
    "q.l3#0.o2" to "Billiger",
    "q.l3#0.o3" to "Leichter an- und auszuziehen",
    "q.l3#0.e" to "Der Innenschuh kommt heraus, kann am Körper oder im Schlafsack getrocknet werden und gefriert nicht – der entscheidende Punkt auf mehrtägigen Hochtouren. Der Preis dafür sind Gewicht und Kosten.",

    "q.l3#1.p" to "Welche Angabe ist bei einer Schneebrille am wichtigsten?",
    "q.l3#1.o0" to "Wie dunkel das Glas ist",
    "q.l3#1.o1" to "UV400-Schutz gegen Ultraviolettstrahlung",
    "q.l3#1.o2" to "Die Marke des Rahmens",
    "q.l3#1.o3" to "Ob das Glas verspiegelt ist",
    "q.l3#1.e" to "Schnee reflektiert sehr viel UV-Strahlung. UV400 bedeutet nahezu vollständige Blockung und ist der Schlüssel zur Vermeidung von Schneeblindheit; die Tönung beeinflusst nur den Sehkomfort.",

    "q.l3#2.p" to "Worauf kommt es bei der Größenwahl eines Bergschuhs an?",
    "q.l3#2.o0" to "Enger ist besser, damit der Fuß nicht rutscht",
    "q.l3#2.o1" to "Die Zehen dürfen vorn nicht anstoßen; etwas Platz, damit sie beim Abstieg nicht verletzt werden",
    "q.l3#2.o2" to "Größer ist besser, um dickere Socken zu tragen",
    "q.l3#2.o3" to "Genau die Alltagsschuhgröße",
    "q.l3#2.e" to "Beim Abstieg rutscht der Fuß nach vorn. Stößt er vorn an, kann ein langer Abstieg die Zehen prellen oder sogar einen Nagel kosten. Lassen Sie etwas Platz und fixieren Sie die Ferse mit der Schnürung.",

    "q.l3#3.p" to "Was ist das entscheidende Konstruktionsmerkmal eines 8.000-m-Gipfelschuhs?",
    "q.l3#3.o0" to "So leicht wie möglich",
    "q.l3#3.o1" to "Ein herausnehmbarer Isolationsinnenschuh mit wasserdichtem, winddichtem und abriebfestem Obermaterial",
    "q.l3#3.o2" to "Er muss einlagig sein",
    "q.l3#3.o3" to "Je weicher die Sohle, desto bequemer",
    "q.l3#3.e" to "Ein herausnehmbarer Innenschuh lässt sich nachts trocknen oder am Körper warm halten und gefriert so nicht – der Schlüssel zu funktionsfähigen Füßen auf mehrtägigen Hochtouren. Das Obermaterial ist meist ein Dreilagenlaminat für Wasserdichtigkeit, Winddichtigkeit und Haltbarkeit.",

    "q.l3#4.p" to "Warum darf die erste Lage nie aus Baumwolle sein?",
    "q.l3#4.o0" to "Baumwolle ist zu teuer",
    "q.l3#4.o1" to "Baumwolle hält Schweiß und trocknet langsam, nasse Stoffe auf der Haut beschleunigen den Wärmeverlust",
    "q.l3#4.o2" to "Baumwolle löst Allergien aus",
    "q.l3#4.o3" to "Baumwolle atmet nicht und fühlt sich deshalb kälter an",
    "q.l3#4.e" to "Die Aufgabe der ersten Lage ist, Schweiß von der Haut wegzutransportieren. Baumwolle saugt Wasser auf und gibt es kaum ab, sodass nasser kalter Stoff weiter Wärme entzieht. Wählen Sie Polyester oder Merinowolle, die Feuchtigkeit schnell weiterleiten.",

    "q.l3#5.p" to "Welches Material wird für einen 6.000-m-Schuh empfohlen?",
    "q.l3#5.o0" to "Gewöhnliches Leder",
    "q.l3#5.o1" to "Ein wasserdichtes, atmungsaktives Material wie GORE-TEX",
    "q.l3#5.o2" to "Reiner Baumwollstoff",
    "q.l3#5.o3" to "Eine harte Kunststoffschale",
    "q.l3#5.e" to "Ein 6.000-m-Schuh legt Wert auf Leichtigkeit, Komfort und Grip und muss zudem stundenlang gut laufen. Eine wasserdichte, dampfdurchlässige Membran wie GORE-TEX hält Wasser draußen und lässt Feuchtigkeit entweichen – wasserdicht ohne Atmungsaktivität staut nur Schweiß, und Sie sind am Ende trotzdem nass und kalt.",

    "q.l3#6.p" to "Welches Material sollten Bergsocken meiden?",
    "q.l3#6.o0" to "Merinowolle",
    "q.l3#6.o1" to "Synthetikfasern wie Polyester",
    "q.l3#6.o2" to "Baumwolle",
    "q.l3#6.o3" to "Nylon",
    "q.l3#6.e" to "Dieselbe Logik wie bei der ersten Lage: Baumwolle saugt Schweiß auf und gibt ihn kaum ab, nasser kalter Stoff entzieht weiter Wärme und erhöht das Blasenrisiko deutlich. Wählen Sie Synthetik (ohne Baumwolle) oder Merino, in kniehoher Form, die Wärme und Durchblutung ausbalanciert.",

    "q.l3#7.p" to "Wie geht man bei der Wahl der Gamaschen richtig vor?",
    "q.l3#7.o0" to "Auf jeder Tour dieselben kurzen Gamaschen",
    "q.l3#7.o1" to "Für hohe Berge längere Gamaschen, die Schnee aus dem Schuh halten",
    "q.l3#7.o2" to "Gamaschen sind nur für Regen",
    "q.l3#7.o3" to "Kürzer und leichter ist immer besser",
    "q.l3#7.e" to "Gamaschen sind ein Stoffrohr über dem Schuh, das Schnee und Schmutz draußen hält. In tiefem Höhenschnee sind kurze Modelle schnell begraben und nutzlos, daher längere; kurze passen zu bekannten Trekkingrouten und flachem Schnee im Alpinstil.",

    "q.l3#8.p" to "Wozu dienen Camp-Schuhe und -Pantoffeln, und was müssen sie können?",
    "q.l3#8.o0" to "Für den Gipfel; sie müssen sehr steif sein",
    "q.l3#8.o1" to "Für die Bewegung im Lager; sie müssen warm, wasserdicht und rutschfest sein",
    "q.l3#8.o2" to "Fürs technische Klettern; sie brauchen Frontzacken",
    "q.l3#8.o3" to "Rein dekorativ; optional",
    "q.l3#8.e" to "Sie lassen die Hauptschuhe ruhen: Im Zelt in Camp-Schuhe oder Pantoffeln wechseln, damit die Innenschuhe trocknen und die Füße nicht den ganzen Tag komprimiert sind. Sie haben keine technische Funktion, beeinflussen aber unmittelbar den Zustand Ihrer Füße am nächsten Morgen.",

    "q.l3#9.p" to "Was bringt ein kniehoher Sockenaufbau auf einer langen Expedition?",
    "q.l3#9.o0" to "Er wirkt professioneller",
    "q.l3#9.o1" to "Er hält den Fuß warm und unterstützt die Durchblutung",
    "q.l3#9.o2" to "Er lässt sich leichter anziehen",
    "q.l3#9.o3" to "Er fügt Dämpfungsschicht hinzu",
    "q.l3#9.e" to "An langen Tagen schwellen die Füße an und die Durchblutung leidet. Ein kniehoher Socken bedeckt die Wade, wärmt sie und fördert durch gleichmäßigen Druck den venösen Rückfluss – was auf einer Mehrtagestour entscheidet, ob Ihre Füße am dritten Tag noch funktionieren.",

    // ---------- l4 Gehtechnik im Schnee ----------
    "q.l4#0.p" to "Wie tritt man Stufen im Schnee richtig?",
    "q.l4#0.o0" to "Mit langen Schritten, um Stufen zu sparen",
    "q.l4#0.o1" to "Kleine Stufen in gleichmäßigem Rhythmus treten und den Körperschwerpunkt stabil halten",
    "q.l4#0.o2" to "Nur mit den Zehen",
    "q.l4#0.o3" to "Die Ferse durchgehend in den Schnee drücken",
    "q.l4#0.e" to "Kleine Stufen in gleichmäßigem Rhythmus halten den Schwerpunkt stabil und sparen Kraft. Lange Schritte lassen den Körper seitlich pendeln – der einfachste Weg, am Schneehang das Gleichgewicht zu verlieren.",

    "q.l4#1.p" to "In welcher Hand trägt man den Pickel beim Gehen?",
    "q.l4#1.o0" to "In der bergabwärts gelegenen Hand",
    "q.l4#1.o1" to "In der bergaufwärts gelegenen Hand, bereit zur sofortigen Selbstbremsung",
    "q.l4#1.o2" to "In keiner Hand",
    "q.l4#1.o3" to "Außen am Rucksack",
    "q.l4#1.e" to "Tragen Sie ihn in der bergseitigen Hand in der Piolet-canne-Position, Haue nach hinten, Kopf nach vorn. Bei einem Rutsch können Sie sofort in die Selbstbremsung drücken, ohne umzugreifen – und diese Sekunden des Umgreifens sind oft das ganze Unfallfenster.",

    "q.l4#2.p" to "Welche Technik erleichtert den Aufstieg bei Atemnot in der Höhe?",
    "q.l4#2.o0" to "Beim Gehen die Luft anhalten",
    "q.l4#2.o1" to "Druckatmung: tief einatmen und kräftig ausatmen, synchron zum Schrittrhythmus",
    "q.l4#2.o2" to "Schnelle flache Atmung",
    "q.l4#2.o3" to "Durch den Handschuh atmen",
    "q.l4#2.e" to "Druckatmung erzeugt durch aktives Ausatmen einen Überdruck in der Lunge und verbessert den Gasaustausch. Mit dem Schrittrhythmus gekoppelt – etwa ein Atemzug alle zwei bis drei Schritte – nimmt das Erstickungsgefühl der Höhe spürbar ab.",

    "q.l4#3.p" to "Wie wird beim Aufstieg einer Seilschaft am Schneehang richtig Stufen getreten?",
    "q.l4#3.o0" to "Jeder tritt seine eigene Spur",
    "q.l4#3.o1" to "Der Erste tritt eine gleichmäßige Treppe, alle folgenden nutzen dieselben Stufen",
    "q.l4#3.o2" to "Jeder tritt, wie er möchte",
    "q.l4#3.o3" to "So tief und breit wie möglich",
    "q.l4#3.e" to "Eine einzige Stufenspur senkt den Aufwand für alle dahinter deutlich und hält die Gruppe auf einer Linie und in einem Rhythmus. Eine gleichmäßige Treppe mit gleichen Abständen ist selbst ein Zeichen von Effizienz und Sicherheit der Gruppe.",

    "q.l4#4.p" to "Was ist in der Höhe das Kernprinzip des Tempos?",
    "q.l4#4.o0" to "So schnell wie möglich gehen und früher Pause machen",
    "q.l4#4.o1" to "Ein nachhaltiges gleichmäßiges Tempo halten und wiederholte explosive Anstrengungen meiden",
    "q.l4#4.o2" to "Schnell und langsam abwechseln, um Kraft zu sparen",
    "q.l4#4.o3" to "Einfach am Partner bleiben und den eigenen Zustand ignorieren",
    "q.l4#4.e" to "Die Sauerstoffaufnahme ist in der Höhe begrenzt; wiederholte explosive Anstrengungen häufen Laktat an und vertiefen die Hypoxie. Ein gleichmäßiges Tempo mit Druckatmung bringt Sie weiter und verhindert, dass ein einzelner Sprint die ganze Gruppe aus dem Rhythmus bringt.",

    "q.l4#5.p" to "Wer gibt am Schneehang das Tempo der Gruppe vor?",
    "q.l4#5.o0" to "Das fitteste Mitglied",
    "q.l4#5.o1" to "Es sollte sich am langsamsten Mitglied orientieren, damit die Gruppe zusammenbleibt",
    "q.l4#5.o2" to "Der Tourenleiter, fest am Zeitplan",
    "q.l4#5.o3" to "Jeder in seinem eigenen Tempo",
    "q.l4#5.e" to "Sobald am Schneehang Lücken entstehen, verlieren die Hinteren sowohl Sicherung als auch Unterstützung; ein zu schnelles Tempo erschöpft die Schwächeren, bevor sie das gefährliche Gelände überhaupt erreichen. Im Tempo des Langsamsten bleibt die Sicherheitsreserve bei der ganzen Gruppe.",

    "q.l4#6.p" to "Was empfiehlt das Lehrbuch für das Queren eines deutlich geneigten Eishangs?",
    "q.l4#6.o0" to "Wie eine normale Seilschaft gehen",
    "q.l4#6.o1" to "Ein Fixseil legen oder im Wechsel sichern; in der Regel nicht gemeinsam gehen",
    "q.l4#6.o2" to "So schnell wie möglich hinüber",
    "q.l4#6.o3" to "Steigeisen abnehmen, um mehr Reibung zu haben",
    "q.l4#6.e" to "Bremsen auf Eis ist weit weniger zuverlässig als auf Schnee, und eine Seilschaft am Eis kann die ganze Gruppe mitreißen. Richtig ist, am geneigten Eis ein Fixseil zu legen oder im Wechsel zu sichern – Sicherung durch das System, nicht durch individuelle Bremswirkung.",

    "q.l4#7.p" to "Was ist der Hauptvorteil des Zickzack-Aufstiegs gegenüber der direkten Linie?",
    "q.l4#7.o0" to "Ein kürzerer Weg",
    "q.l4#7.o1" to "Er verringert den wirksamen Winkel der einzelnen Abschnitte und spart Kraft",
    "q.l4#7.o2" to "Bessere Aussicht",
    "q.l4#7.o3" to "Man braucht den Pickel nicht",
    "q.l4#7.e" to "Zickzack zerlegt einen steilen Hang in mehrere flachere Abschnitte, entlastet Waden und Knöchel stark und passt zur französischen Technik (Flachfuß). Der Preis ist Wegstrecke, also passen Sie Ihr Zeitbudget an – ein weiterer Grund für eine Reserve in der Umkehrzeit.",

    // ---------- l5 Steigeisentechnik ----------
    "q.l5#0.p" to "Was ist der Kernpunkt der französischen Technik (Flachfußtechnik)?",
    "q.l5#0.o0" to "Nur mit den Frontzacken ins Eis stechen",
    "q.l5#0.o1" to "Alle unteren Zacken des Steigeisens flach auf den Hang setzen, den Fuß flach stellen",
    "q.l5#0.o2" to "Auf einem Fuß hochhüpfen",
    "q.l5#0.o3" to "Die Schuhkante ins Eis kanten",
    "q.l5#0.e" to "Bei der französischen Technik geht es ums Flachstellen: Alle zwölf unteren Zacken greifen, die Last verteilt sich auf Oberschenkel und ganzen Körper – deshalb ist sie am wenigsten anstrengend. Darum eignet sie sich für lange Strecken in mäßigem Schnee.",

    "q.l5#1.p" to "Warum ist das Frontzackengehen (die deutsche Technik) am anstrengendsten?",
    "q.l5#1.o0" to "Weil man dabei die Arme nutzt",
    "q.l5#1.o1" to "Weil die Last auf den Frontzacken liegt und die Wade dauerhaft arbeiten muss",
    "q.l5#1.o2" to "Weil man die Luft anhalten muss",
    "q.l5#1.o3" to "Weil die Reibung höher ist",
    "q.l5#1.e" to "Frontzackengehen legt das Gewicht auf zwei oder drei Zacken, sodass die Wade dauerhaft angespannt bleibt, um die Position zu halten. Das ist extrem anstrengend und nicht lange durchzuhalten – genau deshalb bleibt es steilem Gelände vorbehalten.",

    "q.l5#2.p" to "Welche Fußtechnik verwendet man beim Queren eines Schneehangs?",
    "q.l5#2.o0" to "Frontzacken, die Zacken gerade hineintreten",
    "q.l5#2.o1" to "Den Entenschritt: Fersen zusammen, Zehen nach außen, sodass das ganze Steigeisen auf dem Hang liegt",
    "q.l5#2.o2" to "Seitliche Sprünge",
    "q.l5#2.o3" to "Auf den Knien kriechen",
    "q.l5#2.e" to "Beim Entenschritt greifen Seiten- und untere Zacken gleichzeitig, sodass das Gewicht nicht auf den inneren Zacken konzentriert ist, wo es abrutschen kann. Lehnen Sie sich beim Queren leicht in den Hang.",

    "q.l5#3.p" to "Welches Gelände passt am besten zur französischen Technik (Flachfuß)?",
    "q.l5#3.o0" to "Senkrechtes Eis",
    "q.l5#3.o1" to "Harter Schnee in geringer bis mittlerer Neigung, wo man stundenlang unterwegs ist",
    "q.l5#3.o2" to "Überhängende Dächer",
    "q.l5#3.o3" to "Nur flaches Gelände",
    "q.l5#3.e" to "Die französische Technik verteilt die Last auf Körper und Oberschenkel, ist deshalb am wenigsten anstrengend und das Arbeitstier für geringe bis mittlere Neigungen und lange Schneehänge. Steiles Gelände braucht Frontzacken – aber die sind nicht dauerhaft durchzuhalten.",

    "q.l5#4.p" to "Was passiert, wenn Sie am Steilhang lange auf den Frontzacken gehen?",
    "q.l5#4.o0" to "Es wird mit der Zeit leichter",
    "q.l5#4.o1" to "Die Wade ermüdet schnell, bis Sie die Position nicht mehr halten können",
    "q.l5#4.o2" to "Die Steigeisen fallen von selbst ab",
    "q.l5#4.o3" to "Gar nichts",
    "q.l5#4.e" to "Frontzackengehen konzentriert das Gewicht auf zwei oder drei Zacken und hält die Wade in Dauerkontraktion, deshalb kommt die Ermüdung schnell. Darum eignet es sich nur für kurze steile Passagen – und deshalb muss Ihr Energiebudget es bei der Routenplanung berücksichtigen.",

    "q.l5#5.p" to "Wie verteilen die beiden Füße die Arbeit in der gemischten (amerikanischen) Technik?",
    "q.l5#5.o0" to "Beide Füße bleiben flach auf dem Hang",
    "q.l5#5.o1" to "Beide Füße arbeiten auf den Frontzacken",
    "q.l5#5.o2" to "Ein Fuß flach als Stütze, der andere auf den Frontzacken als Antrieb, im Wechsel",
    "q.l5#5.o3" to "Ein Fuß macht die ganze Arbeit, der andere ruht",
    "q.l5#5.e" to "Die gemischte Technik verbindet französische und deutsche Technik: Der flache Fuß gibt Stabilität und einen Moment Ruhe, der Frontzackenfuß liefert den Antrieb. In mäßig steilem Gelände bleibt man so effizient, ohne die Waden wie beim reinen Frontzackengehen zu verbrauchen.",

    "q.l5#6.p" to "【Zuordnung】Ordnen Sie jede Steigeisenklasse dem passenden Schuh zu.",
    "q.l5#6.l0" to "C1, reine Riemenbindung",
    "q.l5#6.l1" to "C2, Riemen vorn und Kipphebel hinten",
    "q.l5#6.l2" to "C3, reine Kippbindung",
    "q.l5#6.r0" to "Weicher B1-Schuh",
    "q.l5#6.r1" to "Halbsteifer B2-Schuh",
    "q.l5#6.r2" to "Voll steifer B3-Schuh",
    "q.l5#6.e" to "Schuh und Steigeisen müssen zusammenpassen: weiche Schuhe mit C1, halbsteife mit C2, steife mit C3. Vollkippbindungen an einem weichen Schuh lassen diesen durchbiegen, die Kipphebel verlieren Halt und das Steigeisen kann am Steilhang abgehen – eine eindeutig gefährliche Kombination.",

    "q.l5#7.p" to "Was sind die beiden grundlegendsten Techniken der Fortbewegung auf Eis?",
    "q.l5#7.o0" to "Flachfußgehen und Seitwärtstreten",
    "q.l5#7.o1" to "Die Flachzackentechnik (französisch) und die Frontzackentechnik (deutsch)",
    "q.l5#7.o2" to "Hüpfen und Rutschen",
    "q.l5#7.o3" to "Aufstiegs- und Abstiegstechnik",
    "q.l5#7.e" to "Die Flachzackentechnik setzt alle aufrechten Zacken außer den Frontzacken ein; die Frontzackentechnik treibt die Frontzacken gerade ins Eis. Komplexes Gelände mischt meist beide – deshalb beherrscht man erst beide, bevor man die gemischte Technik angeht.",

    "q.l5#8.p" to "Welche Muskulatur trägt die Last bei der Flachzackentechnik (französisch)?",
    "q.l5#8.o0" to "Die Waden",
    "q.l5#8.o1" to "Die Oberschenkel",
    "q.l5#8.o2" to "Die Unterarme",
    "q.l5#8.o3" to "Der untere Rücken",
    "q.l5#8.e" to "Weil der Fuß flach bleibt, tragen Oberschenkel und ganzer Körper die Last – das ist sparsam und stundenlang durchzuhalten. Frontzackengehen ist das Gegenteil: Die Last liegt auf zwei oder drei Zacken und die Wade macht die ganze Arbeit – zwei völlig verschiedene Energiebilanzen.",

    "q.l5#9.p" to "Für welche Hangneigung eignet sich die Flachzackentechnik (französisch) besonders?",
    "q.l5#9.o0" to "0°–30°",
    "q.l5#9.o1" to "30°–50°",
    "q.l5#9.o2" to "50°–70°",
    "q.l5#9.o3" to "Über 70°",
    "q.l5#9.e" to "Die Lehrbücher nennen ausdrücklich 0°–30°. Wird es steiler, kann der Fuß nicht mehr flach bleiben und man muss auf die Frontzacken wechseln. Den Winkelbereich einer Technik zu kennen heißt also zu wissen, wann man die Technik wechselt.",

    // ---------- l6 Selbstbremsung ----------
    "q.l6#0.p" to "Wo sollen die Füße bei der Selbstbremsung sein?",
    "q.l6#0.o0" to "In den Schnee gedrückt, um zu bremsen",
    "q.l6#0.o1" to "Vom Schnee abgehoben, Zehen hoch, damit das ganze Gewicht über den Pickel geht",
    "q.l6#0.o2" to "Mit den Zehen in den Schnee gestochen, um zu ankern",
    "q.l6#0.o3" to "Zusammen und flach auf dem Schnee",
    "q.l6#0.e" to "Sobald ein Fuß den Schnee berührt, nimmt er Gewicht vom Pickel, die Bremswirkung bricht ein und Sie riskieren Knöchel- und Knieverletzungen. Heben Sie beide Füße, damit das gesamte Körpergewicht über die Haue in den Schnee geht.",

    "q.l6#1.p" to "Sie rutschen kopfüber mit den Füßen bergauf. Was ist das Erste?",
    "q.l6#1.o0" to "Versuchen, das Seil zu greifen",
    "q.l6#1.o1" to "Sofort in die Bauchlage mit den Füßen bergab drehen, dann die Bremsung aufbauen",
    "q.l6#1.o2" to "Weiterrutschen und warten, bis das Tempo sinkt",
    "q.l6#1.o3" to "Zuerst den Rucksack wegwerfen",
    "q.l6#1.e" to "Kopfüber lässt sich die Haue nicht wirksam in den Schnee drücken, und ein Aufprall mit dem Kopf ist extrem gefährlich. Drehen Sie sich mit Rumpf und Rumpfmuskulatur zuerst in die Bauchlage der Bremsstellung und drücken Sie dann die Haue hinein.",

    "q.l6#2.p" to "Wie lernt man die Selbstbremsung richtig?",
    "q.l6#2.o0" to "Ein Video zu schauen genügt",
    "q.l6#2.o1" to "Das Lehrbuch lesen und die Kernpunkte auswendig lernen",
    "q.l6#2.o2" to "Wiederholt an einem sicheren, weichen Schneehang mit sicherndem Ausbilder üben, bis es sitzt",
    "q.l6#2.o3" to "Es durch einen Sturz am echten Steilhang lernen",
    "q.l6#2.e" to "Selbstbremsung ist eine Fertigkeit auf Reflexniveau: Es braucht hunderte Wiederholungen unter kontrollierten Bedingungen, bis sie zuverlässig sitzt. Üben Sie an einem flachen Hang mit sauberem Auslauf, weichem Schnee und einem sichernden Ausbilder.",

    "q.l6#3.p" to "Wie bringen Sie bei der Selbstbremsung die Kraft am wirksamsten ein?",
    "q.l6#3.o0" to "Kräftig mit den Armen nach unten drücken",
    "q.l6#3.o1" to "Die Haue mit dem Körpergewicht senkrecht nach unten drücken",
    "q.l6#3.o2" to "Den Schaft seitlich über den Schnee ziehen",
    "q.l6#3.o3" to "Die Haue schnell über die Oberfläche wischen",
    "q.l6#3.e" to "Armkraft versagt unter Müdigkeit und Panik; nur das Körpergewicht treibt die Haue tiefer. Deshalb ist die Position – Bauchlage, Füße angehoben – wichtiger als rohe Kraft.",

    "q.l6#4.p" to "Wie gut funktioniert die Selbstbremsung auf hartem Schnee oder Eis?",
    "q.l6#4.o0" to "Besser – sie stoppt sofort",
    "q.l6#4.o1" to "Der Bremsweg wird sehr viel länger und kann ganz versagen",
    "q.l6#4.o2" to "Kein Unterschied zu weichem Schnee",
    "q.l6#4.o3" to "Sie wird automatisch zur Rutschpartie",
    "q.l6#4.e" to "Auf hartem Schnee und Eis findet die Haue schwer Halt. Deshalb betritt man einen steilen Hartschneehang nicht ungesichert – Technik ersetzt nicht das Umgehen, und die Grenzen einer Technik zu kennen ist genauso wichtig.",

    "q.l6#5.p" to "Wie teilen sich die Hände bei der Selbstbremsung die Aufgabe?",
    "q.l6#5.o0" to "Beide Hände am Schaft",
    "q.l6#5.o1" to "Beide Hände drücken auf den Kopf",
    "q.l6#5.o2" to "Eine Hand drückt nahe der Haue auf den Kopf für die Kraft nach unten, die andere liegt am Schaft für Richtung und Stabilität",
    "q.l6#5.o3" to "Eine Hand genügt; die andere bleibt frei",
    "q.l6#5.e" to "Die Hand am Kopf überträgt das Körpergewicht auf die Haue; die Hand am Schaft stabilisiert und korrigiert die Richtung. Mit klaren Rollen bremst es sich sowohl kräftig als auch gerade.",

    "q.l6#6.p" to "【Reihenfolge】Bringen Sie die Schritte der Sturzbremsung in die richtige Reihenfolge.",
    "q.l6#6.o0" to "Den Pickel fest greifen und den Kopf in der Bremsstellung unter den Körper drücken",
    "q.l6#6.o1" to "In die Bauchlage drehen, Kopf bergauf, Gesicht zum Schnee",
    "q.l6#6.o2" to "Die Haue mit dem Körpergewicht in Schnee und Eis drücken, Beine gespreizt, Knie am Untergrund",
    "q.l6#6.o3" to "Beide Füße anheben, damit die Steigeisen nicht greifen und Sie überschlagen",
    "q.l6#6.e" to "Der am häufigsten vergessene Schritt ist der letzte: das Anheben der Füße. Sobald ein Fuß den Schnee berührt, stiehlt er dem Pickel das Gewicht, und die Steigeisen können plötzlich greifen und Sie umdrehen – und damit die Bremsung selbst unterbrechen.",

    "q.l6#7.p" to "Wo soll die Haue (die flache Seite des Kopfes) bei der Selbstbremsung liegen?",
    "q.l6#7.o0" to "Außerhalb des Knies",
    "q.l6#7.o1" to "In der Schulterhöhle",
    "q.l6#7.o2" to "An der Hüfte",
    "q.l6#7.o3" to "Weit seitlich neben dem Kopf",
    "q.l6#7.e" to "Mit der Haue in der Schulterhöhle liegt der Schaft nahe der Körpermittellinie und die Last zentriert unter dem Rumpf – dort wirkt die Kraft nach unten am besten. Weiter außen verteilt sich die Last, die Haue wandert und der Bremsweg wächst deutlich.",

    "q.l6#8.p" to "【Mehrfachauswahl】Wovon hängt vor allem ab, ob eine Sturzbremsung gelingt?",
    "q.l6#8.o0" to "Der Neigung von Schnee oder Eis",
    "q.l6#8.o1" to "Der Härte von Schnee oder Eis",
    "q.l6#8.o2" to "Der Position des stürzenden Bergsteigers",
    "q.l6#8.o3" to "Der Reaktionsgeschwindigkeit",
    "q.l6#8.o4" to "Marke und Preis der Ausrüstung",
    "q.l6#8.e" to "Die Lehrbücher sind offen: Neben der Reaktionsgeschwindigkeit hängt der Erfolg von Neigung, Härte und Position ab – „manchmal lässt sich selbst die geübteste Bewegung nicht mehr bremsen“. Dieses Limit zu akzeptieren macht klar, warum das Nichtstürzen wichtiger ist als das Bremsen.",

    "q.l6#9.p" to "Wie ist die richtige Position von Beinen und Knien während der Bremsung?",
    "q.l6#9.o0" to "Beine zusammen, Knie über dem Boden",
    "q.l6#9.o1" to "Beine gespreizt, Knie gegen Schnee und Eis gedrückt",
    "q.l6#9.o2" to "Ein Bein gestreckt, das andere gebeugt",
    "q.l6#9.o3" to "Beide Beine vom Schnee abgehoben",
    "q.l6#9.e" to "Gespreizte Beine geben Seitenstabilität und verhindern das Wegrollen; Knie am Untergrund fügen einen Stützpunkt hinzu, der hilft, das Gewicht auf dem Pickel zu halten. Beachten Sie den Unterschied: Die Knie dürfen leicht aufliegen, die Füße – und die Steigeisen – müssen hoch.",

    // ---------- l7 Absturz verhindern ----------
    "q.l7#0.p" to "Wie verhindert man beim Gehen am wirksamsten ein Ausrutschen?",
    "q.l7#0.o0" to "Schneller gehen",
    "q.l7#0.o1" to "Den Pickel zur Selbstsicherung nutzen und sich mit jedem Schritt einen temporären Anker geben",
    "q.l7#0.o2" to "Den Pickel im Rucksack verstauen",
    "q.l7#0.o3" to "Sich allein auf das Seil verlassen",
    "q.l7#0.e" to "Selbstsicherung ist die direkteste Verteidigungslinie beim Gehen: Die Pickelhand setzt den Schaft mit jedem Schritt in den Schnee und schafft einen dritten Kontaktpunkt. Die überwiegende Mehrheit der Ausrutscher passiert in dem Moment, in dem diese Stütze fehlt.",

    "q.l7#1.p" to "Ihr Partner stürzt plötzlich, während Sie in der Seilschaft gehen. Was tun Sie zuerst?",
    "q.l7#1.o0" to "Hinunterlaufen und ihn packen",
    "q.l7#1.o1" to "Sofort in die Bremsstellung gehen und Seil einholen, um ihn zu halten",
    "q.l7#1.o2" to "Sich losbinden, um nicht mitgerissen zu werden",
    "q.l7#1.o3" to "Um Hilfe rufen und warten",
    "q.l7#1.e" to "Eine Seilschaft funktioniert, weil Sie zuerst sich selbst halten – dann überträgt das Seil die Bremsung. Hinunterlaufen oder Losbinden lässt die ganze Gruppe rutschen: das klassische Kettenversagen bei Gletscherunfällen.",

    "q.l7#2.p" to "Was ist im Moment des Ausrutschens die erste Handlung?",
    "q.l7#2.o0" to "Die Ausrüstung ordnen",
    "q.l7#2.o1" to "Warnen rufen und sofort in die Bauchlage zur Bremsung drehen",
    "q.l7#2.o2" to "Den Hangwinkel schätzen",
    "q.l7#2.o3" to "Schauen, was unten ist",
    "q.l7#2.e" to "Die ersten zwei Sekunden entscheiden. Der Warnruf bringt die Partner gleichzeitig in Schutzhaltung, während Sie sich in die Bauchlage drehen – diese Drehung ist die zentrale schadensbegrenzende Handlung.",

    "q.l7#3.p" to "In welchem Zustand sollte das Seil beim Gehen in der Seilschaft sein?",
    "q.l7#3.o0" to "So locker wie möglich für Bewegungsfreiheit",
    "q.l7#3.o1" to "Mäßig gespannt, ohne große durchhängende Schlaufen",
    "q.l7#3.o2" to "Vollständig gespannt",
    "q.l7#3.o3" to "So, wie es sich angenehm anfühlt",
    "q.l7#3.e" to "Große Schlaufen bedeuten, dass der Stürzende erst frei fällt, bevor das Seil Last aufnimmt – das vervielfacht den Impuls und lässt das Seil in den Schnee sägen. Mäßige Spannung lässt die Bremsung früher greifen.",

    "q.l7#4.p" to "Warum ist „nicht ausrutschen“ grundlegender als „bremsen lernen“?",
    "q.l7#4.o0" to "Weil Bremstechnik nutzlos ist",
    "q.l7#4.o1" to "Weil die Bremsung auf hartem Schnee und steilen Hängen versagen kann – nicht auszurutschen ist der zuverlässige Schutz",
    "q.l7#4.o2" to "Weil Bremsen zu anstrengend ist",
    "q.l7#4.o3" to "Weil Ausbilder das Üben verbieten",
    "q.l7#4.e" to "Selbstbremsung ist unverzichtbar, hat aber klare Grenzen. Die zuverlässige Strategie ist, gar nicht erst ungesichert in Gelände zu gehen, in dem man rutschen könnte. Technik ist die letzte Verteidigungslinie, nicht die erste.",

    "q.l7#5.p" to "Bei der Bremsung springt die Haue auf hartem Schnee und greift nicht. Was tun Sie?",
    "q.l7#5.o0" to "Anheben und erneut zuschlagen",
    "q.l7#5.o1" to "In der Bauchlage bleiben und mit dem Körpergewicht weiterdrücken, damit die Haue allmählich greift",
    "q.l7#5.o2" to "Den Schaft seitlich über den Schnee ziehen",
    "q.l7#5.o3" to "Die Bremsung aufgeben und den Kopf schützen",
    "q.l7#5.e" to "Den Pickel anzuheben hebt die Bremsung vollständig auf und kostet die aufgebaute Druckposition. Bleiben Sie in der Bauchlage und drücken Sie weiter; beim Rutschen gräbt sich die Haue tiefer. Bremsen ist ein fortschreitender Prozess, keine Einzelaktion.",

    "q.l7#6.p" to "Warum gilt Bremsen auf Eis als sehr schwierig?",
    "q.l7#6.o0" to "Weil Eis zu kalt ist",
    "q.l7#6.o1" to "Weil die Haue im Eis kaum greift und man an Eishängen deshalb ein Seil legt statt auf die Bremsung zu setzen",
    "q.l7#6.o2" to "Weil die Reibung auf Eis zu hoch ist",
    "q.l7#6.o3" to "Weil Eis leicht bricht",
    "q.l7#6.e" to "Bremsen hängt vom Greifen der Haue ab, und Eis ist die am schwersten zu greifende Oberfläche. Die Lehrbücher antworten systemisch: An geneigtem Eis ein Fixseil legen oder im Wechsel sichern und in der Regel nicht gemeinsam gehen – mit dem System lösen, nicht mit Hoffnung auf individuelle Technik.",

    "q.l7#7.p" to "【Reihenfolge】Ihr Partner stürzt beim Gehen in der Seilschaft. Was ist die richtige Abfolge?",
    "q.l7#7.o0" to "Sofort in die Bremsstellung gehen und sich selbst halten",
    "q.l7#7.o1" to "Seil einholen, um den Sturz zu bremsen",
    "q.l7#7.o2" to "Einen unabhängigen Anker bauen (Schneeanker, vergrabener Pickel usw.)",
    "q.l7#7.o3" to "Die Last auf den Anker übertragen, dann mit der Rettung beginnen",
    "q.l7#7.e" to "Die vier Schritte lassen sich nicht umstellen: Sie müssen sich zuerst selbst halten, bevor Sie irgendetwas anderes tun können, und eine Rettung ohne Anker legt das Gewicht beider Personen auf Sie. In der Realität dauern diese Schritte Minuten – sie müssen vorher geübt sein.",

    "q.l7#8.p" to "Die Bremsung hat gewirkt, der Rutsch ist gestoppt. Wie geht es weiter?",
    "q.l7#8.o0" to "Aufstehen und weitergehen",
    "q.l7#8.o1" to "Die Bremsung halten, Schritt für Schritt Sicherung aufbauen und das Gewicht auf den Anker übertragen",
    "q.l7#8.o2" to "Das Seil losbinden",
    "q.l7#8.o3" to "Prüfen, ob die Ausrüstung beschädigt ist",
    "q.l7#8.e" to "Ein gestoppter Rutsch ist keine Sicherheit – Sie sind weiter in ungesicherter Position und würden eine erneute Bremsung kaum schaffen. Halten Sie die Bremsung, während Sie zuverlässige Sicherung aufbauen, sich befreien und erst dann Verletzungen und Route angehen.",

    "q.l7#9.p" to "【Mehrfachauswahl】Was verhindert Ausrutscher wirksam?",
    "q.l7#9.o0" to "Beim Gehen laufend mit dem Pickel selbst sichern",
    "q.l7#9.o1" to "Auf Hartschnee oder Eishängen ein Fixseil legen",
    "q.l7#9.o2" to "Ein nachhaltiges gleichmäßiges Tempo halten und plötzliche Kraftakte vermeiden, die das Gleichgewicht brechen",
    "q.l7#9.o3" to "Im Tempo des langsamsten Mitglieds gehen, damit die Gruppe nicht auseinanderzieht",
    "q.l7#9.o4" to "Schneller gehen, um die Expositionszeit zu verkürzen",
    "q.l7#9.e" to "Diese vier wirken auf verschiedenen Ebenen: persönliche Technik, Systemsicherung, Tempo und Gruppenzusammenhalt. Absturzverhütung ist nie eine Einzelaktion – sie ist alle diese Schichten zugleich.",

    // ---------- l8 Abstieg und Abseilen ----------
    "q.l8#0.p" to "Warum passieren beim Abstieg mehr Unfälle?",
    "q.l8#0.o0" to "Weil der Untergrund bergab schwieriger ist",
    "q.l8#0.o1" to "Weil Ermüdung Aufmerksamkeit und Bewegungsqualität verschlechtert",
    "q.l8#0.o2" to "Weil das Wetter beim Abstieg immer schlechter ist",
    "q.l8#0.o3" to "Weil die Ausrüstung versagt",
    "q.l8#0.e" to "Ist der Gipfel erreicht, sinkt die Wachheit, während der Körper schon fast leer ist. Ein großer Teil der bergsteigerischen Unfälle geschieht beim Abstieg – daher der Satz, der Gipfel sei nur die Hälfte des Weges.",

    "q.l8#1.p" to "Unter welchen Bedingungen darf man rutschen (Glissade)?",
    "q.l8#1.o0" to "Immer wenn der Hang steil genug ist",
    "q.l8#1.o1" to "Keine Gletscherspalten, kein Steinschlagrisiko, sauberer Auslauf unten und die Fähigkeit, jederzeit zu bremsen",
    "q.l8#1.o2" to "An jedem Schneehang",
    "q.l8#1.o3" to "Immer wenn die Partner zustimmen",
    "q.l8#1.e" to "Eine Glissade ist eine unumkehrbare Beschleunigung – einmal begonnen, ist sie schwer zu stoppen. Sie müssen Gletscherspalten, Steinschlag und Personen unten ausschließen und sicher sein, jederzeit in die Bremsung drehen zu können. Sonst steigen Sie anständig ab.",

    "q.l8#2.p" to "Wie steigt man technisches Gelände am besten ab?",
    "q.l8#2.o0" to "Zum Hang gewandt abklettern, mit drei Kontaktpunkten",
    "q.l8#2.o1" to "Mit dem Gesicht nach außen hinunterlaufen",
    "q.l8#2.o2" to "Rutschen (Glissade)",
    "q.l8#2.o3" to "Sitzen und rutschen",
    "q.l8#2.e" to "Zum Hang gewandt sehen Sie Ihre Tritte, halten den Körperschwerpunkt nah an der Oberfläche und haben beide Hände frei zur Unterstützung. Mit dem Gesicht nach außen verdecken Sie Ihre Tritte – ein sehr häufiger Fehler.",

    "q.l8#3.p" to "Was ist der gefährlichste und häufigste Fehler beim Abstieg?",
    "q.l8#3.o0" to "Zum Hang gewandt auf drei Punkten abklettern",
    "q.l8#3.o1" to "Sich vorlehnen und mit dem Gesicht nach außen absteigen",
    "q.l8#3.o2" to "Einen gleichmäßigen Rhythmus halten",
    "q.l8#3.o3" to "Mit dem Pickel selbst sichern",
    "q.l8#3.e" to "Mit dem Gesicht nach außen sehen Sie Ihre Tritte nicht, und Vorlehnen macht Sie noch instabiler. Kommt dann Ermüdung hinzu, die die Beinkontrolle senkt, haben Sie den wahren Grund, warum Abstiege so unfallträchtig sind.",

    "q.l8#4.p" to "Was muss vor dem Beginn einer Glissade geklärt sein?",
    "q.l8#4.o0" to "Den Pickel im Rucksack verstauen",
    "q.l8#4.o1" to "Bestätigen, dass niemand unten ist und keine Spalten oder Steinschlag in der Linie liegen, und den Pickel bremsbereit in der Hand halten",
    "q.l8#4.o2" to "Die Rucksackriemen festziehen",
    "q.l8#4.o3" to "Der Familie den Zeitplan mitteilen",
    "q.l8#4.e" to "Eine Glissade ist unumkehrbare Beschleunigung. Vor dem Start müssen Personen unten, Gletscherspalten und Steinschlag ausgeschlossen sein und der Pickel in der Hand bleiben – sonst haben Sie keine Möglichkeit zu bremsen, wenn etwas schiefgeht.",

    "q.l8#5.p" to "Wie geht man mit der Ermüdung der Gruppe auf einem langen Abstieg um?",
    "q.l8#5.o0" to "Mit möglichst wenigen Pausen durchgehen",
    "q.l8#5.o1" to "Kurze geplante Pausen machen, trinken und essen und den Zustand der Gruppe neu beurteilen",
    "q.l8#5.o2" to "Schneller gehen, um die Expositionszeit zu verkürzen",
    "q.l8#5.o3" to "Nur bei Verletzungen anhalten",
    "q.l8#5.e" to "Der Abstieg ist die risikoreiche Hälfte, und Ermüdung ist der Haupttreiber. Regelmäßige kurze Pausen geben Energie zurück und erlauben, Wetter, Route und Partner neu zu lesen – Urteile, die bei langem Durchhalten zuerst verschwinden.",

    "q.l8#6.p" to "【Reihenfolge】Bringen Sie die Vorbereitung eines Abseilens in sinnvolle Reihenfolge.",
    "q.l8#6.o0" to "Abseillinie und Ausstieg bestätigen und Personen darunter wegbitten",
    "q.l8#6.o1" to "Prüfen, dass Seil, Sicherungsgerät, Karabiner und Schlingen vollständig sind",
    "q.l8#6.o2" to "Einen zuverlässigen Anker bauen oder den vorhandenen Stand bestätigen",
    "q.l8#6.o3" to "Das Seil ordnen, um Knoten und Verdrehungen zu vermeiden, dann mit dem Abstieg beginnen",
    "q.l8#6.e" to "Beim Abseilen hängt das Leben an einem einzigen Punkt, also gilt: erst entscheiden, wohin; dann die Ausrüstung bestätigen; dann einsteigen. Das Ordnen des Seils ist genauso wichtig – ein Knoten oder eine Verdrehung lässt Sie lange am Seil hängen.",

    "q.l8#7.p" to "Was entscheidet vor allem zwischen Abseilen und Abklettern?",
    "q.l8#7.o0" to "Je kürzer der Abstieg, desto eher abseilen",
    "q.l8#7.o1" to "Die Schwierigkeit des Geländes, die vorhandenen Anker und das Können der Gruppe",
    "q.l8#7.o2" to "Das Wetter",
    "q.l8#7.o3" to "Wie neu die Ausrüstung ist",
    "q.l8#7.e" to "Abseilen ist schnell, hängt aber von Ankern und Ausführung ab; Abklettern ist langsamer, aber selbstständig. Gelände, Ankerzuverlässigkeit und Können entscheiden gemeinsam. Denken Sie daran: Abseilen hat eine hohe Unfallquote, weil der Spielraum für Bedienfehler so klein ist.",

    "q.l8#8.p" to "Welche technische Ausrüstung braucht ein Abseilen normalerweise?",
    "q.l8#8.o0" to "Einen Karabiner und eine Schlinge",
    "q.l8#8.o1" to "Mehrere Karabiner, eine lange Schlinge oder einen Personal Anchor, Prusikkordel usw.",
    "q.l8#8.o2" to "Nur ein Seil",
    "q.l8#8.o3" to "Nur ein Sicherungsgerät",
    "q.l8#8.e" to "Die Lehrbücher nennen mehrere Karabiner, eine lange Schlinge oder Daisy Chain und Prusikkordel. Ein Abstieg bedeutet oft, Anker unterwegs abzubauen und trotzdem eine Rückfallsicherung zu behalten – zu wenig Material zwingt Sie, hoch über dem Boden zu improvisieren, und genau dort entstehen Unfälle.",

    "q.l8#9.p" to "【Mehrfachauswahl】Was sind die Hauptrisiken beim Abstieg?",
    "q.l8#9.o0" to "Ankerversagen",
    "q.l8#9.o1" to "Über das Seilende hinaus abseilen, weil die Enden nicht verknotet waren",
    "q.l8#9.o2" to "Verklemmen oder Verdrehen des Seils",
    "q.l8#9.o3" to "Steinschlag und Personen darunter",
    "q.l8#9.o4" to "Der Abstieg ist weniger riskant als der Aufstieg, weil die Schwerkraft hilft",
    "q.l8#9.e" to "Die ersten vier sind die üblichen Ursachen von Abseilunfällen. Am häufigsten übersehen wird das unverknotete Seilende: Ist das Seil zu kurz und die Enden frei, rutschen Sie unbemerkt über das Ende und stürzen. Dieser Fehler passiert besonders oft auf einem müden Abstieg.",

    // ---------- l9 Seiltechnik ----------
    "q.l9#0.p" to "Welcher Knoten verbindet das Seil mit dem Gurt und ist auf Gletscherrouten üblich?",
    "q.l9#0.o0" to "Achterknoten (eingefädelt)",
    "q.l9#0.o1" to "Kreuzknoten",
    "q.l9#0.o2" to "Überhandknoten",
    "q.l9#0.o3" to "Palstek",
    "q.l9#0.e" to "Der eingefädelte Achterknoten ist stark, gut lesbar und für andere leicht zu prüfen und lässt sich nach Belastung noch lösen. Ein Kreuzknoten kann unter Last rutschen oder sich zuziehen und darf niemals eine lebenswichtige Verbindung tragen.",

    "q.l9#1.p" to "Welcher Knoten lässt sich einhändig in der Länge verstellen, um das Seil an einem Karabiner zu fixieren?",
    "q.l9#1.o0" to "Doppelter Fischerknoten",
    "q.l9#1.o1" to "Mastwurf (Weberknoten)",
    "q.l9#1.o2" to "Alpiner Schmetterling",
    "q.l9#1.o3" to "Wasserknoten",
    "q.l9#1.e" to "Der Mastwurf lässt sich am Karabiner einhändig schieben und ziehen und ist die Standardsicherung am Standplatz. Der doppelte Fischer verbindet zwei Seile; der Schmetterling schafft einen Befestigungspunkt mitten im Seil.",

    "q.l9#2.p" to "Was ist die entscheidende Eigenschaft eines Klemmknotens wie des Prusik?",
    "q.l9#2.o0" to "Er klemmt unter Last und gleitet am Seil, wenn er entlastet wird",
    "q.l9#2.o1" to "Er kann das Hauptseil dauerhaft ersetzen",
    "q.l9#2.o2" to "Er ist nur dekorativ",
    "q.l9#2.o3" to "Er öffnet sich unter Last von selbst",
    "q.l9#2.e" to "Die Einwegklemmung macht Klemmknoten für Aufstieg, Rückfallsicherung und mechanische Systeme nutzbar. Und weil die Zuverlässigkeit von Kordeldurchmesser und Windungszahl abhängt, müssen Sie sie vor Ort testen, bevor Sie sich darauf verlassen.",

    "q.l9#3.p" to "Wie viel Restlänge sollte nach dem Fertigstellen eines Knotens übrig bleiben?",
    "q.l9#3.o0" to "Etwa 1 cm genügt",
    "q.l9#3.o1" to "Mindestens zehn Seildurchmesser",
    "q.l9#3.o2" to "Ein Rest ist nicht nötig",
    "q.l9#3.o3" to "So lang wie möglich – mindestens 1 m",
    "q.l9#3.e" to "Genug Rest ist die grundlegende Absicherung dagegen, dass ein Knoten unter Last rutscht oder sich durch Rütteln löst. Machen Sie auch die gegenseitige Kontrolle zur Gewohnheit – Knoten sind der einzige Teil des Sicherungssystems, der ausschließlich von Hand entsteht, ohne Werksprüfung.",

    "q.l9#4.p" to "Welcher Knoten verbindet zwei Seile oder schließt eine Prusikschlinge?",
    "q.l9#4.o0" to "Kreuzknoten",
    "q.l9#4.o1" to "Doppelter Fischerknoten",
    "q.l9#4.o2" to "Überhandknoten",
    "q.l9#4.o3" to "Palstek",
    "q.l9#4.e" to "Der doppelte Fischer ist extrem stabil und löst sich kaum, aber nach Belastung schwer zu öffnen – ideal zum Verbinden von Seilen und zum Schließen von Kordelschlingen. Ein Kreuzknoten kann unter Last rutschen und darf nie Gewicht tragen.",

    "q.l9#5.p" to "Warum hängt die Zuverlässigkeit eines Klemmknotens vom Kordeldurchmesser ab?",
    "q.l9#5.o0" to "Der Durchmesser spielt keine Rolle",
    "q.l9#5.o1" to "Ist die Kordel viel dünner als das Seil, sind Kontaktfläche und Klemmkraft zu klein, um zu greifen",
    "q.l9#5.o2" to "Je dünner die Kordel, desto besser greift sie",
    "q.l9#5.o3" to "Je dicker die Kordel, desto besser greift sie",
    "q.l9#5.e" to "Ein Klemmknoten greift, indem er das Hauptseil einschnürt. Zu dünn: Kontaktfläche und Klemmkraft reichen nicht; zu dick: Er legt sich nicht eng genug. Prüfen Sie daher jedes Mal die Kombination und testen Sie sie an einer sicheren Stelle, bevor Sie sich darauf verlassen.",

    "q.l9#6.p" to "Wofür wird der alpine Schmetterling vor allem verwendet?",
    "q.l9#6.o0" to "Zum Verbinden zweier Seile",
    "q.l9#6.o1" to "Für eine feste Schlaufe mitten im Seil, die Last aus mehr als einer Richtung aufnehmen kann",
    "q.l9#6.o2" to "Als Ersatz für den Achter beim Einbinden",
    "q.l9#6.o3" to "Zum Herstellen einer Prusikschlinge",
    "q.l9#6.e" to "Der Schmetterling bildet eine Schlaufe in der Seilmitte, die Last aus beiden Richtungen hält – deshalb erscheint er in Seilschaften, beim Gletschergehen und in Rettungssystemen. Er wird auch zwischen Bergsteigern geknüpft, um die Reibung zu erhöhen, wo das Seil über Schnee läuft.",

    "q.l9#7.p" to "【Zuordnung】Ordnen Sie jedem Knoten seinen Hauptzweck zu.",
    "q.l9#7.l0" to "Achterknoten",
    "q.l9#7.l1" to "Doppelter Fischerknoten",
    "q.l9#7.l2" to "Klemmknoten (Prusik)",
    "q.l9#7.l3" to "Palstek",
    "q.l9#7.r0" to "Die übliche Verbindung zu einem Anker oder Gurt",
    "q.l9#7.r1" to "Zwei Seile verbinden oder eine Kordelschlinge schließen",
    "q.l9#7.r2" to "Klemmknoten: greift unter Last, gleitet ohne Last",
    "q.l9#7.r3" to "An einen Anker binden; auch beim Festmachen eines Bootes üblich",
    "q.l9#7.e" to "Diese vier decken den größten Teil des Gletschergehens und der Basissicherung ab. Die Lehrbücher ordnen sie nach Funktion – am Anker befestigen, Seile verbinden, Klemmknoten. Nach Funktion zu lernen bleibt viel besser haften als nach Form.",

    "q.l9#8.p" to "Welche Aussage über Knoten und Seilfestigkeit ist richtig?",
    "q.l9#8.o0" to "Knoten beeinflussen die Seilfestigkeit nicht",
    "q.l9#8.o1" to "Jeder Knoten senkt die Seilfestigkeit an dieser Stelle, unterschiedlich stark",
    "q.l9#8.o2" to "Knoten machen das Seil stärker",
    "q.l9#8.o3" to "Ein gut gebundener Knoten hat keinen Einfluss auf die Festigkeit",
    "q.l9#8.e" to "Am Knoten wird das Seil gebogen, unter Last tragen die Fasern ungleichmäßig, und die Festigkeit sinkt immer – nur das Ausmaß variiert. Deshalb drucken die Lehrbücher Tabellen zum Festigkeitsverlust je Knoten: Man wählt einen Knoten nach seiner Funktion und nach dem, was er an Festigkeit kostet.",

    "q.l9#9.p" to "Das Lehrbuch fasst den Sinn der Knoten in einem Satz zusammen: „Ein Knoten gibt dem Seil ( ).“",
    "q.l9#9.a0" to "Leben",
    "q.l9#9.a1" to "das Leben",
    "q.l9#9.e" to "Im Original heißt es „ein Knoten gibt dem Seil Leben“. Das trifft den Kern: Ein Seil allein ist nur eine Leine, und erst durch Knoten – die Verbindung mit Sicherung, Ankern und anderen Seilen – wird es ein System, das ein Leben tragen kann.",

    // ---------- l10 Gletscher und Seilschaft ----------
    "q.l10#0.p" to "Wie groß sollte eine Seilschaft auf dem Gletscher idealerweise sein?",
    "q.l10#0.o0" to "2",
    "q.l10#0.o1" to "3",
    "q.l10#0.o2" to "6 oder mehr",
    "q.l10#0.o3" to "Eine Person allein",
    "q.l10#0.e" to "Eine Dreierseilschaft hat genug Leute, um einen Anker zu bauen und ein Rettungssystem zu bedienen, wenn einer in eine Spalte fällt. Bei zweien muss der andere gleichzeitig bremsen, bauen und ziehen – fast kein Spielraum.",

    "q.l10#1.p" to "Welcher Seilabstand ist beim Gletschergehen üblich?",
    "q.l10#1.o0" to "2–3 m",
    "q.l10#1.o1" to "8–12 m",
    "q.l10#1.o2" to "Mehr als 30 m",
    "q.l10#1.o3" to "So kurz wie möglich",
    "q.l10#1.e" to "8–12 m geben dem Partner Zeit und Distanz zu reagieren und zu bremsen und erlauben weiterhin Verständigung und Zusammenarbeit. Zu kurz, und es bleibt fast kein Seil, das den Impuls aufnehmen kann.",

    "q.l10#2.p" to "Was braucht eine Seilschaft, bevor sie tatsächlich Schutz bietet?",
    "q.l10#2.o0" to "Eingebunden zu sein macht schon sicher",
    "q.l10#2.o1" to "Partner, die wirksam bremsen und Sicherung bauen können",
    "q.l10#2.o2" to "Ein ausreichend langes Seil",
    "q.l10#2.o3" to "Eine ausreichend große Gruppe",
    "q.l10#2.e" to "Sicherheit in der Seilschaft entsteht aus zwei zuverlässig ausgeführten Handlungen: bremsen und ankern. Eine Seilschaft ohne Bremstechnik und Ankerbau ist einfach eine Gruppe, die gemeinsam in dasselbe Loch fällt.",

    "q.l10#3.p" to "Warum knüpft man auf dem Gletscher Knoten (etwa den Schmetterling) zwischen die Bergsteiger?",
    "q.l10#3.o0" to "Rein zur Zierde",
    "q.l10#3.o1" to "Um die Reibung zu erhöhen, wo das Seil über Schnee läuft, und die Falltiefe eines Stürzenden zu begrenzen",
    "q.l10#3.o2" to "Um die Partner zu erkennen",
    "q.l10#3.o3" to "Um das Seil leichter zu machen",
    "q.l10#3.e" to "Jeder Knoten schafft einen zusätzlichen Bremspunkt an der Schneeoberfläche, verkürzt die Falltiefe deutlich und verschafft den obenstehenden Partnern Zeit, Sicherung zu bauen. Es ist eine sehr billige, sehr wirksame Bremse.",

    "q.l10#4.p" to "Wo trägt man die Rettungsausrüstung beim Gehen auf dem Gletscher?",
    "q.l10#4.o0" to "Ganz unten im Rucksack",
    "q.l10#4.o1" to "In Reichweite, jederzeit einsatzbereit",
    "q.l10#4.o2" to "Im Zelt am Lagerplatz",
    "q.l10#4.o3" to "Beim Partner abgegeben",
    "q.l10#4.e" to "Das goldene Zeitfenster bei einer Spaltenrettung sind wenige Minuten. Liegen Prusikkordeln, Karabiner und Eishaken ganz unten im Rucksack, ist der Partner beim Ausgraben vielleicht schon unterkühlt oder das Seil hat die Randlippe durchschnitten.",

    "q.l10#5.p" to "Was ist das Hauptrisiko einer Zweierseilschaft gegenüber einer Dreierseilschaft?",
    "q.l10#5.o0" to "Sie ist langsamer",
    "q.l10#5.o1" to "Fällt einer, kann der Verbleibende nicht gleichzeitig bremsen und die Rettung durchführen",
    "q.l10#5.o2" to "Das Seil ist nicht lang genug",
    "q.l10#5.o3" to "Man muss mehr Ausrüstung tragen",
    "q.l10#5.e" to "Bei zweien muss der andere, wenn einer in die Spalte fällt, gleichzeitig die Bremsung halten, einen Anker bauen und ein Zugsystem bedienen – fast kein Spielraum. Wer zu zweit gehen muss, wählt eine konservativere Route und plant weiter voraus.",

    "q.l10#6.p" to "Warum sollte man auf dem Gletscher nicht nach Belieben ausbinden?",
    "q.l10#6.o0" to "Weil Aus- und Einbinden lästig ist",
    "q.l10#6.o1" to "Weil die Gefahr im Spaltengelände kontinuierlich ist – im Moment des Ausbindens gibt es keinen Schutz",
    "q.l10#6.o2" to "Weil das Seil verloren gehen könnte",
    "q.l10#6.o3" to "Weil die Partner sich beschweren",
    "q.l10#6.e" to "Die Gefahr auf dem Gletscher ist ungleich verteilt und schwer vorherzusagen, und meist bindet man aufgrund der Fehleinschätzung aus, „dieses Stück sei harmlos“. Wenn es wirklich nötig ist, halten Sie zuerst an, prüfen Gelände und Schnee und handeln dann als Gruppe.",

    "q.l10#7.p" to "【Zuordnung】Ordnen Sie die internationalen Kletterkommandos ihrer Bedeutung zu.",
    "q.l10#7.l0" to "On belay",
    "q.l10#7.l1" to "Climbing",
    "q.l10#7.l2" to "Falling",
    "q.l10#7.l3" to "Off belay",
    "q.l10#7.r0" to "Sicherung ist bereit, Sie können starten",
    "q.l10#7.r1" to "Ich beginne zu klettern",
    "q.l10#7.r2" to "Ich stürze (Warnung)",
    "q.l10#7.r3" to "Sicherung freigegeben, Sicherung ist beendet",
    "q.l10#7.e" to "Das Kommandosystem funktioniert, weil es keine Erklärung braucht. In der Höhe ist der Wind laut und die Abstände sind groß, daher beseitigen kurze Wörter mit beiderseits gleicher Bedeutung die Mehrdeutigkeit. Der gefährlichste Moment beim Sichern ist der, in dem jeder annimmt, der andere wisse Bescheid. Die Lehrbücher nennen die internationalen Kommandos, weil sie die minimale Verabredung über Teams und Sprachen hinweg sind.",

    "q.l10#8.p" to "Welche technische Grundausrüstung braucht ein Sichernder?",
    "q.l10#8.o0" to "Ein Gurt, ein Karabiner, ein Sicherungsgerät, ein Paar Handschuhe, ein Helm",
    "q.l10#8.o1" to "Nur ein Sicherungsgerät und ein Karabiner",
    "q.l10#8.o2" to "Ein Helm und eine Sonnenbrille",
    "q.l10#8.o3" to "Ein Gurt und ein Seil",
    "q.l10#8.e" to "Die Liste wirkt einfach, aber jedes fehlende Teil hat eine konkrete Folge: ohne Handschuhe verbrennen die Hände und die Seilkontrolle leidet; ohne Helm gibt es keine Antwort auf Steinschlag. Der Sichernde ist der, der andere fängt – deshalb muss die eigene Ausrüstung zuerst vollständig sein.",

    "q.l10#9.p" to "Warum macht man vor dem Klettern einen Partnercheck?",
    "q.l10#9.o0" to "Weil die Disziplin der Gruppe es verlangt",
    "q.l10#9.o1" to "Weil Fehler an Gurt, Knoten und Sicherungsgerät für den Träger oft unsichtbar sind",
    "q.l10#9.o2" to "Um den Fortschritt zu dokumentieren",
    "q.l10#9.o3" to "Zum Aufwärmen",
    "q.l10#9.e" to "Bei der Selbstkontrolle sehen Sie, was Sie zu sehen glauben. Ein Partner sieht von hinten und von der Seite in Bereiche, die Sie selbst nicht sehen. Die Lehrbücher stellen den Partnercheck an den Anfang der Sicherungskommunikation – er nutzt fremde Augen, um Ihren blinden Fleck abzudecken.",

    // ---------- l11 Prinzipien des Standplatzes ----------
    "q.l11#0.p" to "Wofür steht das R in den SRENE-Prinzipien?",
    "q.l11#0.o0" to "Rapid (schnell)",
    "q.l11#0.o1" to "Redundant (redundant)",
    "q.l11#0.o2" to "Rope (Seil)",
    "q.l11#0.o3" to "Rigid (steif)",
    "q.l11#0.e" to "Redundant heißt: Das System hat mehrere unabhängige Sicherungspunkte, sodass bei Versagen eines Punktes die anderen die Last weiter tragen. Es ist das wichtigste Einzelelement der Standplatzsicherheit.",

    "q.l11#1.p" to "Was bedeutet das Prinzip „No Extension“ (keine Dehnung)?",
    "q.l11#1.o0" to "Je länger das Seil, desto besser",
    "q.l11#1.o1" to "Fällt ein Punkt aus, darf sich das System nicht ausdehnen und die übrigen Punkte schockbelasten",
    "q.l11#1.o2" to "Standplätze dürfen nicht tief gebaut werden",
    "q.l11#1.o3" to "Es wird keine Reserveausrüstung gebraucht",
    "q.l11#1.e" to "Bleibt Lose zwischen den Punkten, fällt bei einem Versagen die Last als plötzlicher Schock auf die verbleibenden Punkte – weit mehr als die statische Last. No Extension heißt ausgleichen und vorspannen, damit dieser Schock gar nicht erst ins System kommt.",

    "q.l11#2.p" to "Was ist der Kerngedanke der Standplatzgestaltung?",
    "q.l11#2.o0" to "So wenig Material wie möglich verwenden",
    "q.l11#2.o1" to "Der Ausfall eines einzelnen Punktes darf nicht das ganze System zum Einsturz bringen",
    "q.l11#2.o2" to "So hoch wie möglich bauen",
    "q.l11#2.o3" to "Nur das dickste Seil verwenden",
    "q.l11#2.e" to "Fels- und Schneeanker können nie absolut sicher sein, deshalb wird das System auf Fehlertoleranz ausgelegt: Kein einzelner Ausfall ist tödlich, was dem Kletterer Zeit zur Reaktion und eine Rückfallebene verschafft.",

    "q.l11#3.p" to "Welche zwei Dimensionen fügt EARNEST den SRENE hinzu?",
    "q.l11#3.o0" to "Efficient und Timely (effizient und rechtzeitig)",
    "q.l11#3.o1" to "Easy und Tight (einfach und stramm)",
    "q.l11#3.o2" to "Equal und Nice (gleich und schön)",
    "q.l11#3.o3" to "Empty und True (leer und wahr)",
    "q.l11#3.e" to "Ein Standplatz muss nicht nur sicher sein, er muss auch schnell gehen und einfach zu bedienen sein – denn die Zeit, die man zum Bauen braucht, ist Zeit in der Exposition. Genau hier kommt EARNEST dem echten Gelände näher als SRENE.",

    "q.l11#4.p" to "Wovon hängt die Zuverlässigkeit eines Schneeankers vor allem ab?",
    "q.l11#4.o0" to "Von der Marke der Ausrüstung",
    "q.l11#4.o1" to "Von der Schnee- und der Vergrabungsqualität",
    "q.l11#4.o2" to "Von der Farbe des Seils",
    "q.l11#4.o3" to "Von der Höhe",
    "q.l11#4.e" to "Derselbe Eishaken oder Deadman hält in tiefem Schnee, in nassem Schnee und am Rand einer Schneebrücke völlig unterschiedliche Lasten. Schneeanker verlangen, die Schneedecke vor Ort zu lesen – ein festes Verfahren genügt nicht.",

    "q.l11#5.p" to "Warum braucht ein Standplatz eine ausgeglichene Lastverteilung?",
    "q.l11#5.o0" to "Damit er ordentlich aussieht",
    "q.l11#5.o1" to "Damit die Last wie geplant auf die Punkte verteilt wird und kein Punkt überlastet ist",
    "q.l11#5.o2" to "Um Ausrüstung zu sparen",
    "q.l11#5.o3" to "Damit er leichter abzubauen ist",
    "q.l11#5.e" to "Ausgleichen heißt, jeder Punkt trägt annähernd seine Auslegungslast, statt dass einer alles übernimmt. Erreicht ein Punkt seine Grenze und versagt, springt die Last plötzlich auf die anderen und kann eine Kettenreaktion auslösen.",

    "q.l11#6.p" to "Welche dieser Praktiken verletzt das Redundanzprinzip?",
    "q.l11#6.o0" to "Bauteile unterschiedlicher Festigkeit verwenden",
    "q.l11#6.o1" to "Zwei Sicherungspunkte, die tatsächlich von derselben Risslinie oder demselben Block abhängen",
    "q.l11#6.o2" to "Die Punkte mit Schlingen verbinden",
    "q.l11#6.o3" to "Drei Sicherungspunkte setzen",
    "q.l11#6.e" to "Redundanz verlangt, dass jeder Punkt unabhängig versagt. Teilen zwei Punkte einen Riss, nimmt dessen Öffnen beide gleichzeitig mit – es sieht nach zwei aus, wirkt aber wie einer. Diese falsche Redundanz ist häufig und tödlich.",

    "q.l11#7.p" to "【Zuordnung】Ordnen Sie jeden Begriff der Standplatzbewertung seiner Bedeutung zu.",
    "q.l11#7.l0" to "S (Solid)",
    "q.l11#7.l1" to "R (Redundant)",
    "q.l11#7.l2" to "E (Equalized)",
    "q.l11#7.l3" to "No Extension",
    "q.l11#7.r0" to "Stark: Jeder Punkt trägt die erwartete Last",
    "q.l11#7.r1" to "Redundant: Mehrere unabhängige Sicherungspunkte",
    "q.l11#7.r2" to "Ausgeglichen: Last sinnvoll auf die Punkte verteilt",
    "q.l11#7.r3" to "Keine Dehnung: Ein Ausfall erzeugt keine schockartige Ausdehnung",
    "q.l11#7.e" to "Diese vier bilden das Grundgerüst, abgekürzt SRENE. Die Reihenfolge lohnt sich zu merken: Erst fragen, ob jeder Punkt solide ist, dann, ob das System redundant ist – ist ein Einzelpunkt unzuverlässig, ist die Diskussion über Redundanz sinnlos.",

    "q.l11#8.p" to "Welcher Winkel zwischen den Schlingen Schenkeln ist nach den Lastwerten anzustreben?",
    "q.l11#8.o0" to "Innerhalb von 60°",
    "q.l11#8.o1" to "Innerhalb von 90°",
    "q.l11#8.o2" to "Innerhalb von 120°",
    "q.l11#8.o3" to "Der Winkel beeinflusst die Last nicht",
    "q.l11#8.e" to "Bei 0° trägt jeder Punkt etwa 50 %, bei 60° etwa 58 %, bei 90° etwa 71 % – je weiter der Winkel, desto größer die Last, die das Gewicht einer Person auf jeden Punkt bringt. Die Faustregel „unter 60° bleiben“ stammt direkt aus diesen Zahlen.",

    "q.l11#9.p" to "Warum gehören Effizienz und Rechtzeitigkeit zur Standplatzbewertung?",
    "q.l11#9.o0" to "Damit die Arbeit besser aussieht",
    "q.l11#9.o1" to "Weil der Bau des Standplatzes selbst Zeit in der Exposition ist",
    "q.l11#9.o2" to "Um Ausrüstung zu sparen",
    "q.l11#9.o3" to "Um das Lehren zu erleichtern",
    "q.l11#9.e" to "Beim Bau eines Standplatzes ist man oft ungesichert oder schlecht gesichert. Je kürzer diese Exposition, desto geringer das Risiko – „schnell gebaut, einfach bedient“ ist also keine Bequemlichkeit, sondern Teil des Sicherheitsmaßstabs.",

    "q.l11#10.p" to "【Mehrfachauswahl】Wie sieht ein angemessener Standplatz aus?",
    "q.l11#10.o0" to "Jeder Sicherungspunkt ist für sich stark",
    "q.l11#10.o1" to "Die Punkte versagen unabhängig voneinander",
    "q.l11#10.o2" to "Die Last ist sinnvoll auf die Punkte verteilt",
    "q.l11#10.o3" to "Das System behält Lose, um Stöße aufzunehmen",
    "q.l11#10.e" to "Die ersten drei sind Anforderungen, das letzte ist das Gegenteil. Ein Standplatz muss dehnungsfrei sein, nicht mit Reserve-Lose – Lose lässt einen Punktesausfall die anderen schockbelasten, und Schocklasten sind weit größer als statische.",

    "q.l11#11.p" to "Wenn die Verhältnisse nur einen einzigen Sicherungspunkt zulassen – wie geht man richtig vor?",
    "q.l11#11.o0" to "Den Aufstieg abbrechen und den Weg zurückgehen",
    "q.l11#11.o1" to "Ihn so zuverlässig wie möglich machen und die Zeit minimieren, die das System auf ihm verbringt",
    "q.l11#11.o2" to "Irgendeinen zweiten Punkt hinzufügen, um zwei zu haben",
    "q.l11#11.o3" to "Das Seil direkt am Gurt festbinden",
    "q.l11#11.e" to "Situationen mit nur einem Punkt gibt es wirklich – etwa einen guten Eishaken. Die ehrliche Haltung ist, zuzugeben, dass es keinen Spielraum gibt: diesen Punkt so gut wie möglich machen und Leute schnell darüber hinwegbringen, statt einen nutzlosen zweiten Punkt zu setzen, der falsches Vertrauen erzeugt.",

    // ---------- l12 Spaltenrettung ----------
    "q.l12#0.p" to "Ihr Partner stürzt in eine Gletscherspalte. Was ist der erste Schritt?",
    "q.l12#0.o0" to "Hinterherspringen",
    "q.l12#0.o1" to "In die Selbstbremsung gehen, einen Anker bauen und die Last darauf übertragen",
    "q.l12#0.o2" to "Zuerst Hilfe rufen",
    "q.l12#0.o3" to "Das Seil durchschneiden",
    "q.l12#0.e" to "Das volle Gewicht des Gestürzten liegt jetzt auf Ihnen. Erst bremsen, um sich zu halten, dann einen unabhängigen Anker bauen und die Last übertragen – erst dann haben Sie die Hände für das Rettungssystem frei. Hinterherspringen oder Durchschneiden verschlimmert alles sofort.",

    "q.l12#1.p" to "Welches mechanische System ist beim Ziehen zur Rettung am gebräuchlichsten?",
    "q.l12#1.o0" to "Direktes Ziehen 1:1",
    "q.l12#1.o1" to "Das 3:1-Z-System (Z-Flaschenzug)",
    "q.l12#1.o2" to "Ein 10:1-System",
    "q.l12#1.o3" to "Es wird keine Übersetzung gebraucht",
    "q.l12#1.e" to "Das 3:1-Z-System nutzt einen Prusik plus eine Umlenkrolle und gewinnt die dreifache Kraft. Es ist einfach, schnell gebaut und braucht wenig Material – deshalb ist es der Standard in der Spaltenrettung.",

    "q.l12#2.p" to "Warum sind Schneebrücken besonders gefährlich?",
    "q.l12#2.o0" to "Weil sie immer Geräusche machen",
    "q.l12#2.o1" to "Weil sie unter Neuschnee wie gewöhnlicher Boden aussehen und schwer zu erkennen sind",
    "q.l12#2.o2" to "Weil sie nur nachts auftreten",
    "q.l12#2.o3" to "Weil sie immer dünn sind",
    "q.l12#2.e" to "Eine Schneebrücke ist die am besten getarnte Gletschergefahr: Die Oberfläche wirkt glatt und mächtig, während darunter Hohlraum ist. Sie zu beurteilen heißt, Risslinien, Schneedeckenaufbau und Jahreszeit zu lesen – genau deshalb geht man angeseilt.",

    "q.l12#3.p" to "In welchem Zustand sollte das Seil beim Queren von Spaltengelände sein?",
    "q.l12#3.o0" to "Völlig locker für Bewegungsfreiheit",
    "q.l12#3.o1" to "Mäßig gespannt, ohne große durchhängende Schlaufen",
    "q.l12#3.o2" to "So stramm wie möglich",
    "q.l12#3.o3" to "Absichern ist unnötig",
    "q.l12#3.e" to "Lose lässt den Stürzenden erst frei fallen, bevor das Seil Last aufnimmt – das vervielfacht den Impuls und erhöht die Gefahr, dass das Seil in die Randlippe sägt. Mäßige Spannung lässt die Bremsung früher greifen und senkt dieses Risiko.",

    "q.l12#4.p" to "Wie quert man eine Schneebrücke am sichersten?",
    "q.l12#4.o0" to "Allein schnell hinüberlaufen",
    "q.l12#4.o1" to "Angeseilt mit gespanntem Seil gehen, einer quert, die anderen sind bremsbereit",
    "q.l12#4.o2" to "Jede Schneebrücke meiden",
    "q.l12#4.o3" to "Kräftig stampfen, um sie zu prüfen, dann queren",
    "q.l12#4.e" to "Eine Schneebrücke lässt sich nicht durch Hinsehen beurteilen. Angeseilt und bremsbereit zu sein verwandelt Unsicherheit in beherrschbares Risiko. Kräftiges Stampfen zum Prüfen kann sie einfach unter Ihnen zusammenbrechen lassen.",

    "q.l12#5.p" to "Während ein Partner im Inneren einer Spalte am Seil hängt – was ist die größte Gefahr?",
    "q.l12#5.o0" to "Dass der Partner dort unten einschläft",
    "q.l12#5.o1" to "Dass das belastete Seil die Schneekante durchsägt, bis sie plötzlich nachgibt",
    "q.l12#5.o2" to "Dass Ausrüstung abfällt",
    "q.l12#5.o3" to "Ein plötzlicher Wetterumschwung",
    "q.l12#5.e" to "Ein belastetes Seil schneidet vor und zurück über die Kante und gräbt eine immer tiefere Kerbe. Das ist die Hauptquelle des Zeitdrucks bei einer Rettung – Sie müssen ziehen oder die Last auf einen soliden Anker übertragen, bevor die Kante durchtrennt ist.",

    "q.l12#6.p" to "Warum ist beim Bau eines Z-Systems mit Prusiks eine Rückfallsicherung nötig?",
    "q.l12#6.o0" to "Damit das System vollständig aussieht",
    "q.l12#6.o1" to "Versagt der Hauptprusik, geht die Übersetzung sofort verloren und der Gestürzte fällt erneut",
    "q.l12#6.o2" to "Um die Reibung zu erhöhen",
    "q.l12#6.o3" to "Um Seil zu sparen",
    "q.l12#6.e" to "Ein Prusik greift durch Reibung, und Eis, Schmutz oder Seilabrieb können ihn überwinden. Ein Rückfallprusik fängt die Last, wenn der Hauptprusik versagt, und vermeidet einen zweiten Sturz samt zusätzlicher Verletzung und Verzögerung.",

    "q.l12#7.p" to "【Reihenfolge】Bringen Sie die Standardabfolge der Spaltenrettung in Ordnung.",
    "q.l12#7.o0" to "Sofort selbst bremsen und sich halten",
    "q.l12#7.o1" to "Einen unabhängigen Anker bauen",
    "q.l12#7.o2" to "Das Gewicht vom Körper auf den Anker übertragen",
    "q.l12#7.o3" to "Mit einem 3:1-System ziehen",
    "q.l12#7.e" to "Die vier Schritte lassen sich nicht umstellen. Schritt drei wird am häufigsten übersprungen: Ohne Lastübertragung müssen Sie den Partner mit dem Körper halten und haben keine Hände für das System – der häufigste Grund, warum Rettungen scheitern.",

    "q.l12#8.p" to "Was sollte die Person in der Spalte tun?",
    "q.l12#8.o0" to "Kräftig am Seil rütteln, um Aufmerksamkeit zu erregen",
    "q.l12#8.o1" to "Ruhig bleiben, versuchen hochzusteigen (Prusik) und vermeiden, dass das Seil weiter in die Kante sägt",
    "q.l12#8.o2" to "Sich sofort ausbinden",
    "q.l12#8.o3" to "Hinabklettern, um einen Ausweg zu suchen",
    "q.l12#8.e" to "Die Mitarbeit des Gestürzten macht die Rettung viel leichter. Am Seil zu rütteln verstärkt das Sägen, und Ausbinden trennt die einzige Verbindung. Ruhig bleiben, das Schneiden verringern und wo möglich etwas Gewicht auf einen Prusik nehmen.",

    "q.l12#9.p" to "【Mehrfachauswahl】Welche Rettungsmittel sollten am Gletscher am Körper und in Reichweite sein?",
    "q.l12#9.o0" to "Prusikkordel",
    "q.l12#9.o1" to "Karabiner und eine Umlenkrolle",
    "q.l12#9.o2" to "Ein Schneeanker oder Eishaken",
    "q.l12#9.o3" to "Schlingen",
    "q.l12#9.o4" to "Trekkingstöcke",
    "q.l12#9.e" to "Zusammen ergeben diese vier das improvisierte System: Prusikkordel für die Einwegklemmung, Karabiner und Rolle für die Übersetzung, Eishaken oder Anker für den Fixpunkt, Schlingen für Verbindung und Verlängerung. Entscheidend ist „in Reichweite“ – Ausrüstung ganz unten im Rucksack existiert praktisch nicht.",

    "q.l12#10.p" to "Warum muss die Last vor dem Ziehen auf den Anker übertragen werden?",
    "q.l12#10.o0" to "Um die Last gleichmäßiger auf das Seil zu verteilen",
    "q.l12#10.o1" to "Weil sonst die Hände mit dem Halten der Bremsung gebunden bleiben und das System nicht bedienen können",
    "q.l12#10.o2" to "Um Energie zu sparen",
    "q.l12#10.o3" to "Um das Seil zu schonen",
    "q.l12#10.e" to "Liegt das volle Gewicht des Gestürzten auf Ihnen, müssen Sie die Bremsung halten und können weder die Hände frei machen noch stabil arbeiten. Die Last an den Anker zu geben ist der einzige Weg, aufzuhören, menschlicher Anker zu sein, und Bediener zu werden.",

    "q.l12#11.p" to "Welche Rolle spielt der Prusik in einem Rettungssystem?",
    "q.l12#11.o0" to "Zierde",
    "q.l12#11.o1" to "Einwegklemmung – er hält unter Last und gleitet am Seil, wenn er frei ist",
    "q.l12#11.o2" to "Er erhöht die Seilfestigkeit",
    "q.l12#11.o3" to "Wasserdichtigkeit",
    "q.l12#11.e" to "Die Einwegklemmung macht ein mechanisches System überhaupt erst möglich: Der Prusik rückt am Seil vor, läuft aber unter Last nicht zurück. Seine Zuverlässigkeit hängt von Kordeldurchmesser und Windungszahl ab – testen Sie ihn, bevor Sie sich auf ihn verlassen.",

    // ---------- l13 Akute Höhenkrankheit (AMS) ----------
    "q.l13#0.p" to "Welches Symptom muss nach den Lake-Louise-Kriterien vorliegen, um eine AMS zu diagnostizieren?",
    "q.l13#0.o0" to "Kopfschmerz plus mindestens eines von Übelkeit, Schwindel, Erschöpfung oder Schlaflosigkeit",
    "q.l13#0.o1" to "Husten allein",
    "q.l13#0.o2" to "Muskelkater allein",
    "q.l13#0.o3" to "Verbesserter Appetit allein",
    "q.l13#0.e" to "Kopfschmerz ist das Kernsymptom der AMS. Erschöpfung oder Schlaflosigkeit allein genügen nicht; sie müssen mit Kopfschmerz zusammenkommen. Der praktische Wert der Kriterien liegt darin, dass man sich im Lager selbst einschätzen und danach handeln kann.",

    "q.l13#1.p" to "Wie reagiert man richtig, wenn AMS-Symptome auftreten?",
    "q.l13#1.o0" to "Ein Schmerzmittel nehmen und wie geplant weiter aufsteigen",
    "q.l13#1.o1" to "Nicht weiter aufsteigen; bei Verschlechterung sofort absteigen",
    "q.l13#1.o2" to "Mehr Kaffee für Energie trinken und weitergehen",
    "q.l13#1.o3" to "Ignorieren und durchhalten",
    "q.l13#1.e" to "Aus einer AMS kann eine tödliche HACE oder HAPE werden. Den Aufstieg zu stoppen gibt dem Körper Zeit zur Anpassung; sobald die Symptome schlimmer werden, ist der Abstieg die einzige sichere Behandlung. Jeder Plan zum Durchhalten ist eine Wette mit dem Leben.",

    "q.l13#2.p" to "Der Kopfschmerz ist nach einem Schmerzmittel weg. Dürfen Sie weiter aufsteigen?",
    "q.l13#2.o0" to "Ja, das Symptom ist verschwunden",
    "q.l13#2.o1" to "Nein – ein unterdrücktes Symptom bedeutet nicht, dass der Körper akklimatisiert ist",
    "q.l13#2.o2" to "Ja, aber langsamer gehen",
    "q.l13#2.o3" to "Ja, wenn Sie mehr Wasser trinken",
    "q.l13#2.e" to "Ein Schmerzmittel unterdrückt das Signal; die physiologische Belastung durch die Höhe besteht weiter. Wer unter diesem Deckmantel aufsteigt, lässt eine AMS ohne Warnung in eine HACE oder HAPE übergehen.",

    "q.l13#3.p" to "Wie lange nach der Ankunft in der Höhe treten AMS-Symptome meist auf?",
    "q.l13#3.o0" to "Sofort",
    "q.l13#3.o1" to "6–12 Stunden",
    "q.l13#3.o2" to "Nach drei Tagen",
    "q.l13#3.o3" to "Nach einer Woche",
    "q.l13#3.e" to "Der Zeitpunkt ist wichtig: Die Symptome beginnen oft, nachdem man das Lager erreicht, zu Abend gegessen und sich zum Schlafen gerichtet hat – und nachts werden sie am leichtesten übersehen und am ehesten schlimmer.",

    "q.l13#4.p" to "Wie behandelt man eine leichte AMS im Feld richtig?",
    "q.l13#4.o0" to "Wie geplant weiter aufsteigen",
    "q.l13#4.o1" to "Nicht weiter an Höhe gewinnen, auf der aktuellen Höhe ruhen und bei Fortbestehen oder Verschlechterung absteigen",
    "q.l13#4.o2" to "Ein Schmerzmittel nehmen und weiter aufsteigen",
    "q.l13#4.o3" to "Sofort 2.000 m absteigen",
    "q.l13#4.e" to "Bei leichter AMS ist die erste Wahl, den Aufstieg zu stoppen und dem Körper Zeit zu geben. Ein Schmerzmittel lindert den Kopfschmerz, ändert aber nichts an der Akklimatisierung. Bleiben die Symptome nach der Ruhe oder werden schlimmer, ist der Abstieg die sichere Behandlung.",

    "q.l13#5.p" to "Warum verbessert „hoch steigen, tief schlafen“ die Akklimatisierung?",
    "q.l13#5.o0" to "Weil es tagsüber wärmer ist",
    "q.l13#5.o1" to "Die Hypoxie am Tag liefert den Reiz, während das Zurückgehen zum Schlafen die Schlafqualität schützt",
    "q.l13#5.o2" to "Weil man weniger Ausrüstung trägt",
    "q.l13#5.o3" to "Weil Gehen bei Nacht sicherer ist",
    "q.l13#5.e" to "Akklimatisierung braucht hypoxischen Reiz, aber auch Schlafqualität ist Voraussetzung – schwere nächtliche Hypoxie verstärkt periodische Atmung und Symptome. „Hoch steigen, tief schlafen“ bringt beides zusammen, deshalb wirkt es besser, als durchgehend oben zu bleiben.",

    "q.l13#6.p" to "Was ist die schlimmste Folge, wenn man mit einer AMS weiter aufsteigt?",
    "q.l13#6.o0" to "Man fühlt sich etwas müder",
    "q.l13#6.o1" to "Der Übergang in HACE oder HAPE, die innerhalb von Stunden lebensbedrohlich sein können",
    "q.l13#6.o2" to "Weniger Appetit",
    "q.l13#6.o3" to "Schlechterer Schlaf",
    "q.l13#6.e" to "Eine AMS beruhigt sich meist mit Ruhe oder Abstieg, kann aber der Vorläufer einer kritischen Erkrankung sein. Genau deshalb wird „nicht mit Symptomen aufsteigen“ so oft wiederholt – es blockiert das erste Glied der ganzen Verschlechterungskette.",

    "q.l13#7.p" to "Worauf achtet man am meisten, wenn man beurteilt, ob eine AMS schlimmer wird?",
    "q.l13#7.o0" to "Ob der Kopfschmerz weg ist",
    "q.l13#7.o1" to "Ob die Symptome fortschreitend schlimmer werden, besonders Bewusstsein, Gang und Atmung",
    "q.l13#7.o2" to "Ob die Körpertemperatur normal ist",
    "q.l13#7.o3" to "Ob der Sauerstoffwert gestiegen ist",
    "q.l13#7.e" to "Der Umschlag von AMS zu HACE/HAPE zeigt sich in drei Dimensionen: Bewusstsein, Gang und Atmung. Diese drei zu beobachten ist zuverlässiger als ein einzelnes Symptom oder eine Oxymeterzahl.",

    "q.l13#8.p" to "Was ist für den Kopfschmerz bei AMS typisch?",
    "q.l13#8.o0" to "Er ist meist das erste Symptom",
    "q.l13#8.o1" to "Er tritt nur nachts auf",
    "q.l13#8.o2" to "Er tritt nur bei Anstrengung auf",
    "q.l13#8.o3" to "Er ist meist das letzte Symptom",
    "q.l13#8.e" to "Kopfschmerz ist oft das früheste Signal und ein Pflichtelement der Lake-Louise-Kriterien. Weil er so häufig ist, wird er leicht als gewöhnliche Müdigkeit abgetan – entscheidend ist der Kontext: Er trat nach dem Höhengewinn auf.",

    "q.l13#9.p" to "Welches Schema empfiehlt das Lehrbuch für Acetazolamid zur Vorbeugung von Höhenkrankheit?",
    "q.l13#9.o0" to "250 mg dreimal täglich",
    "q.l13#9.o1" to "125 mg zweimal täglich, Beginn etwa einen Tag vor dem Aufstieg, Ende etwa zwei Tage danach",
    "q.l13#9.o2" to "500 mg einmal täglich",
    "q.l13#9.o3" to "Erst nach Auftreten von Symptomen",
    "q.l13#9.e" to "Nach neueren medizinischen Empfehlungen liegt die Dosis bei 125 mg zweimal täglich – niedriger als die ältere Angabe 250 mg dreimal täglich. Die niedrigere Dosis wirkt und verursacht seltener starke Nebenwirkungen. Es ist verschreibungspflichtig und nur nach ärztlicher Anweisung anzuwenden.",

    "q.l13#10.p" to "Warum ist Symptomfreiheit nach Medikamenten kein Grund, weiter aufzusteigen?",
    "q.l13#10.o0" to "Weil das Medikament eine Illusion erzeugt",
    "q.l13#10.o1" to "Weil das Medikament Symptome lindert, aber die Anpassung an den Sauerstoffmangel nicht verbessert",
    "q.l13#10.o2" to "Weil das Medikament aufhört zu wirken",
    "q.l13#10.o3" to "Weil die Dosis ständig erhöht werden muss",
    "q.l13#10.e" to "Das ist der wichtigste Gedanke in der Behandlung von Höhenkrankheit: Das Symptom ist der Alarm, nicht die Krankheit. Das Medikament bringt den Alarm zum Schweigen, während die physiologische Belastung durch die Hypoxie weiter wächst – wer darunter aufsteigt, lässt die Krankheit still voranschreiten.",

    "q.l13#11.p" to "【Mehrfachauswahl】Welche Zustände werden leicht mit AMS verwechselt und müssen sorgfältig abgegrenzt werden?",
    "q.l13#11.o0" to "Dehydratation",
    "q.l13#11.o1" to "Infekte der oberen Atemwege, etwa eine Erkältung",
    "q.l13#11.o2" to "Übermüdung",
    "q.l13#11.o3" to "Schlafmangel",
    "q.l13#11.o4" to "Schneeblindheit (Ultraviolett-Keratitis)",
    "q.l13#11.e" to "Alle vier verursachen Kopfschmerz, Müdigkeit, Übelkeit oder schlechten Schlaf – stark überlappend mit AMS. Nützliche Unterscheidungsmerkmale sind, ob die Symptome mit dem Höhengewinn auftraten, ob sie sich mit Ruhe bessern und ob sich Gang oder Bewusstsein verändert haben.",

    "q.l13#12.p" to "Wie viele Menschen über 4.000 m erkranken nach klinischen und Führerangaben etwa an akuter Höhenkrankheit?",
    "q.l13#12.o0" to "5–10 %",
    "q.l13#12.o1" to "20–30 %",
    "q.l13#12.o2" to "50–65 %",
    "q.l13#12.o3" to "Fast 100 %",
    "q.l13#12.e" to "Je höher und schneller man aufsteigt, desto häufiger: Über 4.000 m erkranken etwa 50–65 %, und Studien zwischen 2.500 und 4.300 m nennen rund 25–43 %. Höhenkrankheit ist also normal, nicht die Ausnahme – deshalb ist ein geplanter Akklimatisierungsplan Notwendigkeit, nicht Vorsichtigkeit.",

    "q.l13#13.p" to "Welche Aussage über Alter und Höhenkrankheitsrisiko ist richtig?",
    "q.l13#13.o0" to "Junge Menschen bekommen keine Höhenkrankheit",
    "q.l13#13.o1" to "Je älter, desto höher muss das Risiko sein",
    "q.l13#13.o2" to "Das Alter erhöht das Risiko nicht wesentlich; entscheidend sind Aufstiegsgeschwindigkeit und Schlafhöhe",
    "q.l13#13.o3" to "Nur Untrainierte bekommen sie",
    "q.l13#13.e" to "Studien zeigen, dass ältere Trekker in mittleren Höhen (im Mittel 65 Jahre) ähnliche Raten haben wie jüngere. Was das Risiko tatsächlich bestimmt, sind Aufstiegsgeschwindigkeit, Schlafhöhe und individuelle Physiologie – Alter oder Fitness verantwortlich zu machen, ist eine gefährliche Fehleinschätzung.",

    // ---------- l14 HACE und HAPE ----------
    "q.l14#0.p" to "Welche Zeichen sollten bei HACE Alarm auslösen?",
    "q.l14#0.o0" to "Unsicherer Gang (kann nicht geradeaus gehen) und verändertes Bewusstsein",
    "q.l14#0.o1" to "Ein leichter Kopfschmerz",
    "q.l14#0.o2" to "Etwas schlechter Appetit",
    "q.l14#0.o3" to "Leichtes Ziehen in den Beinen",
    "q.l14#0.e" to "Ataxie und verändertes Bewusstsein sind die Kernzeichen einer HACE: Das Hirnödem beeinträchtigt bereits Bewegung und Kognition. Bei diesen Zeichen müssen Sie sofort absteigen und medizinische Unterstützung suchen – kein weiteres Abwarten.",

    "q.l14#1.p" to "Was ist das typischste Frühzeichen einer HAPE?",
    "q.l14#1.o0" to "Atemnot in Ruhe mit starkem Abfall der Leistungsfähigkeit",
    "q.l14#1.o1" to "Eine etwas laufende Nase",
    "q.l14#1.o2" to "Leichtes Taubheitsgefühl in den Fingern",
    "q.l14#1.o3" to "Durst",
    "q.l14#1.e" to "Charakteristisch für HAPE ist Atemnot schon in Ruhe. Anders als einfache Erschöpfung bessert sie sich nicht mit Ruhe, sondern verschlechtert sich weiter und kann zu schaumigem Auswurf und Zyanose führen – ein Signal zum sofortigen Abstieg.",

    "q.l14#2.p" to "Was ist die grundlegende Behandlung von HACE und HAPE?",
    "q.l14#2.o0" to "Ein Schmerzmittel nehmen und weiter aufsteigen",
    "q.l14#2.o1" to "Sofort auf geringere Höhe absteigen, mit Sauerstoff und weiteren unterstützenden Maßnahmen",
    "q.l14#2.o2" to "Zwei Tage am Ort ruhen",
    "q.l14#2.o3" to "Mehr trinken und mehr schlafen",
    "q.l14#2.e" to "Der Abstieg ist die einzige Maßnahme, die die Krankheit zuverlässig umkehrt, weil sie die Ursache beseitigt: die Hypoxie. Sauerstoff, eine Überdruckkammer und Medikamente sind Ergänzungen, die Zeit gewinnen, wenn der Abstieg nicht sofort beginnen kann.",

    "q.l14#3.p" to "Welches Dexamethason-Schema nennen klinische Quellen üblicherweise zur Behandlung einer HACE?",
    "q.l14#3.o0" to "Zunächst 8–10 mg, dann 4 mg alle 6 Stunden",
    "q.l14#3.o1" to "2 mg einmal täglich",
    "q.l14#3.o2" to "10 mg alle 2 Stunden",
    "q.l14#3.o3" to "Nur wenn der Patient bewusstlos ist",
    "q.l14#3.e" to "Das ist eine Behandlungsdosis und muss unter medizinischer Aufsicht gegeben werden. Das Medikament gewinnt Zeit für den Abstieg; es ersetzt ihn nie. Der Abstieg bleibt die grundlegende Behandlung von HACE und HAPE.",

    "q.l14#4.p" to "Wie häufig treten HAPE und HACE etwa gemeinsam auf?",
    "q.l14#4.o0" to "Fast nie",
    "q.l14#4.o1" to "Etwa 13–20 % der HAPE-Fälle entwickeln auch eine HACE",
    "q.l14#4.o2" to "In 100 % der Fälle",
    "q.l14#4.o3" to "Nur bei Kindern",
    "q.l14#4.e" to "Die Zahl zeigt, dass die beiden kritischen Formen der Höhenkrankheit oft zusammen auftreten. Wenn ein Mitglied Zeichen eines Lungenödems zeigt, beobachten Sie deshalb auch Bewusstsein und Gang, bereiten Sie sich auf das Schlimmste vor und steigen Sie sofort ab.",

    "q.l14#5.p" to "Wenn ein Gruppenmitglied nicht mehr gehen kann, was hat Priorität?",
    "q.l14#5.o0" to "Ermutigen, weiterzugehen",
    "q.l14#5.o1" to "Einen Trage-Transport organisieren, Sauerstoff geben, Überdruckkammer erwägen und so schnell wie möglich absteigen",
    "q.l14#5.o2" to "Am Ort ruhen und auf Erholung warten",
    "q.l14#5.o3" to "Zuerst ins Lager zurückgehen und Ausrüstung holen",
    "q.l14#5.e" to "Der Verlust der Gehfähigkeit bedeutet eine kritische Erkrankung. Der Abstieg hängt dann davon ab, dass die Gruppe den Patienten trägt, oder von externer Rettung – die eigentliche Sicherheitsstrategie ist also, niemanden je so weit kommen zu lassen. Genau darin liegt der Wert der frühen AMS-Erkennung.",

    "q.l14#6.p" to "Was leistet eine tragbare Überdruckkammer (etwa ein Gamow Bag)?",
    "q.l14#6.o0" to "Sie heilt die Höhenkrankheit vollständig",
    "q.l14#6.o1" to "Sie simuliert eine geringere Höhe und stabilisiert den Patienten, wenn ein sofortiger Abstieg unmöglich ist",
    "q.l14#6.o2" to "Sie ersetzt den Abstieg",
    "q.l14#6.o3" to "Sie wärmt vor allem",
    "q.l14#6.e" to "Eine Überdruckkammer gewinnt Zeit; sie ist nicht das Ende der Behandlung. Sie kann die Krankheit bei schlechtem Wetter, beim Warten auf einen Hubschrauber oder wenn der Abstieg nicht sofort beginnt, in Schach halten – aber am Ende ist der Abstieg weiterhin nötig.",

    "q.l14#7.p" to "Wie ist die richtige Haltung zu Medikamenten gegen Höhenkrankheit?",
    "q.l14#7.o0" to "Wenn die Symptome nachlassen, weiter aufsteigen",
    "q.l14#7.o1" to "Sie sind eine Ergänzung, die Zeit gewinnt, werden nach ärztlichem Rat eingesetzt und ersetzen nie den Abstieg",
    "q.l14#7.o2" to "Sie dürfen frei unter Kameraden geteilt werden",
    "q.l14#7.o3" to "Je früher, desto besser, ohne medizinische Abklärung",
    "q.l14#7.e" to "Diese Medikamente haben bestimmte Indikationen, Kontraindikationen und Nebenwirkungen, und unter ihrem Deckmantel aufzusteigen verbirgt die Zeichen der Verschlechterung. Der Maßstab ist: Einsatz nach ärztlicher Beurteilung, mit dem Abstieg als grundlegender Behandlung.",

    "q.l14#8.p" to "Welche Dexamethason-Dosis ist bei Höhenhirnödem üblich?",
    "q.l14#8.o0" to "20 mg alle 12 Stunden",
    "q.l14#8.o1" to "4 mg alle 6 Stunden",
    "q.l14#8.o2" to "8 mg einmal täglich",
    "q.l14#8.o3" to "10 mg alle 2 Stunden",
    "q.l14#8.e" to "Das Lehrbuch nennt 4 mg alle 6 Stunden. Es senkt den Hirndruck und lindert das Hirnödem, meist mit klarer Besserung innerhalb von sechs Stunden – aber es gewinnt nur Zeit für den Abstieg und ersetzt ihn nie.",

    "q.l14#9.p" to "Behandelt Dexamethason ein Höhenlungenödem?",
    "q.l14#9.o0" to "Ja, es ist das Mittel der ersten Wahl",
    "q.l14#9.o1" to "Nein, es hat keine therapeutische Wirkung auf das Lungenödem",
    "q.l14#9.o2" to "Ja, aber die Dosis muss verdoppelt werden",
    "q.l14#9.o3" to "Es wirkt nur bei Kindern",
    "q.l14#9.e" to "Das wird leicht verwechselt: Dexamethason zielt auf das Hirnödem und wirkt beim Lungenödem nicht, während Nifedipin auf das Lungenödem zielt und beim Hirnödem begrenzt wirkt. Die beiden kritischen Krankheitsbilder brauchen unterschiedliche Medikamente – das falsche ist keine Behandlung.",

    "q.l14#10.p" to "Für das Höhenlungenödem: Welches Nifedipin-Schema wird empfohlen, und welche wichtige Nebenwirkung hat es?",
    "q.l14#10.o0" to "20–30 mg Retardtablette alle 12 Stunden; der Blutdruck kann schnell fallen, sodass schnelles Aufstehen zu Ohnmacht führen kann",
    "q.l14#10.o1" to "4 mg alle 6 Stunden; es macht schläfrig",
    "q.l14#10.o2" to "125 mg einmal täglich; es erhöht den Blutdruck",
    "q.l14#10.o3" to "Nur intravenös; keine Nebenwirkungen",
    "q.l14#10.e" to "Nifedipin löst die hypoxische Lungenvasokonstriktion und wird zur Vorbeugung und Behandlung des Lungenödems eingesetzt. Die Nebenwirkung ist sehr praktisch: Der Blutdruck kann schnell fallen, sodass Aufstehen aus dem Sitzen oder Liegen Ohnmacht auslösen kann – besonders gefährlich am Steilhang oder beim nächtlichen Verlassen des Zelts.",

    "q.l14#11.p" to "Wie soll Dexamethason einem Höhenkranken gegeben werden, der sich ständig erbricht?",
    "q.l14#11.o0" to "Oral, in höherer Dosis",
    "q.l14#11.o1" to "Es muss injiziert werden",
    "q.l14#11.o2" to "Unter die Zunge",
    "q.l14#11.o3" to "Es kann nicht gegeben werden; einfach abwarten",
    "q.l14#11.e" to "Anhaltendes Erbrechen bedeutet, dass orale Medikamente nicht aufgenommen und womöglich einfach ausgebrochen werden. Das Lehrbuch stellt klar, dass injiziert werden muss – ein Hinweis darauf, dass die Applikationsform in jedem Höhennotfallplan vorab mitgedacht werden muss.",

    // ---------- l15 Akklimatisierung planen ----------
    "q.l15#0.p" to "Um wie viel darf die Schlafhöhe über 3.000 m pro Tag steigen?",
    "q.l15#0.o0" to "Nicht mehr als 500 m",
    "q.l15#0.o1" to "Nicht mehr als 1.500 m",
    "q.l15#0.o2" to "So schnell wie möglich",
    "q.l15#0.o3" to "Es gibt keine Grenze",
    "q.l15#0.e" to "Den täglichen Anstieg der Schlafhöhe auf 500 m zu begrenzen und etwa alle 1.000 m einen Ruhetag einzulegen, ist die Grundempfehlung internationaler Leitlinien. Sie gibt dem Körper Zeit zum Ausgleich. (Quellen nennen Werte zwischen 300 und 700 m; dieser Kurs verwendet eine der gebräuchlicheren Angaben.)",

    "q.l15#1.p" to "Was bedeutet „hoch steigen, tief schlafen“?",
    "q.l15#1.o0" to "Tagsüber höher gehen und zum Schlafen auf geringere Höhe zurückkehren",
    "q.l15#1.o1" to "Tagsüber ruhen und nachts gehen",
    "q.l15#1.o2" to "Durchgehend auf derselben Höhe bleiben",
    "q.l15#1.o3" to "Nur am höchsten Punkt schlafen",
    "q.l15#1.e" to "Die Exposition in der Höhe am Tag regt die Bildung roter Blutkörperchen und die Atemanpassung an, während die Rückkehr zum Schlafen Symptome lindert und die Schlafqualität schützt. Beides zu verbinden ist der effizienteste Weg zu akklimatisieren.",

    "q.l15#2.p" to "Was erhöht die Belastung der Akklimatisierung?",
    "q.l15#2.o0" to "Ausreichend Wasser trinken",
    "q.l15#2.o1" to "Alkohol oder sedierende Medikamente",
    "q.l15#2.o2" to "Überwiegend Kohlenhydrate essen",
    "q.l15#2.o3" to "Ausreichend schlafen",
    "q.l15#2.e" to "Alkohol und Sedativa dämpfen den Atemantrieb und verstärken nächtliche periodische Atmung und Hypoxie, was das Krankheitsrisiko deutlich erhöht. In der Höhe ist die Qualität der Atmung im Schlaf selbst Teil der Akklimatisierung.",

    "q.l15#3.p" to "Wozu dient die Kontrolle der Sauerstoffsättigung mit einem Pulsoximeter?",
    "q.l15#3.o0" to "Sie kann die Symptombeurteilung vollständig ersetzen",
    "q.l15#3.o1" to "Sie liefert eine objektive Referenz, besonders für Menschen mit früherer Höhenkrankheit",
    "q.l15#3.o2" to "Nur zur Dokumentation",
    "q.l15#3.o3" to "Sie hat keinen praktischen Wert",
    "q.l15#3.e" to "Die Sättigung ist eine nützliche Referenz, aber die individuelle Streuung ist groß und sie darf nicht die einzige Entscheidungsgrundlage sein. Symptome und Funktionszustand – kann die Person geradeaus gehen, ist sie handlungsfähig – bleiben das Hauptkriterium.",

    "q.l15#4.p" to "Welche vorbeugenden Medikamente könnte ein Arzt für Menschen mit hohem HAPE-Risiko erwägen?",
    "q.l15#4.o0" to "Nifedipin oder Sildenafil (ein PDE-Hemmer)",
    "q.l15#4.o1" to "Breitbandantibiotika",
    "q.l15#4.o2" to "Gewöhnliche Schmerzmittel",
    "q.l15#4.o3" to "Vitaminpräparate",
    "q.l15#4.e" to "Beide Gruppen senken den Pulmonalisdruck und werden bei Risikopersonen nach ärztlicher Beurteilung zur HAPE-Vorbeugung eingesetzt. Sie wirken an einer anderen Stelle als Acetazolamid und können es nicht ersetzen.",

    "q.l15#5.p" to "Warum ist zu schnelles Aufsteigen einer der stärksten Risikofaktoren für Höhenkrankheit?",
    "q.l15#5.o0" to "Weil es anstrengend ist",
    "q.l15#5.o1" to "Weil der Körper keine Zeit hat, Atemanpassung und vermehrte rote Blutkörperchen zu entwickeln",
    "q.l15#5.o2" to "Weil man mehr Gewicht trägt",
    "q.l15#5.o3" to "Weil das Wetter im Gebirge schnell wechselt",
    "q.l15#5.e" to "Akklimatisierung ist die Anhäufung einer Reihe physiologischer Kompensationen und braucht Zeit in Tagen. Läuft der Aufstieg der Kompensation davon, zeigt sich die Lücke als Symptome – daher stammt jede Empfehlung zur Aufstiegsgeschwindigkeit.",

    "q.l15#6.p" to "Was bewirkt ausreichendes Trinken für die Akklimatisierung?",
    "q.l15#6.o0" to "Es löscht nur den Durst",
    "q.l15#6.o1" to "Es erhält Kreislauf und Stoffwechsel; Dehydratation verschlechtert die Symptome deutlich",
    "q.l15#6.o2" to "Es verhindert ein Lungenödem",
    "q.l15#6.o3" to "Es ersetzt vorbeugende Medikamente",
    "q.l15#6.e" to "Trockene Luft und schnellere Atmung in der Höhe erhöhen den Flüssigkeitsverlust deutlich, und Dehydratation verdickt das Blut, was das Gefühl von Sauerstoffmangel und den Kopfschmerz verstärkt. Ebenso gilt: nicht übertrinken – gleichmäßig und ausreichend ist das Ziel.",

    "q.l15#7.p" to "Warum Überanstrengung in der Höhe meiden?",
    "q.l15#7.o0" to "Weil man schnell müde wird",
    "q.l15#7.o1" to "Überanstrengung kann ein HAPE auslösen, besonders vor der Akklimatisierung",
    "q.l15#7.o2" to "Weil sie Dehydratation verursacht",
    "q.l15#7.o3" to "Weil sie die Gruppe aufhält",
    "q.l15#7.e" to "Harte Anstrengung treibt den Pulmonalisdruck höher und ist bei noch nicht akklimatisierten Menschen ein klarer Auslöser für HAPE. Das Tempo zu kontrollieren dient nicht nur dem Energiesparen; es senkt das Krankheitsrisiko.",

    "q.l15#8.p" to "Wann beginnt und endet die Einnahme von Acetazolamid?",
    "q.l15#8.o0" to "Bei Ankunft in der Höhe beginnen und nach der Akklimatisierung beenden",
    "q.l15#8.o1" to "Etwa einen Tag vor dem Aufstieg beginnen und etwa zwei Tage danach beenden",
    "q.l15#8.o2" to "Durchgehend für die ganze Reise",
    "q.l15#8.o3" to "Erst nach Auftreten von Symptomen",
    "q.l15#8.e" to "Einen Tag früher zu beginnen heißt, dass das Medikament beim Aufstieg bereits wirkt; etwa zwei Tage nach dem Aufstieg zu beenden, weil der Körper begonnen hat, sich selbst anzupassen. Acetazolamid beschleunigt die Akklimatisierung, ersetzt sie aber nicht.",

    "q.l15#9.p" to "Führt das Absetzen von Acetazolamid zu einem Wiederaufflammen der Symptome?",
    "q.l15#9.o0" to "Ja, die Dosis muss ausgeschlichen werden",
    "q.l15#9.o1" to "Nein, die Akklimatisierung kehrt einfach zu ihrer normalen Geschwindigkeit zurück",
    "q.l15#9.o2" to "Ja, die Symptome kommen doppelt zurück",
    "q.l15#9.o3" to "Das hängt von der Höhe ab",
    "q.l15#9.e" to "Das Lehrbuch stellt klar, dass das Absetzen kein Wiederaufflammen verursacht – die Akklimatisierung kehrt nur zu ihrem normalen Tempo zurück. Das ist wichtig: Es zeigt, dass das Medikament nichts unterdrückt, sondern den Prozess eine Zeit lang beschleunigt.",

    "q.l15#10.p" to "Wie wird Aspirin zur Linderung von Höhenkopfschmerz eingesetzt?",
    "q.l15#10.o0" to "500 mg einmal, nachdem der Kopfschmerz begonnen hat",
    "q.l15#10.o1" to "Einen Tag vor dem Aufstieg beginnen, 320 mg dreimal täglich, bis die Akklimatisierung abgeschlossen ist",
    "q.l15#10.o2" to "100 mg einmal täglich",
    "q.l15#10.o3" to "Nur zur Schlafenszeit",
    "q.l15#10.e" to "Das ist vorbeugender Einsatz statt „nehmen, wenn es weh tut“: früh beginnen, regelmäßig dosieren, bis der Akklimatisierungsprozess abgeschlossen ist. Beachten Sie, dass Aspirin Magen-Darm- und Blutungsrisiken birgt – es ist eine medizinische Entscheidung und sollte ärztlich beurteilt werden.",

    "q.l15#11.p" to "Wie ist die richtige Sicht auf Ginkgo-Extrakt zur Vorbeugung von Höhenkrankheit?",
    "q.l15#11.o0" to "Es wirkt besser als Acetazolamid und kann es ersetzen",
    "q.l15#11.o1" to "Es hat eine gewisse vorbeugende Wirkung, aber kontrollierte Studien zeigen eine deutlich geringere Wirksamkeit als Acetazolamid",
    "q.l15#11.o2" to "Es ist völlig unwirksam",
    "q.l15#11.o3" to "Es wirkt nur bei Hirnödem",
    "q.l15#11.e" to "Das Lehrbuch ist vorsichtig: Einige Studien zeigen Symptomlinderung, doch Dosen und Bedingungen schwanken zu stark für eine verlässliche Dosierung, und direkte Vergleichsstudien zeigen eine viel schwächere Wirkung als Acetazolamid. Beachten Sie außerdem die Wechselwirkung mit gerinnungshemmenden Medikamenten.",

    // ---------- l16 Unterkühlung und Erfrierung ----------
    "q.l16#0.p" to "Was bedeutet es, wenn das Zittern aufhört?",
    "q.l16#0.o0" to "Der Körper hat sich an die Kälte angepasst",
    "q.l16#0.o1" to "Die Unterkühlung verschlechtert sich – ein Warnzeichen",
    "q.l16#0.o2" to "Man kann weitergehen",
    "q.l16#0.o3" to "Man muss sofort Wasser trinken",
    "q.l16#0.e" to "Zittern ist das letzte Mittel des Körpers zur Wärmebildung. Hört es auf, ist die Wärmeproduktion gescheitert und die Kerntemperatur fällt schneller – die entscheidende Grenze zwischen leichter und mittelschwerer bis schwerer Unterkühlung und ein Grund, sofort zu handeln.",

    "q.l16#1.p" to "Wie werden Erfrierungen im Feld richtig wiedererwärmt?",
    "q.l16#1.o0" to "Die Stelle mit Schnee einreiben",
    "q.l16#1.o1" to "In Wasser von 37–40 °C etwa 30 Minuten eintauchen, bis die Haut rot und weich wird",
    "q.l16#1.o2" to "Am Feuer wärmen",
    "q.l16#1.o3" to "Eine Wärmflasche direkt auflegen",
    "q.l16#1.e" to "Erfrorenes Gewebe enthält Eiskristalle, und Reiben verursacht sekundären Zellschaden; starke Hitze verbrennt die gefühllose Haut. Schnelles Wiedererwärmen in warmem Wasser ist die einzige Standardmethode – die unverletzte Hand oder die Achselhöhle dienen als Notlösung.",

    "q.l16#2.p" to "Wann sollte eine Erfrierung im Feld nicht wiedererwärmt werden?",
    "q.l16#2.o0" to "Jede Erfrierung immer wiedererwärmen",
    "q.l16#2.o1" to "Wenn die Gefahr des Wiedererfrierens besteht, weil Auftauen–Erfrieren–Auftauen größeren Schaden verursacht",
    "q.l16#2.o2" to "Tagsüber nie wiedererwärmen",
    "q.l16#2.o3" to "Nur leichte Erfrierungen sollten wiedererwärmt werden",
    "q.l16#2.e" to "Ein Zyklus aus Auftauen und Wiedererfrieren zerstört weit mehr Gewebe als das Erfrorenbleiben. Ist weitere Kälteexposition wahrscheinlich und Wärme nicht zu gewährleisten, schützen Sie die Stelle, vermeiden Reibung und steigen ab, wo dauerhafte Wärme möglich ist – erst dort wiedererwärmen.",

    "q.l16#3.p" to "Warum bei mittelschwerer oder schwerer Unterkühlung keine heftigen Gliedmaßenbewegungen?",
    "q.l16#3.o0" to "Weil es Energie verbraucht",
    "q.l16#3.o1" to "Weil der kalte Herzmuskel leicht in eine Rhythmusstörung gerät",
    "q.l16#3.o2" to "Weil der Patient dadurch gereizt wird",
    "q.l16#3.o3" to "Weil es die Erfrierung verschlechtert",
    "q.l16#3.e" to "Das ist der am wenigsten intuitive Punkt in der Unterkühlungsversorgung: Den Patienten gehen zu lassen ist oft tödlich. Im kalten Herzen ist der Herzmuskel hoch reizbar, und plötzliche Bewegung der Gliedmaßen oder grobe Handhabung können unmittelbar Kammerflimmern auslösen.",

    "q.l16#4.p" to "Welche Wassertemperatur ist zum Wiedererwärmen einer Erfrierung richtig?",
    "q.l16#4.o0" to "0–5 °C",
    "q.l16#4.o1" to "20–25 °C",
    "q.l16#4.o2" to "37–40 °C",
    "q.l16#4.o3" to "Über 60 °C",
    "q.l16#4.e" to "Zu kühl und die Wiedererwärmung scheitert; zu heiß und die gefühllose Haut verbrennt. 37–40 °C schmelzen die Eiskristalle schnell, ohne thermischen Schaden. Die Wiedererwärmung ist sehr schmerzhaft und braucht Schmerzbehandlung.",

    "q.l16#5.p" to "Warum bei Unterkühlung zuerst der Rumpf und dann die Gliedmaßen erwärmt werden?",
    "q.l16#5.o0" to "Weil die Gliedmaßen keine Rolle spielen",
    "q.l16#5.o1" to "Weil das Erwärmen der Gliedmaßen kaltes peripheres Blut zum Kern zurückschickt und die Kerntemperatur weiter senkt",
    "q.l16#5.o2" to "Weil der Rumpf leichter zu behandeln ist",
    "q.l16#5.o3" to "Weil die Gliedmaßen schon erfroren sein können",
    "q.l16#5.e" to "Das ist einer der Kernprinzipien der Unterkühlungsversorgung. Behandelt man zuerst die Gliedmaßen, strömt kaltes peripheres Blut in den Kern zurück, kann die Kerntemperatur weiter senken und Rhythmusstörungen auslösen – erst der Kern, dann die Gliedmaßen.",

    "q.l16#6.p" to "Wie behandelt man eine leichte Unterkühlung im Feld?",
    "q.l16#6.o0" to "Sofort ins Krankenhaus bringen",
    "q.l16#6.o1" to "Aus Wind und Kälte gehen, nasse Kleidung wechseln, Wärme zuführen und die Verschlechterung weiter beobachten",
    "q.l16#6.o2" to "Weitergehen lassen, um Wärme zu erzeugen",
    "q.l16#6.o3" to "Den Körper mit Schnee einreiben, um die Durchblutung anzuregen",
    "q.l16#6.e" to "Ein leicht unterkühlter Mensch kann noch Wärme erzeugen, deshalb ist das Wichtigste, weiteren Wärmeverlust zu stoppen und Energie zuzuführen. Aber beobachten Sie weiter: Dass das Zittern aufhört, ist meist ein Zeichen des Übergangs in mittelschwere Unterkühlung, nicht der Besserung.",

    "q.l16#7.p" to "Darf man eine Wärmflasche direkt auf erfrorenes Gewebe legen?",
    "q.l16#7.o0" to "Ja, je schneller die Wiedererwärmung, desto besser",
    "q.l16#7.o1" to "Nein – gefühllose Haut verbrennt leicht; nur Wasser von 37–40 °C verwenden",
    "q.l16#7.o2" to "Ja, wenn sie in ein Handtuch gewickelt ist",
    "q.l16#7.o3" to "Ja, solange die Temperatur nicht zu hoch ist",
    "q.l16#7.e" to "Erfrorene Haut hat Schmerz- und Temperaturempfinden verloren und kann nicht signalisieren, dass etwas zu heiß ist. Eine direkte Wärmequelle fügt leicht eine Verbrennung hinzu und kann Gewebe zerstören, das sich sonst vielleicht erholt hätte.",

    "q.l16#8.p" to "【Mehrfachauswahl】Was ist bei der Ersten Hilfe bei Unterkühlung falsch?",
    "q.l16#8.o0" to "Dem Patienten Alkohol geben, um ihn aufzuwärmen",
    "q.l16#8.o1" to "Einen schwer unterkühlten Patienten gehen lassen, um Wärme zu erzeugen",
    "q.l16#8.o2" to "Erfrorene Gliedmaßen kräftig massieren",
    "q.l16#8.o3" to "Die Gliedmaßen vor dem Rumpf erwärmen",
    "q.l16#8.o4" to "Den Patienten aus dem Wind bringen und nasse Kleidung wechseln",
    "q.l16#8.e" to "Die ersten vier sind alle falsch, jede aus ihrem eigenen Grund: Alkohol erweitert die peripheren Gefäße und beschleunigt den Wärmeverlust; Gehen kann bei schwerer Unterkühlung Rhythmusstörungen auslösen; Massieren schädigt erfrorenes Gewebe zusätzlich; und die Gliedmaßen zuerst zu wärmen schickt kaltes Blut in den Kern und senkt die Kerntemperatur weiter.",

    "q.l16#9.p" to "Wie lautet die Kern-Prioritätenfolge in der Unterkühlungsversorgung?",
    "q.l16#9.o0" to "Zuerst die Gliedmaßen, dann den Rumpf",
    "q.l16#9.o1" to "Zuerst den Rumpf erwärmen und dabei grobe Handhabung und heftige Gliedmaßenbewegungen vermeiden",
    "q.l16#9.o2" to "Dem Patienten zuerst heißes Wasser geben",
    "q.l16#9.o3" to "Zuerst alle Kleidung entfernen",
    "q.l16#9.e" to "Kern zuerst ist das erste Prinzip: Ist der Rumpf warm, können Herz und Gehirn wieder arbeiten und das Blut kann sicher zu den Gliedmaßen geschickt werden. Die Reihenfolge umzukehren senkt die Kerntemperatur direkt weiter.",

    "q.l16#10.p" to "Wie ist die richtige Nachsorge, nachdem eine Erfrierung wiedererwärmt wurde?",
    "q.l16#10.o0" to "Die Blasen aufstechen, um den Druck zu nehmen",
    "q.l16#10.o1" to "Die Blasen nicht aufstechen, locker mit sterilem Material verbinden und nicht belasten",
    "q.l16#10.o2" to "Kräftig massieren, um die Durchblutung zu verbessern",
    "q.l16#10.o3" to "Die Stelle sofort an eine Wärmequelle halten",
    "q.l16#10.e" to "Wiedererwärmtes Gewebe ist extrem empfindlich: Blasen sind ein natürlicher Verband, und Aufstechen lädt Infektionen ein; Massieren verursacht mechanischen Schaden; Hitze verbrennt gefühllose Haut. Schützen, trocken halten, nicht belasten und medizinische Versorgung organisieren.",

    "q.l16#11.p" to "Welche Langzeitfolgen kann eine Erfrierung hinterlassen?",
    "q.l16#11.o0" to "Meist vollständige Erholung ohne Folgeerscheinungen",
    "q.l16#11.o1" to "Kälteempfindlichkeit, Gefühlsstörungen und gestörtes Schwitzen, die Monate oder länger brauchen können",
    "q.l16#11.o2" to "Nur kosmetische Auswirkungen",
    "q.l16#11.o3" to "Nur ein Verlust der sportlichen Leistungsfähigkeit",
    "q.l16#11.e" to "Erfrierungen schädigen tiefes Gewebe und Nervenendigungen, sodass Kälteempfindlichkeit, Taubheit, Kribbeln und gestörtes Schwitzen auch dann bestehen bleiben können, wenn die Haut erholt aussieht. Genau deshalb ist Vorbeugung weit wichtiger als Behandlung.",

    // ---------- l17 Eisklettern ----------
    "q.l17#0.p" to "Wie schwingt man ein Eisgerät?",
    "q.l17#0.o0" to "Mit dem Oberarm kräftig zuschlagen",
    "q.l17#0.o1" to "Aus dem Handgelenk schwingen, sodass die Haue senkrecht ins Eis eindringt",
    "q.l17#0.o2" to "Mit der Haue auf die Oberfläche hämmern",
    "q.l17#0.o3" to "Waagerecht ins Eis schneiden",
    "q.l17#0.e" to "Ein Schlag aus dem Handgelenk treibt die Haue senkrecht und schnell hinein: Sie greift leichter und kostet weniger Kraft. Mit dem ganzen Arm zu schlagen landet die Haue meist schräg und zertrümmert die Oberfläche zu einer Schale, die nicht mehr hält.",

    "q.l17#1.p" to "Was bedeutet Drei-Punkt-Kontakt beim Eisklettern?",
    "q.l17#1.o0" to "Zwei Hände und ein Fuß (oder zwei Füße und eine Hand) halten drei stabile Kontakte, während der vierte sich bewegt",
    "q.l17#1.o1" to "Drei Personen klettern gemeinsam",
    "q.l17#1.o2" to "Drei Knoten teilen die Last",
    "q.l17#1.o3" to "Die Ausrüstung braucht drei Befestigungspunkte",
    "q.l17#1.e" to "Drei-Punkt-Kontakt ist die Bewegungsregel, die Eis und Fels teilen: immer drei zuverlässige Kontakte halten und nur einen bewegen. So haben Sie noch Halt, wenn ein Kontakt versagt.",

    "q.l17#2.p" to "Was ist typisch für WI4?",
    "q.l17#2.o0" to "Flaches Eis, das man hinaufgehen kann",
    "q.l17#2.o1" to "Nahezu senkrecht mit kurzen senkrechten Passagen und möglicherweise schlechter Absicherung",
    "q.l17#2.o2" to "Nur Überhänge",
    "q.l17#2.o3" to "Man braucht nur einen Trekkingstock",
    "q.l17#2.e" to "WI4 bedeutet nahezu senkrechtes Gelände mit kurzen senkrechten Abschnitten, und die Stellen für einen Eishaken sind vielleicht nicht gut. Es verlangt bessere Technik und Beurteilung. WI1–WI2 ist Lerngelände.",

    "q.l17#3.p" to "Warum beim Eisklettern sparsam mit Schlägen sein?",
    "q.l17#3.o0" to "Um Energie zu sparen",
    "q.l17#3.o1" to "Zerschlagenes Eis wird zu einer Schale, die nicht mehr hält",
    "q.l17#3.o2" to "Weil das Gerät verschleißt",
    "q.l17#3.o3" to "Weil es die Partner stört",
    "q.l17#3.e" to "Jeder Fehlschlag hinterlässt einen Krater. Wiederholtes Hämmern zerstört das tragende Eis über eine ganze Fläche und zwingt Sie, an den Armen zu hängen – ein Teufelskreis.",

    "q.l17#4.p" to "Warum ist Eisklettern gefährlicher als Sportklettern?",
    "q.l17#4.o0" to "Weil es kälter ist",
    "q.l17#4.o1" to "Eishaken können unter Last ausbrechen, und das Eis ändert sich von Tag zu Tag",
    "q.l17#4.o2" to "Weil es keine Sicherung gibt",
    "q.l17#4.o3" to "Weil man kein Seil verwenden kann",
    "q.l17#4.e" to "Ein gut gesetzter Klemmkeil oder Bohrhaken im Fels bleibt zuverlässig; ein Eishaken hängt vom Eis selbst ab, und Eis schmilzt, wird spröde und bildet Hohlräume – eine gestern solide Platzierung kann heute nichts bedeuten.",

    "q.l17#5.p" to "Warum zuerst die Füße stabilisieren, bevor man das Gerät schwingt?",
    "q.l17#5.o0" to "Weil die Arme schneller ermüden als die Beine",
    "q.l17#5.o1" to "Die Füße tragen das Gewicht und geben die Ruhe; die Arme helfen nur",
    "q.l17#5.o2" to "Weil Eisgeräte teuer sind",
    "q.l17#5.o3" to "Weil es professioneller aussieht",
    "q.l17#5.e" to "Armkraft geht am Eis sehr schnell aus; die Füße können stundenlang Gewicht tragen. Wer schwingt, bevor die Füße sitzen, verbrennt die Arme früh und erhöht sogar die Gefahr abzustürzen.",

    "q.l17#6.p" to "Unter welchen Bedingungen wird Eis typischerweise schlecht?",
    "q.l17#6.o0" to "Nach einer kalten Nacht",
    "q.l17#6.o1" to "Nach starker Sonne oder steigender Temperatur, wenn das Eis weich und wabig wird",
    "q.l17#6.o2" to "Direkt nach Neuschnee",
    "q.l17#6.o3" to "Wenn der Wind auffrischt",
    "q.l17#6.e" to "Eis ist eine Funktion der Temperatur. Hartes Morgen-Eis nimmt präzise Platzierungen an; nachmittäglicher Sulz fühlt sich leicht an, aber seine Haken brechen leichter aus. Eis zu beurteilen heißt, Tageszeit, Exposition, Temperatur und Sonnengeschichte abzuwägen.",

    "q.l17#7.p" to "Was sollte man vor dem Setzen eines Eishakens prüfen?",
    "q.l17#7.o0" to "Ob der Haken eine auffällige Farbe hat",
    "q.l17#7.o1" to "Ob das Eis dort massiv ist, ohne Hohlräume oder Wabenbildung",
    "q.l17#7.o2" to "Ob er auf Fotos gut wirkt",
    "q.l17#7.o3" to "Wie weit er über dem Boden liegt",
    "q.l17#7.e" to "Die Festigkeit eines Hakens kommt vom Eis, nicht von der Technik. Ein Haken in einem Hohlraum oder wabigem Eis hält einen Sturz kaum – das ist der grundlegendste Unterschied zwischen Eis- und Felsabsicherung.",

    "q.l17#8.p" to "Die Unterarme machen am Eispitch zu. Was tun Sie?",
    "q.l17#8.o0" to "Schneller klettern, um durchzukommen",
    "q.l17#8.o1" to "So schnell wie möglich in eine Ruheposition kommen, Gewicht auf die Füße verlagern und die Arme ausschütteln",
    "q.l17#8.o2" to "Fester zugreifen, um stabil zu bleiben",
    "q.l17#8.o3" to "Sofort zurücksteigen",
    "q.l17#8.e" to "Pump ist eine Unterarmischämie; wer weitermacht, verliert den Griff völlig. Richtig ist, das Gewicht auf die Füße zu verlagern, solange man es noch kontrolliert, und das Blut zurückfließen zu lassen – genau das heißt „die Füße nicht faul sein lassen“ in der Praxis.",

    "q.l17#9.p" to "【Zuordnung】Ordnen Sie jedem WI-Eisgrad seinen typischen Charakter zu.",
    "q.l17#9.l0" to "WI2",
    "q.l17#9.l1" to "WI3",
    "q.l17#9.l2" to "WI4",
    "q.l17#9.l3" to "WI5",
    "q.l17#9.r0" to "Anhaltendes Eis um 60° mit möglichen Beulen; gute Absicherung",
    "q.l17#9.r1" to "Anhaltend 60–75°; meist gute Absicherung, aber anstrengend",
    "q.l17#9.r2" to "Nahezu senkrecht mit kurzen senkrechten Passagen; Absicherung kann schlecht sein",
    "q.l17#9.r3" to "Anhaltend senkrecht; schlechte Absicherung und sehr fordernd",
    "q.l17#9.e" to "Ein WI-Grad verbindet drei Variablen: Winkel, Qualität der Absicherung und körperlicher Aufwand. Je höher der Grad, desto weniger Raum bleibt für Rückzug oder Selbstrettung – deshalb ist der Grad nur eine Referenz, und das Eis des Tages und der Zustand der Gruppe entscheiden.",

    "q.l17#10.p" to "【Mehrfachauswahl】Welche Ausrüstung sollte am Gurt in Reichweite hängen beim Eisklettern?",
    "q.l17#10.o0" to "Mehrere Eishaken",
    "q.l17#10.o1" to "Karabiner und Expressschlingen",
    "q.l17#10.o2" to "Prusikkordel",
    "q.l17#10.o3" to "Ein Sicherungsgerät",
    "q.l17#10.o4" to "Ein Ersatzschlafsack",
    "q.l17#10.e" to "Eisklettern heißt, die Sicherung im Gehen zu bauen, deshalb existiert alles, was im Rucksack vergraben ist, praktisch nicht. Die Rettungsliste des Lehrbuchs – Haken, Karabiner, Schlingen, Umlenkrolle, Prusiks, Aufstiegsgerät – folgt derselben Logik: alles, was man brauchen könnte, bleibt in Reichweite.",

    "q.l17#11.p" to "Warum kann ein Eishaken ausbrechen?",
    "q.l17#11.o0" to "Weil der Haken zu kurz ist",
    "q.l17#11.o1" to "Weil das Eis selbst Hohlräume haben, wabig oder schmelzend sein kann und nicht hält",
    "q.l17#11.o2" to "Weil zu viel daran eingehängt ist",
    "q.l17#11.o3" to "Weil der Haken stumpf ist",
    "q.l17#11.e" to "Die Festigkeit kommt vom Eis, nicht von der Platzierung. Ein Haken in einem Hohlraum oder wabigem Eis hält einen Sturz kaum – der wesentliche Unterschied zur Felsabsicherung und der Grund, das Eis vor dem Setzen zu prüfen.",

    "q.l17#12.p" to "Warum ist ein Eisgrad nur eine Referenz?",
    "q.l17#12.o0" to "Weil Grade willkürlich sind",
    "q.l17#12.o1" to "Weil sich das Eis täglich ändert – Sonne, Temperatur und Jahreszeit können dieselbe Route deutlich verändern",
    "q.l17#12.o2" to "Weil die Grade von Land zu Land verschieden sind",
    "q.l17#12.o3" to "Weil Grade nur die Länge beschreiben",
    "q.l17#12.e" to "Eis ist eine Funktion der Temperatur: Hartes Morgen-Eis braucht präzise Platzierungen, weiches Nachmittagseis wirkt leicht, aber seine Haken brechen leichter aus. Dieselbe Route kann um mehr als einen Grad schwanken – was Sie vor sich sehen, zählt immer mehr als die Zahl im Führer.",

    "q.l17#13.p" to "【Reihenfolge】Bringen Sie den Rhythmus des Drei-Punkt-Kontakts beim Eisklettern in die richtige Ordnung.",
    "q.l17#13.o0" to "Das Eis lesen und wählen, wohin Gerät und Füße gehen",
    "q.l17#13.o1" to "Die Frontzacken eintreten, um beide Füße zu setzen",
    "q.l17#13.o2" to "Mit stabilen Füßen das Gerät schwingen und prüfen, ob es sitzt",
    "q.l17#13.o3" to "Mit drei stabilen Punkten den vierten bewegen",
    "q.l17#13.e" to "Diese Reihenfolge erklärt, warum „die Füße nicht faul sein lassen“ die Kerndisziplin des Eiskletterns ist: Füße tragen stundenlang Gewicht, Arme helfen nur. Wer vor dem Setzen der Füße schwingt, erschöpft die Arme früh – an steilem Eis ist das fatal.",

    // ---------- l18 Lawinen ----------
    "q.l18#0.p" to "In welchen Hangneigungen häufen sich Lawinen am stärksten?",
    "q.l18#0.o0" to "10°–25°",
    "q.l18#0.o1" to "34°–45°",
    "q.l18#0.o2" to "55°–70°",
    "q.l18#0.o3" to "Senkrechtes Eis",
    "q.l18#0.e" to "Statistiken zeigen, dass die große Mehrheit der Lawinen zwischen 34° und 45° abgeht (96 % liegen zwischen 30–50°). Das ist gerade steil genug zum Gleiten und doch flach genug, um Schnee zu halten – das Gefahrenfenster, und der Winkel, den Bergrouten am häufigsten queren.",

    "q.l18#1.p" to "Warum passieren die meisten Unfälle bei Gefahrenstufe 3 (erheblich)?",
    "q.l18#1.o0" to "Weil die Schneedecke dann am instabilsten ist",
    "q.l18#1.o1" to "Weil die Verhältnisse akzeptabel aussehen und am leichtesten unterschätzt werden",
    "q.l18#1.o2" to "Weil dann alle zu Hause bleiben",
    "q.l18#1.o3" to "Weil die Prognose ungenau ist",
    "q.l18#1.e" to "Das Paradox von Stufe 3: Lawinen sind wirklich möglich, während das Gelände „in Ordnung“ aussieht – also gehen viele Menschen in Lawinengelände. Bei Stufe 4 und 5 bleiben die meisten weg, deshalb sinkt der Anteil der Unfälle. Am gefährlichsten ist nie das extreme Verhältnis, sondern das mittlere, das unterschätzt wird.",

    "q.l18#2.p" to "Was ist das Lawinen-Trio?",
    "q.l18#2.o0" to "LVS-Gerät, Sonde und Schaufel",
    "q.l18#2.o1" to "Helm, Seil und Gurt",
    "q.l18#2.o2" to "Pickel, Steigeisen und Eishaken",
    "q.l18#2.o3" to "Zelt, Schlafsack und Matte",
    "q.l18#2.e" to "Das LVS-Gerät sucht, die Sonde lokalisiert punktgenau, die Schaufel gräbt. Alle drei sind nötig, und alle drei müssen geübt sein, wenn eine Rettung im goldenen Fenster von gut zehn Minuten gelingen soll.",

    "q.l18#3.p" to "Warum sind Hänge, die nicht steil aussehen, oft am gefährlichsten?",
    "q.l18#3.o0" to "Weil der Schnee tiefer ist",
    "q.l18#3.o1" to "Weil sich bei 34–45° die Lawinen häufen und Menschen den Winkel systematisch unterschätzen",
    "q.l18#3.o2" to "Weil man sich darauf schneller bewegt",
    "q.l18#3.o3" to "Weil die Sonne stärker ist",
    "q.l18#3.e" to "Unter etwa 30° ist es zu flach für Schneebrettlawinen; über etwa 50° sammelt sich kein Schnee. Das Gefahrenfenster liegt genau in dem Bereich, der begehbar wirkt – und genau deshalb unterschätzt wird.",

    "q.l18#4.p" to "Wie quert man Lawinengelände richtig?",
    "q.l18#4.o0" to "Die ganze Gruppe schnell gemeinsam durchgehen",
    "q.l18#4.o1" to "Aufteilen, einer nach dem anderen queren, eine Beobachtungsperson postieren und eine Fluchtroute planen",
    "q.l18#4.o2" to "Die kürzeste Linie am Talboden nehmen",
    "q.l18#4.o3" to "Dort bleiben, wo der Schnee am tiefsten ist",
    "q.l18#4.e" to "Einer nach dem anderen begrenzt das Risiko auf eine Person, und eine Beobachtungsperson kann sofort orten und eine Rettung organisieren. Wenn alle gemeinsam queren, verschüttet ein Auslöser die ganze Gruppe – das schlechteste Ergebnis.",

    "q.l18#5.p" to "Sie hören ein „Whumpf“, während die Schneedecke nachgibt. Was bedeutet das?",
    "q.l18#5.o0" to "Sie sind nur in ein Loch getreten",
    "q.l18#5.o1" to "Es gibt eine leicht auslösbare Schwachschicht und die Schneedecke ist instabil",
    "q.l18#5.o2" to "Der Schnee ist tief und das Gehen gut",
    "q.l18#5.o3" to "Die Schneedecke hat sich stabilisiert",
    "q.l18#5.e" to "Ein Whumpf ist das Geräusch der nachgebenden Schneedecke, wenn eine Schwachschicht versagt. Es ist ein sehr direktes Stabilitätssignal – weiter auf diesen Hang zu gehen heißt, sich selbst als Test zu benutzen, ob er als Brett abgeht.",

    "q.l18#6.p" to "Warum sind Schneebrettlawinen tödlicher als Lockerschneelawinen?",
    "q.l18#6.o0" to "Weil sie kälter sind",
    "q.l18#6.o1" to "Ein ganzes Brett geht auf einmal ab und verschüttet Sie, sodass Selbstrettung fast unmöglich bleibt",
    "q.l18#6.o2" to "Weil sie lauter sind",
    "q.l18#6.o3" to "Weil sie häufiger auftreten",
    "q.l18#6.e" to "Ein Brett bricht auf der ganzen Fläche gleichzeitig, sodass Sie den Halt verlieren, während Sie noch am Hang sind. Verschüttet machen das Gewicht des Schnees und dessen rasches Abbinden die Selbstrettung fast unmöglich – deshalb muss die Kameradenrettung sofort beginnen.",

    "q.l18#7.p" to "Wie sollte ein LVS-Gerät getragen und benutzt werden?",
    "q.l18#7.o0" to "Irgendwo im Rucksack ist in Ordnung",
    "q.l18#7.o1" to "Vor dem Aufbruch gegenseitig den Sendestatus prüfen und die Suchabläufe regelmäßig üben",
    "q.l18#7.o2" to "Nur vom Tourenleiter getragen",
    "q.l18#7.o3" to "Ausgeschaltet, um Batterie zu sparen",
    "q.l18#7.e" to "Ein LVS-Gerät im Rucksack ist nahezu nutzlos – unter dem Schnee bewegen sich Ihre Arme vielleicht gar nicht, deshalb wird es am Körper getragen, meist an der Brust. Auch der Suchablauf muss geübt sein, sonst finden Sie in den goldenen zehn Minuten niemanden.",

    "q.l18#8.p" to "Was ist vor dem Betreten von Lawinengelände die wichtigste Vorbereitung?",
    "q.l18#8.o0" to "Die Ausrüstung vollständig dabeizuhaben genügt",
    "q.l18#8.o1" to "Die Tageslawinenprognose lesen und Route und Plan anhand der Feldbeobachtungen laufend anpassen",
    "q.l18#8.o2" to "Voll auf die eigene Erfahrung vertrauen",
    "q.l18#8.o3" to "Den Spuren anderer folgen",
    "q.l18#8.e" to "Die Prognose liefert ein regionales Urteil, die Feldbeobachtung Belege im Maßstab des Hangs; beides braucht man. Alten Spuren zu folgen ist besonders gefährlich – sie können Stunden alt sein, und die Schneedecke hat sich längst verändert.",

    "q.l18#9.p" to "Welche Ursache verursacht laut Statistik die meisten tödlichen Bergunfälle?",
    "q.l18#9.o0" to "Zuerst Lawinen, dann Abstürze",
    "q.l18#9.o1" to "Zuerst Abstürze, dann Lawinen",
    "q.l18#9.o2" to "Zuerst Krankheit, dann Steinschlag",
    "q.l18#9.o3" to "Zuerst Unterkühlung, dann Lawinen",
    "q.l18#9.e" to "Das Lehrbuch ist eindeutig: zuerst Abstürze, dann Lawinen. Diese Reihenfolge ist wichtig – Lawinen werden am meisten gefürchtet, aber der alltägliche Ausrutscher tötet die meisten. Risiken ordnet man nach Daten, nicht nach Eindruck.",

    "q.l18#10.p" to "Wie lange ist das goldene Rettungsfenster nach einer Verschüttung etwa?",
    "q.l18#10.o0" to "Etwa zehn bis fünfzehn Minuten",
    "q.l18#10.o1" to "Zwei Stunden",
    "q.l18#10.o2" to "Sechs Stunden",
    "q.l18#10.o3" to "24 Stunden",
    "q.l18#10.e" to "Zehn bis fünfzehn Minuten – eine Zeitspanne, die bedeutet, dass die Rettung von Ihren Partnern kommen muss, weil organisierte Rettung viel zu spät eintrifft. Deshalb wird das Trio getragen und geübt, nicht nur eingepackt.",

    "q.l18#11.p" to "【Mehrfachauswahl】Welche Feldsignale sind bei der Beurteilung der Lawinengefahr wichtig?",
    "q.l18#11.o0" to "Ein Whumpf beim Nachgeben der Schneedecke",
    "q.l18#11.o1" to "Frische Risse, die am Hang entstehen",
    "q.l18#11.o2" to "Kürzlicher Neuschnee oder offensichtliche Windverfrachtung",
    "q.l18#11.o3" to "Hörbares Setzen und Einsinken unter den Füßen beim Aufstieg",
    "q.l18#11.o4" to "Cirruswolken und ausgezeichnete Sicht",
    "q.l18#11.e" to "Diese sind direkter Beleg dafür, dass die Stabilität gerade jetzt sinkt. Ihr Wert liegt in der Unmittelbarkeit: Die Prognose liefert ein regionales Bild, diese Signale beschreiben den Hang unter Ihren Füßen in diesem Moment. Beides braucht man.",

    "q.l18#12.p" to "Das Bild zeigt drei Abschnitte desselben Berges. Tippen Sie den Abschnitt mit dem höchsten Lawinenrisiko an.",
    "q.l18#12.e" to "Lawinen häufen sich zwischen 34° und 45°. Der flache Hang links (etwa 16°) ist zu flach für Schneebrettlawinen; der steile rechts (etwa 60°) ist zu steil, als dass sich ein mächtiges Brett aufbauen könnte. Nur der mittlere Hang mit etwa 40° liegt im Fenster, in dem sich Schnee sowohl sammelt als auch abgleiten kann – und genau diesen Winkel queren Bergrouten am häufigsten, weshalb er so leicht unterschätzt wird.",

    // ---------- l19 Tourenplanung und Umkehrentscheidung ----------
    "q.l19#0.p" to "Wozu dient die Festlegung einer Umkehrzeit?",
    "q.l19#0.o0" to "Um zu dieser Uhrzeit bedingungslos umzukehren und sich nicht vom Ziel gefangen nehmen zu lassen",
    "q.l19#0.o1" to "Um die Aufstiegsgeschwindigkeit zu berechnen",
    "q.l19#0.o2" to "Um zu entscheiden, wie viel Verpflegung mitkommt",
    "q.l19#0.o3" to "Um einer Formalität zu genügen",
    "q.l19#0.e" to "Eine Umkehrzeit nimmt die Entscheidung aus dem Moment heraus: Eine Regel, die Sie in klarem Zustand festgelegt haben, setzt Ihr Urteilsvermögen durch, wenn Sie müde und unwillig sind. Sie ist das wirksamste Mittel gegen Gipfelfieber.",

    "q.l19#1.p" to "Was verursacht typischerweise Gipfelfieber?",
    "q.l19#1.o0" to "Sehr gutes Wetter",
    "q.l19#1.o1" to "Versunkene Kosten und Gruppendruck verzerren das Urteil",
    "q.l19#1.o2" to "Unzureichende Ausrüstung",
    "q.l19#1.o3" to "Eine zu geringe Höhe",
    "q.l19#1.e" to "Zeit, Geld und Mühe, die schon investiert sind, machen es schwer zuzugeben, dass man umkehren sollte; Schweigen oder gegenseitige Ermutigung in der Gruppe ersticken Zweifel zusätzlich. Den Mechanismus zu verstehen ist die Voraussetzung dafür, vorher objektive Regeln zu setzen.",

    "q.l19#2.p" to "Wann sollte eine Gruppe ihre Rückzugsentscheidung festlegen?",
    "q.l19#2.o0" to "Vor dem Aufbruch: objektive Auslöser und Zuständigkeit vereinbaren",
    "q.l19#2.o1" to "Auf dem Gipfel",
    "q.l19#2.o2" to "Wenn Gefahr auftritt, improvisiert",
    "q.l19#2.o3" to "Vor Ort durch die stärkste Person",
    "q.l19#2.e" to "Über Rückzug zu diskutieren, während man müde, sauerstoffarm und emotional ist, kippt fast immer in Richtung Weitergehen. Vereinbaren Sie vorher objektive Auslöser — eine Uhrzeit, eine Wetteränderung, ein bestimmtes Bild der Gruppe — und legen Sie fest, wer das letzte Wort hat.",

    "q.l19#3.p" to "Warum passieren so viele Unfälle beim Abstieg?",
    "q.l19#3.o0" to "Weil das Gelände abwärts schwieriger ist",
    "q.l19#3.o1" to "Weil die Aufmerksamkeit nach erreichtem Ziel sinkt, während der Körper schon am Limit ist",
    "q.l19#3.o2" to "Weil das Wetter abwärts immer schlechter ist",
    "q.l19#3.o3" to "Weil die Ausrüstung versagt",
    "q.l19#3.e" to "Der Gipfel ist nur die Hälfte des Weges heißt übersetzt: Das Risiko der Tour wird beim Abstieg freigesetzt. Anseilen, Sichern und Tempo dürfen nicht nachlassen, nur weil Sie den Gipfel erreicht haben.",

    "q.l19#4.p" to "Worin liegt der Wert, die Rückzugsentscheidung vorab zu vereinbaren?",
    "q.l19#4.o0" to "Es spart Zeit",
    "q.l19#4.o1" to "Es nimmt die Entscheidung aus Müdigkeit und Emotion und lässt Ihr Urteil von vor dem Aufbruch handeln",
    "q.l19#4.o2" to "Es gibt der Leitung mehr Autorität",
    "q.l19#4.o3" to "Es vermeidet Diskussionen",
    "q.l19#4.e" to "Entscheidungen in Sauerstoffmangel, Müdigkeit und Widerwillen kippen fast immer in Richtung Weitergehen. Objektive Auslöser und Entscheidungsrechte vorher zu vereinbaren heißt: Die ruhige Version von Ihnen entscheidet für die erschöpfte.",

    "q.l19#5.p" to "Warum muss ein Rückzugsplan im Tourenplan stehen?",
    "q.l19#5.o0" to "Damit der Plan vollständig aussieht",
    "q.l19#5.o1" to "Rückzug braucht Ausrüstung, Route und Zeitbudget; improvisierte Entscheidungen lassen keine Zeit zur Vorbereitung",
    "q.l19#5.o2" to "Um eine Kontrolle zu bestehen",
    "q.l19#5.o3" to "Weil Vorschriften es verlangen",
    "q.l19#5.e" to "Rückzug ist eine echte technische Operation: Er kann einen Standplatz, eine Abseilstelle und Bewegung im Dunkeln erfordern. Hat der Plan dafür nie Zeit und Material eingeplant, wird der Rückzug zur Improvisation mit hohem Risiko.",

    "q.l19#6.p" to "Wenn Gruppenmitglieder über Route oder Wetter uneinig sind — was ist richtig?",
    "q.l19#6.o0" to "Mehrheitsentscheid",
    "q.l19#6.o1" to "Die konservativste Sicht gilt, bis neue Belege alle überzeugen",
    "q.l19#6.o2" to "Die stärkste Person entscheidet",
    "q.l19#6.o3" to "Abstimmen und dann nicht mehr darüber reden",
    "q.l19#6.e" to "In Risikosituationen soll die konservativste Sicht Gewicht haben. Mehrheitsentscheide unterdrücken die berechtigte Sorge einer Minderheit — und der häufigste Satz in Unfallauswertungen lautet: Jemand hatte ein schlechtes Gefühl, aber niemand sagte etwas.",

    "q.l19#7.p" to "Welche Sicht auf 'mit Bergführer sind Sie sicher' stimmt?",
    "q.l19#7.o0" to "Ein Bergführer macht Sie absolut sicher",
    "q.l19#7.o1" to "Ein Bergführer senkt das Risiko, kann objektive Gefahren aber nicht beseitigen; Teilnehmer müssen weiter selbst beurteilen",
    "q.l19#7.o2" to "Bergführer zeigen nur den Weg; Sicherheit ist Ihre Sache",
    "q.l19#7.o3" to "Teilnehmer müssen nichts beurteilen",
    "q.l19#7.e" to "Der Wert eines Bergführers liegt in Erfahrung und Entscheidungsqualität, aber Lawinen, Steinschlag und Wetter verschwinden nicht, weil jemand vorangeht. Teilnehmer, die das Risiko verstehen, Warnzeichen erkennen und den Mund aufmachen, sind selbst Teil der Sicherheitsreserve der Gruppe.",

    "q.l19#8.p" to "Was ist Goal Creep beim Bergsteigen?",
    "q.l19#8.o0" to "Den Schwierigkeitsgrad der Route herabsetzen",
    "q.l19#8.o1" to "Die selbst gesetzten Sicherheitsstandards schrittweise aufweichen, um den Gipfel zu erreichen",
    "q.l19#8.o2" to "Den Zielberg unterwegs wechseln",
    "q.l19#8.o3" to "Die Gruppengröße verkleinern",
    "q.l19#8.e" to "Goal Creep ist die klassische Signatur des Gipfelfiebers: Die Umkehrzeit rutscht weiter, das akzeptable Wetterfenster wird breiter, Symptome werden weiter toleriert. Die einzige Abwehr ist, die Standards vorher zu beziffern — dann wird jede Aufweichung ausdrücklich und muss den Partnern erklärt werden.",

    "q.l19#9.p" to "[Mehrfachauswahl] Was sollte ein vollständiger Tourenplan enthalten?",
    "q.l19#9.o0" to "Route und Zeitplan einschließlich Umkehrzeit",
    "q.l19#9.o1" to "Rückzugsplan und Alternativrouten",
    "q.l19#9.o2" to "Einschätzung des Gruppenzustands und Rollenverteilung",
    "q.l19#9.o3" to "Kommunikationsweg, Kontaktperson und Notfallprozedur",
    "q.l19#9.o4" to "Einen Medien- und Publizitätsplan",
    "q.l19#9.e" to "Die ersten vier sind alle nötig. Am häufigsten übersprungen werden der zweite und der vierte — weil sie bei gutem Verlauf nicht gebraucht werden. Aber ein Plan zeigt seinen Wert genau dann, wenn es schlecht läuft, und dann ist keine Zeit mehr, ihn zu schreiben.",

    "q.l19#10.p" to "Warum Reserve-Tage im Zeitplan einplanen?",
    "q.l19#10.o0" to "Um Verzögerungen aufzufangen, etwa ein späteres Wetterfenster oder Unwohlsein eines Mitglieds",
    "q.l19#10.o1" to "Um mehr zu ruhen",
    "q.l19#10.o2" to "Um Geld zu sparen",
    "q.l19#10.o3" to "Damit der Zeitplan bequem aussieht",
    "q.l19#10.e" to "Hochtouren verschieben sich fast immer: Das Wetter spielt nicht mit, jemand braucht einen zusätzlichen Akklimatisierungstag, der Zustieg dauert länger als gedacht. Ohne Reserve zwingt jede Verzögerung dazu, Akklimatisierung zu kürzen oder Tagesetappen zu verlängern — beides erhöht das Risiko deutlich.",

    "q.l19#11.p" to "[Reihenfolge] Bringen Sie die Schritte eines Tourenplans in eine sinnvolle Reihenfolge.",
    "q.l19#11.o0" to "Ziel und Route festlegen; Informationen und historisches Wetter sammeln",
    "q.l19#11.o1" to "Gruppenkönnen und verfügbare Zeit einschätzen; Akklimatisierungsrhythmus planen",
    "q.l19#11.o2" to "Umkehrzeit und messbare Rückzugsauslöser setzen",
    "q.l19#11.o3" to "Rückzugsplan und Notfallprozedur schreiben, Kontakt zu Hause einweisen",
    "q.l19#11.e" to "Die Reihenfolge lautet: Ziel setzen, Können prüfen, rote Linie ziehen, dann den Ausstieg sichern. Viele machen es umgekehrt — Ziel zuerst, Ausstieg zuletzt — und deshalb landet der Ausstieg am Ende der Liste und wird nie richtig entworfen.",

    "q.l19#12.p" to "Warum wird die Abstiegszeit so oft unterschätzt?",
    "q.l19#12.o0" to "Weil es abwärts schneller geht",
    "q.l19#12.o1" to "Weil Sie erschöpft sind, die Oberfläche schlechter sein kann und Sie noch sichern und Material abbauen müssen",
    "q.l19#12.o2" to "Weil Karten ungenau sind",
    "q.l19#12.o3" to "Weil Bergführer zur Eile treiben",
    "q.l19#12.e" to "Der Aufstieg hat vielleicht sechs Stunden gedauert, der Abstieg oft länger: weniger Kraft, weicherer oder vereister Schnee, schlechtere Sicht und womöglich Abseilstellen und Materialbergung. Die Abstiegszeit aus der Aufstiegszeit zu schätzen ist einer der häufigsten Planungsfehler.",

    "q.l19#13.p" to "Warum Kommunikation und Kontaktwege im Plan ausdrücklich festhalten?",
    "q.l19#13.o0" to "Für die Akten",
    "q.l19#13.o1" to "Weil die Menschen zu Hause wissen müssen, wo gesucht wird und wann begonnen werden soll, falls Sie ausbleiben",
    "q.l19#13.o2" to "Um dem Veranstalter zu berichten",
    "q.l19#13.o3" to "Um Permit-Auflagen zu erfüllen",
    "q.l19#13.e" to "Das Schwierigste an der Rettung ist, nicht zu wissen, wo die Person ist. Routenverlauf, Aufstiegsroute, Alternativen und Check-in-Zeiten verkürzen eine Suche von Tagen auf Stunden — und diese Angaben kann man nur vor dem Aufbruch liefern.",

    "q.l19#14.p" to "Wie beeinflusst die Gruppengröße den Plan?",
    "q.l19#14.o0" to "Die Größe ist für die Planung unerheblich",
    "q.l19#14.o1" to "Mehr Leute heißt langsamer, mehr Logistik und schwerer zu synchronisierende Akklimatisierung",
    "q.l19#14.o2" to "Mehr Leute ist sicherer, also braucht es keine Anpassung",
    "q.l19#14.o3" to "Mehr Leute ist schneller",
    "q.l19#14.e" to "Eine große Gruppe teilt Arbeitskraft und Ressourcen — zum Preis von Tempo und Flexibilität: Jeder hat seinen Rhythmus, und die Gruppe kann nur im Tempo der Langsamsten gehen. Die Gruppengröße gehört in die Zeitschätzung, nicht in die Beschwerde danach.",

    "q.l19#15.p" to "Ergänzen Sie: Hochtouren planen meist etwa ( ) % Reserve-Tage ein.",
    "q.l19#15.a0" to "20",
    "q.l19#15.a1" to "30",
    "q.l19#15.a2" to "25",
    "q.l19#15.a3" to "20-30",
    "q.l19#15.a4" to "20–30",
    "q.l19#15.a5" to "zwanzig bis dreißig",
    "q.l19#15.e" to "Üblich sind 20–30 % Reserve. Eine zehntägige Tour sollte man für Verpflegung, Erlaubnisse und Anreise also als zwölf bis dreizehn Tage planen — das wirkt konservativ, bis man es damit vergleicht, wie oft es tatsächlich zu Verzögerungen kommt.",

    // ---------- l20 Rettung und Erste Hilfe ----------
    "q.l20#0.p" to "Was ist das erste Prinzip der Rettung?",
    "q.l20#0.o0" to "Den Verletzten so schnell wie möglich bewegen",
    "q.l20#0.o1" to "Die Unfallstelle sichern, damit kein zweiter Verletzter entsteht",
    "q.l20#0.o2" to "Zuerst die Unfallstelle fotografieren",
    "q.l20#0.o3" to "Dem Verletzten zuerst Wasser geben",
    "q.l20#0.e" to "Bei Steinschlag, Lawinen, Spalten oder steilem Gelände wird aus dem Retter schnell ein zweiter Verletzter — und die verfügbare Mannschaft halbiert sich. Die Lage zu beurteilen ist der erste und der einzige Schritt, den man nicht überspringen kann.",

    "q.l20#1.p" to "Wo beginnt die richtige Notfallreihenfolge?",
    "q.l20#1.o0" to "Erst die Lage sichern, dann die Verletzungen beurteilen",
    "q.l20#1.o1" to "Den Verletzten zuerst in Sicherheit bringen",
    "q.l20#1.o2" to "Nach Essen und Wasser suchen",
    "q.l20#1.o3" to "Ein Seilsystem bauen",
    "q.l20#1.e" to "Die Standardreihenfolge ist: sichern, beurteilen, Hilfe rufen, behandeln, transportieren. Die Sicherung zu überspringen und direkt zum Verletzten zu laufen ist der häufigste Rettungsfehler.",

    "q.l20#2.p" to "Warum zählt Prävention in der Höhe weit mehr als Rettung?",
    "q.l20#2.o0" to "Weil Rettung teuer ist",
    "q.l20#2.o1" to "Weil Rettung durch Wetter, Sauerstoff und Mannschaft begrenzt ist und oft nicht rechtzeitig ankommt",
    "q.l20#2.o2" to "Weil Rettungsteams nicht wollen",
    "q.l20#2.o3" to "Weil es kein Telefonsignal gibt",
    "q.l20#2.e" to "Die Höhe schwächt beide Seiten: Helikopter sind durch Turbulenz und Höhe begrenzt, Bodenteams brauchen Stunden, und ein Verletzter verschlechtert sich in Hypoxie und Kälte schneller. Diese Zeitlücke ist die einzige Rettungsressource, die Sie wirklich haben.",

    "q.l20#3.p" to "Warum dauert Bergrettung oft Stunden oder Tage?",
    "q.l20#3.o0" to "Weil die Teams nicht gehen wollen",
    "q.l20#3.o1" to "Enge Grenzen durch Wetter, Sauerstoff, Kommunikation und Mannschaft; Helikopter sind durch Turbulenz und Höhe eingeschränkt",
    "q.l20#3.o2" to "Weil die Entfernungen zu groß sind",
    "q.l20#3.o3" to "Weil es zu viel kostet",
    "q.l20#3.e" to "In der Höhe kämpft ein Helikopter mit Auftrieb und Turbulenz, und ein Bodenteam braucht Stunden bis zu Ihnen. Diese Lücke bedeutet eines: In der Höhe sind Sie Ihr eigenes erstes Rettungsteam.",

    "q.l20#4.p" to "Wozu Routenmeldung und Kontaktperson?",
    "q.l20#4.o0" to "Um einer Formalität zu genügen",
    "q.l20#4.o1" to "Wenn Sie ausbleiben, wissen Retter, wo sie suchen müssen — das verkürzt die Suche erheblich",
    "q.l20#4.o2" to "Um Spesenabrechnungen zu erleichtern",
    "q.l20#4.o3" to "Um Vorschriften zu erfüllen",
    "q.l20#4.e" to "Das Schwierigste an der Rettung ist, nicht zu wissen, wo die Person ist. Routenverlauf, Route, Alternativpläne und Kontaktwege verkürzen eine Suche von Tagen auf Stunden.",

    "q.l20#5.p" to "Was wird bei der Beurteilung eines Verletzten zuerst behandelt?",
    "q.l20#5.o0" to "Knochenbrüche schienen",
    "q.l20#5.o1" to "Lebensbedrohliches wie Atemweg und Atmung",
    "q.l20#5.o2" to "Die Verletzungen detailliert dokumentieren",
    "q.l20#5.o3" to "Sichtbare Wunden reinigen",
    "q.l20#5.e" to "Die Beurteilung folgt dem Prinzip Lebensbedrohliches zuerst: Atemweg, Atmung und Kreislauf vor Frakturen und Wunden, die nicht sofort tödlich sind. Stimmt die Reihenfolge nicht, verliert alles Weitere an Bedeutung.",

    "q.l20#6.p" to "Warum ist Wärmeerhalt in der Höhe ein kritischer Teil der Ersten Hilfe?",
    "q.l20#6.o0" to "Weil es den Verletzten bequemer macht",
    "q.l20#6.o1" to "Weil ein bewegungsunfähiger Verletzter schnell auskühlt, was die Verletzung verschlimmert",
    "q.l20#6.o2" to "Weil Vorschriften es verlangen",
    "q.l20#6.o3" to "Um den Transport zu erleichtern",
    "q.l20#6.e" to "In Kälte und Hypoxie verliert ein Verletzter, der sich nicht bewegen kann, schnell seine Wärmeproduktion. Unterkühlung vertieft den Schock und verschleiert Symptome — deshalb zählen Unterlage, Windschutz und nasse Kleidung wechseln so viel wie Blutstillung.",

    "q.l20#7.p" to "Was soll der Notfallplan der Gruppe bei Kommunikationsausfall sein?",
    "q.l20#7.o0" to "An Ort und Stelle warten, bis der Kontakt wieder da ist",
    "q.l20#7.o1" to "Vorher einen Sammelpunkt, eine Frist für Kontaktverlust und die Folgemaßnahmen vereinbaren",
    "q.l20#7.o2" to "Sofort aufteilen und suchen",
    "q.l20#7.o3" to "Alle gleichzeitig absteigen",
    "q.l20#7.e" to "Kommunikationsausfall im Gebirge ist normal, nicht die Ausnahme. Vorher zu vereinbaren, was passiert, wenn Sie sich bis zu einer bestimmten Zeit nicht melden, verhindert Panik zu Hause und sagt der Kontaktperson, wann sie Alarm auslösen soll.",

    "q.l20#8.p" to "Welche Haltung zu Erste-Hilfe- und Rettungstraining ist richtig?",
    "q.l20#8.o0" to "Ein Tutorial schauen und die Schritte auswendig lernen genügt",
    "q.l20#8.o1" to "Regelmäßig praktisch üben; Lesen allein trägt nicht in eine echte Situation",
    "q.l20#8.o2" to "Nur die Leitung braucht das",
    "q.l20#8.o3" to "Das ist nur etwas für professionelle Retter",
    "q.l20#8.e" to "Erste Hilfe und Rettung sind stark prozedurale Fähigkeiten, und unter Druck fallen Sie auf das Niveau zurück, auf dem Sie tatsächlich geübt haben. Lesen baut das Gerüst; nur wiederholtes Üben hält die Handgriffe richtig, wenn Sie Angst haben.",

    "q.l20#9.p" to "[Reihenfolge] Bringen Sie die übliche Reihenfolge von Beurteilung und Behandlung in Ordnung.",
    "q.l20#9.o0" to "Die Unfallstelle sichern, damit kein zweiter Verletzter entsteht",
    "q.l20#9.o1" to "Bewusstsein, Atemweg, Atmung und Kreislauf prüfen",
    "q.l20#9.o2" to "Akute Lebensgefahr behandeln: Blutung, Wärmeerhalt, Schienen",
    "q.l20#9.o3" to "Hilfe rufen und Transport organisieren oder auf professionelle Rettung warten",
    "q.l20#9.e" to "Die Schritte eins und vier werden am häufigsten übersprungen — unter Stress läuft man direkt zum Verletzten. Aber eine unsichere Lage macht den Retter zum zweiten Verletzten und halbiert die Mannschaft, und ohne Hilferuf gibt es keinen Rückhalt für alles Folgende.",

    "q.l20#10.p" to "[Mehrfachauswahl] Welche Angaben gehören in einen Notruf?",
    "q.l20#10.o0" to "Genaue Lage (Koordinaten oder ein erkennbarer Orientierungspunkt)",
    "q.l20#10.o1" to "Zahl der Verletzten, Bewusstsein und Atmung",
    "q.l20#10.o2" to "Gelände und Wetter vor Ort",
    "q.l20#10.o3" to "Verfügbarer Kommunikationsweg und Meldezeiten",
    "q.l20#10.o4" to "Der bergsteigerische Lebenslauf des Verletzten",
    "q.l20#10.e" to "Diese vier entscheiden, was geschickt wird, wie viel und auf welchem Weg. Eine vage Lage kostet Stunden, unbekannte Verletzungen bringen falsches Material, und unbekanntes Wetter kann auch das Rettungsteam in Gefahr bringen. Hilfe zu rufen ist eine Kommunikationsfähigkeit, die man üben sollte.",

    "q.l20#11.p" to "Warum ist Helikopterrettung in der Höhe oft unmöglich?",
    "q.l20#11.o0" to "Weil sie zu teuer ist",
    "q.l20#11.o1" to "Weil dünne Luft Auftrieb und Nutzlast senkt, die Turbulenz stark ist und die Wetterfenster kurz sind",
    "q.l20#11.o2" to "Weil Piloten dort nicht fliegen wollen",
    "q.l20#11.o3" to "Weil es in der Höhe keine Luftstraßen gibt",
    "q.l20#11.e" to "Der Auftrieb eines Helikopters kommt aus der Luft, und oben ist die Luft dünn — das begrenzt direkt, wie viel er heben und wie hoch er arbeiten kann. Dazu turbulente Gebirgsluft und schnell wechselndes Wetter, und das fliegbare Fenster kann nur wenige zehn Minuten betragen. Deshalb darf Rettung nicht Ihr Plan sein.",

    "q.l20#12.p" to "[Zuordnung] Ordnen Sie jede Erste-Hilfe-Maßnahme ihrem Anwendungsfall zu.",
    "q.l20#12.l0" to "Wärmeerhalt",
    "q.l20#12.r0" to "Bei jedem Verletzten in der Höhe vorrangig, damit Unterkühlung den Schock nicht vertieft",
    "q.l20#12.l1" to "Blutstillung",
    "q.l20#12.r1" to "Erste Maßnahme bei offener Wunde oder Blutung an einer Extremität",
    "q.l20#12.l2" to "Schienen",
    "q.l20#12.r2" to "Bei Verdacht auf Fraktur oder Gelenkverletzung, um weiteren Schaden beim Bewegen zu vermeiden",
    "q.l20#12.l3" to "Sauerstoff",
    "q.l20#12.r3" to "Bei Atemnot, deutlich zu niedriger Sättigung oder Verdacht auf Lungenödem",
    "q.l20#12.e" to "Alle vier sind in der Höhe Grundmaßnahmen, keine Spezialverfahren. Gemeinsam ist ihnen, dass sie kein komplexes Material brauchen, aber die richtige Reihenfolge — Wärmeerhalt etwa kommt in der allgemeinen Ersten Hilfe oft spät, ist in der Höhe aber vorrangig.",

    "q.l20#13.p" to "Warum das Risiko der Rettung selbst beurteilen?",
    "q.l20#13.o0" to "Weil Rettung anstrengend ist",
    "q.l20#13.o1" to "Weil die Rettung mehr Menschen in Gefahr bringen und die Überlebenschance insgesamt senken kann",
    "q.l20#13.o2" to "Weil die Versicherung es verlangt",
    "q.l20#13.o3" to "Weil Vorschriften es verlangen",
    "q.l20#13.e" to "Rettungsentscheidungen sind Ressourcenverteilung: Wenn zwei Retter beim Zugang verletzt werden, gehen Sie von einem Verletzten und zwei Rettern zu drei Verletzten und niemandem über. Das ist keine Kälte, sondern die Rechnung, die das Überleben insgesamt maximiert.",

    "q.l20#14.p" to "Wann sollte Selbstrettung aufhören und auf professionelle Rettung gewartet werden?",
    "q.l20#14.o0" to "Selbst retten, solange Kraft da ist",
    "q.l20#14.o1" to "Wenn Selbstrettung weitere Verletzungen riskiert oder die Bedingungen das Können der Gruppe übersteigen",
    "q.l20#14.o2" to "Erst bei völliger Erschöpfung",
    "q.l20#14.o3" to "Niemals mit der Selbstrettung aufhören",
    "q.l20#14.e" to "Selbstrettung dient dem Zeitgewinn, nicht dem Glücksspiel. Wenn Weitermachen den Verletzten oder die Retter schwerer verletzen könnte, oder wenn ein Sturm das Bewegen riskanter macht als das Bleiben, ist es die bessere Antwort, die Lage zu stabilisieren und auf Rückhalt zu warten.",

    "q.l20#15.p" to "Ergänzen Sie: Im SAMPLE-Schema steht E für ( ).",
    "q.l20#15.a0" to "Ereignis",
    "q.l20#15.a1" to "das Ereignis",
    "q.l20#15.a2" to "Vorfall",
    "q.l20#15.a3" to "Hergang",
    "q.l20#15.e" to "E steht für Event — Ereignis, also was passiert ist. Dieser Punkt wird oft unterschätzt: Der Mechanismus (wie der Sturz ablief, ob der Kopf aufschlug, wie lange die Verschüttung dauerte) weist direkt auf die wahrscheinlichen Verletzungen hin und ist ein entscheidender Hinweis in der Beurteilung.",

    // ---------- l21 Kleidung und Ausrüstung im Detail ----------
    "q.l21#0.p" to "Was ist im Drei-Schichten-System die Hauptaufgabe der Basisschicht?",
    "q.l21#0.o0" to "Wind und Schnee abhalten",
    "q.l21#0.o1" to "Schweiß von der Haut wegführen und Sie trocken halten",
    "q.l21#0.o2" to "Den größten Teil der Wärme liefern",
    "q.l21#0.o3" to "Ersatzteile verstauen",
    "q.l21#0.e" to "Die Kernfunktion der Basisschicht ist der Feuchtigkeitstransport. Sie liegt direkt auf der Haut, und bleibt sie feucht, wird Wärme abgezogen, egal wie viele Schichten Sie darüber tragen — deshalb heißt die Basisschicht auch zweite Haut.",

    "q.l21#1.p" to "Warum ist Fleece bei Nässe verlässlicher als Daune?",
    "q.l21#1.o0" to "Weil Fleece dicker ist",
    "q.l21#1.o1" to "Weil Polyesterfaser von Natur aus wasserabweisend ist und auch nass noch isoliert",
    "q.l21#1.o2" to "Weil Fleece billiger ist",
    "q.l21#1.o3" to "Weil Daune nicht als Innenschicht getragen werden kann",
    "q.l21#1.e" to "Fleece besteht aus Kunststofffaser (Polyester), die praktisch kein Wasser aufnimmt und deshalb auch feucht noch eine Luftschicht hält und isoliert. Daune fällt zusammen und verliert ihre Loft, sobald sie nass wird — deshalb muss Daune streng trocken bleiben.",

    "q.l21#2.p" to "Welche Fillpower wird für eine Daunenjacke im extremen Höhenwinter empfohlen?",
    "q.l21#2.o0" to "Unter 500",
    "q.l21#2.o1" to "Etwa 600",
    "q.l21#2.o2" to "800 Fillpower oder mehr",
    "q.l21#2.o3" to "Fillpower spielt keine Rolle",
    "q.l21#2.e" to "Je höher die Fillpower, desto mehr Luft hält dasselbe Gewicht Daune und desto effizienter die Isolation. Für Hochtouren empfiehlt man üblicherweise 800 und mehr, dazu eine Kapuze und keine Kunstfaserfüllung.",

    "q.l21#3.p" to "Was ist die Kernfunktion einer Hardshell-Jacke?",
    "q.l21#3.o0" to "Den größten Teil der Wärme liefern",
    "q.l21#3.o1" to "Wasserdicht, winddicht und atmungsaktiv, mit einer Kapuze, die über den Helm passt",
    "q.l21#3.o2" to "Schweiß nach außen führen",
    "q.l21#3.o3" to "Gewicht für den Trainingseffekt hinzufügen",
    "q.l21#3.e" to "Die Hülle hält Wind, Regen und Schnee ab und lässt die Feuchtigkeit entweichen, die Sie selbst produzieren. Ist die Atmungsaktivität schlecht, kondensiert der Schweißdampf in den inneren Schichten — dann schaffen Sie sich Ihre eigene feuchte Umgebung.",

    "q.l21#4.p" to "Welcher Handschuh im System ist speziell für die Bedienung von Touchscreens gedacht?",
    "q.l21#4.o0" to "Dünne Fleece-Handschuhe",
    "q.l21#4.o1" to "Ein winddichter und abriebfester Handschuh mit guter Touchscreen-Empfindlichkeit",
    "q.l21#4.o2" to "Dicke gefütterte Führerhandschuhe",
    "q.l21#4.o3" to "Gipfelhandschuhe",
    "q.l21#4.e" to "Telefon, GPS oder Kamera in der Höhe zu bedienen braucht einen Handschuh, der winddicht und zugleich touchscreenfähig ist. Handschuhe auszuziehen, um etwas zu bedienen, ist einer der häufigsten Auslöser für Erfrierungen — besser ein zusätzliches Paar genau dafür mitnehmen.",

    "q.l21#5.p" to "Welche Aussage zu Hand- und Fußwärmern ist richtig?",
    "q.l21#5.o0" to "Sie können außen an den Socken beliebig aufgeklebt werden",
    "q.l21#5.o1" to "Nur in geschlossenen Räumen wie Handschuh oder Schuhinnerem verwenden; an belüfteter Luft erreichen sie etwa 74 °C",
    "q.l21#5.o2" to "Je näher an der Haut, desto besser",
    "q.l21#5.o3" to "Sie können außen an der Mütze befestigt werden",
    "q.l21#5.e" to "Wärmer brauchen begrenzte Luft, um ihre Temperatur zu regeln. An belüfteter Luft reagieren sie heftig und erreichen rund 74 °C — genug für Verbrennungen. Deshalb gehören sie in geschlossene Räume wie Handschuhe und Schuhinneres und nie direkt auf die Haut oder auf eine freie Fläche.",

    "q.l21#6.p" to "Warum werden Isolations- und Daunenjacken mit Kapuze empfohlen?",
    "q.l21#6.o0" to "Weil sie besser aussehen",
    "q.l21#6.o1" to "Weil sie vielseitiger sind und den Wärmeverlust über den Kopf deutlich senken",
    "q.l21#6.o2" to "Weil sie sich leichter packen lassen",
    "q.l21#6.o3" to "Weil Kapuzenversionen leichter sind",
    "q.l21#6.e" to "Der Kopf ist eine wesentliche Wärmequelle nach außen, und eine Kapuze ist die leichteste Isolation direkt am Kern. Eine Jacke mit Kapuze ist im Lager, in Pausen oder bei plötzlichem Temperatursturz sofort einsatzbereit; ohne Kapuze müssen Sie eine separate Mütze mitnehmen — mehr Aufwand und mehr Gewicht.",

    "q.l21#7.p" to "[Mehrfachauswahl] Welche Regeln für Gebrauch und Lagerung einer Daunenjacke stimmen?",
    "q.l21#7.o0" to "Streng trocken halten; einmal feucht verliert sie schnell an Isolationskraft",
    "q.l21#7.o1" to "Trocken lagern",
    "q.l21#7.o2" to "Bei extremer Kälte eine Kapuzenversion ohne Kunstfaserfüllung wählen",
    "q.l21#7.o3" to "Je höher die Fillpower, desto wärmer bei gleichem Gewicht",
    "q.l21#7.o4" to "Dauerhaft im Kompressionssack lagern, um Platz zu sparen",
    "q.l21#7.e" to "Daune isoliert, indem sie Luft einschließt, und fällt nass zusammen. Deshalb wird bei Nässe Fleece (hydrophobes Polyester) als arbeitende Mittelschicht bevorzugt und Daune als Kernisolation für trockene Bedingungen aufgespart.",

    "q.l21#8.p" to "Was ist eine sinnvolle Spezifikation für Sonnencreme in der Höhe?",
    "q.l21#8.o0" to "SPF 15, eine gewöhnliche Lotion genügt",
    "q.l21#8.o1" to "Hoher Zinkoxidanteil, Niveau SPF 50",
    "q.l21#8.o2" to "Unter SPF 30 ist atmungsaktiver",
    "q.l21#8.o3" to "Irgendein Produkt mit Lichtschutz, unabhängig von der Zahl",
    "q.l21#8.e" to "UV ist in der Höhe intensiv, und die Reflexion des Schnees liefert eine zweite Dosis — gewöhnliche Sonnencreme reicht deshalb schnell nicht mehr. Hoher Zinkoxidanteil und SPF 50 sind die übliche Empfehlung, und sie muss planmäßig nachgetragen werden, weil Schweiß, Abwischen und Reibung den Schutz abbauen.",

    "q.l21#9.p" to "Worauf kommt es bei der Wahl eines Lippenpflegestifts für draußen an?",
    "q.l21#9.o0" to "Je billiger, desto besser",
    "q.l21#9.o1" to "Reich an Zink, einigermaßen schweißfest, mit SPF 30–50",
    "q.l21#9.o2" to "Feuchtigkeitsspendend genügt",
    "q.l21#9.o3" to "Menthol fühlt sich kühler an",
    "q.l21#9.e" to "Lippenhaut ist dünn und hat fast keinen Melaninschutz, brennt und reißt in der Höhe also leicht. Zink bietet physikalischen Schutz, und Schweißfestigkeit hält ihn beim Schwitzen, Essen und Trinken an Ort und Stelle — das kleinste Ausrüstungsteil, das am häufigsten vergessene und das, das das Tourengefühl am stärksten beeinflusst.",

    // ---------- l22 Technische Ausrüstung und Kommunikation ----------
    "q.l22#0.p" to "Was ist das grundlegendste Ausrüstungsteil für ein Spaltenrettungssystem?",
    "q.l22#0.o0" to "Prusikschlingen (Reepschnur)",
    "q.l22#0.o1" to "Ein Fernglas",
    "q.l22#0.o2" to "Ein Ersatzschlafsack",
    "q.l22#0.o3" to "Trekkingstöcke",
    "q.l22#0.e" to "Prusikschlingen dienen zum Knüpfen von Klemmknoten und sind der Kern eines 3:1-Flaschenzugs. Ohne sie haben Sie nur den 1:1-Zug Ihrer bloßen Hände — und eine Person schafft es fast nie, den Partner mit reiner Muskelkraft aus einer Spalte zu ziehen.",

    "q.l22#1.p" to "Was ist im Hochgebirge meist der verlässlichste Weg, Hilfe zu rufen?",
    "q.l22#1.o0" to "Mobilfunknetz",
    "q.l22#1.o1" to "Ein Satellitentelefon oder GPS-Tracker",
    "q.l22#1.o2" to "Rufen",
    "q.l22#1.o3" to "Ein Rauchfeuer anzünden",
    "q.l22#1.e" to "In den meisten Berggebieten gibt es kein Mobilfunknetz. Ein Satellitentelefon erlaubt Anruf und Nachricht direkt, ein GPS-Tracker lässt die Außenwelt Ihre Position verfolgen — beides muss vor dem Aufbruch geklärt sein, nicht am Berg.",

    "q.l22#2.p" to "Welche Helligkeit wird für eine Ersatz-Stirnlampe empfohlen?",
    "q.l22#2.o0" to "Unter 100 Lumen",
    "q.l22#2.o1" to "200 Lumen genügen",
    "q.l22#2.o2" to "400 Lumen oder mehr",
    "q.l22#2.o3" to "Die Helligkeit spielt keine Rolle",
    "q.l22#2.e" to "Eine Stirnlampe braucht man nachts im Zelt und für den Aufbruch vor der Dämmerung (Gipfeletappen beginnen meist in den frühen Morgenstunden). Bei Wind, Schnee, Nebel und wenn Sie die Route erkennen müssen, wirkt sich ausreichende Helligkeit direkt auf die Qualität Ihres Urteils aus. Wetterfeste Modelle sind bei schlechten Bedingungen klar besser.",

    "q.l22#3.p" to "Was ist die zentrale Anforderung an einen Bergsteigergurt?",
    "q.l22#3.o0" to "So leicht wie möglich, unabhängig von der Größe",
    "q.l22#3.o1" to "In Taille und Beinschlaufen groß genug, um über die äußerste Kleidungsschicht zu passen",
    "q.l22#3.o2" to "Er muss mehrere Materialschlaufen haben",
    "q.l22#3.o3" to "Eine auffällige Farbe",
    "q.l22#3.e" to "In der Höhe tragen Sie meist voluminöse Kleidung, und der Gurt muss darüber noch korrekt sitzen. Einen Gurt bis zur letzten Einstellung zu strecken, nur damit er über dicke Schichten schließt, ist eine häufige und gefährliche Fehlkonfiguration.",

    "q.l22#4.p" to "Womit erkennt die Sturmalarm-Funktion einer Höhenmesseruhr Stürme?",
    "q.l22#4.o0" to "Mit Satelliten-Wolkenbildern",
    "q.l22#4.o1" to "Mit einem schnellen Luftdruckabfall in kurzer Zeit",
    "q.l22#4.o2" to "Mit einer Windgeschwindigkeitsmessung",
    "q.l22#4.o3" to "Mit einem plötzlichen Temperatursturz",
    "q.l22#4.e" to "Ein schneller Druckabfall ist das Vorzeichen sich verschlechternden Wetters. Die Höhenmesseruhr warnt, indem sie die Druckänderung laufend verfolgt — in der Höhe sehr praktisch, weil die Verschiebung des Wetterfensters oft die entscheidende Variable einer Tour ist.",

    "q.l22#5.p" to "[Zuordnung] Ordnen Sie jeder Karabinerform die passendste Verwendung zu.",
    "q.l22#5.l0" to "HMS birnenförmig",
    "q.l22#5.r0" to "Weite Schnapperöffnung; nimmt den Halbmastwurf zum Abseilen, am vielseitigsten",
    "q.l22#5.l1" to "D-Form",
    "q.l22#5.r1" to "Häufig mit Umlenkrolle in Rettungssystemen kombiniert",
    "q.l22#5.l2" to "X-Form",
    "q.l22#5.r2" to "Symmetrisch, einfache Verschlusssicherung, leicht einzuhängen",
    "q.l22#5.l3" to "B-Form",
    "q.l22#5.r3" to "Der Basiskarabiner für alle möglichen temporären Verbindungen",
    "q.l22#5.e" to "Jede Form hat ihre Stärke: HMS öffnet weit genug für Knoten und Abseilen, D ist kräftig und nimmt eine Rolle gut auf, X ist symmetrisch und handlich, B ist der Allzweck-Grundtyp. Bei der Wahl geht es nicht darum, welcher stärker ist, sondern ob der Mechanismus zur Aufgabe passt.",

    "q.l22#6.p" to "Wovor warnt das Handbuch beim Einsatz eines Steigklemmen-Geräts ausdrücklich?",
    "q.l22#6.o0" to "Vor dem Einsatz bei Nässe",
    "q.l22#6.o1" to "Davor, das Gerät zu nah an das feste Ende (einen Knoten) zu schieben",
    "q.l22#6.o2" to "Vor einhändiger Bedienung",
    "q.l22#6.o3" to "Vor dem Einsatz auf Schnee",
    "q.l22#6.e" to "Direkt an einen Knoten oder Fixpunkt geschoben, kann das Gerät nicht weiterlaufen und lässt sich zugleich schwer schnell lösen — dann sitzen Sie fest: weder hinauf noch frei. Diese Art Klemmen ist gefährlich, wenn Sie schnell umbauen müssen; lösen Sie es, solange Sie noch Reserve haben.",

    "q.l22#7.p" to "Welche Aussage zum Vergleich von Fixseilen und Anseilen der Gruppe stimmt?",
    "q.l22#7.o0" to "Fixseile sind immer sicherer als das Anseilen der Gruppe",
    "q.l22#7.o1" to "Große Gruppen nutzen eher Fixseile; kleine Gruppen oder technische Gipfel sind angeseilt effizienter",
    "q.l22#7.o2" to "Angeseiltes Gehen eignet sich nur für Schneehänge",
    "q.l22#7.o3" to "Fixseile sind nur für den Abstieg",
    "q.l22#7.e" to "Fixseile erhöhen die Sicherheit insgesamt, brauchen aber mehr Leute und Material und längere Einrichtungszeit. Eine kleine, eingespielte Gruppe oder ein technischer Gipfel ist angeseilt oft besser bedient. Es ist das Lehrbuchbeispiel für: keine grundsätzlich beste Antwort, nur die passende.",

    "q.l22#8.p" to "[Mehrfachauswahl] Welche dieser Geräte dienen der Kommunikation und Navigation in der Höhe?",
    "q.l22#8.o0" to "Satellitentelefon",
    "q.l22#8.o1" to "Handsprechfunkgerät",
    "q.l22#8.o2" to "GPS-Tracker",
    "q.l22#8.o3" to "Höhenmesseruhr mit Barometer",
    "q.l22#8.o4" to "Fernglas",
    "q.l22#8.e" to "Die vier haben verschiedene Aufgaben: das Satellitentelefon für den Notruf nach außen, das Funkgerät für die Abstimmung in der Gruppe, der GPS-Tracker damit die Außenwelt weiß, wo Sie sind, und die Höhenmesseruhr für Druck- und Höhentrends. Die Risiken in der Höhe sind genau das: nicht rufen zu können und nicht zu wissen, wo man ist — diese Geräte adressieren beides direkt.",

    "q.l22#9.p" to "Warum muss ein Helm eine Halterung für die Stirnlampe aufnehmen können?",
    "q.l22#9.o0" to "Für ein einheitliches Aussehen",
    "q.l22#9.o1" to "Weil Gipfeletappen meist vor Sonnenaufgang beginnen und die Lampe stabil am Kopf sitzen muss",
    "q.l22#9.o2" to "Um das Gewicht der Stirnlampe zu senken",
    "q.l22#9.o3" to "Um die Festigkeit des Helms zu erhöhen",
    "q.l22#9.e" to "Der Gipfeltag beginnt meist in den frühen Morgenstunden, und die Stirnlampe ist die einzige Lichtquelle; mit Helm muss sie am Helm sitzen, um ruhig zu leuchten. Eine Lampe, die wackelt oder abgeht, während Sie in Bewegung sind, heißt: Sie sehen die Tritte nicht — in technischem Gelände ein echtes Risiko.",

    // ---------- m01 Die Wissenschaft der Höhe ----------
    "q.m01#0.p" to "Um wie viel fällt die Lufttemperatur je 1.000 m Aufstieg ungefähr?",
    "q.m01#0.o0" to "Etwa 1,5 °C",
    "q.m01#0.o1" to "Etwa 3 °C",
    "q.m01#0.o2" to "Etwa 6,5 °C",
    "q.m01#0.o3" to "Etwa 10 °C",
    "q.m01#0.e" to "Die Temperatur sinkt um etwa 6,5 °C je 1.000 m — der Umgebungstemperaturgradient. Er erklärt die Höhe der Schneegrenze und warum ein 5.000er auch im Sommer schneebedeckt bleibt.",

    "q.m01#1.p" to "Was ist die grundlegende Ursache der Hypoxie in der Höhe?",
    "q.m01#1.o0" to "Der Sauerstoffanteil der Luft ist geringer",
    "q.m01#1.o1" to "Der Luftdruck fällt, damit sinkt der Sauerstoffpartialdruck in jedem Atemzug",
    "q.m01#1.o2" to "Ultraviolettes Licht zerlegt den Sauerstoff",
    "q.m01#1.o3" to "Die Luft wird dünn und Sauerstoff durch andere Gase ersetzt",
    "q.m01#1.e" to "Das ist ein sehr verbreiteter Irrtum. Sauerstoff macht in der Höhe weiterhin etwa 21 % der Luft aus — der Anteil ändert sich nicht. Was sich ändert, ist der Druck: Bei niedrigerem Druck sind im gleichen Volumen weniger Sauerstoffmoleküle, also sinkt der Partialdruck und der Körper bekommt weniger Sauerstoff.",

    "q.m01#2.p" to "[Mehrfachauswahl] Welche Merkmale sind für die Höhenumgebung typisch?",
    "q.m01#2.o0" to "Niedriger Druck und niedriger Sauerstoffpartialdruck",
    "q.m01#2.o1" to "Niedrige Temperatur mit großem Tag-Nacht-Unterschied",
    "q.m01#2.o2" to "Deutlich stärkere ultraviolette Strahlung",
    "q.m01#2.o3" to "Sehr trockene Luft",
    "q.m01#2.o4" to "Ein deutlich geringerer Sauerstoffanteil der Luft",
    "q.m01#2.e" to "Die ersten vier stimmen, und sie verstärken sich gegenseitig: Kälte plus Hypoxie heißt, der Körper kämpft zugleich um Wärme und um Sauerstoff; Trockenheit plus starke UV schädigen Atemwege, Haut und Augen schneller. Ausrüstung und Zeitplan müssen alle vier gleichzeitig abdecken.",

    "q.m01#3.p" to "Der Druck auf Meereshöhe liegt bei etwa 1.013 hPa. Wie hoch ist der Druck in 5.000 m?",
    "q.m01#3.o0" to "Etwa 900 hPa",
    "q.m01#3.o1" to "Etwa 700 hPa",
    "q.m01#3.o2" to "Etwa 540 hPa",
    "q.m01#3.o3" to "Etwa 300 hPa",
    "q.m01#3.e" to "In 5.000 m liegt der Druck etwa bei der Hälfte des Meeresspiegelniveaus. Jeder Atemzug enthält damit rund halb so viele Sauerstoffmoleküle — der Körper gleicht das über höhere Atem- und Herzfrequenz aus, und das ist der physikalische Grund, warum Sie oben außer Atem und langsamer sind.",

    "q.m01#4.p" to "Ergänzen Sie: Die Temperatur fällt um etwa ( ) °C je 1.000 m Aufstieg.",
    "q.m01#4.a0" to "6.5",
    "q.m01#4.a1" to "sechs Komma fünf",
    "q.m01#4.e" to "6,5 °C je 1.000 m. Diese Zahl ist für die Planung wirklich nützlich: Von einem 3.000er Basislager auf 5.000 m zu gehen heißt rund 13 °C kälter, und das entscheidet direkt, wie dick Daunenjacke und Schlafsack sein müssen.",

    "q.m01#5.p" to "[Reihenfolge] Bringen Sie die Wirkungskette der Höhenhypoxie in Ordnung.",
    "q.m01#5.o0" to "Der Luftdruck fällt und senkt den eingeatmeten Sauerstoffpartialdruck",
    "q.m01#5.o1" to "Die arterielle Sauerstoffsättigung sinkt",
    "q.m01#5.o2" to "Der Körper gleicht mit höherer Atem- und Herzfrequenz aus",
    "q.m01#5.o3" to "Anhaltende Hypoxie kann in Höhenkrankheit übergehen",
    "q.m01#5.e" to "Diese Kette ist das Skelett der Höhenmedizin: Umwelt, Physiologie, Kompensation, Dekompensation. Wer sie einmal sieht, versteht AMS, HACE und HAPE nicht mehr als getrennte Fakten, sondern als verschiedene Stufen einer Kette.",

    "q.m01#6.p" to "Wie hoch ist das Reflexionsvermögen von Neuschnee?",
    "q.m01#6.o0" to "Etwa 20 %",
    "q.m01#6.o1" to "Etwa 40 %",
    "q.m01#6.o2" to "Etwa 60 %",
    "q.m01#6.o3" to "Etwa 80–90 %",
    "q.m01#6.e" to "Neuschnee reflektiert rund 80–90 % der Sonnenstrahlung. Die UV-Belastung auf einem Schneefeld ist damit fast doppelt so hoch — direkt von oben plus reflektiert von der Oberfläche. Deshalb sind Schneeblindheit und schwere Sonnenbrände im Gebirge so häufig.",

    "q.m01#7.p" to "Warum ist Sonnenschutz in der Höhe Pflicht und nicht Kür?",
    "q.m01#7.o0" to "Weil die Sonne dort näher an der Erde ist",
    "q.m01#7.o1" to "Weil die UV-Strahlung mit der Höhe zunimmt und der Schnee sie ins Gesicht zurückwirft",
    "q.m01#7.o2" to "Weil die Ozonschicht dünner ist und sichtbares Licht stärker wird",
    "q.m01#7.o3" to "Weil Kälte die Widerstandskraft der Haut senkt",
    "q.m01#7.e" to "Die UV-Intensität steigt um etwa 10–12 % je 1.000 m, und Schnee liefert zusätzlich 80–90 % Reflexion. Zusammen liegt die Dosis weit über der eines Ortes gleicher Breite im Tiefland. Sonnencreme, Lippenpflege und UV400-Brille sind Ausrüstung, kein Extra.",

    "q.m01#8.p" to "Trockene Luft in der Höhe hat eine leicht übersehene Folge. Welche?",
    "q.m01#8.o0" to "Bessere Haut",
    "q.m01#8.o1" to "Unbemerkter Wasserverlust über Atmung und Schwitzen, was Dehydrierung und Höhensymptome verschlimmert",
    "q.m01#8.o2" to "Größerer Appetit",
    "q.m01#8.o3" to "Tieferer Schlaf",
    "q.m01#8.e" to "Trockene Luft und schnellere Atmung entziehen den Atemwegen laufend Feuchtigkeit, und oft spüren Sie gar keinen Durst. Dehydrierung verdickt das Blut und verstärkt das Gefühl von Sauerstoffmangel und Kopfschmerz — regelmäßiges Trinken gehört deshalb zur Akklimatisierung, nicht zum Nachgedanken.",

    "q.m01#9.p" to "[Mehrfachauswahl] Welche dieser Schäden entstehen direkt durch die Höhenumgebung?",
    "q.m01#9.o0" to "Sonnenbrand",
    "q.m01#9.o1" to "Schneeblindheit",
    "q.m01#9.o2" to "Dehydrierung",
    "q.m01#9.o3" to "Aufgesprungene Lippen",
    "q.m01#9.o4" to "Ein verknackster Knöchel",
    "q.m01#9.e" to "Die ersten vier sind Umgebungsschäden, und sie teilen ein Merkmal: Sie sind fast vollständig vermeidbar. Anders als Lawinen sind sie nicht schwer vorherzusagen — sie hängen allein an Ausrüstung und Gewohnheiten, deshalb deutet ihr Auftreten in einer Gruppe meist auf einen Fehler in der Vorbereitung.",

    "q.m01#10.p" to "Welche Aussage zur Zusammensetzung der Luft in der Höhe ist richtig?",
    "q.m01#10.o0" to "Der Sauerstoffanteil fällt mit zunehmender Höhe",
    "q.m01#10.o1" to "Der Anteil bleibt etwa gleich; der niedrigere Druck senkt den Partialdruck",
    "q.m01#10.o2" to "Der Stickstoffanteil steigt mit der Höhe",
    "q.m01#10.o3" to "Sauerstoff wird in der Höhe von anderen Gasen verdrängt",
    "q.m01#10.e" to "In der Troposphäre ist das Gemisch praktisch konstant (etwa 21 % Sauerstoff, 78 % Stickstoff). Was sich mit der Höhe ändert, ist der Druck — wie viele Moleküle in diesem einen Atemzug sind. Ist dieser Unterschied klar, werden viele Ausrüstungs- und Physiologiefragen einfach.",

    "q.m01#11.p" to "Warum sind 5.000er im Sommer noch schneebedeckt?",
    "q.m01#11.o0" to "Weil hohe Orte weiter von der Sonne entfernt sind",
    "q.m01#11.o1" to "Weil die Höhenluft viel kälter ist als das Tiefland gleicher Breite, sodass Niederschlag als Schnee fällt",
    "q.m01#11.o2" to "Weil starke Gipfelwinde das Schmelzen verhindern",
    "q.m01#11.o3" to "Weil gepresster Schnee zu Eis wird und nie mehr schmilzt",
    "q.m01#11.e" to "Die Regel von 6,5 °C je 1.000 m hält die Sommertemperaturen in 5.000 m unter dem Gefrierpunkt. Sie erklärt auch, warum derselbe Berg in einer Jahreszeit schwieriger ist als in einer anderen — die Schneegrenze verschiebt sich, und mit ihr die Route.",

    "q.m01#12.p" to "Von einem 3.000er Basislager zu einem Lager auf 5.000 m: Wie viel kälter ist es dort nach dem mittleren Gradienten ungefähr?",
    "q.m01#12.a0" to "13",
    "q.m01#12.e" to "13 °C. Die Rechnung: 2.000 m Aufstieg bei 6,5 °C je 1.000 m ergibt 2 × 6,5 = 13 °C. Diese Schätzung ist vor einer Tour sehr praktisch — sie entscheidet, wie dick Isolation und Schlafsack sein müssen.",

    // ---------- m02 Kondition und Ernährung ----------
    "q.m02#0.p" to "Welche Art von Fitness zählt für das Höhenbergsteigen am meisten?",
    "q.m02#0.o0" to "Explosivkraft und kurze Sprints",
    "q.m02#0.o1" to "Ausdauer über Stunden",
    "q.m02#0.o2" to "Maximale Griffkraft",
    "q.m02#0.o3" to "Beweglichkeit",
    "q.m02#0.e" to "Höhenbergsteigen ist lange, niedrig intensive Arbeit: sechs bis zehn Stunden am Tag, nie steil, aber unablässig. Hypoxie begrenzt die anaerobe Kapazität stark, deshalb trägt Sie eine aerobe Basis und die Fähigkeit, ein gleichmäßiges Tempo zu halten.",

    "q.m02#1.p" to "Wie sollte das Training vor dem Aufbruch aufgebaut sein?",
    "q.m02#1.o0" to "In der Woche davor alles nachholen",
    "q.m02#1.o1" to "In den letzten zwei bis drei Wochen reduzieren und erholt losgehen",
    "q.m02#1.o2" to "Bis zum Vortag mit maximaler Intensität trainieren",
    "q.m02#1.o3" to "Gar nicht trainieren, auf die Akklimatisierung vor Ort setzen",
    "q.m02#1.e" to "Trainingsgewinne entstehen in der Erholung. Müde anzureisen untergräbt Leistung und Akklimatisierung — und die Akklimatisierung selbst kostet Energie. Das Tapern ist der Schritt, der Training in Form übersetzt.",

    "q.m02#2.p" to "Worauf sollte die Ernährung in der Höhe aufbauen?",
    "q.m02#2.o0" to "Fettreiche Kost",
    "q.m02#2.o1" to "Kohlenhydrate",
    "q.m02#2.o2" to "Eiweißreiche Kost",
    "q.m02#2.o3" to "Nur Flüssigkeit",
    "q.m02#2.e" to "Kohlenhydrate werden effizienter verstoffwechselt und verbrauchen unter Hypoxie weniger Sauerstoff, und der Körper bevorzugt sie in der Höhe instinktiv. Das läuft der Intuition zuwider, Höhe verlange kaloriendichtes Fett — die Begrenzung ist die Sauerstoffeffizienz.",

    "q.m02#3.p" to "Was ist ein praktischer Hinweis auf ausreichende Flüssigkeitszufuhr?",
    "q.m02#3.o0" to "Wie durstig Sie sich fühlen",
    "q.m02#3.o1" to "Hellbleibender Urin",
    "q.m02#3.o2" to "Feste 1 Liter pro Tag trinken",
    "q.m02#3.o3" to "Veränderungen des Körpergewichts",
    "q.m02#3.e" to "Durst ist in der Höhe unzuverlässig — Kälte und Hypoxie dämpfen ihn beide. Urinfarbe und -geruch sind ein direkteres Tagesmaß: hell heißt ungefähr genug, dunkler und strenger heißt mehr trinken.",

    "q.m02#4.p" to "Warum in der Höhe auf Alkohol verzichten?",
    "q.m02#4.o0" to "Weil man davon zunimmt",
    "q.m02#4.o1" to "Weil er den Atemantrieb dämpft und die nächtliche Hypoxie verschlimmert",
    "q.m02#4.o2" to "Weil er UV-Schäden beschleunigt",
    "q.m02#4.o3" to "Weil es keinen Kühlschrank gibt",
    "q.m02#4.e" to "Alkohol und Sedativa dämpfen beide das Atemzentrum. Nächte in der Höhe neigen ohnehin zu periodischer Atmung, und zusätzliche Atemdämpfung senkt die Sättigung deutlich — einer der zentralen Mechanismen, durch die sich Höhenkrankheit über Nacht verschlechtert.",

    "q.m02#5.p" to "[Mehrfachauswahl] Wie nimmt man in der Höhe beim Gehen richtig Energie auf?",
    "q.m02#5.o0" to "Kleine Mengen oft, bevor Sie hungern",
    "q.m02#5.o1" to "Leicht verdauliche Kost mit etwas Wassergehalt bevorzugen",
    "q.m02#5.o2" to "Auf Kohlenhydraten aufbauen",
    "q.m02#5.o3" to "Eine große Mahlzeit essen, um Essenszeiten zu sparen",
    "q.m02#5.e" to "Klein und oft erleichtert die Verdauung und hält den Blutzucker stabil. Eine große Mahlzeit verursacht unter Hypoxie leicht Blähungen und Übelkeit — und da Appetitlosigkeit selbst ein häufiges Symptom ist, bewirkt erzwungenes Essen das Gegenteil.",

    "q.m02#6.p" to "Der Appetit sinkt in der Höhe. Was ist die richtige Reaktion?",
    "q.m02#6.o0" to "Aufhören zu essen und auf Hunger warten",
    "q.m02#6.o1" to "Bewusst essen und kohlenhydratreiche, leicht verdauliche Kost wählen",
    "q.m02#6.o2" to "Viel Kaffee statt Essen trinken",
    "q.m02#6.o3" to "Nur Elektrolyte nehmen",
    "q.m02#6.e" to "Appetitlosigkeit gehört zur Höhenkrankheit, und zu wenig zu essen schwächt die Akklimatisierung — ein Teufelskreis. Bewusst essen, in kleinen Mengen, oft: Es geht nicht darum, ob Sie Hunger spüren, sondern das ist eine notwendige Maßnahme.",

    "q.m02#7.p" to "Welche Aussage zu Fitness und Höhe ist richtig?",
    "q.m02#7.o0" to "Wer fit ist, bekommt keine Höhenkrankheit",
    "q.m02#7.o1" to "Fitness verbessert die Leistung, ersetzt aber keine Akklimatisierung",
    "q.m02#7.o2" to "Untrainierte sollten nicht in die Höhe gehen",
    "q.m02#7.o3" to "Je fitter, desto weniger Akklimatisierung nötig",
    "q.m02#7.e" to "Fitness und Akklimatisierung sind zwei getrennte Linien. Eine fitte Person fühlt sich auf gleicher Höhe vielleicht wohler, aber die Physiologie braucht weiterhin Zeit in Tagen — 'Ich bin fit' als 'Ich werde nicht krank' zu lesen ist die Logik hinter vielen Unfällen.",

    "q.m02#8.p" to "[Reihenfolge] Bringen Sie eine sinnvolle Vorbereitung vor der Tour in zeitliche Ordnung.",
    "q.m02#8.o0" to "Grundlagenausdauer trainieren (zwei bis drei Monate vorher)",
    "q.m02#8.o1" to "Tapern und Erholung sichern (zwei bis drei Wochen vorher)",
    "q.m02#8.o2" to "Ausrüstung, Zeitplan und Versicherung prüfen (eine Woche vorher)",
    "q.m02#8.o3" to "Planmäßig akklimatisieren (während der Tour)",
    "q.m02#8.e" to "Die Reihenfolge ist die Methode: früh trainieren, Raum zur Erholung lassen, detailliert vorbereiten, langsam akklimatisieren. Am häufigsten aus dem Takt geraten die letzten beiden Schritte — viele prüfen die Ausrüstung gründlich und hetzen dann am Berg dem Zeitplan nach, mit verkürzter Akklimatisierung.",

    "q.m02#9.p" to "Welches Problem kann übermäßiges Trinken (viel in kurzer Zeit) in der Höhe verursachen?",
    "q.m02#9.o0" to "Gar keines",
    "q.m02#9.o1" to "Es verdünnt die Blutelektrolyte und verursacht in schweren Fällen eine Hyponatriämie",
    "q.m02#9.o2" to "Es verhindert wirksam ein Lungenödem",
    "q.m02#9.o3" to "Es kann Essen ersetzen",
    "q.m02#9.e" to "Genug trinken heißt nicht verzweifelt trinken. Eine große Menge in kurzer Zeit ohne Elektrolyte kann das Natrium im Blut verdünnen und Kopfschmerz, Übelkeit und Bewusstseinsstörung auslösen — Symptome, die der Höhenkrankheit sehr ähneln und leicht fehlgedeutet werden. Die Antwort ist gleichmäßige, ausreichende Zufuhr.",

    // ---------- m03 Low Impact (LNT) ----------
    "q.m03#0.p" to "Was bedeutet das Low-Impact-Prinzip im Kern?",
    "q.m03#0.o0" to "Leichtere Ausrüstung tragen, um den eigenen Körper zu schonen",
    "q.m03#0.o1" to "Die Wirkung menschlicher Aktivität auf die Bergumwelt minimieren",
    "q.m03#0.o2" to "Die Schwierigkeit der Tour senken, um sicher zu bleiben",
    "q.m03#0.o3" to "Die Zahl der Leute in der Gruppe verringern",
    "q.m03#0.e" to "Das Low-Impact-Prinzip ist die Umweltethik des Outdoor-Bergsteigens. Es geht nicht darum, wie leicht Sie unterwegs sind, sondern darum, wie stark der Berg durch Ihre Anwesenheit verändert wird — Müll, Trittspuren, Feuer und Störung von Wildtieren zählen alle dazu.",

    "q.m03#1.p" to "Wie geht man beim Verlassen des Lagers mit Müll richtig um?",
    "q.m03#1.o0" to "Essensreste können vor Ort vergraben werden",
    "q.m03#1.o1" to "Alles mitnehmen, einschließlich Toilettenpapier und Hygienartikeln",
    "q.m03#1.o2" to "Nur Plastik mitnehmen",
    "q.m03#1.o3" to "In einer Grube verbrennen",
    "q.m03#1.e" to "Das Handbuch ist eindeutig: Alles, was Sie produzieren, in Beutel packen und mitnehmen, Lager und Aktivitätsbereich kontrollieren und Hygienartikel wie Toilettenpapier mitnehmen. Vergraben und Verbrennen hinterlassen beide Spuren, und unter kalten Höhenbedingungen zersetzt sich Abfall extrem langsam.",

    "q.m03#2.p" to "Welches Prinzip leitet die Wahl des Ortes für ein Notgeschäft in der Natur?",
    "q.m03#2.o0" to "Je versteckter, desto besser — Privatsphäre zuerst",
    "q.m03#2.o1" to "Abseits von Wasserquellen, Lagern und Wegen",
    "q.m03#2.o2" to "Wo der Schnee am flachsten liegt",
    "q.m03#2.o3" to "Nahe am Bach, damit es weggespült wird",
    "q.m03#2.e" to "Das Ziel ist, Wasser nicht zu verunreinigen und nicht die nächste Gruppe hineinlaufen zu lassen. Praktisch heißt das: definierter Abstand zu Wasser und Wegen, ein flaches Loch, benutztes Papier mitnehmen — und oberhalb der Schneegrenze alles mitnehmen, weil es dort kaum verrottet.",

    "q.m03#3.p" to "Warum Essen und Müll dicht verschließen?",
    "q.m03#3.o0" to "Damit es nicht feucht wird",
    "q.m03#3.o1" to "Damit Tiere es nicht plündern und nicht zahm werden",
    "q.m03#3.o2" to "Um Platz im Rucksack zu sparen",
    "q.m03#3.o3" to "Damit man es leichter wiegen kann",
    "q.m03#3.e" to "Tiere, die Nahrung plündern, werden meist von Gruppen dazu erzogen: Sobald sie Lager mit Futter verbinden, steigt das Risiko auf dieser Route dauerhaft. Verschließen schützt Ihr Essen, die Tiere und alle, die nach Ihnen kommen.",

    "q.m03#4.p" to "Was bezeichnet die sensible Phase bei Wildtieren vor allem?",
    "q.m03#4.o0" to "Die Fresszeiten am Tag",
    "q.m03#4.o1" to "Paarungs- und Säugezeit",
    "q.m03#4.o2" to "Die Wanderzeit",
    "q.m03#4.o3" to "Die Winterruhe",
    "q.m03#4.e" to "Tiere sind während Paarung und Jungenaufzucht besonders störungsempfindlich, und eine Mutter, die Junge verteidigt, kann aggressiv werden. Deshalb neben ihrem Lebensraum auch feste Tränkezeiten und -orte meiden — das schützt sie und Sie.",

    "q.m03#5.p" to "Warum auf bestehenden Wegen bleiben?",
    "q.m03#5.o0" to "Weil die Regeln es verlangen",
    "q.m03#5.o1" to "Weil Tritte dauerhafte neue Pfade schaffen und Erosion auslösen",
    "q.m03#5.o2" to "Weil Wege leichter zu gehen sind",
    "q.m03#5.o3" to "Weil Bergführer sie markieren",
    "q.m03#5.e" to "Höhenvegetation wächst extrem langsam; ein einzelner Tritt kann Jahre sichtbar bleiben. Parallele Abkürzungen schneiden in die Vegetation und bündeln den Wasserabfluss, bis daraus Rinnen werden — so beginnt eine Route zu verfallen.",

    "q.m03#6.p" to "[Mehrfachauswahl] Was muss aus den Bergen mitgenommen werden?",
    "q.m03#6.o0" to "Verpackungen von Lebensmitteln",
    "q.m03#6.o1" to "Obstschalen und Essensreste",
    "q.m03#6.o2" to "Benutztes Toilettenpapier",
    "q.m03#6.o3" to "Zigarettenstummel",
    "q.m03#6.o4" to "Klebeband und Schnur dürfen vor Ort verbrannt werden",
    "q.m03#6.e" to "Die ersten vier gehen alle mit Ihnen hinaus. Das häufigste Missverständnis sind Obstschalen und Reste — sie wirken kompostierbar, zersetzen sich unter kalten, trockenen Bedingungen aber sehr langsam und locken Tiere an, deren Verhalten sich dadurch ändert.",

    "q.m03#7.p" to "Welche Haltung ist richtig, wenn man natürliche Dinge (Steine, Pflanzen, Fossilien) als Souvenir sammeln will?",
    "q.m03#7.o0" to "Kleine Stücke darf man mitnehmen",
    "q.m03#7.o1" to "Nichts Natürliches mitnehmen — stattdessen fotografieren",
    "q.m03#7.o2" to "In Ordnung, solange man die Umwelt nicht schädigt",
    "q.m03#7.o3" to "Sammeln hilft der Wissenschaft",
    "q.m03#7.e" to "Nur Fotos mitnehmen, nur Fußspuren hinterlassen ist die klassische Formel. Natürliche Dinge sind Teil der lokalen Ökologie und Landschaft, und wenn jede Gruppe ein bisschen mitnimmt, ist der kumulative Effekt erheblich.",

    "q.m03#8.p" to "Wie wirkt das Bergsteigen vor allem auf die Bergumwelt?",
    "q.m03#8.o0" to "Nur durch Müll",
    "q.m03#8.o1" to "Schäden an der Vegetation, schrumpfender Lebensraum der Tiere, Müll und der kulturelle Einfluss fremder Besucher auf lokale Gemeinschaften",
    "q.m03#8.o2" to "Vor allem durch Lärm",
    "q.m03#8.o3" to "Die Wirkung ist vernachlässigbar",
    "q.m03#8.e" to "Das Handbuch trennt ökologische und soziale Wirkung: Vegetationsschäden, Verdrängung von Tieren und Müll auf der einen Seite, kultureller Druck auf lokale Lebensweisen auf der anderen. Das zu verstehen ist der Grund, warum Etikette Teil der Bergsteigerausbildung ist.",

    "q.m03#9.p" to "[Reihenfolge] Bringen Sie das Low-Impact-Abschiedsritual beim Lagerabbau in die richtige Reihenfolge.",
    "q.m03#9.o0" to "Persönliche und Gruppenausrüstung einpacken",
    "q.m03#9.o1" to "Allen Müll sortieren und in Beutel packen",
    "q.m03#9.o2" to "Menschliche Hinterlassenschaften regeln (vergraben oder mitnehmen)",
    "q.m03#9.o3" to "Lager und Aktivitätsbereich abgehen und prüfen, dass nichts bleibt",
    "q.m03#9.e" to "Der letzte Schritt — der Rundgang — wird am häufigsten übersprungen und ist der wichtigste: Man nimmt instinktiv 'seine eigenen Sachen' mit, und genau so bleiben Heringe, Seilenden und weggewehte Verpackungen liegen. Ein Blick zurück kostet fast nichts.",

    // ---------- m04 Wetter und Karte ----------
    "q.m04#0.p" to "Was ist das verlässlichste Zeichen für einen Wetterumschwung?",
    "q.m04#0.o0" to "Ob es gerade sonnig ist",
    "q.m04#0.o1" to "Der Trend von Druck, Bewölkung und Wind",
    "q.m04#0.o2" to "Die Vorhersage von vor dem Aufbruch",
    "q.m04#0.o3" to "Wie sich Ihre Partner fühlen",
    "q.m04#0.e" to "Der Moment ist ein Schnappschuss, der Trend ist die Richtung. Druck fällt stetig, Bewölkung wird dichter und tiefer, Wind frischt auf — treten alle drei zusammen auf, dreht das Wetter. Darin liegt der praktische Wert eines Barometers, ob in der Uhr oder separat.",

    "q.m04#1.p" to "Was ist für Cumulonimbus typisch, und was bedeutet es?",
    "q.m04#1.o0" to "Dünn und gleichmäßig — stabiles Wetter",
    "q.m04#1.o1" to "Vertikale Entwicklung mit Amboss oben — Gewitter und starker Niederschlag",
    "q.m04#1.o2" to "Schichtartig ausgebreitet — nur Niesel",
    "q.m04#1.o3" to "Faserige Schleier — gutes Wetter",
    "q.m04#1.e" to "Das vertikale Wachstum zeigt starke Konvektion, und der Amboss bedeutet, dass er seine Reife erreicht hat. So einer in der Höhe bedeutet: Blitz, Hagel und starker Niederschlag sind alle möglich — verlassen Sie sofort exponierte Grate und hohe Flächen.",

    "q.m04#2.p" to "Welche Kartenmaßstäbe sind im Bergsteigen üblich?",
    "q.m04#2.o0" to "1:1.000 und 1:5.000",
    "q.m04#2.o1" to "1:50.000 und 1:10.000",
    "q.m04#2.o2" to "1:250.000 und 1:500.000",
    "q.m04#2.o3" to "Jeder Maßstab ist geeignet",
    "q.m04#2.e" to "1:50.000 und 1:10.000 sind das übliche Paar: das erste deckt eine große Fläche ab und eignet sich für die Tourenplanung, das zweite trägt Details und eignet sich für technisches Gelände. 1:200.000 wird gelegentlich genutzt, 1:10.000 seltener — das Blatt deckt so wenig Fläche ab, dass Sie schnell darüber hinaus sind.",

    "q.m04#3.p" to "Was bedeuten eng stehende Höhenlinien auf einer topografischen Karte?",
    "q.m04#3.o0" to "Einen flachen Hang",
    "q.m04#3.o1" to "Einen steilen Hang",
    "q.m04#3.o2" to "Ein Tal",
    "q.m04#3.o3" to "Einen Gletscher",
    "q.m04#3.e" to "Je enger die Höhenlinien, desto mehr Höhe wird auf gleicher horizontaler Distanz gewonnen — anders gesagt: desto steiler. Das ist eine nützliche Lesefähigkeit in der Planung: Sie können steile Passagen, Verflachungen und mögliche Zeltplätze schon vor dem Aufbruch markieren.",

    "q.m04#4.p" to "Was zeigt eine geschlossene Höhenlinie auf einer topografischen Karte?",
    "q.m04#4.o0" to "Einen See",
    "q.m04#4.o1" to "Einen eigenständigen Gipfel",
    "q.m04#4.o2" to "Einen Gletscher",
    "q.m04#4.o3" to "Eine Felswand",
    "q.m04#4.e" to "Eine geschlossene Höhenlinie heißt, dass das Massiv nach allen Seiten abfällt — genau die Definition eines eigenständigen Gipfels. Mehrere konzentrische geschlossene Ringe bedeuten, dass der Berg stufenweise ansteigt, wobei der innerste Ring den Gipfelbereich markiert.",

    "q.m04#5.p" to "[Mehrfachauswahl] Worauf muss man beim Umgang mit dem Kompass achten?",
    "q.m04#5.o0" to "So waagerecht wie möglich halten",
    "q.m04#5.o1" to "Abstand zu magnetischen Gegenständen halten",
    "q.m04#5.o2" to "Das S-Ende der Nadel nicht für Norden halten",
    "q.m04#5.o3" to "Die örtliche Missweisung berücksichtigen",
    "q.m04#5.o4" to "Ihn nahe an den Metallschnallen des Rucksacks halten, damit er ruhig bleibt",
    "q.m04#5.e" to "Alle vier stehen ausdrücklich im Handbuch. Allein der Fehler mit dem S-Ende ergibt eine Richtungsabweichung von 180° — in komplexem Gelände schickt Sie das in die Gegenrichtung, ohne dass Sie es merken.",

    "q.m04#6.p" to "Was ist die magnetische Missweisung?",
    "q.m04#6.o0" to "Ein Herstellungsfehler des Kompasses",
    "q.m04#6.o1" to "Der Versatz zwischen magnetisch Nord und geografisch Nord, der korrigiert werden muss",
    "q.m04#6.o2" to "Eine Winkeländerung durch die Höhe",
    "q.m04#6.o3" to "Eine Verzerrung durch die Kartenprojektion",
    "q.m04#6.e" to "Die Nadel zeigt auf magnetisch Nord, während Karten auf geografisch Nord bezogen sind — und die beiden unterscheiden sich. Die Missweisung ist regional verschieden, deshalb muss sie bei der Kombination von Karte und Kompass korrigiert werden; sonst verschiebt sich die ganze Route.",

    "q.m04#7.p" to "Was stellen die sauberen quadratischen Gitterlinien auf einer topografischen Karte dar?",
    "q.m04#7.o0" to "Breiten- und Längengrade",
    "q.m04#7.o1" to "Ein UTM-Gitter (Universal Transverse Mercator)",
    "q.m04#7.o2" to "Höhenlinien",
    "q.m04#7.o3" to "Verwaltungsgrenzen",
    "q.m04#7.e" to "Das Gitter ist nicht Breite und Länge, sondern UTM. Das ist wichtig, weil die Erde ein Ellipsoid ist: Breiten- und Längenzellen sind in verschiedenen Breiten nicht gleich groß, UTM-Quadrate dagegen schon — was Distanz- und Koordinatenmessung unkompliziert macht.",

    "q.m04#8.p" to "Warum sich nicht allein auf GPS verlassen?",
    "q.m04#8.o0" to "Weil GPS nicht genau genug ist",
    "q.m04#8.o1" to "Weil das Gerät Strom verlieren, nass werden, kaputtgehen oder das Signal verlieren kann",
    "q.m04#8.o2" to "Weil GPS nur in Städten funktioniert",
    "q.m04#8.o3" to "Weil GPS ein Abo braucht",
    "q.m04#8.e" to "GPS ist eine hervorragende Hilfe, setzt aber ein funktionierendes Gerät voraus. Batterien lassen in Höhenkälte schnell nach, und Wasser und Stürze sind häufig. Karte und Kompass brauchen keinen Strom — deshalb bleiben sie in der Bergsteigerausbildung Pflicht.",

    "q.m04#9.p" to "Was tun Sie zuerst, wenn die Sicht zusammenbricht (Nebel, Whiteout)?",
    "q.m04#9.o0" to "Schneller gehen und durchkommen",
    "q.m04#9.o1" to "Sofort Position und Richtung bestätigen und nötigenfalls an Ort und Stelle warten",
    "q.m04#9.o2" to "Gerade weiterlaufen wie geplant",
    "q.m04#9.o3" to "Aufteilen und die Route suchen",
    "q.m04#9.e" to "Die Gefahr eines Whiteouts ist der Verlust jeder visuellen Referenz, und Menschen laufen instinktiv in die falsche Richtung. Position feststellen, Richtung notieren und bei Bedarf warten — viel sicherer als weiterzudrücken, und Aufteilen ist die schlechteste aller Optionen.",

    // ---------- m05 Einsteigergipfel ----------
    "q.m05#0.p" to "Was ist der Kernunterschied zwischen einem Trekkinggipfel und einem technischen Gipfel?",
    "q.m05#0.o0" to "Die Höhe",
    "q.m05#0.o1" to "Ob technische Ausrüstung und technische Bewegung nötig sind",
    "q.m05#0.o2" to "In welchem Land er liegt",
    "q.m05#0.o3" to "Ob eine Genehmigung nötig ist",
    "q.m05#0.e" to "Die Trennlinie ist der technische Anspruch, nicht die Höhe. Der Kilimandscharo mit 5.895 m braucht keine technische Ausrüstung, der Haba Snow Mountain mit 5.396 m verlangt oberhalb der Schneegrenze Steigeisen und Pickel. Höhe ist nur eine Dimension der Schwierigkeit.",

    "q.m05#1.p" to "Wie heißt der höchste Punkt des Kilimandscharo?",
    "q.m05#1.o0" to "Uhuru Peak",
    "q.m05#1.o1" to "Kibo",
    "q.m05#1.o2" to "Mawenzi",
    "q.m05#1.o3" to "Shira",
    "q.m05#1.e" to "Der Gipfel ist der Uhuru Peak mit 5.895 m. Der Kilimandscharo ist ein ruhender Vulkan aus drei Kegeln — Kibo, Mawenzi und Shira — und Uhuru ist der höchste Punkt auf dem Kibo.",

    "q.m05#2.p" to "Was macht den Kilimandscharo einzigartig?",
    "q.m05#2.o0" to "Er ist der am seltensten bestiegene 5.000er der Welt",
    "q.m05#2.o1" to "Er liegt nahe dem Äquator und trägt dennoch Gletscher, mit Klimazonen von Regenwald bis Wüste",
    "q.m05#2.o2" to "Er verlangt hoch technische Ausrüstung",
    "q.m05#2.o3" to "Er ist nur einen Monat im Jahr besteigbar",
    "q.m05#2.e" to "Äquator plus Gletscher macht den Kilimandscharo zu einem vertikalen Klimakorridor: Regenwald bis Eis in einer einzigen Tour. Daraus entsteht auch ein praktisches Problem — große Höhendifferenz bei schnellem Höhengewinn, sodass die Akklimatisierung zur Hauptaufgabe wird.",

    "q.m05#3.p" to "Zu welcher Gipfelgruppe gehört Aotaina?",
    "q.m05#3.o0" to "Siguniang",
    "q.m05#3.o1" to "Die Schneeberge San'ao",
    "q.m05#3.o2" to "Gongga",
    "q.m05#3.o3" to "Meili Snow Mountain",
    "q.m05#3.e" to "Die San'ao-Gruppe in Heishui, Sichuan, besteht aus Aotaiji (Vater der Berge), Aotaimei (Mutter) und Aotaina (Sohn). Aotaina ist der einfachste der drei und wird oft als erster Schneegipfel gewählt.",

    "q.m05#4.p" to "Welche Angabe zur Höhe von Aotaina ist zutreffend?",
    "q.m05#4.o0" to "Alle Quellen stimmen bei 4.800 m überein",
    "q.m05#4.o1" to "Offiziell 5.211 m, gemessen aber etwa 4.800 m — die Quellen weichen ab",
    "q.m05#4.o2" to "Offiziell 4.800 m, gemessen 5.211 m",
    "q.m05#4.o3" to "Die Höhe war nie umstritten",
    "q.m05#4.e" to "Solche Abweichungen sind bei Gipfeldaten häufig: offizielle Angaben, Messwerte und unterschiedliche Vermessungsstandards variieren. Die praktische Lehre ist, bei Gipfeldaten immer die Quelle zu nennen, statt eine Zahl als absolute Wahrheit zu behandeln.",

    "q.m05#5.p" to "Wie hoch sind Da Feng und Er Feng des Siguniang?",
    "q.m05#5.o0" to "5.025 m und 5.276 m",
    "q.m05#5.o1" to "5.276 m und 5.025 m",
    "q.m05#5.o2" to "5.025 m und 5.355 m",
    "q.m05#5.o3" to "4.850 m und 5.276 m",
    "q.m05#5.e" to "Da Feng ist 5.025 m, Er Feng 5.276 m. Sie werden oft als Einstiegsprogression kombiniert: erst Da Feng für Höhenerfahrung, dann Er Feng, dessen Schlussabschnitt einfache technische Unterstützung braucht — ein natürlicher Schritt zum technischen Bergsteigen.",

    "q.m05#6.p" to "[Mehrfachauswahl] Welche Faktoren lohnt es beim ersten Schneegipfel am meisten zu vergleichen?",
    "q.m05#6.o0" to "Wie etabliert die Route ist und wie hoch die Gipfelquote liegt",
    "q.m05#6.o1" to "Ob Führung und Rettungsunterstützung verlässlich sind",
    "q.m05#6.o2" to "Ob der Höhengewinn sinnvoll getaktet ist",
    "q.m05#6.o3" to "Ihre aktuelle Kondition und die verfügbare Zeit",
    "q.m05#6.o4" to "Wie beliebt der Gipfel in sozialen Medien ist",
    "q.m05#6.e" to "Die ersten vier beantworten zusammen: Passt dieser Berg jetzt zu mir. Nur auf die Höhenzahl zu schauen führt in die Irre: Ein 5.000er mit sinnvollem Takt und guter Unterstützung kann sicherer sein als ein 5.500er, der drei gehetzte Tage erzwingt.",

    "q.m05#7.p" to "Was ist auf einem Einsteigergipfel am häufigsten die Ursache fürs Scheitern?",
    "q.m05#7.o0" to "Technische Schwierigkeit",
    "q.m05#7.o1" to "Höhenkrankheit und Wetter, nicht die technische Schwierigkeit",
    "q.m05#7.o2" to "Unzureichende Ausrüstung",
    "q.m05#7.o3" to "Eine zu kleine Gruppe",
    "q.m05#7.e" to "Das ist der am meisten unterschätzte Punkt: Auf Einsteigergipfeln lautet das Scheitern fast immer 'die Kraft ging aus' oder 'das Wetter hat nicht gewartet', nicht 'wir kamen an der Schlüsselstelle nicht vorbei'. Die eigentliche Hausaufgabe auf diesem Niveau sind also Akklimatisierung, Takt und Kondition — nicht technische Züge.",

    "q.m05#8.p" to "Warum ist die Gipfelquote bei der Gipfelwahl eine nützliche Zahl?",
    "q.m05#8.o0" to "Weil sie zeigt, wie schön der Gipfel ist",
    "q.m05#8.o1" to "Weil sie Routenschwierigkeit, Takt und das reale Niveau der Unterstützung zusammenfasst",
    "q.m05#8.o2" to "Weil sie die Kosten bestimmt",
    "q.m05#8.o3" to "Weil sie nichts mit Sicherheit zu tun hat",
    "q.m05#8.e" to "Die Gipfelquote ist das Produkt vieler Dinge: wie hart die Route ist, ob der Höhengewinn sinnvoll ist, wie breit die Wetterfenster sind, wie verlässlich die Logistik läuft. Sie sagt Ihnen mehr über das, was Sie tatsächlich erwartet, als die Höhe allein.",

    "q.m05#9.p" to "Welche Haltung ist gegenüber einem Einsteiger-Schneegipfel richtig?",
    "q.m05#9.o0" to "Einsteiger heißt ohne Risiko",
    "q.m05#9.o1" to "Einsteiger heißt nur geringerer technischer Anspruch; Höhen- und Wetterrisiken bleiben real",
    "q.m05#9.o2" to "Einsteigergipfel brauchen keinen Führer",
    "q.m05#9.o3" to "Einsteigergipfel brauchen keine Konditionsvorbereitung",
    "q.m05#9.e" to "Einsteiger beschreibt die technische Schwelle, nicht das Gesamtrisiko. Höhe selbst, plötzliches Wetter und Erschöpfung können in jeder Höhe tödlich sein. Einsteiger als leicht zu lesen ist der Anfang schlechter Vorbereitung.",

    // ---------- m06 Einstieg ins technische Bergsteigen ----------
    "q.m06#0.p" to "Welche drei Grundsysteme hat das technische Bergsteigen?",
    "q.m06#0.o0" to "Ausrüstung, Kondition, Wetter",
    "q.m06#0.o1" to "Bremsen, Sichern, Bewegen",
    "q.m06#0.o2" to "Aufstieg, Abstieg, Rast",
    "q.m06#0.o3" to "Steigeisen, Pickel, Seil",
    "q.m06#0.e" to "Bremsen beantwortet 'was tue ich nach einem Ausrutscher', Sichern beantwortet 'wer fängt mich, wenn ich falle', Bewegen beantwortet 'wie komme ich über gefährliches Gelände'. Zusammen schließen sie den Kreis — fällt eines weg, funktioniert technisches Bergsteigen nicht.",

    "q.m06#1.p" to "Was ist der eigentliche Zweck, technisches Bergsteigen zu lernen?",
    "q.m06#1.o0" to "Schwierigere Routen zu klettern",
    "q.m06#1.o1" to "Einen unkontrollierten Rutsch in ein beherrschtes Risiko zu verwandeln",
    "q.m06#1.o2" to "Ein Zertifikat zu erwerben",
    "q.m06#1.o3" to "Schneller zu sein",
    "q.m06#1.e" to "Technik macht den Berg nicht niedriger; sie verändert, was nach einem Fehler passiert. Mit Bremstechnik ist ein Ausrutscher keine unumkehrbare Katastrophe mehr, mit Sicherung bedeutet ein Fehler nicht automatisch einen Sturz. Darin liegt der eigentliche Wert.",

    "q.m06#2.p" to "Wie beherrscht man eine technische Bewegung am wirksamsten?",
    "q.m06#2.o0" to "Lehrvideos wiederholt anschauen",
    "q.m06#2.o1" to "Auf gesichertem Gelände so lange üben, bis es ein Reflex ist",
    "q.m06#2.o2" to "Das Handbuch lesen und die Punkte auswendig lernen",
    "q.m06#2.o3" to "Es in einem Zug am echten Steilhang lernen",
    "q.m06#2.e" to "Technische Handlungen müssen unter Druck ablaufen, und Druck bringt Sie auf das Niveau zurück, auf dem Sie tatsächlich geübt haben. Flacher Hang, weicher Schnee, freier Auslauf und ein Sichernder daneben — wenn alle vier gegeben sind, wird eine Fähigkeit wirklich gelernt.",

    "q.m06#3.p" to "Warum kann man Selbstbremsung nicht aus Videos lernen?",
    "q.m06#3.o0" to "Weil die Videoqualität schlecht ist",
    "q.m06#3.o1" to "Weil es ein Reflex ist, der durch wiederholte Praxis im Gelände entstehen muss",
    "q.m06#3.o2" to "Weil die gezeigte Technik falsch ist",
    "q.m06#3.o3" to "Weil Selbstbremsung eigentlich einfach ist",
    "q.m06#3.e" to "Nach einem Ausrutscher haben Sie ein bis zwei Sekunden, ohne Raum zum Nachdenken. Muskelgedächtnis kauft man mit Wiederholungen — deshalb besteht jeder vernünftige Kurs darauf, es zu drillen, bis Sie es ohne Nachdenken können.",

    "q.m06#4.p" to "Was sind die drei Startausrüstungsteile der Technik?",
    "q.m06#4.o0" to "Helm, Handschuhe, Brille",
    "q.m06#4.o1" to "Zum Schuh passende Steigeisen, ein Eispickel und ein Gurt",
    "q.m06#4.o2" to "Zelt, Schlafsack, Matte",
    "q.m06#4.o3" to "GPS, Funkgerät, Stirnlampe",
    "q.m06#4.e" to "Steigeisen geben Halt, der Pickel gibt Bremse und Stütze, der Gurt verbindet Sie mit dem Sicherungssystem. Gemeinsam ist ihnen, dass sie nur Sicherheit erzeugen, wenn sie aufeinander abgestimmt und als System mit einem Partner benutzt werden — kein einzelnes Teil schützt jemanden für sich.",

    "q.m06#5.p" to "Was wird die wichtigste Fähigkeit, sobald Sie die Technik beherrschen?",
    "q.m06#5.o0" to "Aufstiegsgeschwindigkeit",
    "q.m06#5.o1" to "Zu beurteilen, wann Sie die technische Ausrüstung gar nicht brauchen",
    "q.m06#5.o2" to "Ausrüstungspflege",
    "q.m06#5.o3" to "Weitere Konditionsgewinne",
    "q.m06#5.e" to "Das ist der kontraintuitivste Punkt im technischen Bergsteigen: Können lässt Sie in schwierigeres Gelände einsteigen, während echte Könner es nutzen, um sich die Option zu kaufen, dort nicht hinzugehen. Urteilskraft steht immer über Ausführung.",

    "q.m06#6.p" to "[Mehrfachauswahl] Was davon zählt zum technischen Bergsteigen?",
    "q.m06#6.o0" to "Sich am Eishang bewegen und bremsen",
    "q.m06#6.o1" to "Angeseilt einen Gletscher queren",
    "q.m06#6.o2" to "Einen Sicherungspunkt bauen",
    "q.m06#6.o3" to "Abseilen",
    "q.m06#6.o4" to "Auf einem gut ausgebauten Wanderweg gehen",
    "q.m06#6.e" to "Die ersten vier sind technisch: Jede braucht Ausrüstung, Systeme und gezielte Ausbildung. Einfach auf Schnee gehen oder einem ausgebauten Weg folgen ist es nicht — der Unterschied ist, ob diese Systeme erforderlich sind.",

    "q.m06#7.p" to "Warum kann technisches Können die Urteilskraft nie ersetzen?",
    "q.m06#7.o0" to "Weil technisches Können nicht trainierbar ist",
    "q.m06#7.o1" to "Weil schlechtes Urteil Sie in Gelände bringt, das Sie nie hätten betreten dürfen, wo Technik Sie nicht retten kann",
    "q.m06#7.o2" to "Weil Urteilskraft leichter zu lernen ist",
    "q.m06#7.o3" to "Weil Technik nur am Fels gilt",
    "q.m06#7.e" to "Technik nutzen Sie, wenn Sie schon in Gefahr sind; Urteilskraft entscheidet, ob Sie überhaupt in Gefahr geraten. In Unfallauswertungen steht selten 'der Zug war falsch' — viel häufiger steht dort 'sie hätten dort nicht sein dürfen'.",

    "q.m06#8.p" to "[Reihenfolge] Bringen Sie die Lernreihenfolge im technischen Bergsteigen in eine sinnvolle Ordnung.",
    "q.m06#8.o0" to "Die Ausrüstung verstehen: wie Steigeisen, Pickel und Gurt wirken",
    "q.m06#8.o1" to "Die Grundbewegungen auf sicherem Grund wiederholt üben (etwa Selbstbremsung)",
    "q.m06#8.o2" to "Seilsysteme lernen: Knoten, Anseilen, Sicherungspunkte",
    "q.m06#8.o3" to "Alles auf echten, aber kontrollierten Routen anwenden",
    "q.m06#8.e" to "Die Logik ist: erst sich selbst schützen, dann mit anderen verbinden, dann in echtes Gelände gehen. Wird ein Schritt übersprungen, bleibt eine Lücke — wer mit ungeübter Bremstechnik auf einen Gletscher anseilt, vervielfacht das Risiko für die ganze Gruppe.",

    "q.m06#9.p" to "Was hat diese Einheit geleistet?",
    "q.m06#9.o0" to "Die gesamte Höhenausbildung abgeschlossen",
    "q.m06#9.o1" to "Die Grundlage in Umwelt, Wissenschaft und Ausrüstung gelegt, bereit für die technische Bewegung",
    "q.m06#9.o2" to "Die Vorbereitung auf 8.000 m abgeschlossen",
    "q.m06#9.o3" to "Ein Rettungszertifikat erworben",
    "q.m06#9.e" to "In der 5.000-m-Einstiegseinheit geht es um das Fundament: Umweltkunde, Ausrüstung, Kleidung, Kondition, Low-Impact-Praxis, Wetter und Navigation und schließlich technisches Bergsteigen. Die nächste Einheit beginnt richtig mit Steigeisen, Pickel, Bremsen und Seilarbeit.",

    // ---------- m07 Prinzipien des Standplatzes ----------
    "q.m07#0.p" to "Was ist der Kerngedanke beim Bau eines Standplatzes?",
    "q.m07#0.o0" to "So wenig Material wie möglich verwenden",
    "q.m07#0.o1" to "Der Ausfall eines einzelnen Sicherungspunkts darf das System nicht zum Einsturz bringen",
    "q.m07#0.o2" to "Den Standplatz so hoch wie möglich bauen",
    "q.m07#0.o3" to "Nur natürliche Sicherungen verwenden",
    "q.m07#0.e" to "Fels- und Schneesicherungen sind nie absolut sicher, deshalb wird das System so gebaut, dass es Fehler toleriert, statt absolut stark zu sein. Alles Weitere — Redundanz, Lastverteilung, keine Extension — ist nur dieser Gedanke ausbuchstabiert.",

    "q.m07#1.p" to "Zwei Sicherungspunkte im Winkel von 90° zueinander: Welchen Anteil der Last trägt jeder ungefähr?",
    "q.m07#1.o0" to "Etwa 50 %",
    "q.m07#1.o1" to "Etwa 58 %",
    "q.m07#1.o2" to "Etwa 71 %",
    "q.m07#1.o3" to "Etwa 100 %",
    "q.m07#1.e" to "Das sind die Kernzahlen aus der Tabelle im Handbuch: Bei 0° trägt jeder Punkt etwa 50 %, bei 60° etwa 58 %, bei 90° etwa 71 %. Je größer der Winkel, desto mehr Kraft spürt jeder Punkt von derselben Person — und das bestimmt direkt, wie Sie die Punkte wählen und anordnen.",

    "q.m07#2.p" to "Wie sollte der Winkel zwischen Sicherungspunkten unter Lastgesichtspunkten gewählt werden?",
    "q.m07#2.o0" to "So klein wie möglich, damit die Lastrichtungen nahezu parallel sind",
    "q.m07#2.o1" to "So groß wie möglich, um die Last in verschiedene Richtungen zu verteilen",
    "q.m07#2.o2" to "Er muss 90° betragen",
    "q.m07#2.o3" to "Der Winkel beeinflusst die Last nicht",
    "q.m07#2.e" to "Je kleiner der Winkel, desto näher liegt die Verteilung bei 50/50; wird er größer, steigt die Last an jedem Punkt. Die gängige Regel 'den Schlingenwinkel innerhalb von 60° halten' stammt direkt aus diesen Zahlen.",

    "q.m07#3.p" to "[Mehrfachauswahl] Welche Dimensionen sollten Sie bei der Beurteilung eines Standplatzes prüfen?",
    "q.m07#3.o0" to "Solid: Jeder Punkt ist stark genug",
    "q.m07#3.o1" to "Redundant: mehrere unabhängige Punkte",
    "q.m07#3.o2" to "Equalized: Die Last wird sinnvoll geteilt",
    "q.m07#3.o3" to "No Extension: Ein Ausfall erzeugt keine Stoßbelastung durch Längenausgleich",
    "q.m07#3.o4" to "Symmetrie: ein ordentliches, optisch ausgewogenes Layout",
    "q.m07#3.e" to "Diese vier sind das Grundgerüst. No Extension wird am häufigsten übersehen: Bleibt Lose zwischen den Punkten, belastet ein Ausfall die übrigen als Stoß. Stoßlasten sind weit größer als statische Lasten, was vielen nicht klar ist.",

    "q.m07#4.p" to "[Zuordnung] Ordnen Sie jeder Sicherungsart ihr Medium und ihre Methode zu.",
    "q.m07#4.l0" to "Natürliche Sicherung",
    "q.m07#4.r0" to "Felspfeiler, große Bäume, große Blöcke — prüfen, ob sie intakt und stabil sind",
    "q.m07#4.l1" to "Schneesicherung",
    "q.m07#4.r1" to "Schneeanker, Deadman, T-Gräbe — die Zuverlässigkeit hängt stark von Schnee und Einbindetiefe ab",
    "q.m07#4.l2" to "Eissicherung",
    "q.m07#4.r2" to "Eisschrauben — prüfen, dass das Eis kompakt ist, ohne Hohlräume oder Wabenstruktur",
    "q.m07#4.e" to "Drei Medien, drei völlig verschiedene Kriterien. Eine der häufigsten Unfallursachen ist, Schnee oder Eis mit Felsreflexen zu beurteilen — 'sieht solide aus' bedeutet im Schneedeckenaufbau fast nichts.",

    "q.m07#5.p" to "Was davon ist eine Scheinredundanz?",
    "q.m07#5.o0" to "Zwei Teile unterschiedlicher Festigkeit verwenden",
    "q.m07#5.o1" to "Zwei Sicherungspunkte, die tatsächlich von derselben Rissfuge oder demselben Block abhängen",
    "q.m07#5.o2" to "Die Punkte mit Schlingen verbinden",
    "q.m07#5.o3" to "Drei Sicherungspunkte setzen",
    "q.m07#5.e" to "Redundanz verlangt unabhängiges Versagen. Teilen zwei Punkte eine Rissfuge, reißt diese auf und nimmt beide gleichzeitig mit — es sieht nach zwei Punkten aus, wirkt aber wie einer. Scheinredundanz ist häufig und tödlich.",

    "q.m07#6.p" to "Warum das System vorspannen, um keine Extension zu bekommen?",
    "q.m07#6.o0" to "Für ein ordentliches Aussehen",
    "q.m07#6.o1" to "Damit ein Ausfall die verbleibenden Punkte nicht als Stoß belastet",
    "q.m07#6.o2" to "Um Schlingenlänge zu sparen",
    "q.m07#6.o3" to "Damit der Abbau schneller geht",
    "q.m07#6.e" to "Eine Stoßlast ist weit größer als eine statische — dieselbe Person, die plötzlich in einen Punkt fällt, erzeugt viel mehr Kraft, als wenn sie ruhig hängt. Ein loses System wirkt 'flexibler', verstärkt aber tatsächlich einen Ausfall zu einem Stoß im ganzen System.",

    "q.m07#7.p" to "[Reihenfolge] Bringen Sie die Schritte beim Bau eines Standplatzes in eine sinnvolle Ordnung.",
    "q.m07#7.o0" to "Umsehen und brauchbare, voneinander unabhängige Punkte auswählen",
    "q.m07#7.o1" to "Jeden Punkt setzen und prüfen, dass er für sich hält",
    "q.m07#7.o2" to "Die Punkte mit Schlinge oder Seil verbinden, Winkel kontrollieren und vorspannen",
    "q.m07#7.o3" to "Das ganze System auf Scheinredundanz und Extension prüfen",
    "q.m07#7.e" to "Die Reihenfolge ist: Positionen wählen, Einzelpunkte bauen, System verbinden, dann überprüfen. Die Überprüfung ist keine Formalität — beim Bauen konzentrieren Sie sich auf jede einzelne Platzierung und übersehen leicht die Gesamtbeziehung, etwa zwei Punkte an derselben Struktur.",

    "q.m07#8.p" to "Was ist bei natürlichen Sicherungen am wichtigsten zu prüfen?",
    "q.m07#8.o0" to "Ob sie groß genug sind",
    "q.m07#8.o1" to "Ob sie intakt sind — nicht lose, verwittert oder vom Hauptmassiv gelöst",
    "q.m07#8.o2" to "Ob sie gut aussehen",
    "q.m07#8.o3" to "Ob sie sich leicht anschlingen lassen",
    "q.m07#8.e" to "Die Gefahr bei natürlichen Sicherungen ist meist, dass sie groß aussehen, aber schon lose sind. Entscheidend ist, ob sie wirklich Teil des Hauptmassivs sind und ob Risse oder Verwitterungsspuren vorhanden sind. Groß, dick und offensichtlich heißt nicht solide.",

    "q.m07#9.p" to "Warum einen Standplatz so schnell bauen, wie es vernünftig geht?",
    "q.m07#9.o0" to "Um Kraft zu sparen",
    "q.m07#9.o1" to "Weil die Bauzeit Zeit in der Gefährdung ist",
    "q.m07#9.o2" to "Weil die Partner drängen",
    "q.m07#9.o3" to "Weil Material verloren geht",
    "q.m07#9.e" to "Beim Bau eines Standplatzes sind Sie oft ungesichert oder schlecht gesichert, deshalb soll diese Exposition kurz sein. Deshalb prüft die Beurteilung nicht nur solid, redundant und ausgeglichen, sondern auch Effizienz und Rechtzeitigkeit.",

    "q.m07#10.p" to "Wovon hängt die Zuverlässigkeit einer Schneesicherung vor allem ab?",
    "q.m07#10.o0" to "Von der Marke der Ausrüstung",
    "q.m07#10.o1" to "Von der Schneebeschaffenheit und davon, wie gut sie eingegraben ist",
    "q.m07#10.o2" to "Von der Höhe",
    "q.m07#10.o3" to "Von der Farbe des Seils",
    "q.m07#10.e" to "Derselbe Schneeanker hält in tiefem Schnee, in Nassschnee oder am Rand einer Schneebrücke völlig unterschiedliche Lasten. Schneesicherungen verlangen, die Schneedecke vor Ort zu lesen — genau das macht Schneesicherungen zu einer der anspruchsvollsten Fähigkeiten.",

    "q.m07#11.p" to "Wenn ein Standplatz nur einen einzigen Sicherungspunkt hat, was ist das größte Problem?",
    "q.m07#11.o0" to "Die Last ist zu hoch",
    "q.m07#11.o1" to "Es gibt keinerlei Reserve — fällt dieser Punkt aus, fällt das System",
    "q.m07#11.o2" to "Er ist unbequem zu bedienen",
    "q.m07#11.o3" to "Er sieht hässlich aus",
    "q.m07#11.e" to "Ein Einpunkt-Standplatz übergibt Ihr Leben einem unsicheren Faktor. Manchmal ist er wirklich die einzige Option — etwa eine gute Eisschraube — und dann lautet die Strategie: diesen Punkt so gut machen, wie er sein kann, und die Zeit minimieren, in der das System von ihm abhängt.",

    // ---------- m08 5.000er-Ziele ----------
    "q.m08#0.p" to "Wie hoch ist der Hauptgipfel des Gangshika?",
    "q.m08#0.o0" to "5.005 m",
    "q.m08#0.o1" to "5.150 m",
    "q.m08#0.o2" to "5.254,5 m",
    "q.m08#0.o3" to "5.396 m",
    "q.m08#0.e" to "Der Hauptgipfel ist 5.254,5 m. Beachten Sie die Hierarchie: dritter Gipfel 5.005 m < Schultergipfel 5.150 m < Hauptgipfel 5.254,5 m — drei Höhen, drei Schwierigkeitsstufen, weshalb der Gangshika oft als stufenweises Ziel dient.",

    "q.m08#1.p" to "Was zeichnet den dritten Gipfel des Gangshika aus?",
    "q.m08#1.o0" to "5.005 m, technisch im Einstiegsbereich, etwa 95 % Gipfelquote für Anfänger",
    "q.m08#1.o1" to "5.254 m, hoch technisch",
    "q.m08#1.o2" to "5.150 m, reine Trekkingtour",
    "q.m08#1.o3" to "5.396 m, Gletscherroute",
    "q.m08#1.e" to "Der dritte Gipfel ist 5.005 m und technisch im Einstiegsbereich. Eine Anfänger-Gipfelquote von etwa 95 % zeigt, dass die Route machbar und die Logistik eingespielt ist — gut geeignet, um zum ersten Mal technische Ausrüstung anzulegen.",

    "q.m08#2.p" to "Welche geografische Bedeutung hat der Gangshika?",
    "q.m08#2.o0" to "Der höchste Gipfel des Kunlun",
    "q.m08#2.o1" to "Der höchste Gipfel des östlichen Qilian",
    "q.m08#2.o2" to "Der höchste Gipfel des tibetischen Plateaus",
    "q.m08#2.o3" to "Der höchste Gipfel des Hengduan",
    "q.m08#2.e" to "Der Gangshika ist der höchste Gipfel des östlichen Qilian, im Kreis Menyuan, Bezirk Haibei, Qinghai. Er ist zugleich einer der stadtnächsten hohen Schneegipfel Chinas — Erreichbarkeit bestimmt direkt, wie beliebt ein Gipfel als Ausbildungsziel wird.",

    "q.m08#3.p" to "Wie lang ist der Zustieg zum dritten Gipfel des Gangshika und wie viel Zeit braucht er üblicherweise?",
    "q.m08#3.o0" to "Etwa 3 km / 2 Stunden",
    "q.m08#3.o1" to "Etwa 10 km / 6 Stunden",
    "q.m08#3.o2" to "Etwa 25 km / zwei Tage",
    "q.m08#3.o3" to "Etwa 1 km / 30 Minuten",
    "q.m08#3.e" to "Etwa 10 km und sechs Stunden. Diese Belastung passt genau zu einer ersten technischen Tour: Sie gewinnen nicht durch langes Durchhalten, sondern durch Konzentration auf Technik und Urteil.",

    "q.m08#4.p" to "Wie hoch ist der Haba Snow Mountain?",
    "q.m08#4.o0" to "5.005 m",
    "q.m08#4.o1" to "5.254 m",
    "q.m08#4.o2" to "5.396 m",
    "q.m08#4.o3" to "5.642 m",
    "q.m08#4.e" to "Der Haba ist 5.396 m, in Shangri-La, Yunnan. Sein Wert liegt darin, dass oberhalb der Schneegrenze echtes Eis liegt, das Steigeisen und Pickel verlangt — ohne den strengen Akklimatisierungsdruck eines 6.000ers.",

    "q.m08#5.p" to "Wo verlangt der Haba Snow Mountain technisches Können?",
    "q.m08#5.o0" to "Er verlangt Kletterkönnen am Fels",
    "q.m08#5.o1" to "Oberhalb der Schneegrenze liegt ein Eishang, der Steigeisen und Pickel verlangt",
    "q.m08#5.o2" to "Er verlangt Tauchfähigkeiten",
    "q.m08#5.o3" to "Er braucht überhaupt keine technische Ausrüstung",
    "q.m08#5.e" to "Das Stichwort beim Haba lautet 'Eis oberhalb der Schneegrenze'. Sie müssen mit Steigeisen sicher im Eis gehen und den Pickel für Stütze und Bremsung nutzen — genau das, was die früheren Lektionen dieser 5.000-m-Stufe abdecken.",

    "q.m08#6.p" to "Wie hoch ist der Elbrus und welchen Status hat er?",
    "q.m08#6.o0" to "5.642 m, der höchste Gipfel Europas",
    "q.m08#6.o1" to "5.895 m, der höchste Afrikas",
    "q.m08#6.o2" to "5.254 m, der höchste des Qilian",
    "q.m08#6.o3" to "6.178 m, ein Hochgipfel des Kunlun",
    "q.m08#6.e" to "Der Elbrus ist 5.642 m, der höchste Gipfel Europas, im Kaukasus in Russland. Seine Stellung in der Progression ist ungewöhnlich: von der Höhe ein 5.000er, aber mit Gletscherbegehung und Anseilen — eine klassische Brücke von Trekking- zu technischen Gipfeln.",

    "q.m08#7.p" to "Was sind die Grundvoraussetzungen für eine Elbrus-Besteigung?",
    "q.m08#7.o0" to "Nur Kondition",
    "q.m08#7.o1" to "Steigeisen und Pickel; Gletscherbegehung und Anseilen sind Grundvoraussetzung",
    "q.m08#7.o2" to "Zusätzlicher Sauerstoff",
    "q.m08#7.o3" to "Kletterkönnen am Fels",
    "q.m08#7.e" to "Die Route am Elbrus quert Gletscher, deshalb sind Anseilen, Spaltenbewusstsein und Steigeisen-Gebrauch Basiswissen. Er wird oft mit dem Kilimandscharo verglichen: beide 5.000er, einer eine reine Trekkingtour, der andere echte technische Arbeit.",

    "q.m08#8.p" to "[Mehrfachauswahl] Beim Übergang von Trekking- zu technischen Gipfeln: Welche Fähigkeiten sollten Sie zuerst aufbauen?",
    "q.m08#8.o0" to "Korrekter Umgang mit technischer Ausrüstung (Steigeisen, Pickel, Gurt)",
    "q.m08#8.o1" to "Grundlegende technische Handlungen wie das Abfangen eines Sturzes",
    "q.m08#8.o2" to "Angeseilte Gletscherbegehung und grundlegende Sicherungssysteme",
    "q.m08#8.o3" to "Urteilskraft dafür, wann man nicht weitergeht",
    "q.m08#8.o4" to "Teurere Ausrüstung kaufen",
    "q.m08#8.e" to "Die ersten drei sind Fähigkeiten, die vierte ist eine Randbedingung. Viele bauen nur die ersten drei auf und werden mit wachsendem Können selbstsicherer — was das Risiko erhöht. Technik- und Urteilstraining müssen gemeinsam wachsen, deshalb verbindet diese Einheit Techniklektionen mit Gipfellektionen.",

    "q.m08#9.p" to "[Reihenfolge] Bringen Sie diese Ziele in die Reihenfolge steigender Schwierigkeit.",
    "q.m08#9.o0" to "Aotaina (Trekking, keine technische Schwierigkeit)",
    "q.m08#9.o1" to "Gangshika, dritter Gipfel (technischer Einstieg)",
    "q.m08#9.o2" to "Haba / Elbrus (gemischt, Steigeisen und Anseilen)",
    "q.m08#9.o3" to "Yuzhu, Südhang (6.000 m, gemischt)",
    "q.m08#9.e" to "Der Schlüssel ist, jeweils nur eine neue Variable hinzuzufügen: keine Technik, dann technische Ausrüstung, dann Einsatz in echtem Eis, dann Höhe. Der übliche Fehler ist nicht ein übersprungener Schritt, sondern Schwierigkeit und Höhe gleichzeitig zu maximieren — dann wissen Sie nicht, worauf Sie nicht vorbereitet waren.",

    "q.m08#10.p" to "Warum ist der Weg vom dritten Gipfel zum Hauptgipfel eine sinnvolle Progression?",
    "q.m08#10.o0" to "Weil der dritte Gipfel dem Hauptgipfel am nächsten liegt",
    "q.m08#10.o1" to "Weil verschiedene Routen an einem Berg die technische von der Umgebungsschwierigkeit trennen",
    "q.m08#10.o2" to "Weil der Hauptgipfel billiger ist",
    "q.m08#10.o3" to "Weil man sich am dritten Gipfel leichter verläuft",
    "q.m08#10.e" to "An demselben Berg weiterzugehen hält die Umgebungsvariablen — Wetter, Anreise, Logistik, Führung — nahezu konstant, sodass Sie klar spüren, woher die zusätzliche Schwierigkeit kommt. Wechseln Sie jedes Mal den Berg, wissen Sie nie, ob Technik oder Akklimatisierung die Grenze war.",

    "q.m08#11.p" to "Welche Haltung ist bei der Wahl eines 5.000-m-Ziels richtig?",
    "q.m08#11.o0" to "Das höchste nehmen und Stufen überspringen",
    "q.m08#11.o1" to "Jeweils eine neue Schwierigkeit hinzufügen und verlässliche Unterstützung priorisieren",
    "q.m08#11.o2" to "Das billigste nehmen",
    "q.m08#11.o3" to "Nur auf die Gipfelquote schauen, nicht auf den technischen Anspruch",
    "q.m08#11.e" to "Können wächst kumulativ, und jeder übersprungene Schritt vervielfacht das Risiko. Verlässliche Unterstützung — Führung, Rettung, ein Rückzugsplan — ist die gemeinsame Sicherheitsbasis auf jedem Einstiegsniveau: Sie verhindert keine Fehler, aber sie verhindert, dass ein Fehler tödlich wird.",

    // ---------- m09 Höhenmedikamente ----------
    "q.m09#0.p" to "Was sind die zwei grundlegenden Ziele von Medikamenten in der Höhe?",
    "q.m09#0.o0" to "Höhenkrankheit heilen und den Abstieg ersetzen",
    "q.m09#0.o1" to "Die Akklimatisierung beschleunigen und Zeit für den Abstieg gewinnen",
    "q.m09#0.o2" to "Kondition und Ausdauer verbessern",
    "q.m09#0.o3" to "Erkältungen vorbeugen und den Schlaf verbessern",
    "q.m09#0.e" to "Diese beiden auseinanderzuhalten ist entscheidend: Acetazolamid gehört zum ersten Ziel (schnellere Akklimatisierung), Dexamethason und Nifedipin zum zweiten (Zeitgewinn). Ein zeitgewinnendes Medikament als Beweis der Erholung zu lesen ist die gefährlichste Fehleinschätzung in der Höhenmedizin.",

    "q.m09#1.p" to "Beeinflusst Dexamethason die Akklimatisierung?",
    "q.m09#1.o0" to "Ja, es beschleunigt sie",
    "q.m09#1.o1" to "Nein, es hat keinen Einfluss auf die Akklimatisierung",
    "q.m09#1.o2" to "Ja, es verlangsamt sie",
    "q.m09#1.o3" to "Nur bei langfristiger Einnahme",
    "q.m09#1.e" to "Das Handbuch ist deutlich: Dexamethason lindert Symptome des Hirnödems, hat keinen Einfluss auf die Akklimatisierung und behandelt kein Lungenödem. Es kauft ausschließlich Zeit — und diese Zeit muss für den Abstieg verwendet werden.",

    "q.m09#2.p" to "Welche Nebenwirkung von Nifedipin erfordert die größte Vorsicht?",
    "q.m09#2.o0" to "Müdigkeit",
    "q.m09#2.o1" to "Ein schneller Blutdruckabfall, sodass schnelles Aufstehen zu Ohnmacht führen kann",
    "q.m09#2.o2" to "Tinnitus",
    "q.m09#2.o3" to "Appetitlosigkeit",
    "q.m09#2.e" to "Das ist in der Praxis gefährlich: Ohnmacht durch orthostatische Hypotonie am Steilhang oder beim Verlassen des Zelts bei Nacht kann unmittelbarere Folgen haben als die Höhenkrankheit selbst. Das Handbuch merkt außerdem an, dass Nifedipin Trekkingreisenden helfen kann, für Kletterer aber nicht die beste Wahl ist.",

    "q.m09#3.p" to "Welche Haltung zu Höhenmedikamenten ist richtig?",
    "q.m09#3.o0" to "Dosis auswendig lernen und selbst anwenden",
    "q.m09#3.o1" to "Es ist eine medizinische Entscheidung — mit einem Arzt abklären und dessen Anweisung folgen",
    "q.m09#3.o2" to "Gruppenmitglieder können es frei weitergeben",
    "q.m09#3.o3" to "Nebenwirkungen beeinflussen die Anwendung nicht",
    "q.m09#3.e" to "Jedes Medikament hat spezifische Indikationen, Kontraindikationen und Nebenwirkungen (Nifedipin senkt den Blutdruck, Aspirin birgt Blutungsrisiko, Dexamethason ist ein Steroid). Das ist kein 'Höhen-Allgemeinwissen', sondern medizinisches Eingreifen — daher die wiederholte Betonung ärztlichen Rats.",

    "q.m09#4.p" to "Die Symptome bessern sich nach Dexamethason. Was tun Sie?",
    "q.m09#4.o0" to "Wie geplant weiter aufsteigen",
    "q.m09#4.o1" to "Trotzdem nicht aufsteigen; so schnell wie möglich absteigen",
    "q.m09#4.o2" to "Die Dosis erhöhen und weitergehen",
    "q.m09#4.o3" to "Das Medikament sofort absetzen und beobachten",
    "q.m09#4.e" to "Das Medikament nimmt die Symptome, aber die Ursache des Hirnödems — die Hypoxie — bleibt. Die Schlussfolgerung im Handbuch ist klar: Auch bei Symptomlinderung nicht weiter an Höhe gewinnen. Abstieg ist die einzige Maßnahme, die die Ursache beseitigt.",

    "q.m09#5.p" to "Wie wird Aspirin bei Höhenkopfschmerz eingesetzt?",
    "q.m09#5.o0" to "Wenn der Schmerz beginnt",
    "q.m09#5.o1" to "Vorbeugend: früh beginnen und regelmäßig dosieren",
    "q.m09#5.o2" to "Nur zum Schlafengehen",
    "q.m09#5.o3" to "Erst nach dem Abstieg",
    "q.m09#5.e" to "Das Handbuch nennt 320 mg dreimal täglich, beginnend am Tag vor dem Aufstieg, bis die Akklimatisierung abgeschlossen ist — ein regelmäßiges vorbeugendes Schema, nicht bei Bedarf. Die beiden Vorgehensweisen folgen völlig unterschiedlicher Logik.",

    "q.m09#6.p" to "Was ist der grundlegende Unterschied zwischen Acetazolamid und Dexamethason?",
    "q.m09#6.o0" to "Eines ist billig, eines teuer",
    "q.m09#6.o1" to "Eines beschleunigt die Akklimatisierung, das andere lindert nur Symptome",
    "q.m09#6.o2" to "Eines ist oral, eines injizierbar",
    "q.m09#6.o3" to "Sie wirken gleich",
    "q.m09#6.e" to "Diese Unterscheidung entscheidet alles Weitere: Bei Acetazolamid darf Besserung als echte Akklimatisierung gelesen werden, bei Dexamethason ist Besserung nur Maskierung — und ob Sie weiter aufsteigen dürfen, hat in beiden Fällen die entgegengesetzte Antwort.",

    "q.m09#7.p" to "[Mehrfachauswahl] Welche Aussagen zu Höhenmedikamenten sind richtig?",
    "q.m09#7.o0" to "Medikamente können den Abstieg nicht ersetzen",
    "q.m09#7.o1" to "Dosis und Zeitpunkt brauchen ärztliche Anleitung",
    "q.m09#7.o2" to "Verschiedene Medikamente zielen auf verschiedene Krankheitsbilder und dürfen nicht verwechselt werden",
    "q.m09#7.o3" to "Sobald Medikamente die Symptome maskieren, wird das Urteil schwieriger",
    "q.m09#7.o4" to "Sobald die Symptome nachlassen, können Sie sicher weiter aufsteigen",
    "q.m09#7.e" to "Die ersten vier sind entscheidend. Am meisten übersehen wird, dass Maskierung das Urteil erschwert: Mit verschwundenen Symptomen verlieren Sie Ihr direktestes Maß und müssen sich auf objektivere Zeichen stützen — Gangbild, Bewusstsein, Atmung. Beobachten Sie diese drei nach der Gabe umso genauer.",

    "q.m09#8.p" to "Warum ist 'keine Medikamente, sofort absteigen' oft die verlässlichste Wahl?",
    "q.m09#8.o0" to "Weil Medikamente nicht wirken",
    "q.m09#8.o1" to "Weil der Abstieg die Ursache beseitigt, während Medikamente nur indirekt wirken",
    "q.m09#8.o2" to "Weil Medikamente teuer sind",
    "q.m09#8.o3" to "Weil Medikamente unhandlich zu tragen sind",
    "q.m09#8.e" to "Die Ursache der Höhenkrankheit ist Hypoxie, und die kommt direkt von der Höhe. Der Abstieg beseitigt die Ursache, Medikamente ändern nur die Reaktion des Körpers darauf. Wann immer die Bedingungen es zulassen, ist der Abstieg die vorrangige Maßnahme.",

    "q.m09#9.p" to "[Reihenfolge] Ein Gruppenmitglied zeigt Zeichen schwerer Höhenkrankheit. Was ist die richtige Reihenfolge?",
    "q.m09#9.o0" to "Sofort aufhören aufzusteigen; Bewusstsein, Gangbild und Atmung beurteilen",
    "q.m09#9.o1" to "Abstieg organisieren (mindestens 1.000 m), mit Sauerstoff, falls verfügbar",
    "q.m09#9.o2" to "Das passende Medikament (etwa Dexamethason) unter medizinischer Aufsicht geben",
    "q.m09#9.o3" to "Ist der Abstieg unmöglich, Überdruckkammer nutzen und Rettung rufen",
    "q.m09#9.e" to "Die Reihenfolge ist die Priorität: beurteilen, absteigen, medikamentös unterstützen und erst dann zu zeitgewinnenden Maßnahmen greifen. Der häufigste Fehler in der Praxis ist die Umkehrung — zuerst nach dem Medikament suchen und vergessen, dass der Abstieg die definitive Behandlung ist.",

    "q.m09#10.p" to "Warum ist es für Höhentouren so wichtig, den Medikamentenplan vorher mit einem Arzt zu besprechen?",
    "q.m09#10.o0" to "Weil man am Berg keine Medikamente kaufen kann",
    "q.m09#10.o1" to "Weil dort oben kein fachlicher Rat verfügbar ist und Erbrechen den Aufnahmeweg ändern kann",
    "q.m09#10.o2" to "Weil Medikamente ablaufen",
    "q.m09#10.o3" to "Weil Führer es verlangen",
    "q.m09#10.e" to "In der Höhe gibt es keinen Arzt und keine Diagnostik; schlimmer noch, der Patient erbricht vielleicht und kann nichts oral aufnehmen. Der Plan — Dosis, Zeitpunkt, Aufnahmeweg und Kontraindikationen — muss vor dem Aufbruch abgestimmt sein.",

    "q.m09#11.p" to "[Zuordnung] Ordnen Sie jedem Medikament seine Hauptwirkung zu.",
    "q.m09#11.l0" to "Acetazolamid",
    "q.m09#11.r0" to "Beschleunigt die Akklimatisierung; vorbeugend eingesetzt",
    "q.m09#11.l1" to "Dexamethason",
    "q.m09#11.r1" to "Senkt den intrakraniellen Druck und lindert das Hirnödem",
    "q.m09#11.l2" to "Nifedipin",
    "q.m09#11.r2" to "Löst die pulmonale Vasokonstriktion und wird beim Lungenödem eingesetzt",
    "q.m09#11.e" to "Drei Karten, drei Aufgaben: Acetazolamid für die Akklimatisierung, Dexamethason für das Gehirn, Nifedipin für die Lunge. Erst klären, welches Problem der Patient hat, dann die Karte wählen — statt jedes Medikament als allgemeine Höhenpille zu behandeln.",

    // ---------- m10 Wetterfenster ----------
    "q.m10#0.p" to "Was ist ein Wetterfenster?",
    "q.m10#0.o0" to "Der Tag mit der geringsten Niederschlagswahrscheinlichkeit in der Vorhersage",
    "q.m10#0.o1" to "Der Zeitraum, in dem Sie das Ziel sicher abschließen können",
    "q.m10#0.o2" to "Die Stunden mit dem meisten Tageslicht",
    "q.m10#0.o3" to "Die Zeit mit dem wenigsten Wind",
    "q.m10#0.e" to "Ein Wetterfenster ist ein zusammengesetzter Begriff: Es erfüllt zugleich 'das Wetter lässt es zu' und 'die Gruppe kann es leisten'. Bei identischem Wetter sind die Fenster einer starken und einer schwachen Gruppe deshalb völlig unterschiedlich breit — Fenster sind relativ, nicht absolut.",

    "q.m10#1.p" to "Warum ist die Bergwettervorhersage verhältnismäßig ungenau?",
    "q.m10#1.o0" to "Weil es zu wenige Wetterstationen gibt",
    "q.m10#1.o1" to "Weil komplexes Gelände enorme lokale Unterschiede erzeugt — verschiedene Höhen und Expositionen können völlig verschiedenes Wetter haben",
    "q.m10#1.o2" to "Weil die Meteorologen nachlässig sind",
    "q.m10#1.o3" to "Weil es in der Höhe keine Daten gibt",
    "q.m10#1.e" to "Orografische Hebung, Blockierung und Umströmung von Graten teilen das Wetter kleinräumig scharf — wenige Kilometer entfernt ist eine andere Welt. Eine regionale Vorhersage ist nur Hintergrund; entschieden wird nach der Beobachtung vor Ort.",

    "q.m10#2.p" to "Zunehmende Bewölkung und sinkende Wolkenuntergrenze deuten meist auf was hin?",
    "q.m10#2.o0" to "Besserung",
    "q.m10#2.o1" to "Verschlechterung, wobei die Sicht wahrscheinlich schnell abnimmt",
    "q.m10#2.o2" to "Baldige Auflockerung",
    "q.m10#2.o3" to "Nichts Bestimmtes",
    "q.m10#2.e" to "Eine sinkende Wolkenuntergrenze bedeutet steigende Feuchte und ein fallendes Kondensationsniveau — oft der Vorbote eines Niederschlagssystems. Im Gebirge heißt es außerdem, dass Ihre Sicht gleich schrumpft, was ein Risiko für sich ist.",

    "q.m10#3.p" to "Warum ist der Drucktrend wichtiger als der Druckwert?",
    "q.m10#3.o0" to "Weil der Wert immer falsch ist",
    "q.m10#3.o1" to "Weil das Wetter von der Druckänderung getrieben wird und Basiswerte sich ohnehin mit der Höhe unterscheiden",
    "q.m10#3.o2" to "Weil Trends leichter zu merken sind",
    "q.m10#3.o3" to "Weil Werte zu stark schwanken",
    "q.m10#3.e" to "Derselbe Druckwert bedeutet in verschiedenen Höhen und Orten völlig Verschiedenes, eine isolierte Zahl hat also keinen Bezug. Ein anhaltender Abfall dagegen zeigt überall dasselbe: Das Wetter dreht.",

    "q.m10#4.p" to "Worin liegt der praktische Wert der Beaufort-Skala?",
    "q.m10#4.o0" to "Sie lässt Wind professioneller aussehen",
    "q.m10#4.o1" to "Sie übersetzt Windgeschwindigkeit in eine beobachtbare, mitteilbare Skala, um Beweglichkeit zu beurteilen und miteinander zu reden",
    "q.m10#4.o2" to "Sie misst Niederschlag",
    "q.m10#4.o3" to "Sie schätzt die Temperatur",
    "q.m10#4.e" to "Wind ist Information, die ausgesprochen werden muss: Eine Gruppe braucht eine gemeinsame Sprache für 'können wir weiter'. Beaufort macht aus einer abstrakten Geschwindigkeit beobachtbare Zeichen — Blätter, Schneetreiben, das Gefühl — sodass das Urteil schnell durch die Gruppe läuft.",

    "q.m10#5.p" to "[Mehrfachauswahl] Welche dieser Feldzeichen zeigen eine Wetterverschlechterung?",
    "q.m10#5.o0" to "Druck fällt stetig",
    "q.m10#5.o1" to "Bewölkung verdichtet sich schnell und die Untergrenze sinkt",
    "q.m10#5.o2" to "Wind frischt deutlich auf und dreht häufig",
    "q.m10#5.o3" to "Cumulonimbus baut sich in der Ferne auf",
    "q.m10#5.o4" to "Druck steigt stetig und der Wind lässt nach",
    "q.m10#5.e" to "Die ersten vier sind die wichtigsten Verschlechterungssignale im Handbuch. Sie beschreiben alle einen Trend, nicht einen Moment — deshalb zählt regelmäßige, getaktete Beobachtung. Nur mit einem Vergleichswert bedeutet ein Trend etwas.",

    "q.m10#6.p" to "Was ist während eines Gewitters am gefährlichsten?",
    "q.m10#6.o0" to "Anhalten und absteigen",
    "q.m10#6.o1" to "Auf Grat, Gipfel oder offener Fläche bleiben — überall, wo man exponiert ist",
    "q.m10#6.o2" to "Metallausrüstung einpacken",
    "q.m10#6.o3" to "Sich klein machen und warten",
    "q.m10#6.e" to "Das Schlimmste im Gewitter ist, das höchste Objekt der Umgebung zu sein. Grate und Gipfel sind genau die exponiertesten Orte, deshalb verlassen Sie sie, sobald Blitze drohen. Metallausrüstung zusammen und weg vom Körper halten.",

    "q.m10#7.p" to "Warum beginnt der Gipfelanstieg meist vor der Dämmerung?",
    "q.m10#7.o0" to "Um den Andrang zu vermeiden",
    "q.m10#7.o1" to "Weil der frühe Morgen meist der stabilste Teil des Tages ist, während nachmittags die Konvektion zunimmt und die Wahrscheinlichkeiten schlechter werden",
    "q.m10#7.o2" to "Weil man um 3 Uhr die meiste Energie hat",
    "q.m10#7.o3" to "Weil es tagsüber zu heiß ist",
    "q.m10#7.e" to "Das folgt dem Tagesgang: Die Erwärmung am Tag treibt die Konvektion, deshalb steigen Bewölkung und Niederschlagsneigung am Nachmittag. Den härtesten und kritischsten Teil vor die Dämmerung zu legen heißt, ein nachsichtigeres Fenster zu kaufen.",

    "q.m10#8.p" to "Wie hängt die Umkehrzeit mit dem Wetterfenster zusammen?",
    "q.m10#8.o0" to "Sie haben nichts miteinander zu tun",
    "q.m10#8.o1" to "Die Umkehrzeit sollte aus dem Wetterfenster abgeleitet werden; ein sich verengendes Fenster verschiebt sie nach vorn",
    "q.m10#8.o2" to "Die Umkehrzeit ist immer fest",
    "q.m10#8.o3" to "Bei gutem Wetter braucht es keine Umkehrzeit",
    "q.m10#8.e" to "Die Umkehrzeit ist keine feste Zahl, sondern wird aus dem Fenster des Tages berechnet. Wie lange bis zum Gipfel, wie lange hinunter, wann beginnt das Fenster zu schließen — rückwärts gerechnet ergibt den spätesten Zeitpunkt, zu dem Sie umkehren müssen.",

    "q.m10#9.p" to "[Reihenfolge] Bringen Sie die Schritte einer routinemäßigen Wetterbeurteilung in eine sinnvolle Ordnung.",
    "q.m10#9.o0" to "Vor dem Aufbruch die regionale Vorhersage und den Drucktrend prüfen",
    "q.m10#9.o1" to "Unterwegs Bewölkung, Wind und Sicht in regelmäßigen Abständen beobachten",
    "q.m10#9.o2" to "Feldbeobachtung mit der Vorhersage vergleichen, um die Richtung des Trends zu beurteilen",
    "q.m10#9.o3" to "Den Plan entsprechend anpassen oder früh umkehren",
    "q.m10#9.e" to "Schritt drei ist der Knackpunkt — viele bleiben bei Schritt zwei stehen, spüren, dass sich das Wetter ändert, und machen keine Entscheidung daraus. Beobachtung, die nie zur Handlung wird, ist keine Beobachtung.",

    "q.m10#10.p" to "Was geben Sie zuerst auf, wenn das Wetterfenster enger wird?",
    "q.m10#10.o0" to "Sicherheitsausrüstung",
    "q.m10#10.o1" to "Das Gipfelziel selbst",
    "q.m10#10.o2" to "Gruppenmitglieder",
    "q.m10#10.o3" to "Kommunikationsausrüstung",
    "q.m10#10.e" to "Das ist eine Prioritätenfrage: Wenn das Fenster nicht Gipfel und sicheren Abstieg zugleich trägt, behalten Sie den Abstieg und streichen den Gipfel. Entscheiden Sie das vor dem Aufbruch, nicht am Berg.",

    "q.m10#11.p" to "Welche Sicht auf Whiteout-Bedingungen ist richtig?",
    "q.m10#11.o0" to "Nur schlechte Sicht, keine Gefahr",
    "q.m10#11.o1" to "Sie verlieren jede visuelle Referenz und laufen instinktiv falsch — erst die Position feststellen",
    "q.m10#11.o2" to "Er bringt Niederschlag",
    "q.m10#11.o3" to "Er tritt nur nachts auf",
    "q.m10#11.e" to "Die Gefahr eines Whiteouts ist nicht, dass Sie nichts sehen — sondern dass Sie glauben, Sie sähen etwas. Ohne Referenzen driftet Ihr Richtungssinn systematisch, deshalb ist die erste Aufgabe, Position und Kurs festzuhalten, nicht weiterzugehen.",

    // ---------- m11 6.000er-Ziele ----------
    "q.m11#0.p" to "Wie hoch ist der Yuzhu und wo liegt er?",
    "q.m11#0.o0" to "6.178 m, Golmud, Qinghai, östlicher Kunlun",
    "q.m11#0.o1" to "6.206 m, Damxung, Tibet, Nyainqêntanglha",
    "q.m11#0.o2" to "6.119 m, Khumbu, Nepal",
    "q.m11#0.o3" to "6.189 m, Khumbu, Nepal",
    "q.m11#0.e" to "Der Yuzhu ist 6.178 m, im östlichen Kunlun auf dem Gebiet von Golmud, Qinghai. Seine Südhangroute ist verhältnismäßig flach und der Zugang gut — deshalb ist er für viele der erste 6.000er.",

    "q.m11#1.p" to "Wie hoch ist der Qizi und zu welcher Kette gehört er?",
    "q.m11#1.o0" to "6.178 m, Kunlun",
    "q.m11#1.o1" to "6.206 m, Nyainqêntanglha",
    "q.m11#1.o2" to "6.119 m, Himalaya",
    "q.m11#1.o3" to "6.189 m, Karakorum",
    "q.m11#1.e" to "Der Qizi ist 6.206 m, in der Nyainqêntanglha-Kette bei Damxung, Tibet. Sein Merkmal sind stabile Schneehänge und leichter Zugang — stabile Hänge bedeuten vergleichsweise beherrschbare Lawinen- und Spaltenrisiken, was ihn für Aufbautraining geeignet macht.",

    "q.m11#2.p" to "Wie hoch ist der Lobuche East und wo liegt er?",
    "q.m11#2.o0" to "6.119 m, Khumbu, Nepal",
    "q.m11#2.o1" to "6.189 m, Khumbu, Nepal",
    "q.m11#2.o2" to "6.206 m, Damxung, Tibet",
    "q.m11#2.o3" to "6.178 m, Golmud, Qinghai",
    "q.m11#2.e" to "Der Lobuche East ist 6.119 m in der Khumbu-Region Nepals, direkt neben der Everest-Trekkingroute. Diese Lage bedeutet eingespielte Akklimatisierung und Logistik, und seine steileren Schneehänge machen ihn zu einem guten Schritt in größere Höhe.",

    "q.m11#3.p" to "Was ist das typischste technische Merkmal des Island Peak (Imja Tse)?",
    "q.m11#3.o0" to "Es ist überhaupt keine technische Ausrüstung nötig",
    "q.m11#3.o1" to "Anseilen und Queren von Spalten",
    "q.m11#3.o2" to "Zusätzlicher Sauerstoff ist nötig",
    "q.m11#3.o3" to "Kletterkönnen am Fels ist nötig",
    "q.m11#3.e" to "Der Island Peak mit 6.189 m ist ein klassischer technischer 6.000er: Sie seilen an und Sie managen Spalten. Deshalb dient er auch als Vorbereitung auf 7.000 m — er bringt das System Gletscherbegehung plus Seilschaft in echten Einsatz.",

    "q.m11#4.p" to "Verglichen mit 5.000 m: Welches Risiko steigt bei 6.000 m am stärksten?",
    "q.m11#4.o0" to "Steinschlag",
    "q.m11#4.o1" to "Der Akklimatisierungsdruck und das Risiko der Höhenkrankheit",
    "q.m11#4.o2" to "Insekten",
    "q.m11#4.o3" to "Das Gewicht der Ausrüstung",
    "q.m11#4.e" to "Über 6.000 m steigen Häufigkeit und Schwere der Höhenkrankheit deutlich — deshalb behandelt diese Einheit die Höhenkrankheit als Kernkapitel. Technisch mag der Schritt allmählich sein, physiologisch ist er real.",

    "q.m11#5.p" to "[Mehrfachauswahl] Was sollten Sie vor einem 6.000er bereits beherrschen?",
    "q.m11#5.o0" to "Grundlegender Umgang mit Steigeisen und Pickel",
    "q.m11#5.o1" to "Grundknoten und angeseiltes Gehen",
    "q.m11#5.o2" to "Erkennen und Behandeln der Höhenkrankheit",
    "q.m11#5.o3" to "Grundverständnis der Spaltengefahr",
    "q.m11#5.o4" to "Selbstständiges Vorsteigen im WI5-Eis",
    "q.m11#5.e" to "Die ersten vier entsprechen der 5.000-m-Einstiegs- und Aufbaueinheit. Die 6.000-m-Einheit lehrt sie nicht neu, sondern bringt sie in eine härtere Umgebung. Mit schwachen Grundlagen direkt auf 6.000 m zu gehen vervielfacht das Risiko.",

    "q.m11#6.p" to "Warum ist der Südhang des Yuzhu oft das erste 6.000-m-Ziel?",
    "q.m11#6.o0" to "Weil er am billigsten ist",
    "q.m11#6.o1" to "Weil die Route verhältnismäßig flach ist und Zugang und Logistik eingespielt sind, sodass Sie sich auf die Akklimatisierung konzentrieren können",
    "q.m11#6.o2" to "Weil er keine Gefahr bietet",
    "q.m11#6.o3" to "Weil er keinen Führer braucht",
    "q.m11#6.e" to "Der Wert eines ersten Ziels ist, nur eine neue Variable hinzuzufügen. Der Südhang hält die technische Schwierigkeit in einem machbaren Bereich, damit Sie sich auf die eigentliche Herausforderung konzentrieren können — die Akklimatisierung. Wählen Sie einen technisch anspruchsvollen 6.000er, wissen Sie hinterher nicht, was schiefging.",

    "q.m11#7.p" to "[Reihenfolge] Ordnen Sie diese Ziele von der niedrigsten zur höchsten Höhe.",
    "q.m11#7.o0" to "Lobuche East (6.119 m)",
    "q.m11#7.o1" to "Yuzhu (6.178 m)",
    "q.m11#7.o2" to "Island Peak (6.189 m)",
    "q.m11#7.o3" to "Qizi (6.206 m)",
    "q.m11#7.e" to "Die Höhenspanne ist winzig — 6.119 bis 6.206 m, weniger als 90 m. Das macht den Punkt elegant: Im 6.000er-Band sollten Sie nach Routentyp, Unterstützung und eigenen Schwachpunkten wählen, nicht nach der Höhenzahl.",

    "q.m11#8.p" to "Warum müssen Sie bei 6.000 m grundsätzlich mit Spalten rechnen?",
    "q.m11#8.o0" to "Weil Spalten Geräusche machen",
    "q.m11#8.o1" to "Weil Schneebrücken vollständig von Neuschnee bedeckt sein können und wie normaler Boden aussehen",
    "q.m11#8.o2" to "Weil Spalten nur nachts auftreten",
    "q.m11#8.o3" to "Weil Spalten leicht zu erkennen sind",
    "q.m11#8.e" to "Genau das macht Spalten so tödlich: Anders als Steinschlag geben sie keine klare Warnung. Die richtige Haltung bei 6.000 m ist 'sie sind überall' — das Risiko mit Seilschaft und Ausrüstung managen, statt danach zu urteilen, ob es sicher aussieht.",

    "q.m11#9.p" to "Was zählt bei der Wahl eines 6.000ers mehr als die Höhe?",
    "q.m11#9.o0" to "Wie bekannt der Gipfel ist",
    "q.m11#9.o1" to "Routentyp (Trekking / gemischt / technisch), Unterstützungsbedingungen und Aufstiegstempo",
    "q.m11#9.o2" to "Die Kosten",
    "q.m11#9.o3" to "Beliebtheit in sozialen Medien",
    "q.m11#9.e" to "Gipfel ähnlicher Höhe können sich in technischem Anspruch und Akklimatisierungsdruck enorm unterscheiden. Erst die Kombination aus Routentyp, Unterstützung und Aufstiegstempo beantwortet die Frage, ob dieser Berg jetzt zu Ihnen passt.",

    "q.m11#10.p" to "Welche Sicht auf die technische Schwelle bei 6.000 m ist richtig?",
    "q.m11#10.o0" to "Sie ist sehr niedrig; Kondition ist alles",
    "q.m11#10.o1" to "Sie ist nicht hoch, aber Sie können nicht bei null anfangen, und Gletschertechnik ist Pflicht",
    "q.m11#10.o2" to "Sie brauchen einen Kletterhintergrund am Fels",
    "q.m11#10.o3" to "Sie müssen mit zusätzlichem Sauerstoff umgehen können",
    "q.m11#10.e" to "Das typische 6.000er-Profil: mäßige technische Schwierigkeit, aber Sie müssen bereits anseilen, Spaltenrisiko beurteilen und sich selbstständig auf einem Gletscher bewegen können. Hier beginnt 'ich kann mich mit einem System schützen' — nicht das Zuschauen bei anderen.",

    "q.m11#11.p" to "Warum ist die beste Jahreszeit eines Gipfels so entscheidend für den Plan?",
    "q.m11#11.o0" to "Weil Permits außerhalb der Saison billiger sind",
    "q.m11#11.o1" to "Weil das besteigbare Fenster stark von saisonalen Wettermustern abhängt; die falsche Jahreszeit bietet womöglich fast kein Fenster",
    "q.m11#11.o2" to "Weil die Jahreszeit die Farbe des Schnees ändert",
    "q.m11#11.o3" to "Weil Führer nur in der Hochsaison arbeiten",
    "q.m11#11.e" to "Die Gründe unterscheiden sich je Gipfel: Manche Jahreszeiten meiden Monsunniederschlag, andere die extreme Winterkälte und den Wind. Zu verstehen, warum eine Jahreszeit funktioniert, ist weit wichtiger als den Monat auswendig zu lernen — zumal der Klimawandel diese Muster verschiebt.",

    // ---------- m12 Mechanische Systeme ----------
    "q.m12#0.p" to "Warum erzeugt ein 3:1-Z-System (Z-Drag) die dreifache Zugkraft?",
    "q.m12#0.o0" to "Weil es ein dickeres Seil verwendet",
    "q.m12#0.o1" to "Weil die Kombination aus Prusik und Rolle Ihren Zugweg verdreifacht",
    "q.m12#0.o2" to "Weil die Schwerkraft hilft",
    "q.m12#0.o3" to "Weil Rollen automatisch Kraft sparen",
    "q.m12#0.e" to "Mechanische Übersetzung heißt im Kern: Weg gegen Kraft tauschen. Sie ziehen drei Meter Seil, und die Last steigt einen Meter. Der Preis ist Tempo — und bei der Spaltenrettung ist dieser Preis vollkommen akzeptabel.",

    "q.m12#1.p" to "Was ist die Hauptaufgabe der Rolle im Rettungssystem?",
    "q.m12#1.o0" to "Zusätzliche Festigkeit liefern",
    "q.m12#1.o1" to "Seilreibungsverluste senken und die Systemeffizienz erhöhen",
    "q.m12#1.o2" to "Das Seil fixieren",
    "q.m12#1.o3" to "Das Seil vor Verschleiß schützen",
    "q.m12#1.e" to "Reibung ist der versteckte Feind der Übersetzung: Jede Umlenkung kostet Kraft. Eine Rolle macht aus Gleitreibung Rollreibung, sodass das theoretische 3:1 dem realen 3:1 näherkommt.",

    "q.m12#2.p" to "Kann man ein Rettungssystem ohne Rollen bauen?",
    "q.m12#2.o0" to "Auf keinen Fall",
    "q.m12#2.o1" to "Ja, mit Karabinern — aber die Reibung steigt deutlich und die Effizienz sinkt",
    "q.m12#2.o2" to "Ja, nur mit Seil, bei gleicher Effizienz",
    "q.m12#2.o3" to "Nein, Sie müssen auf Ausrüstung warten",
    "q.m12#2.e" to "Karabiner können Rollen ersetzen, deshalb gelten zusätzliche Verschlusskarabiner bei vielen als Pflichtausrüstung. Der Unterschied ist, dass die tatsächliche Übersetzung deutlich unter dem theoretischen Wert liegt — das zu wissen hilft, sich körperlich und mental vorzubereiten, wenn das Material unvollständig ist.",

    "q.m12#3.p" to "[Mehrfachauswahl] Was nennt das Handbuch als Standard-Rettungsausrüstung der Seilschaft?",
    "q.m12#3.o0" to "2–3 Schneeanker oder Eisschrauben",
    "q.m12#3.o1" to "2–5 Karabiner und 2–5 Schlingen",
    "q.m12#3.o2" to "1 Sicherungsrolle",
    "q.m12#3.o3" to "2–3 Prusikschlingen und 1 Steigklemme",
    "q.m12#3.o4" to "1 Campingkocher mit Gaskartusche",
    "q.m12#3.e" to "Die Kernaussage dieser Liste ist, dass jedes Mitglied der Seilschaft genug Rettungsausrüstung tragen soll — also persönliche Ausrüstung, kein Gemeinschaftsmaterial. Wenn jemand fällt, ist das, was am Gurt hängt, die einzige verfügbare Ausrüstung.",

    "q.m12#4.p" to "Wie bremst eine Steigklemme?",
    "q.m12#4.o0" to "Mit einer Feder, die das Seil klemmt",
    "q.m12#4.o1" to "Durch Gegenreibung zwischen Stahlzähnen und Seil",
    "q.m12#4.o2" to "Durch magnetische Anziehung",
    "q.m12#4.o3" to "Durch das Eigengewicht des Seils",
    "q.m12#4.e" to "Den Mechanismus zu verstehen ist in der Anwendung wichtig: Weil Stahlzähne in die Fasern beißen, schädigt zu viel Kraft das Seil und kann an der Laststelle Fasern durchtrennen. Deshalb betont das Handbuch, sie nach Möglichkeit mit unterstützter Bremsmethode einzusetzen.",

    "q.m12#5.p" to "Was passiert, wenn Sie eine Steigklemme zu hart belasten?",
    "q.m12#5.o0" to "Gar nichts",
    "q.m12#5.o1" to "Die Stahlzähne beschädigen das Seil",
    "q.m12#5.o2" to "Die Steigklemme klemmt fest",
    "q.m12#5.o3" to "Die Steigklemme fällt ab",
    "q.m12#5.e" to "Die Zähne bremsen durch Gegenreibung, deshalb vernarbt starke Kraft den Mantel und kann kumulativ eine Bruchstelle erzeugen. Sie werden viele sehen, die die Steigklemme gewohnheitsmäßig reißen — eine Gewohnheit gegen Sicherheit getauscht.",

    "q.m12#6.p" to "[Reihenfolge] Bringen Sie die Schritte beim Bau eines 3:1-Z-Systems in eine sinnvolle Ordnung.",
    "q.m12#6.o0" to "Prüfen, dass der Standplatz hält, und das Gewicht des Gestürzten darauf übertragen",
    "q.m12#6.o1" to "Den Hauptprusik auf das belastete Seil setzen und einen Sicherungsprusik ergänzen",
    "q.m12#6.o2" to "Eine Rolle oder einen Karabiner am Prusik befestigen, um den Z-Weg zu bilden",
    "q.m12#6.o3" to "Das ganze System prüfen, dann ziehen und nach jedem Zug neu spannen",
    "q.m12#6.e" to "Der erste Schritt ist das Fundament: Ohne Gewichtsübertragung bleiben Ihre Hände zum Halten der Bremse gebunden. Und der letzte Schritt — nach jedem Zug neu spannen — wird leicht übersprungen, und dann ziehen Leute lange und rutschen wieder zurück.",

    "q.m12#7.p" to "[Zuordnung] Ordnen Sie jedem Rettungsmittel seine Rolle im System zu.",
    "q.m12#7.l0" to "Prusik",
    "q.m12#7.r0" to "Einweggriff, damit das System vorwärts kommt und nicht zurückläuft",
    "q.m12#7.l1" to "Rolle",
    "q.m12#7.r1" to "Senkt Reibungsverluste und erhöht die Effizienz",
    "q.m12#7.l2" to "Sicherungsrolle",
    "q.m12#7.r2" to "Blockiert in eine Richtung; dient zur Kontrolle von Ausgeben und Anziehen",
    "q.m12#7.l3" to "Steigklemme",
    "q.m12#7.r3" to "Läuft am Seil aufwärts; auch nützlich zum Fixieren des Systems",
    "q.m12#7.e" to "Vier verschiedene Aufgaben: Der Prusik liefert das Einwegverhalten, die Rolle senkt die Reibung, das Sicherungsgerät liefert die Kontrolle, die Steigklemme die Beweglichkeit. Fällt eines weg, wird das System entweder ineffizient oder unkontrollierbar.",

    "q.m12#8.p" to "Warum einen Sicherungsprusik neben dem Hauptprusik setzen?",
    "q.m12#8.o0" to "Für die Optik",
    "q.m12#8.o1" to "Weil ein Prusik durch Vereisung, Schmutz oder falsche Durchmesser versagen kann, und ein Versagen sofort die Übersetzung kostet",
    "q.m12#8.o2" to "Weil die Regeln es verlangen",
    "q.m12#8.o3" to "Um Seilverdrehung zu verhindern",
    "q.m12#8.e" to "Ein Prusik wirkt durch Reibung, und Reibung hängt von vielem ab. Rutscht der Hauptprusik, stürzt der Gestürzte ohne Vorwarnung erneut — Aufgabe des Sicherungsprusiks ist, genau diesen Moment aufzufangen.",

    "q.m12#9.p" to "Wie wählen Sie zwischen 2:1- und 3:1-System?",
    "q.m12#9.o0" to "2:1 ist immer besser",
    "q.m12#9.o1" to "Nach Mannschaft, Seillänge und Gelände: Mehr Übersetzung braucht mehr Seil und ist langsamer",
    "q.m12#9.o2" to "3:1 ist immer besser",
    "q.m12#9.o3" to "Sie sind identisch",
    "q.m12#9.e" to "Mechanische Übersetzung ist nicht bedingungslos gut: 3:1 braucht mehr Seil, und bei der Spaltenrettung ist Seil oft knapp. Die echte Wahl ist das System, das Sie mit Ihrem Seil und Ihren Leuten abschließen können — nicht das theoretisch optimale.",

    "q.m12#10.p" to "Warum kann ein Übersetzungssystem die Urteilskraft nie ersetzen?",
    "q.m12#10.o0" to "Weil Systeme kaputtgehen",
    "q.m12#10.o1" to "Weil ein System nur Kraft vervielfacht; es kann nicht entscheiden, ob gezogen wird oder in welche Richtung",
    "q.m12#10.o2" to "Weil Systeme schwer sind",
    "q.m12#10.o3" to "Weil sie viele Leute brauchen",
    "q.m12#10.e" to "Das Schwierige an einer Rettung ist nie die Physik, sondern das Urteil — welche Richtung, über welche Kante und ob der Verletzte das überhaupt übersteht. Das System ist ein Werkzeug; die Richtung kommt von Menschen. Ist die Richtung falsch, macht mehr Kraft es schlimmer.",

    "q.m12#11.p" to "Was davon lässt einen Prusik nicht versagen?",
    "q.m12#11.o0" to "Unpassende Seildurchmesser",
    "q.m12#11.o1" to "Eis oder Schmutz",
    "q.m12#11.o2" to "Zu wenige Windungen",
    "q.m12#11.o3" to "Eine hellere Farbe des Hauptseils",
    "q.m12#11.e" to "Durchmesser, Sauberkeit und Zahl der Windungen beeinflussen die Reibung direkt; die Farbe hat mit der Mechanik nichts zu tun. Das zeigt auch, dass sich die Zuverlässigkeit eines Prusiks nicht optisch beurteilen lässt — nur durch vorheriges Prüfen der Kombination und Testen im Feld.",

    "q.m12#12.p" to "Warum wird oft eine Sicherungsrolle statt einer einfachen Rolle verwendet?",
    "q.m12#12.o0" to "Weil sie leichter ist",
    "q.m12#12.o1" to "Weil sie in eine Richtung blockiert, sodass Sie das Ausgeben kontrollieren können, ohne dass das System zurückläuft",
    "q.m12#12.o2" to "Weil sie billiger ist",
    "q.m12#12.o3" to "Weil die Farbe besser sichtbar ist",
    "q.m12#12.e" to "Bei Rettungen wird oft gleichzeitig gezogen und nachgestellt, und eine einfache Rolle läuft in beide Richtungen frei — loslassen heißt Fortschritt verlieren. Ein in eine Richtung blockierendes Bauteil macht das Halten der Position zu einer Eigenschaft des Systems. Ein klares Beispiel dafür, wie Materialwahl die Betriebssicherheit beeinflusst.",

    "q.m12#13.p" to "Ergänzen Sie: Die mechanische Übersetzung des Z-Systems ist ( ):1.",
    "q.m12#13.a0" to "3",
    "q.m12#13.a1" to "drei",
    "q.m12#13.e" to "3:1. Der praktische Wert dieser Zahl liegt in der Lastschätzung: Ein Erwachsener mit Ausrüstung wiegt vielleicht 80–100 kg, bei 3:1 müssen Sie also noch mit etwa 30 kg Kraft ziehen — viel härter, als es klingt, weshalb Rettungen mehrere Leute brauchen.",

    "q.m12#14.p" to "[Mehrfachauswahl] Was soll die Kontrolle nach dem Aufbau abdecken?",
    "q.m12#14.o0" to "Prusikwindungen und Lastrichtung stimmen",
    "q.m12#14.o1" to "Rollen und Karabiner sind verschlossen",
    "q.m12#14.o2" to "Die Anschlagpunkte sitzen am richtigen Teil des Gurtes",
    "q.m12#14.o3" to "Eine Sicherung ist vorhanden und das Seil klemmt nicht",
    "q.m12#14.o4" to "Seil und Kleidung der Partner haben dieselbe Farbe",
    "q.m12#14.e" to "Die vier Prüfungen entsprechen vier klassischen Fehlern: Prusik verkehrt, Verschluss offen, am falschen Ring eingehängt, keine Sicherung. Fehler in Rettungssystemen sind selten Wissensmangel — sie sind ein vergessener Schritt im Dunkeln und unter Stress. Nutzen Sie eine Checkliste, nicht das Gedächtnis.",

    "q.m12#15.p" to "Warum muss ein Rettungssystem vor dem Aufbruch geübt werden?",
    "q.m12#15.o0" to "Um eine Prüfung zu bestehen",
    "q.m12#15.o1" to "Weil die echte Rettung in der Höhe, in Kälte und Dunkelheit aus dem Instinkt heraus passiert",
    "q.m12#15.o2" to "Um die Ausrüstung kennenzulernen",
    "q.m12#15.o3" to "Weil Vorschriften Übungsstunden vorgeben",
    "q.m12#15.e" to "Die Bedingungen bei einer echten Rettung sind fast immer die schlechtesten: Wind, kalte Hände, schlechtes Licht, ein Partner, dem es schlechter geht. Unter diesen Bedingungen werden nur Handlungen ausgeführt, die Sie oft wiederholt haben — vor Ort lernen ist keine Option.",

    // ---------- m13 Selbstrettung ----------
    "q.m13#0.p" to "Warum ist Selbstrettung bei 7.000 m eine harte Anforderung?",
    "q.m13#0.o0" to "Weil Partner nicht retten wollen",
    "q.m13#0.o1" to "Weil Partner in der Höhe möglicherweise nicht rechtzeitig zu Ihnen kommen — Sie müssen Ihre eigene Lage bewältigen können",
    "q.m13#0.o2" to "Weil die Rettungsausrüstung unzureichend ist",
    "q.m13#0.o3" to "Weil die Regeln es verlangen",
    "q.m13#0.e" to "Je höher Sie kommen, desto teurer und langsamer wird Rettung. Ein Partner kämpft vielleicht selbst mit Höhenkrankheit, und das Wetter verbietet womöglich jede Bewegung. Sich ganz der Rettung von außen zu übergeben heißt, eine Prämisse zu akzeptieren, die niemand garantieren kann.",

    "q.m13#1.p" to "Was ist das Grundprinzip des Prusik-Aufstiegs?",
    "q.m13#1.o0" to "Sich mit Armkraft hochziehen",
    "q.m13#1.o1" to "Zwei Prusiks abwechselnd nutzen: Der eine trägt das Gewicht, während der andere am Seil hochgeschoben wird",
    "q.m13#1.o2" to "Es allein mit einer Steigklemme machen",
    "q.m13#1.o3" to "Das Seil zwischen den Beinen einklemmen",
    "q.m13#1.e" to "Ein einzelner Prusik hält nur eine Position und kann sich nicht bewegen, deshalb müssen zwei abwechseln: Während der untere das Gewicht trägt, schiebt sich der obere hoch, und umgekehrt. Diese Wechselbewegung muss in sicherem Umfeld gedrillt werden; sie entscheidet in dem Moment, in dem Sie sie am dringendsten brauchen, ob Sie überhaupt hochkommen.",

    "q.m13#2.p" to "Warum muss beim Prusik-Aufstieg immer mindestens ein Prusik belastet bleiben?",
    "q.m13#2.o0" to "Um Kraft zu sparen",
    "q.m13#2.o1" to "Weil Sie beim gleichzeitigen Lösen beider zurückrutschen oder ganz abstürzen",
    "q.m13#2.o2" to "Damit das Seil ordentlich liegt",
    "q.m13#2.o3" to "Um schneller zu steigen",
    "q.m13#2.e" to "Das ist die Drei-Punkte-Regel auf das Seil übertragen: immer einen verlässlichen Stützpunkt behalten. In einer Spalte kostet ein Rutscher nicht nur Kraft, sondern das Seil kann sich weiter in die Schneekante einschneiden und die ganze Rettung erschweren.",

    "q.m13#3.p" to "[Reihenfolge] Bringen Sie die vier Schritte einer Seilschaftsrettung in die richtige Ordnung.",
    "q.m13#3.o0" to "Sofort selbst bremsen und sich stabilisieren",
    "q.m13#3.o1" to "Einen unabhängigen Standplatz bauen",
    "q.m13#3.o2" to "Die Last auf den Standplatz übertragen",
    "q.m13#3.o3" to "Mit einem 3:1-System ziehen",
    "q.m13#3.e" to "Diese vier Schritte haben Sie in der 6.000-m-Einheit gelernt; hier zählt, sie unter Druck auszuführen. Der größte Unterschied zwischen Übung und Ernstfall: Im Ernstfall müssen die ersten drei Schritte in Sekunden sitzen, in der Übung haben Sie sich vielleicht fünf Minuten gelassen.",

    "q.m13#4.p" to "Wie weit sollten Gruppenmitglieder in einem Gewitter auseinanderbleiben?",
    "q.m13#4.o0" to "Dicht gedrängt",
    "q.m13#4.o1" to "Etwa 50 m",
    "q.m13#4.o2" to "Etwa 500 m",
    "q.m13#4.o3" to "Ohne Begrenzung",
    "q.m13#4.e" to "Das Handbuch empfiehlt etwa 50 m Abstand — der Sinn ist, dass ein Einschlag nicht mehrere Personen gleichzeitig verletzt, sodass noch jemand Erste Hilfe leisten kann. Hinter der Zahl steht ein einfacher Gedanke: niemals alles auf eine Stelle setzen.",

    "q.m13#5.p" to "Was ist die einzige wirksame Maßnahme, um die Gefahr im Gewitter zu senken?",
    "q.m13#5.o0" to "Metallausrüstung wie Eispickel wegwerfen",
    "q.m13#5.o1" to "Hochpunkte und exponiertes Gelände so schnell wie möglich verlassen und dabei so tief wie möglich bleiben",
    "q.m13#5.o2" to "Sich klein machen und die Knie umfassen",
    "q.m13#5.o3" to "Alle Reißverschlüsse öffnen",
    "q.m13#5.e" to "Das Handbuch weist mehrere gängige Praktiken ausdrücklich zurück: Es gibt keinen Beleg, dass kleine Metallgegenstände wie Eispickel oder Zeltstangen Blitze anziehen — verschwenden Sie also keine Zeit damit, sie wegzuwerfen. Was tatsächlich wirkt, ist die Veränderung der Position: vom höchsten Objekt der Umgebung zu einem unauffälligen Teil der Landschaft.",

    "q.m13#6.p" to "Wenn Sie Donner hören können, ist der Blitz höchstens etwa entfernt:",
    "q.m13#6.o0" to "3 km",
    "q.m13#6.o1" to "10–16 km",
    "q.m13#6.o2" to "30 km",
    "q.m13#6.o3" to "50 km",
    "q.m13#6.e" to "Donner zu hören heißt, der Blitz ist innerhalb von 10–16 km — bereits in dem Bereich, in dem Sie reagieren müssen. Einen Blitz zu sehen heißt, die Entfernung beträgt höchstens etwa 24 km — zwei Zahlen, zwei verschiedene Reaktionsstufen.",

    "q.m13#7.p" to "Wie schätzen Sie die Blitzentfernung aus der Verzögerung zwischen Blitz und Donner?",
    "q.m13#7.o0" to "Sekunden × 0,34 = Entfernung in km",
    "q.m13#7.o1" to "Sekunden ÷ 0,34 = Entfernung in km",
    "q.m13#7.o2" to "Sekunden × 3,4 = Entfernung in km",
    "q.m13#7.o3" to "Das lässt sich nicht schätzen",
    "q.m13#7.e" to "Schall breitet sich in Luft mit etwa 0,34 km pro Sekunde aus, jede gezählte Sekunde nach dem Blitz entspricht also rund 0,34 km. Der praktische Wert: ganz ohne Ausrüstung erkennen Sie, ob das Gewitter näher kommt oder abzieht.",

    "q.m13#8.p" to "Ziehen kleine Metallgegenstände (Eispickel, Zeltstangen) Blitze an?",
    "q.m13#8.o0" to "Ja — sofort wegwerfen",
    "q.m13#8.o1" to "Es gibt keinen Beleg dafür, verschwenden Sie also keine Zeit mit Wegwerfen",
    "q.m13#8.o2" to "Ja, aber nur in großer Höhe",
    "q.m13#8.o3" to "Nur wenn sie nass sind",
    "q.m13#8.e" to "Das ist ein klassischer Höhenmythos. Das Handbuch ist deutlich: Es gibt keine Belege, also verschwenden Sie keine kostbare Zeit mit Ausrüstung entsorgen. Sie müssen die exponierte Position so schnell wie möglich verlassen — das ist die entscheidende Variable.",

    "q.m13#9.p" to "Wo ist der beste Ort, um sich im Gewitter zu schützen?",
    "q.m13#9.o0" to "Auf einem Gipfel",
    "q.m13#9.o1" to "Mitten im Wald, abseits von Gipfel und Grat — aber nie an einen Baum gelehnt",
    "q.m13#9.o2" to "Mitten an einem Grashang",
    "q.m13#9.o3" to "In einem Zelt",
    "q.m13#9.e" to "Die Waldmitte funktioniert, weil um Sie herum höhere Objekte stehen, Sie aber nicht direkt an einem Blitzableiter anliegen. Das Gegenbeispiel ist das Zelten auf einem offenen Grat — das Handbuch nennt es ausgesprochen töricht, weil Sie sich damit bewusst am höchsten Punkt der Umgebung einquartiert haben.",

    "q.m13#10.p" to "Warum sollten Sie nicht auf einem Grat zelten, während Quellwolken wachsen?",
    "q.m13#10.o0" to "Weil der Wind stark ist",
    "q.m13#10.o1" to "Weil aus wachsenden Quellwolken Cumulonimbus wird, das heißt Blitze, und ein Grat der exponierteste Ort überhaupt ist",
    "q.m13#10.o2" to "Weil die Sicht schlecht ist",
    "q.m13#10.o3" to "Weil der Boden uneben ist",
    "q.m13#10.e" to "Der Übergang von Quellwolke zu Cumulonimbus dauert oft nur ein bis zwei Stunden. Zelten auf einem Grat stellt Sie direkt an den Anfang der Zugbahn des Gewitters — mit der ganzen Ausrüstung und den Zelten, in einem Zustand, in dem schnelle Evakuierung fast unmöglich ist.",

    "q.m13#11.p" to "Jemand wurde gerade vom Blitz getroffen. Was hat Vorrang?",
    "q.m13#11.o0" to "Zuerst äußere Verletzungen prüfen",
    "q.m13#11.o1" to "Sofort Atmung und Puls prüfen, bei Bedarf mit der Wiederbelebung beginnen und schnellstmöglich medizinische Hilfe holen",
    "q.m13#11.o2" to "Zuerst trockene Kleidung anziehen",
    "q.m13#11.o3" to "Zuerst in tieferes Gelände bringen",
    "q.m13#11.e" to "Ein Einschlag kann Herzstillstand und innere Verletzungen verursachen, ohne sichtbare Spuren zu hinterlassen. Atmung und Puls zu prüfen kommt deshalb vor allem anderen — und auch ein ansprechbarer Patient muss evakuiert werden, weil die Wirkung des Stroms auf das Herz später auftreten kann.",

    "q.m13#12.p" to "[Mehrfachauswahl] Was umfasst Selbstrettungsfähigkeit normalerweise?",
    "q.m13#12.o0" to "Prusik-Aufstieg",
    "q.m13#12.o1" to "Selbstbremsung und Selbstsicherung",
    "q.m13#12.o2" to "Einen Standplatz ohne Hilfe des Partners bauen",
    "q.m13#12.o3" to "Beurteilen, wann man an Ort und Stelle wartet und wann man sich selbst befreit",
    "q.m13#12.o4" to "Free Solo ohne Sicherung",
    "q.m13#12.e" to "Die ersten drei sind Fähigkeiten, die vierte ist Urteilskraft. Beachten Sie besonders 'beurteilen, wann man wartet und wann man sich selbst befreit': Nicht jede Lage verlangt Selbstbefreiung — wenn Sie verletzt sind oder das Wetter schlechter wird, kann Warten auf Rettung sicherer sein als unbedachtes Handeln.",

    "q.m13#13.p" to "Warum kann 'ich warte, bis mein Partner mich rettet' nicht Ihre Hauptsicherheitsstrategie sein?",
    "q.m13#13.o0" to "Weil Partner nicht wollen",
    "q.m13#13.o1" to "Weil der Partner selbst in Gefahr, verletzt oder bewegungsunfähig sein kann",
    "q.m13#13.o2" to "Weil es nicht genug Rettungsausrüstung gibt",
    "q.m13#13.o3" to "Weil die Regeln es nicht erlauben",
    "q.m13#13.e" to "Der Sinn des Anseilens ist gegenseitiger Schutz, aber Sie dürfen nicht annehmen, dass Ihr Partner Reservekapazität hat. In der Höhe übersteigt es oft die Möglichkeiten, wenn ein Mitglied die Probleme von zwei Personen lösen soll — deshalb ist Selbstrettung eine Anforderung und Partnerrettung ein Bonus.",

    // ---------- m14 Gefahrenbeurteilung und Entscheidung ----------
    "q.m14#0.p" to "Welche Frage versucht die Gefahrenbeurteilung wirklich zu beantworten?",
    "q.m14#0.o0" to "Ist da Gefahr?",
    "q.m14#0.o1" to "Ist dieses Risiko akzeptabel, und auf welcher Grundlage?",
    "q.m14#0.o2" to "Wie groß ist die Gefahr?",
    "q.m14#0.o3" to "Werden meine Partner Angst bekommen?",
    "q.m14#0.e" to "Ist da Gefahr? lautet fast immer ja — keine Bergaktivität ist risikofrei. Die eigentliche Frage ist, ob dieses Risiko im Verhältnis zum Gewinn vertretbar ist und worauf wir das stützen. Genau deshalb muss das Urteil aussprechbar und diskutierbar sein.",

    "q.m14#1.p" to "Was ist die Unfallkette?",
    "q.m14#1.o0" to "Die Zahl der Verletzten bei einem Unfall",
    "q.m14#1.o1" to "Ein Prozess, in dem sich mehrere kleine Fehler nacheinander aufstapeln, bis ein Unfall passiert",
    "q.m14#1.o2" to "Der Zeitablauf einer Rettung",
    "q.m14#1.o3" to "Eine Kette von Ausrüstungsdefekten",
    "q.m14#1.e" to "Das Wertvollste an diesem Konzept ist, dass es einen Unfall von Pech in einen beeinflussbaren Prozess verwandelt. An jedem einzelnen Glied eine andere Wahl, und das Ergebnis ändert sich.",

    "q.m14#2.p" to "Was ist die wirksamste Art, die Unfallkette zu unterbrechen?",
    "q.m14#2.o0" to "An irgendeinem Glied eine konservativere Wahl treffen",
    "q.m14#2.o1" to "Sich nur auf das letzte Glied konzentrieren",
    "q.m14#2.o2" to "Mehr Ausrüstung mitnehmen",
    "q.m14#2.o3" to "Die Kondition der Gruppe verbessern",
    "q.m14#2.e" to "Jedes Glied taugt dafür — früher starten, rechtzeitig umkehren, nicht an der Sicherung sparen, um Zeit zu gewinnen. Deshalb ist Reserve besser als Reparatur: Reserve wirkt früh in der Kette, Reparatur meist am letzten Glied.",

    "q.m14#3.p" to "[Mehrfachauswahl] Welche davon sind verbreitete Entscheidungsfehler?",
    "q.m14#3.o0" to "Versunkene Kosten",
    "q.m14#3.o1" to "Gruppendruck",
    "q.m14#3.o2" to "Zielfixierung",
    "q.m14#3.o3" to "Risikonormalisierung",
    "q.m14#3.o4" to "Glaube an Ausrüstungsmarken",
    "q.m14#3.e" to "Die vier wirken zusammen: Wir haben schon viel investiert (versunkene Kosten), alle anderen gehen noch hoch (Gruppendruck), wir sind fast da (Zielfixierung), und letztes Mal ging es gut (Risikonormalisierung). Treten alle vier gleichzeitig auf, kippt das Urteil fast zwangsläufig zum Risiko.",

    "q.m14#4.p" to "Wie beeinflussen versunkene Kosten Bergentscheidungen?",
    "q.m14#4.o0" to "Sie machen vorsichtiger",
    "q.m14#4.o1" to "Nach so viel investierter Zeit und so viel Geld fällt es schwer zuzugeben, dass man aufhören sollte",
    "q.m14#4.o2" to "Sie verbessern die Kondition",
    "q.m14#4.o3" to "Sie haben keinen Einfluss",
    "q.m14#4.e" to "Versunkene Kosten sind dadurch definiert, dass sie nicht zurückzuholen sind — psychologisch werden sie aber zum Grund, weiter zu investieren. Am Berg wird daraus zusammen mit der Zielfixierung aus einem vernünftigen Rückzug ein Aufgeben, und gegen Aufgeben haben Menschen eine natürliche Abwehr.",

    "q.m14#5.p" to "Was ist Risikonormalisierung?",
    "q.m14#5.o0" to "Gefahr in einem akzeptablen Bereich halten",
    "q.m14#5.o1" to "Eine Bedingung nach mehreren sicheren Durchgängen unbewusst als sicher einstufen",
    "q.m14#5.o2" to "Methoden der Risikobeurteilung lernen",
    "q.m14#5.o3" to "Eine standardisierte Risikobewertung verwenden",
    "q.m14#5.e" to "Risikonormalisierung geschieht langsam, deshalb bemerkt sie der Betroffene kaum. Derselbe Kletterer ist beim ersten Mal am Steilhang extrem vorsichtig und seilt beim zehnten Mal nicht mehr an — der Hang hat sich nicht verändert, das Urteil schon.",

    "q.m14#6.p" to "Warum ist Mehrheitsentscheid in Risikoumgebungen problematisch?",
    "q.m14#6.o0" to "Weil er ineffizient ist",
    "q.m14#6.o1" to "Weil ein Mehrheitsentscheid die berechtigte Sorge einer Minderheit unterdrückt",
    "q.m14#6.o2" to "Weil Abstimmungen nicht immer fair sind",
    "q.m14#6.o3" to "Weil die Gruppengrößen verschieden sind",
    "q.m14#6.e" to "Gefahrensignale werden oft nur von ein oder zwei Personen bemerkt — jemand hat einen Riss in der Schneedecke gesehen — und diese Beobachtung ist Wissen einer Minderheit, aber tödlich, wenn sie stimmt. Über ihren Wert abzustimmen ignoriert systematisch Signale mit geringer Wahrscheinlichkeit und schwerer Folge.",

    "q.m14#7.p" to "Warum gilt 'die konservativste Meinung setzt sich durch'?",
    "q.m14#7.o0" to "Weil konservative Menschen erfahrener sind",
    "q.m14#7.o1" to "Weil unter Unsicherheit der Preis eines Irrtums auf der konservativen Seite weit geringer ist als auf der riskanten",
    "q.m14#7.o2" to "Weil die Regeln es verlangen",
    "q.m14#7.o3" to "Damit alle zufrieden sind",
    "q.m14#7.e" to "Das ist ein Lehrbuchfall asymmetrischer Kosten: Konservativ kann eine vergeudete Reise bedeuten, riskant kann Tod bedeuten. Bei asymmetrischen Kosten sollte die Entscheidung zur Seite mit beherrschbarem Preis neigen — und diese Neigung muss vor dem Aufbruch vereinbart sein, sonst ist sie vor Ort kaum umsetzbar.",

    "q.m14#8.p" to "[Zuordnung] Ordnen Sie jedem Entscheidungsfehler seinen typischen Ausdruck zu.",
    "q.m14#8.l0" to "Versunkene Kosten",
    "q.m14#8.r0" to "Wir sind so weit gekommen — jetzt umkehren wäre Verschwendung",
    "q.m14#8.l1" to "Gruppendruck",
    "q.m14#8.r1" to "Alle wollen weiter; es wäre mir unangenehm, den Abbruch vorzuschlagen",
    "q.m14#8.l2" to "Zielfixierung",
    "q.m14#8.r2" to "Es ist nur noch das letzte Stück",
    "q.m14#8.l3" to "Risikonormalisierung",
    "q.m14#8.r3" to "Letztes Mal ging es doch gut",
    "q.m14#8.e" to "Interessant ist, dass diese vier Sätze in Unfallauswertungen ständig auftauchen — und die Leute, die sie sagen, oft erfahrene Bergsteiger sind. Genau das ist der Punkt: Es sind keine Anfängerprobleme, sondern Probleme der menschlichen Kognition.",

    "q.m14#9.p" to "Warum heißt 'erfahrener' nicht 'urteilt genauer'?",
    "q.m14#9.o0" to "Weil Erfahrung langsamer macht",
    "q.m14#9.o1" to "Weil Erfahrung die Risikotoleranz allmählich erhöht",
    "q.m14#9.o2" to "Weil Erfahrung keine Rolle spielt",
    "q.m14#9.o3" to "Weil Veteranen sturer sind",
    "q.m14#9.e" to "Erfahrung bringt Vertrautheit, und Vertrautheit stumpft die Wachsamkeit ab. Erfahrene Gruppen brauchen deshalb mehr äußere Begrenzungen, nicht weniger — feste Umkehrzeiten, bezifferte Wetterschwellen — um mit Regeln einer Intuition entgegenzuwirken, die schon abgestumpft ist.",

    "q.m14#10.p" to "[Reihenfolge] Wie sieht ein sauberer Prozess für eine Rückzugsentscheidung aus?",
    "q.m14#10.o0" to "Die vor dem Aufbruch vereinbarten objektiven Signale prüfen (Zeit, Wetter, Gruppenzustand)",
    "q.m14#10.o1" to "Prüfen, ob die tatsächlichen Bedingungen eines davon ausgelöst haben",
    "q.m14#10.o2" to "Die vorher bestimmte Person ruft den Rückzug aus",
    "q.m14#10.o3" to "Rückzug durchführen und die Menschen zu Hause informieren",
    "q.m14#10.e" to "Der Wert des Prozesses liegt darin, zuerst den Maßstab und dann die Lage zu prüfen — nicht umgekehrt. Drehen Sie die Reihenfolge um, und der Maßstab wird von der Stimmung vor Ort so lange angenagt, bis daraus 'schauen wir noch ein bisschen' wird.",

    "q.m14#11.p" to "Warum vorher festlegen, wer den Rückzug ausrufen darf?",
    "q.m14#11.o0" to "Um die Schuldzuweisung zu erleichtern",
    "q.m14#11.o1" to "Weil es für niemanden leicht ist, spontan gegen die Stimmung der Gruppe zu handeln",
    "q.m14#11.o2" to "Um die Autorität der Leitung zu stärken",
    "q.m14#11.o3" to "Um den Prozess zu dokumentieren",
    "q.m14#11.e" to "Rückzug heißt, die Erwartung der ganzen Gruppe zu enttäuschen, und das ist in einer Gruppenatmosphäre sehr schwer zu beginnen. Machen Sie 'den Rückzug ausrufen' zu einer vorher verliehenen Pflicht statt zu einem Akt persönlichen Muts — nur dann passiert es tatsächlich.",

    "q.m14#12.p" to "Wann sollten Sie in Betracht ziehen, die Tour zu beenden?",
    "q.m14#12.o0" to "Nie, solange der Gipfel noch möglich ist",
    "q.m14#12.o1" to "Wenn eines der vorher vereinbarten objektiven Signale ausgelöst ist",
    "q.m14#12.o2" to "Nur wenn ein Gruppenmitglied verletzt ist",
    "q.m14#12.o3" to "Wann immer die schwächste Person es entscheidet",
    "q.m14#12.e" to "Ausgelöst heißt aufhören: Das ist der ganze Sinn bezifferter Kriterien. Es verwandelt die Entscheidung von 'sollen wir' in 'ist es ausgelöst'. Das erste verlangt Argumente und Überzeugung, das zweite nur die Prüfung von Fakten — deshalb lässt es sich vor Ort wirklich umsetzen.",

    "q.m14#13.p" to "Was ist das wirksamste Mittel gegen Zielfixierung?",
    "q.m14#13.o0" to "Persönliche Willenskraft",
    "q.m14#13.o1" to "Die Kriterien vor dem Aufbruch beziffern, sodass 'Aufweichen' zu einer ausdrücklichen Handlung wird, die den Partnern erklärt werden muss",
    "q.m14#13.o2" to "Gar kein Ziel setzen",
    "q.m14#13.o3" to "Mehr Ausrüstung mitnehmen",
    "q.m14#13.e" to "Psychologische Verzerrung lässt sich nicht durch die Ermahnung vermeiden, nicht darauf hereinzufallen. Der brauchbare Weg ist, 'bei Zeit umkehren' zum Standard zu machen, sodass der, der weiter will, aktiv Gründe liefern muss — die Beweislast mit einem Griff umgedreht.",

    "q.m14#14.p" to "Warum heißt 'niemand hat widersprochen' nicht 'alle waren einverstanden'?",
    "q.m14#14.o0" to "Weil sie es vielleicht nicht gehört haben",
    "q.m14#14.o1" to "Weil Schweigen nur heißen kann, dass niemand die Stimmung verderben wollte, während echte Zweifel unausgesprochen blieben",
    "q.m14#14.o2" to "Weil jemand geschlafen hat",
    "q.m14#14.o3" to "Weil Widerspruch ignoriert wurde",
    "q.m14#14.e" to "Deshalb erzeugen gute Gruppen absichtlich Widerspruch — die Leitung fragt direkt 'wer ist dafür, dass wir nicht weitergehen', oder geht herum und lässt jede Person eine Position beziehen. Schweigen am Berg bedeutet nicht Zustimmung; es bedeutet nur, dass nichts gesagt wurde.",

    "q.m14#15.p" to "Ergänzen Sie: Bei Entscheidungen unter Unsicherheit sollte zuerst die ( ) Meinung übernommen werden.",
    "q.m14#15.a0" to "konservativste",
    "q.m14#15.e" to "Konservativ zuerst ist eine Regel, die Sie vor Ort direkt ausführen können: Sie müssen nicht beurteilen, wessen Argument stärker ist, sondern nur, welche Option konservativer ist. Der Preis ist eine möglicherweise vergeudete Reise — ein Preis, den es wert ist.",

    "q.m14#16.p" to "Szenario: Das Wetter verschlechtert sich am Gipfeltag eines 7.000ers",
    "q.m14#16.c" to "Es ist Gipfeltag auf 7.000 m, Sie sind um 3 Uhr gestartet. Um 8 Uhr erreichen Sie einen Punkt, etwa zwei Stunden unterhalb des Gipfels. Der Wind hat deutlich aufgefrischt, von Westen zieht Bewölkung herein und die Temperatur fällt. Ein Gruppenmitglied hat begonnen, anhaltend zu husten, und wird sichtbar langsamer.",
    "q.m14#16.e" to "Der Kern dieses Szenarios ist keine einzelne Antwort, sondern die Reihenfolge: Fakten prüfen, Gefahrensignale erkennen, dem psychologischen Sog widerstehen, dann den Rückzug sauber durchführen. Die beiden Schritte, die am häufigsten scheitern, sind der erste (übersprungen) und der dritte (von Emotionen gekapert).",
    "q.m14#16.s0.p" to "Schritt 1: Welche Beurteilung ist jetzt zuerst nötig?",
    "q.m14#16.s0.o0" to "Gruppenzustand und Wettertrend bestätigen und mit den vor dem Aufbruch vereinbarten Umkehrsignalen abgleichen",
    "q.m14#16.s0.o1" to "Schneller gehen und den Gipfel erreichen, bevor das Wetter schlechter wird",
    "q.m14#16.s0.o2" to "An Ort und Stelle auf Besserung warten",
    "q.m14#16.s0.o3" to "Das langsame Mitglied allein absteigen lassen",
    "q.m14#16.s0.e" to "Jede Entscheidung sollte mit der Prüfung von Fakten beginnen: Wie steht die Gruppe, bessert oder verschlechtert sich das Wetter, ist ein festgelegtes Signal ausgelöst. Überspringen Sie das, entscheidet die Emotion für Sie.",
    "q.m14#16.s1.p" to "Schritt 2: Ein Gruppenmitglied hustet anhaltend. Was ist die vernünftigste Reaktion?",
    "q.m14#16.s1.o0" to "Kalte Luft reizt die Atemwege — weitergehen",
    "q.m14#16.s1.o1" to "In der Höhe muss das als starker Verdacht auf Lungenödem gelten: Aufstieg stoppen und so schnell wie möglich absteigen",
    "q.m14#16.s1.o2" to "Hustensaft geben und weitergehen",
    "q.m14#16.s1.o3" to "Zehn Minuten Pause machen lassen und dann weiter",
    "q.m14#16.s1.e" to "Auf 7.000 m ist anhaltender Husten in Ruhe oder bei leichter Belastung ein Signal, das hohen Verdacht verlangt. In dieser Höhe können die Kosten von 'noch ein bisschen beobachten' die Kosten eines sofortigen Abstiegs weit übersteigen.",
    "q.m14#16.s2.p" to "Schritt 3: Sie sind zwei Stunden vom Gipfel und entscheiden umzukehren. Was ist der größte psychologische Widerstand?",
    "q.m14#16.s2.o0" to "Unzureichende Kondition",
    "q.m14#16.s2.o1" to "Versunkene Kosten und Zielfixierung — 'wir sind doch so weit gekommen'",
    "q.m14#16.s2.o2" to "Ausrüstungsprobleme",
    "q.m14#16.s2.o3" to "Unkenntnis der Route",
    "q.m14#16.s2.e" to "Genau deshalb gibt es Umkehrzeiten: Sie verlegen die Entscheidung in einen Moment, in dem Sie noch rational sind. Wenn 'es ist nur noch ein Stück' auftaucht, brauchen Sie kein frisches Urteil, sondern den Abgleich mit der vorher vereinbarten Regel.",
    "q.m14#16.s3.p" to "Schritt 4: Wie sollte die Gruppe beim Abstieg organisiert sein?",
    "q.m14#16.s3.o0" to "Die Fittesten gehen voraus und bereiten das Lager vor",
    "q.m14#16.s3.o1" to "Als Gruppe zusammenbleiben, die stärkste Person führt und gibt das Tempo vor, und die Menschen zu Hause über den Zustand der Gruppe informieren",
    "q.m14#16.s3.o2" to "Aufteilen, um schneller abzusteigen",
    "q.m14#16.s3.o3" to "Das schwächste Mitglied langsam allein gehen lassen",
    "q.m14#16.s3.e" to "In der Höhe verliert eine Gruppe, sobald sie sich auseinanderzieht, die gegenseitige Deckung — und der Abstieg ist genau die unfallträchtige Phase. Als Einheit gehen, jemanden das Tempo kontrollieren lassen und die Außenwelt informiert halten: Alle drei sind unverzichtbar.",

    // ---------- m15 Wetterfenster und Wolkenlesen ----------
    "q.m15#0.p" to "Worin liegt der Kernwert des Wolkenlesens?",
    "q.m15#0.o0" to "Es lässt Bergsteigen professioneller aussehen",
    "q.m15#0.o1" to "Es verschafft Ihnen Vorlaufzeit bei Wetteränderungen",
    "q.m15#0.o2" to "Es ersetzt die Wettervorhersage",
    "q.m15#0.o3" to "Es misst die Höhe",
    "q.m15#0.e" to "Eine Vorhersage sagt Ihnen einen Tag voraus Bescheid, aber das Bergwetter ändert sich kleinräumig schnell. Wolken sind die Vorhersage direkt über Ihrem Kopf — die Vorlaufzeit beträgt vielleicht eine oder zwei Stunden, und genau diese Stunde entscheidet, ob Sie umkehren.",

    "q.m15#1.p" to "Was zeigt vertikales Wachsen von Quellwolken an?",
    "q.m15#1.o0" to "Stabiles Wetter",
    "q.m15#1.o1" to "Starke Konvektion, mögliche Entwicklung zum Cumulonimbus",
    "q.m15#1.o2" to "Baldige Abkühlung",
    "q.m15#1.o3" to "Der Bodenwind lässt nach",
    "q.m15#1.e" to "Eine Quellwolke selbst ist nicht gefährlich, aber sie ist ein Signal, das wächst. Entscheidend ist nicht, dass es eine Quellwolke ist, sondern dass Sie sie wachsen, auftürmen und dunkler werden sehen — dieser Prozess ist die Atmosphäre, die Energie sammelt.",

    "q.m15#2.p" to "Was bedeutet ein Amboss über einem Cumulonimbus?",
    "q.m15#2.o0" to "Er bildet sich noch",
    "q.m15#2.o1" to "Er hat Reife erreicht; Blitz, Hagel und starker Niederschlag sind alle möglich",
    "q.m15#2.o2" to "Er löst sich bald auf",
    "q.m15#2.o3" to "Er bedeutet nur starken Höhenwind",
    "q.m15#2.e" to "Der Amboss ist die von Höhenwind abgescherte Wolkenoberseite, was heißt: Der Aufwind hat die Tropopause erreicht und kann nicht weiter steigen — die Signatur eines reifen Gewitters. Wenn Sie einen Amboss sehen, ist Ihre Reaktionszeit schon kurz.",

    "q.m15#3.p" to "Zu welcher Tageszeit entstehen Quellwolken meist?",
    "q.m15#3.o0" to "Frühmorgens",
    "q.m15#3.o1" to "Vormittags",
    "q.m15#3.o2" to "Nachmittags",
    "q.m15#3.o3" to "Spät nachts",
    "q.m15#3.e" to "Die Ursache ist Sonneneinstrahlung: Der Boden erwärmt sich über den Tag und erzeugt Aufwinde und Konvektion. Das ist der physikalische Mechanismus hinter 'früh starten, rechtzeitig absteigen' — nicht bloß ein Stück Bauernweisheit.",

    "q.m15#4.p" to "Was zeigen Lenticularis-Wolken (pilz- oder scheibenförmig) meist an?",
    "q.m15#4.o0" to "Ruhiges Wetter",
    "q.m15#4.o1" to "Starken Wind",
    "q.m15#4.o2" to "Baldigen Regen",
    "q.m15#4.o3" to "Steigende Temperatur",
    "q.m15#4.e" to "Lenticularis sind Leewellenwolken, die entstehen, wenn Luft über einen Grat strömt — ihre bloße Existenz zeigt hohe Windgeschwindigkeiten in der Höhe. Am Berg heißt das: exponierte Grate können sehr starke Böen bekommen, und Böen sind die direkte Ursache für Gleichgewichtsverlust.",

    "q.m15#5.p" to "Deutlich zunehmende Cirren (faserige Hochwolken) zeigen meist:",
    "q.m15#5.o0" to "Ein Wettersystem nähert sich",
    "q.m15#5.o1" to "Die Kältewelle endet",
    "q.m15#5.o2" to "Der Wind lässt gleich nach",
    "q.m15#5.o3" to "Die UV-Strahlung wird schwächer",
    "q.m15#5.e" to "Cirren sind oft die Vorderkante eines Wettersystems — beim Auftreten hat sich das Wetter noch nicht geändert, aber die Änderung ist unterwegs. Das ist wertvolle Vorlaufzeit, besonders für einen Zeitplan, der früh zurück sein muss.",

    "q.m15#6.p" to "Sinkender Stratus mit deutlich fallender Wolkenuntergrenze hat welche unmittelbarste Wirkung?",
    "q.m15#6.o0" to "Die Temperatur steigt",
    "q.m15#6.o1" to "Die Sicht verschlechtert sich schnell und die Geländebeurteilung wird schwierig",
    "q.m15#6.o2" to "Der Wind lässt nach",
    "q.m15#6.o3" to "Der Niederschlag hört auf",
    "q.m15#6.e" to "Sinkender Stratus bringt keinen Regen, sondern Sichtverlust — und Sichtverlust ist ein Risiko für sich: Sie sind vielleicht schon neben der Route, nähern sich einer Wechte oder verpassen die Abzweigung zum Rückzug.",

    "q.m15#7.p" to "[Mehrfachauswahl] Welche Wolkenveränderungen zeigen verschlechterndes Wetter?",
    "q.m15#7.o0" to "Bewölkung nimmt schnell zu und die Schicht wird dicker",
    "q.m15#7.o1" to "Die Wolkenuntergrenze sinkt weiter",
    "q.m15#7.o2" to "Wolken dunkeln ab und entwickeln sich sichtbar vertikal",
    "q.m15#7.o3" to "Ein Amboss bildet sich",
    "q.m15#7.o4" to "Die Bewölkung beginnt abzunehmen und der Himmel klart auf",
    "q.m15#7.e" to "Diese vier sind Stufen eines Prozesses: Bewölkung nimmt zu, Untergrenze sinkt, der Körper dunkelt und türmt, ein Amboss erscheint. Sie in dieser Reihenfolge zu erkennen macht aus 'das Wetter hat gedreht' einen Prozess, vor dem Sie vorher gewarnt werden.",

    "q.m15#8.p" to "Warum entwickeln sich Wolken im Gebirge heftiger als im Flachland?",
    "q.m15#8.o0" to "Weil es höher und kälter ist",
    "q.m15#8.o1" to "Weil das Gelände die Luft nach oben zwingt und die Konvektion verstärkt",
    "q.m15#8.o2" to "Weil die UV-Strahlung stärker ist",
    "q.m15#8.o3" to "Weil die Luft dünn ist",
    "q.m15#8.e" to "Wind, der auf einen Berg trifft, wird nach oben gezwungen, als würde er eine Rampe hinaufgeschoben — Hebung erzeugt direkt Abkühlung und Kondensation, deshalb bilden sich Wolken schneller und lokaler als über einer Ebene. Darum kann Bergwetter in kürzester Zeit komplett umschlagen.",

    "q.m15#9.p" to "Woran erkennen Sie, ob eine Wolke sich entwickelt oder auflöst?",
    "q.m15#9.o0" to "An ihrer Farbe",
    "q.m15#9.o1" to "Daran, ob Volumen, Höhe und Randkontur im Verlauf wachsen und schärfer werden",
    "q.m15#9.o2" to "An der Temperatur",
    "q.m15#9.o3" to "An der Schneehöhe",
    "q.m15#9.e" to "Der Schlüssel ist fortlaufende Beobachtung — ein Blick liefert einen Zustand, zwei Blicke liefern einen Trend. Eine sich entwickelnde Wolke wächst im Volumen, ihr Oberrand steigt, ihre Ränder werden schärfer; eine sich auflösende macht das Gegenteil. In festen Abständen hochzuschauen kostet fast nichts und bringt viel.",

    "q.m15#10.p" to "[Zuordnung] Ordnen Sie jeder Wolkenart ihre Wetterbedeutung zu.",
    "q.m15#10.l0" to "Cumulonimbus (mit Amboss)",
    "q.m15#10.r0" to "Gewitter, Hagel und starker Niederschlag",
    "q.m15#10.l1" to "Lenticularis",
    "q.m15#10.r1" to "Starker Höhenwind, heftige Böen an Graten",
    "q.m15#10.l2" to "Cirrus",
    "q.m15#10.r2" to "Ein Wettersystem nähert sich",
    "q.m15#10.l3" to "Tiefer Stratus",
    "q.m15#10.r3" to "Die Sicht fällt, die Geländebeurteilung wird schwierig",
    "q.m15#10.e" to "Diese vier decken die vier Wetterinformationen ab, die Sie am Berg am häufigsten treffen. Eine Einschränkung: Wolkenlesen braucht Bildpraxis, und diese App hat derzeit nur Textfragen — bildgestützte Wolkenbestimmung folgt, sobald die Bildstrecke steht.",

    "q.m15#11.p" to "Warum muss Wolkenlesen mit dem Drucktrend kombiniert werden?",
    "q.m15#11.o0" to "Für die Vollständigkeit der Daten",
    "q.m15#11.o1" to "Weil Wolken den aktuellen Zustand zeigen, der Drucktrend aber die Richtung der Änderung",
    "q.m15#11.o2" to "Weil ein Barometer genauer ist",
    "q.m15#11.o3" to "Um die Höhe zu berechnen",
    "q.m15#11.e" to "Es sind verschiedene Dimensionen: Wolken sagen, was jetzt da ist, der Druck sagt, wohin es geht. Nur Wolken verleiten dazu, 'wird schlechter' als 'ist nur gerade bedeckt' zu lesen — mit dem Trend ist das Bild vollständig.",

    "q.m15#12.p" to "Was verursacht Whiteout-Bedingungen hauptsächlich?",
    "q.m15#12.o0" to "Übermäßigen Schneefall",
    "q.m15#12.o1" to "Dass Wolke, Nebel und Schneeoberfläche ähnlich hell sind, sodass die Grenze zwischen Boden und Himmel verschwindet",
    "q.m15#12.o2" to "Extrem niedrige Temperatur",
    "q.m15#12.o3" to "Übermäßige UV-Strahlung",
    "q.m15#12.e" to "Ein Whiteout ist kein starker Schneefall, sondern fehlender Kontrast. Wenn Schnee und Wolke ähnlich hell sind, verschwindet der Horizont, und Ihre Wahrnehmung von Distanz und Neigung fällt völlig aus — deshalb ist er weit gefährlicher als gewöhnlicher Schneefall.",

    "q.m15#13.p" to "Warum ist eine Vorhersage wie 'vereinzelte Schauer' im Gebirge nur begrenzt brauchbar?",
    "q.m15#13.o0" to "Weil Vorhersagen ungenau sind",
    "q.m15#13.o1" to "Weil die kleinräumige Wettervariation im Gebirge weit unter dem Vorhersageraster liegt, sodass die Bedingungen vor Ort völlig anders sein können",
    "q.m15#13.o2" to "Weil Kletterer keine Vorhersagen lesen",
    "q.m15#13.o3" to "Weil Niederschlag keine Rolle spielt",
    "q.m15#13.e" to "Das Vorhersageraster kann zig Kilometer breit sein, während die beiden Seiten eines Grats völlig anderes Wetter haben können. Die Vorhersage liefert das Hintergrundrisiko; die Beurteilung vor Ort entscheidet, ob Sie heute gehen können. Keines ersetzt das andere.",

    "q.m15#14.p" to "Die Vorhersage sagt 'sonnig', Sie sehen aber schnell vertikal wachsende Quellwolken. Wem vertrauen Sie?",
    "q.m15#14.o0" to "Der Vorhersage — wie geplant weiter",
    "q.m15#14.o1" to "Ihrer eigenen Beobachtung — entscheiden unter der Annahme, dass es schlechter wird",
    "q.m15#14.o2" to "Beides mitteln",
    "q.m15#14.o3" to "Noch eine Stunde weiter beobachten",
    "q.m15#14.e" to "Eine Vorhersage ist grob in Vorlaufzeit und Maßstab, die Beobachtung ist hier und jetzt. Wenn sie sich widersprechen, gewinnt der Befund vor Ort — das ist die Grundhaltung des ganzen Wetterbeurteilungssystems: Die Vorhersage setzt den Hintergrund, der Boden setzt die Handlung.",

    "q.m15#15.p" to "Ergänzen Sie: Nach einem Blitz entspricht jede gezählte Sekunde etwa ( ) Kilometern.",
    "q.m15#15.a0" to "0,34",
    "q.m15#15.a1" to "0.34",
    "q.m15#15.a2" to "null Komma drei vier",
    "q.m15#15.e" to "0,34 km pro Sekunde ist die Schallgeschwindigkeit in Luft. Diese Umrechnung macht aus Sekundenzählen ein brauchbares Werkzeug — ganz ohne Ausrüstung erkennen Sie, ob das Gewitter näher kommt oder abzieht.",

    "q.m15#16.p" to "[Mehrfachauswahl] In welchen Situationen sollten Sie einen sofortigen Abstieg ernsthaft erwägen?",
    "q.m15#16.o0" to "Quellwolken haben sich zu einem Cumulonimbus mit Amboss entwickelt",
    "q.m15#16.o1" to "Ein Whumpf — ein Setzungsgeräusch aus der Schneedecke",
    "q.m15#16.o2" to "Die Sicht fällt schnell und Sie können Ihre Position nicht mehr bestimmen",
    "q.m15#16.o3" to "Ein Gruppenmitglied zeigt fortschreitend schlimmer werdende Höhensymptome",
    "q.m15#16.o4" to "Ein Gruppenmitglied sagt, es sei etwas müde und wolle zehn Minuten Pause",
    "q.m15#16.e" to "Diese vier kommen aus vier Dimensionen — Wetter, Schneedecke, Navigation und Physiologie — und gemeinsam ist ihnen, dass sie fortschreitend sind: Der Preis jetzt ist weit geringer als der Preis in zehn Minuten. Je früher Sie sich zum Abstieg entscheiden, desto billiger wird es.",

    "q.m15#17.p" to "Klicken Sie in der Grafik die Kurve an, die die Nullgradgrenze darstellt.",
    "q.m15#17.e" to "Die Kurve der Nullgradgrenze ist eine der nützlichsten Informationen dieser Vorhersage: Sie markiert die Höhe, in der Niederschlag von Regen zu Schnee übergeht. Eine steigende Kurve heißt, wärmere und feuchtere Luft kommt an und der Niederschlag geht von Schnee zu Regen über; eine fallende Kurve heißt, kalte Luft ist da und höher gelegene Flächen bekommen Schnee. Für die Frage, ob Sie in Ihrer Höhe Schneefall treffen, ist sie besser als das Lesen von Temperaturzahlen.",

    "q.m15#18.p" to "Dies ist die Vorhersage für denselben Berg, bei dem die Saison früh endete. Wie hoch ist der Gesamtschneefall in Zentimetern über die drei Perioden am Fr 25 (vormittags / nachmittags / nachts)? Geben Sie die Summe ein.",
    "q.m15#18.a0" to "280",
    "q.m15#18.e" to "58 + 88 + 134 = 280 cm. Fast 2,8 m Schnee an einem Tag heißt: Die Route ist komplett begraben, die Lawinengefahr steigt stark, und Lager riskieren, eingedrückt zu werden. In dieser Größenordnung lautet die Frage nicht mehr, ob Sie den Gipfel schaffen, sondern ob Sie sicher evakuieren können — das ist die typische Art, in der ein Zyklon eine Saison früh beendet.",

    "q.m15#19.p" to "Szenario: eine Höhenwettervorhersage lesen",
    "q.m15#19.c" to "Ein Bergführer legt Ihnen zwei Manaslu-Vorhersagen vor — eine aus einem normalen Kletterfenster, eine aus den Aufzeichnungen einer Saison, die früh endete. Sie zu verstehen ist wichtiger, als eine Zahl auswendig zu lernen.",
    "q.m15#19.e" to "Wetterbeurteilung landet nie wirklich bei 'wie wird das Wetter morgen', sondern bei 'können wir in diesem Fenster gehen'. Dieselbe Oberfläche, einmal heißt sie weiter, einmal heißt sie aufhören — der Unterschied liegt nicht im Lesen der Grafik, sondern im Wissen, unter welchen Bedingungen Sie aufhören müssen.",
    "q.m15#19.s0.p" to "Schritt 1: In der Vorhersage für das normale Fenster — was stellen die rosa Blöcke in der Zeile der Gipfelhöhe (8.163 m) dar?",
    "q.m15#19.s0.o0" to "Erwarteten Schneefall für diesen Zeitraum",
    "q.m15#19.s0.o1" to "Regen für diesen Zeitraum",
    "q.m15#19.s0.o2" to "Gefühlte Temperatur für diesen Zeitraum",
    "q.m15#19.s0.o3" to "Windgeschwindigkeit für diesen Zeitraum",
    "q.m15#19.s0.e" to "Rosa ist Schnee, blau ist Regen — die Vorhersage markiert die Niederschlagsart auf jeder Höhe getrennt, gerade weil ihre Kernfrage lautet, ob es in Ihrer Höhe schneit oder regnet. Die Blöcke in der obersten Zeile sind klein und spärlich, der Gipfel bekommt also gelegentlich leichten Schnee ohne große Mengen.",
    "q.m15#19.s1.p" to "Schritt 2: Was ist im Vergleich zur Vorhersage am Saisonende die auffälligste Änderung?",
    "q.m15#19.s1.o0" to "Nur die Temperatur fällt",
    "q.m15#19.s1.o1" to "Schneefall und Windgeschwindigkeit steigen beide stark, und der Niederschlag deckt alle Höhenbänder ab",
    "q.m15#19.s1.o2" to "Regen ersetzt Schnee",
    "q.m15#19.s1.o3" to "Die Nullgradgrenze steigt deutlich",
    "q.m15#19.s1.e" to "Der Schneefall geht von verstreuten 1–4 cm auf 280 cm an einem Tag, der Wind von 25–30 km/h auf 55–60 km/h, und das Niederschlagsband reicht durch alle Höhen von 8.163 m bis 1.500 m. Alle drei gleichzeitig sind die Signatur eines Wettersystems, das direkt über Sie hinwegzieht.",
    "q.m15#19.s2.p" to "Schritt 3: Wenn Ihre Gruppe in einem solchen Vorhersagefenster wäre — was ist die richtige Entscheidung?",
    "q.m15#19.s2.o0" to "Den Gipfelanstieg beschleunigen, bevor das Wetter vollends schlechter wird",
    "q.m15#19.s2.o1" to "Den Gipfelversuch sofort abbrechen, planmäßig absteigen und die Evakuierung vorbereiten",
    "q.m15#19.s2.o2" to "Im Hochlager auf Besserung warten",
    "q.m15#19.s2.o3" to "In zwei Gruppen teilen, eine geht zum Gipfel, eine bleibt",
    "q.m15#19.s2.e" to "Wenn eine Vorhersage ein System zeigt, das direkt über einen hinwegzieht, und keine kurze Schwankung, heißt 'warten, bis es vorbei ist' meist mehrere weitere Tage in der Höhe — was weder Vorräte noch Zelte tragen. Deshalb enden so viele Saisons nicht mit 'wir haben es geschafft', sondern mit 'wir mussten raus' — und die Information für diese Entscheidung liefern genau diese beiden Grafiken.",

    "q.m15#20.p" to "Szenario: eine stündliche Vorhersage lesen",
    "q.m15#20.c" to "Dies ist eine stündliche Vorhersage für einen Tag am Gongga Shan (7.556 m). Ihre Informationsdichte ist weit höher als eine 16-Tage-Übersicht, aber es ist auch leichter, die falsche Zeile zu lesen — entscheidend ist zu wissen, was jede Zeile tatsächlich sagt.",
    "q.m15#20.e" to "Eine stündliche Vorhersage beantwortet, was eine Übersicht nicht kann: welcher konkrete Zeitraum handelbar ist. Die Nullgradgrenze legt die Niederschlagsart fest, die gefühlte Temperatur legt fest, ob ein Mensch es aushält, und Windgeschwindigkeit und Sonnenstunden bestimmen, wie breit das Fenster ist. Erst zusammen ergeben sie eine ausführbare Entscheidung.",
    "q.m15#20.s0.p" to "Schritt 1: Die Zeile Freeze zeigt die Nullgradgrenze zwischen 4.895 und 5.304 m, während der Gipfel des Gongga 7.556 m hoch ist. Was bedeutet diese Kombination?",
    "q.m15#20.s0.o0" to "Jeder Niederschlag am Berg fällt als Schnee",
    "q.m15#20.s0.o1" to "Am Gipfel wird es Regen geben",
    "q.m15#20.s0.o2" to "Auch unterhalb der Nullgradgrenze wird es schneien",
    "q.m15#20.s0.o3" to "Die Niederschlagsart lässt sich daraus nicht beurteilen",
    "q.m15#20.s0.e" to "Die Nullgradgrenze ist die Regen-Schnee-Grenze. Sie liegt stabil bei 4.900–5.300 m, während jede Aufstiegsroute darüber liegt. Anders gesagt: Die ganze Route liegt oberhalb der Nullgradgrenze, jeder Niederschlag kommt also als Schnee an. Eine Zahl beantwortet 'welche Niederschlagsform treffe ich' — deshalb ist die Nullgradgrenze nützlicher als eine Temperaturzahl.",
    "q.m15#20.s1.p" to "Schritt 2: Die Zeile Feels °C zeigt −18 bis −21, während Max / Min °C nur −10 bis −11 zeigt. Was erklärt diesen Unterschied vor allem?",
    "q.m15#20.s1.o0" to "Vorhersagefehler",
    "q.m15#20.s1.o1" to "Windchill — je stärker der Wind, desto niedriger die gefühlte Temperatur",
    "q.m15#20.s1.o2" to "Temperaturunterschied durch die Höhe",
    "q.m15#20.s1.o3" to "Die Wirkung von Feuchteänderungen",
    "q.m15#20.s1.e" to "Die Windgeschwindigkeit im selben Zeitraum beträgt 20–30 km/h. Wind auf bloßer Haut beschleunigt den Wärmeverlust, deshalb liegt die gefühlte Temperatur fast 10 °C unter der gemessenen Lufttemperatur. In der Höhe entscheidet die gefühlte Temperatur, ob Sie draußen bleiben können, nicht die Lufttemperatur. Dieselben −10 °C sind mit und ohne Wind völlig verschiedene Bedingungen.",
    "q.m15#20.s2.p" to "Schritt 3: Wie beurteilen Sie das Fenster mit dieser Vorhersage (Wind 20–30 km/h, verstreuter Schneefall 2/1/1 cm, gefühlt um −20 °C, Tageslicht 6:56–19:15)?",
    "q.m15#20.s2.o0" to "Die Bedingungen sind hart — jede Bewegung aufgeben",
    "q.m15#20.s2.o1" to "Es ist ein verhältnismäßig brauchbares Fenster; die Hauptbelastung sind Kälte und Windchill, nicht der Niederschlag",
    "q.m15#20.s2.o2" to "Zu viel Niederschlag — es besteht Lawinengefahr",
    "q.m15#20.s2.o3" to "Zu wenig Daten für ein Urteil",
    "q.m15#20.s2.e" to "Wind von 20–30 km/h liegt noch im handelbaren Bereich, und der Schneefall beträgt nur wenige Zentimeter. Der echte Druck kommt von einer gefühlten Temperatur um −20 °C, deshalb sind Erfrierungen und Unterkühlung das, wogegen Sie sich schützen. Die Logik für solche Fenster: Niederschlag und Wind passen, Temperatur und Dauer sind das Problem. Also Exposition verkürzen, Isolation an den Extremitäten verstärken und die Umkehrzeit vorziehen.",

    "q.m15#21.p" to "In derselben Gongga-Vorhersage liegt die gemessene Lufttemperatur bei etwa −11 °C, der gefühlte Tiefstwert bei −21 °C. Wie groß ist die Differenz in Grad Celsius?",
    "q.m15#21.a0" to "10",
    "q.m15#21.e" to "10 °C: −11 − (−21) = 10. Die Lücke ist selbst Entscheidungsinformation — kleiden Sie sich nach der gefühlten Temperatur, nicht nach der Lufttemperatur. Sie erklärt auch, wie Menschen bei −10 °C Erfrierungen bekommen: Sie haben sich nach der Zahl auf dem Diagramm gekleidet.",

    "q.m15#22.p" to "Diese Vorhersage zeigt die Windgeschwindigkeit als grüne Kreise. Was bedeutet das höchstwahrscheinlich?",
    "q.m15#22.o0" to "Die Windgeschwindigkeit in diesem Zeitraum liegt im für das Bergsteigen geeigneten Bereich",
    "q.m15#22.o1" to "Die Windgeschwindigkeit in diesem Zeitraum hat einen gefährlichen Wert erreicht",
    "q.m15#22.o2" to "In diesem Zeitraum gibt es Regen",
    "q.m15#22.o3" to "Winddaten fehlen für diesen Zeitraum",
    "q.m15#22.e" to "Professionelle Bergwetterdienste kodieren Windgeschwindigkeit meist nach ihrer Wirkung auf die Bewegung. 20–30 km/h in Grün heißt, es liegt im Band 'man kann gehen'; darüber wechselt die Farbe zu Gelb oder Rot.\nAber die Farbe ist der Vorschlag des Anbieters, nicht Ihr Maßstab. Verschiedene Routen und verschiedene Gruppen vertragen denselben Wind unterschiedlich. Die Zahl zu lesen ist wichtiger, als die Farbe zu lesen.",

    "q.m15#23.p" to "Diese professionelle Oberfläche zeigt Temperaturen für 8000 / 6000 / 4000 / 2000 m in vier parallelen Zeilen. Worin liegt der Hauptwert dieses Aufbaus?",
    "q.m15#23.o0" to "Sie können die Vorhersage für Ihre eigene Höhe direkt lesen, ohne aus Tieflanddaten hochzurechnen",
    "q.m15#23.o1" to "Die Seite wirkt dadurch reicher",
    "q.m15#23.o2" to "Es zeigt, dass die vier Zeilen nichts miteinander zu tun haben",
    "q.m15#23.o3" to "Nur um das Ausdrucken auf Papier zu erleichtern",
    "q.m15#23.e" to "Eine gewöhnliche Vorhersage liefert Daten für einen Ort, meist die nächste Stadt oder den Flughafen. Sie müssen mit einem Temperaturgradienten den Berg hochrechnen — ein Schritt, der leicht falsch geht und Geländedetails wegwirft.\nEin professioneller Bergdienst macht das Gegenteil: Er schneidet den Berg zuerst nach Höhen und sagt dann für jede Scheibe voraus. Sie müssen nur die Zeile für die Höhe suchen, in der Sie morgen sein werden, und sie lesen. Das ist zugleich ein einfacher Test, ob ein Wetterdienst taugt: Schneidet er nach Höhen?",

    "q.m15#24.p" to "In der Grafik zeigt die Zeile 'Cloud base (m)' für die meisten Zeiträume einen Strich (—). Wie ist das richtig zu lesen?",
    "q.m15#24.o0" to "Die Wolkenuntergrenze ist in diesem Zeitraum null, die Wolke liegt also am Boden",
    "q.m15#24.o1" to "Für diesen Zeitraum gibt es keine Daten zur Wolkenuntergrenze; es darf nicht als 'Wolkenuntergrenze = 0' gelesen werden",
    "q.m15#24.o2" to "Es heißt, dass es in diesem Zeitraum überhaupt keine Wolken gibt",
    "q.m15#24.o3" to "Es heißt, die Wolkenuntergrenze liegt über dem Gipfel",
    "q.m15#24.e" to "In einer Wettertabelle sind 'leer' und 'null' zwei völlig verschiedene Dinge. Leer heißt: für diesen Punkt in diesem Zeitraum gibt es keine Daten — er ist vielleicht nicht abgedeckt, oder es lässt sich keine sinnvolle Schätzung abgeben. Es heißt nicht, der Wert sei null.\nEin Leerfeld als null zu lesen führt zu Schlüssen wie 'Wolke am Boden, schreckliche Sicht', die mit den Fakten nichts zu tun haben. Bei jeder Wettertabelle: Erst diese beiden trennen. Es ist der leichteste Fehler beim Lesen einer Vorhersage und der am seltensten benannte.",

    "q.m15#25.p" to "In der Windzeile dieser Oberfläche stehen die Zahlen mit Pfeilsymbolen. Was zeigen die Pfeile höchstwahrscheinlich?",
    "q.m15#25.o0" to "Den Trend der Windgeschwindigkeit",
    "q.m15#25.o1" to "Die Windrichtung",
    "q.m15#25.o2" to "Die Niederschlagswahrscheinlichkeit",
    "q.m15#25.o3" to "Steigende oder fallende Temperatur",
    "q.m15#25.e" to "In der Höhe müssen Geschwindigkeit und Richtung zusammen gelesen werden. Dieselben 30 km/h fühlen sich auf der Luv- und der Leeseite völlig verschieden an und wirken auch anders auf die Schneedecke: Wind transportiert Schnee auf die Leeseite und häuft ihn zu Brettern. Das ist eine der wichtigsten Informationen bei der Beurteilung der Lawinengefahr.\nNur die Zahl und nicht die Richtung zu lesen wirft die Hälfte der Information weg. Professionelle Oberflächen setzen den Pfeil genau deshalb neben die Zahl, weil beides nicht getrennt gelesen werden kann.",

    "q.m15#26.p" to "In dieser 16-Tage-Grafik häufen sich rote Marker (Schnee) um das 6.000-m-Band, während blaue Marker (Regen) unter 5.000 m erscheinen. Was zeigt das?",
    "q.m15#26.o0" to "Die Regen-Schnee-Grenze liegt ungefähr zwischen 5.500 und 6.000 m",
    "q.m15#26.o1" to "Am Berg fällt nur Schnee, nie Regen",
    "q.m15#26.o2" to "Regen reicht bis zum Gipfel",
    "q.m15#26.o3" to "Das lässt sich aus dieser Grafik nicht beurteilen",
    "q.m15#26.e" to "Diese Grafik sagt nicht, was zu einer bestimmten Stunde wo fällt; sie beantwortet direkt, in welchem Höhenband der Niederschlag landet. Für Bergsteiger ist das genau die Information, die zählt.\nRot im 6.000-m-Band und Blau nur unter 5.000 m setzt die Regen-Schnee-Grenze ungefähr zwischen 5.500 und 6.000 m. Zusammen mit der violetten Nullgradkurve in der Legende (fallend von etwa 6.000 m auf etwa 4.800 m) sehen Sie außerdem, dass die Grenze im Vorhersagezeitraum weiter sinkt: Bänder, die jetzt Regen bekommen, gehen allmählich in Schnee über.\nDieselbe Niederschlagsmenge wirkt auf eine Tour völlig unterschiedlich, je nachdem ob sie als Regen oder als Schnee fällt.",

    "q.m15#27.p" to "In der stündlichen Vorhersage derselben Grafik erscheint um 17 Uhr ein Blitzsymbol. Was bedeutet dieses Signal in der Höhe?",
    "q.m15#27.o0" to "Nur ein Symbol — keine besondere Behandlung nötig",
    "q.m15#27.o1" to "Gewitterrisiko: Bewegung auf den Vormittag legen und Grate sowie exponiertes Gelände am Nachmittag verlassen",
    "q.m15#27.o2" to "Starker Regen kommt — einfach eine Regenjacke mitnehmen",
    "q.m15#27.o3" to "Die Windgeschwindigkeit steigt auf ein gefährliches Niveau",
    "q.m15#27.e" to "Nachmittagsgewitter sind in der Höhe häufig und wirklich gefährlich. Geländebedingte Hebung lässt Quellwolken am Nachmittag schnell wachsen. 'Früh starten' heißt also nicht nur härterer Schnee — es heißt auch, exponiertes Gelände zu verlassen, bevor Stürme entstehen.\nDie Kernpunkte im Gewitter: Abstand zu Gipfeln, Graten, einzeln stehenden Bäumen und Wasser halten; nicht flach auf dem Boden liegen; die Gruppe etwa 50 m auseinanderziehen, damit ein Einschlag nicht mehrere Menschen verletzt. Die Blitzentfernung in Kilometern lässt sich als Sekunden zwischen Blitz und Donner × 0,34 schätzen.",

    "q.m15#28.p" to "Wie ist bei einer Geländedatenquelle mit Gipfelmarkierung der richtige Kompromiss?",
    "q.m15#28.o0" to "Eine Markierung bedeutet immer mehr Genauigkeit; nur Karten mit Markierung vertrauen",
    "q.m15#28.o1" to "Markierungen sind praktisch für schnelle Orientierung und Verständigung, aber die präzise Geländebeurteilung braucht weiterhin Höhenlinien",
    "q.m15#28.o2" to "Eine Karte ohne Markierungen ist nutzlos",
    "q.m15#28.o3" to "Markierungen stören nur beim Lesen; ignorieren",
    "q.m15#28.e" to "Auf dieser Google-Karte des Muztagh Ata ist der Gipfel direkt mit einer roten Nadel markiert. Das ist für Orientierung und Verständigung sehr nützlich: Sie wissen sofort, wo das Ziel liegt, und können einem Partner genau den Punkt benennen, den Sie meinen.\nAber eine Markierung beantwortet nicht, wie steil dieser Hang ist oder wo ein Lager hin kann. Die präzise Geländebeurteilung hängt weiterhin an den Höhenlinien, und die Markierung spielt darin keine Rolle.\nDas praktische Vorgehen: mit der Markierung schnell lokalisieren, dann mit hochauflösenden Höhenlinien (etwa der SRTM-Version) Hangneigung und Geländedetail lesen. Jedes erfüllt seine Aufgabe.",

    // ---------- m16 Lawinenbeurteilung und Geländelesen ----------
    "q.m16#0.p" to "Welche drei Maßstäbe muss die fortgeschrittene Lawinenbeurteilung verbinden?",
    "q.m16#0.o0" to "Temperatur, Windgeschwindigkeit, Niederschlag",
    "q.m16#0.o1" to "Regionale Prognose, Gelände, Schneedecke",
    "q.m16#0.o2" to "Höhe, Hangneigung, Sonneneinstrahlung",
    "q.m16#0.o3" to "Gruppengröße, Ausrüstung, Zeit",
    "q.m16#0.e" to "Die drei beantworten verschiedene Fragen: Die Prognose sagt, wie riskant der Tag insgesamt ist, das Gelände sagt, ob dieser Hang Schnee halten und abgleiten kann, die Schneedecke sagt, ob er jetzt stabil ist. Mit nur der Prognose beurteilen Sie den Hang unter Ihren Füßen nach einem regionalen Mittelwert.",

    "q.m16#1.p" to "Bei welcher Lawinengefahrenstufe passieren die meisten Unfälle?",
    "q.m16#1.o0" to "1 (gering)",
    "q.m16#1.o1" to "3 (erheblich)",
    "q.m16#1.o2" to "5 (sehr groß)",
    "q.m16#1.o3" to "Kein Unterschied",
    "q.m16#1.e" to "Bei Stufe 5 bleiben die Leute weg, deshalb passieren dann tatsächlich weniger Unfälle; bei Stufe 3 wirkt das Gelände 'gehbar', also gehen viele in Lawinengelände. Der gefährlichste Zustand ist nie der extreme, sondern der unterschätzte mittlere.",

    "q.m16#2.p" to "In welchem Hangneigungsbereich passieren die meisten Lawinen?",
    "q.m16#2.o0" to "10°–25°",
    "q.m16#2.o1" to "34°–45°",
    "q.m16#2.o2" to "55°–70°",
    "q.m16#2.o3" to "Es gibt kein Muster",
    "q.m16#2.e" to "Etwa 96 % der Lawinen entstehen zwischen 30° und 50°, die meisten konzentriert zwischen 34° und 45°. Genau dieser Bereich wird von Aufstiegsrouten am häufigsten durchquert — steil genug zum Abgleiten, flach genug, um Schnee zu halten.",

    "q.m16#3.p" to "[Mehrfachauswahl] Welche Praktiken sind beim Queren von Lawinengelände richtig?",
    "q.m16#3.o0" to "Abstände halten und jeweils eine Person allein queren lassen",
    "q.m16#3.o1" to "Einen Beobachter an einer sicheren Stelle postieren",
    "q.m16#3.o2" to "Die Fluchtroute vorher festlegen",
    "q.m16#3.o3" to "Die ganze Gruppe schnell gemeinsam hinüber schicken, um die Exposition zu verkürzen",
    "q.m16#3.e" to "Die ersten beiden begrenzen das Risiko auf eine Person, der dritte sichert einen Ausweg, falls etwas passiert. 'Alle gleichzeitig hinüber' macht das Gegenteil — es verwandelt das Risiko, vielleicht eine Person zu verschütten, in das Risiko, die ganze Gruppe zu verschütten, und genau deshalb ist es die schlechteste Wahl.",

    "q.m16#4.p" to "Wo sollte der Beobachter stehen?",
    "q.m16#4.o0" to "Im Hang, der gequert wird",
    "q.m16#4.o1" to "Dort, wo er die querende Person klar sieht und selbst sicher ist",
    "q.m16#4.o2" to "Ganz oben am Hang",
    "q.m16#4.o3" to "Am Talboden",
    "q.m16#4.e" to "Ein Beobachter hat zwei Aufgaben: die Person im Blick behalten (um zu wissen, wo sie verschüttet wurde) und sofort handeln, wenn etwas passiert. Im Hang oder am Talboden zu stehen macht ihn zum zweiten Opfer — die eigene Sicherheit des Beobachters ist Voraussetzung für seine Aufgabe.",

    "q.m16#5.p" to "Wozu gräbt man ein Schneeprofil?",
    "q.m16#5.o0" to "Zum Ausruhen",
    "q.m16#5.o1" to "Um Schichtaufbau, Lage der Schwachschicht und Härteunterschiede direkt zu sehen",
    "q.m16#5.o2" to "Um die Temperatur zu messen",
    "q.m16#5.o3" to "Um Fotos zu machen",
    "q.m16#5.e" to "Eine Lawine braucht eine Schwachschicht plus ein Brett darüber, und dieser Aufbau wird erst sichtbar, wenn man hineinschneidet. Ein Profil macht aus einer unsichtbaren inneren Struktur sichtbaren Befund — der entscheidende Schritt vom Vermuten zum Beobachten.",

    "q.m16#6.p" to "Warum ist 'den Spuren der Vorausgehenden folgen' gefährlich?",
    "q.m16#6.o0" to "Weil die Spuren unklar sind",
    "q.m16#6.o1" to "Weil die Spuren Stunden alt sein können und sich die Schneedecke längst verändert hat",
    "q.m16#6.o2" to "Weil man die falsche Route nehmen könnte",
    "q.m16#6.o3" to "Weil Spuren das Gehen behindern",
    "q.m16#6.e" to "Der Zustand der Schneedecke verändert sich mit Temperatur, Wind und Neuschnee laufend — wenige Stunden reichen von 'kaum stabil' zu 'bereit auszulösen'. Spuren belegen nur, dass jemand damals hinüberkam; über die Sicherheit jetzt sagen sie nichts.",

    "q.m16#7.p" to "Wie wirkt Windverfrachtung auf die Lawinengefahr?",
    "q.m16#7.o0" to "Wind glättet den Schnee und senkt das Risiko",
    "q.m16#7.o1" to "Wind transportiert Schnee auf die Leeseite, baut zusätzliche Bretter und Schwachschichten und erhöht das Risiko stark",
    "q.m16#7.o2" to "Wind hat nichts mit Lawinen zu tun",
    "q.m16#7.o3" to "Wind beeinflusst nur die Sicht",
    "q.m16#7.e" to "Wind ist der am meisten unterschätzte Lawinenbildner: In kurzer Zeit kann er viel Schnee auf Leeseiten verfrachten, dicke Bretter bauen und darin Schwachschichten erzeugen. Deshalb kann auch ohne Schneefall nach starkem Wind neue Lawinengefahr entstehen.",

    "q.m16#8.p" to "Was ist die Hauptgefahr einer Wechte?",
    "q.m16#8.o0" to "Sie versperrt die Sicht",
    "q.m16#8.o1" to "Sie kann jederzeit von selbst abbrechen, und ihr Abbruch kann am Hang darunter eine Lawine auslösen",
    "q.m16#8.o2" to "Ihre Farbe unterscheidet sich von der Schneeoberfläche",
    "q.m16#8.o3" to "Sie blockiert die Route",
    "q.m16#8.e" to "Eine Wechte ist doppelt gefährlich: Stehen Sie darauf, gehen Sie womöglich mit; gehen Sie darunter durch, kann sie mit sehr viel Schnee auf Sie herunterkommen. Üblich ist, auf der wechtenfernen Seite auszuweichen und nie auf einer Wechte zu rasten.",

    "q.m16#9.p" to "[Reihenfolge] Wie lautet das vollständige Vorgehen beim Queren von Lawinengelände?",
    "q.m16#9.o0" to "Vor dem Aufbruch die Lawinenprognose des Tages prüfen und die zu meidenden Hänge markieren",
    "q.m16#9.o1" to "Beim Annähern Feldzeichen beobachten (Risse, Setzungsgeräusche, windverfrachtete Oberflächen)",
    "q.m16#9.o2" to "Beobachter, Querungsreihenfolge und Fluchtroute festlegen",
    "q.m16#9.o3" to "Eine nach der anderen mit Abstand queren und an einem sicheren Punkt wieder sammeln",
    "q.m16#9.e" to "Die ersten drei Schritte geschehen alle, bevor Sie den Hang betreten — dort findet die eigentliche Lawinensicherheitsarbeit statt. Sobald Sie im Hang stehen, bleiben sehr wenige Möglichkeiten, und die meisten Unfälle gehen auf übersprungene erste zwei Schritte zurück.",

    "q.m16#10.p" to "Warum muss eine Lawinenrettung sofort von den Partnern durchgeführt werden?",
    "q.m16#10.o0" to "Weil professionelle Rettung teuer ist",
    "q.m16#10.o1" to "Weil das Überlebensfenster einer verschütteten Person nur etwa fünfzehn Minuten beträgt",
    "q.m16#10.o2" to "Weil professionelle Teams nicht hochkommen",
    "q.m16#10.o3" to "Weil Partner das Gelände besser kennen",
    "q.m16#10.e" to "Ein Überlebensfenster von fünfzehn Minuten heißt: Retten können Sie nur die, die neben Ihnen stehen. Deshalb muss das Lawinen-Dreier-Set getragen und geübt werden — Ausrüstung dabeizuhaben, die man nicht bedienen kann, ist wie nichts dabeizuhaben.",

    "q.m16#11.p" to "[Zuordnung] Ordnen Sie jeder Lawinengefahrenstufe ihre Bedeutung zu.",
    "q.m16#11.l0" to "Stufe 1",
    "q.m16#11.r0" to "Gering: natürliche und menschliche Auslösung unwahrscheinlich",
    "q.m16#11.l1" to "Stufe 3",
    "q.m16#11.r1" to "Erheblich: menschliche Auslösung möglich und am leichtesten unterschätzt",
    "q.m16#11.l2" to "Stufe 4",
    "q.m16#11.r2" to "Groß: natürliche Auslösung wahrscheinlich; Lawinengelände meiden",
    "q.m16#11.l3" to "Stufe 5",
    "q.m16#11.r3" to "Sehr groß: großflächige natürliche Lawinen sehr wahrscheinlich",
    "q.m16#11.e" to "Hinter jeder Zahl steht eine Kombination aus Auslösewahrscheinlichkeit und Schadensgröße. Der klassische Anfängerfehler ist, Stufe 3 für 'in Ordnung' zu halten — dabei ist es genau die Stufe, in der sich die Unfälle konzentrieren.",

    "q.m16#12.p" to "Was leistet ein Lawinenairbag, und wo liegen seine Grenzen?",
    "q.m16#12.o0" to "Er verhindert eine Verschüttung vollständig; Grenzen gibt es keine",
    "q.m16#12.o1" to "Er erhöht die Chance, näher an der Oberfläche zu bleiben; er ersetzt aber weder LVS, Sonde und Schaufel noch verhindert er Trauma",
    "q.m16#12.o2" to "Er ist nur für Skigebiete",
    "q.m16#12.o3" to "Er ruft automatisch Hilfe",
    "q.m16#12.e" to "Das Prinzip ist größeres Volumen, also eher nahe an der Oberfläche bleiben — das erhöht die Überlebenschance, garantiert sie aber nicht. Und ein erheblicher Teil der Lawinentoten stirbt an Trauma, nicht an Ersticken; deshalb darf ein Airbag nie die einzige Absicherung sein.",

    "q.m16#13.p" to "Warum sind Hänge, die 'nicht so steil aussehen', oft die gefährlichsten?",
    "q.m16#13.o0" to "Weil der Schnee tiefer liegt",
    "q.m16#13.o1" to "Weil sich Lawinen bei 34°–45° konzentrieren und das menschliche Auge die Hangneigung unterschätzt",
    "q.m16#13.o2" to "Weil dort wenige hingehen",
    "q.m16#13.o3" to "Weil sich der Winkel schnell ändert",
    "q.m16#13.e" to "Ohne Referenz schätzen Menschen Hangneigungen mit großem Fehler und lesen 35° oft als 25°. Und 30°–35° ist genau das Band, das 'gehbar aussieht, aber abgleiten kann'. Neigungsmesser und Höhenlinienkarte sind das Gegenmittel gegen diese Verzerrung.",

    "q.m16#14.p" to "[Mehrfachauswahl] Was muss eine Gruppe vor dem Betreten von Lawinengelände abschließen?",
    "q.m16#14.o0" to "Bestätigen, dass alle LVS, Sonde und Schaufel bedienen können",
    "q.m16#14.o1" to "Querungsreihenfolge und Beobachter vereinbaren",
    "q.m16#14.o2" to "Sammelpunkt und Fluchtroute vereinbaren",
    "q.m16#14.o3" to "Prüfen, dass die LVS senden",
    "q.m16#14.o4" to "Mehrfach kräftig stampfen, um die Schneedecke zu testen",
    "q.m16#14.e" to "Alle vier sind letzte Kontrollen vor dem Einstieg und dauern nur Minuten. Sie zählen, weil Ihnen im Hang als einzige Option bleibt, zu hoffen, dass nichts passiert.",

    "q.m16#15.p" to "Die Schneedecke gibt ein Whumpf — ein Setzungsgeräusch. Was ist die richtige Reaktion?",
    "q.m16#15.o0" to "Weitergehen — der Schnee setzt sich nur",
    "q.m16#15.o1" to "Sofort anhalten und neu beurteilen; eine Schwachschicht beginnt zu versagen",
    "q.m16#15.o2" to "Schneller hinübergehen",
    "q.m16#15.o3" to "Zehn Minuten an Ort und Stelle rasten",
    "q.m16#15.e" to "Ein Whumpf ist der direkte Beleg, dass eine Schwachschicht kollabiert — eine sehr leichte Last hat gerade lokales Versagen ausgelöst. Weiterzugehen heißt praktisch zu fragen, ob ein bisschen mehr das Ganze herunterbringt.",

    "q.m16#16.p" to "Ergänzen Sie: Etwa 96 % der Lawinen entstehen an Hängen von 30°–50°, die meisten konzentriert zwischen 34° und ( )°.",
    "q.m16#16.a0" to "45",
    "q.m16#16.a1" to "fünfundvierzig",
    "q.m16#16.e" to "34°–45°. Diesen Bereich sollte man sich merken, weil er zugleich Lawinen-Hotspot und die Neigung ist, die Aufstiegsrouten am häufigsten durchqueren — diese Überschneidung macht Lawinen zu einer der dominierenden objektiven Gefahren im Hochgebirge.",

    "q.m16#17.p" to "Szenario: ein Stück Lawinengelände queren",
    "q.m16#17.c" to "Die Route muss einen Schneehang von etwa 35° überqueren, rund 200 m lang. Die heutige Lawinenprognose ist Erheblich (Stufe 3), es liegt 30 cm Neuschnee, der Wind kommt aus Nordwest, der Hang zeigt nach Südost.",
    "q.m16#17.e" to "Dieses Szenario prüft den ganzen Lawinenablauf: Gelände und Schneedecke lesen, Vorbereitung vor dem Einstieg abschließen, dann mit der Aufstellung die Folgen begrenzen. Kein einzelner Schritt ist schwer; schwer ist, alle vor einem Hang auszuführen, der gehbar aussieht.",
    "q.m16#17.s0.p" to "Schritt 1: Was verdient an diesem Hang die größte Vorsicht?",
    "q.m16#17.s0.o0" to "Steinschlag",
    "q.m16#17.s0.o1" to "Windverfrachtete Bretter und die Hangneigung selbst",
    "q.m16#17.s0.o2" to "Hohe Temperatur",
    "q.m16#17.s0.o3" to "Bodenvegetation",
    "q.m16#17.s0.e" to "35° liegt mitten im Hotspot 34°–45°; Nordwestwind verfrachtet Schnee auf die Leeseite (hier die Südostflanke) und baut zusätzliche Bretter. Zwei Faktoren, die sich stapeln, sind die klassische Kombination 'sieht gehbar aus, kann abgleiten'.",
    "q.m16#17.s1.p" to "Schritt 2: Was ist beim Annähern an den Hang zuerst zu tun?",
    "q.m16#17.s1.o0" to "Sofort mit dem Queren beginnen",
    "q.m16#17.s1.o1" to "Erst Feldzeichen beobachten, dann Beobachter, Querungsreihenfolge und Fluchtroute festlegen",
    "q.m16#17.s1.o2" to "Kräftig auf den Hang stampfen, um ihn zu testen",
    "q.m16#17.s1.o3" to "Die ganze Gruppe schnell hinüber schicken",
    "q.m16#17.s1.e" to "Alle Vorbereitung gehört vor den Einstieg. Kräftiges Stampfen prüft die Stabilität nicht — es kann eine Schneedecke, die schon nahe am kritischen Punkt ist, direkt auslösen.",
    "q.m16#17.s2.p" to "Schritt 3: Wie soll die Gruppe beim Queren aufgestellt sein?",
    "q.m16#17.s2.o0" to "Eine nach der anderen, die übrigen warten an einem sicheren Punkt",
    "q.m16#17.s2.o1" to "Alle Hand in Hand gemeinsam",
    "q.m16#17.s2.o2" to "Zu zweit nebeneinander, um sich gegenseitig zu beobachten",
    "q.m16#17.s2.o3" to "In einer Reihe dicht hintereinander",
    "q.m16#17.s2.e" to "Eine nach der anderen begrenzt das Risiko auf eine Person und lässt den Beobachter sich auf eine Person konzentrieren. Die ganze Gruppe gleichzeitig zu exponieren vergrößert die Folge von 'vielleicht eine Person verschüttet' auf 'vielleicht alle'.",

    "q.m16#18.p" to "Klicken Sie auf der Karte den ungefähren Bereich des Manaslu-Gipfels an.",
    "q.m16#18.e" to "Ein Gipfel ist auf einer Höhenlinienkarte unverkennbar: Geschlossene Linien ziehen sich Ring für Ring nach innen zusammen, während die Beschriftungen nach oben steigen (7600 → 7750 → 7900 → 7950 …). Finden Sie den Punkt, der von Ringen kleiner geschlossener Kurven umschlossen ist, haben Sie die höchste Stelle.\nUmgekehrt: Wo die Linien nach außen auseinanderlaufen und die Beschriftungen fallen, geht es abwärts — was nebenbei zeigt, auf welcher Seite die Aufstiegsroute verläuft.",

    "q.m16#19.p" to "Auf derselben Karte sind die Höhenlinien auf der Nordost- bis Ostseite extrem dicht. Was bedeutet das?",
    "q.m16#19.o0" to "Diese Seite ist sehr steil und ein Hotspot für Serac- und Steinschlag",
    "q.m16#19.o1" to "Diese Seite ist flach und gut zum Zelten",
    "q.m16#19.o2" to "Diese Seite ist tiefer und deshalb weniger riskant",
    "q.m16#19.o3" to "Dichte Höhenlinien bedeuten, dass das Gelände dort eben ist",
    "q.m16#19.e" to "Je dichter die Höhenlinien, desto größer der Höhenunterschied auf gleicher horizontaler Distanz — also desto steiler. Auf dieser Karte fällt die Nordostseite von 7.950 m auf 5.750 m, mit Dutzenden Linien auf kurzer horizontaler Strecke: eine klassische Steilwand.\nBei der Routenplanung berührt diese Lesefähigkeit zwei Dinge direkt: ob Sie Serac- und Steinschlagzonen durchqueren und ob es brauchbares Rückzugsgelände gibt, wenn etwas schiefgeht. Flachere, dünn besetzte Bereiche sind die, in denen ein Lager eher möglich ist.",

    "q.m16#20.p" to "Szenario: zwei Geländedatenquellen vergleichen",
    "q.m16#20.c" to "Ein Bergführer legt Ihnen zwei Geländekarten desselben Berges vor: eine aus Google Maps, eine aus NASA-SRTM-Höhendaten erzeugt. Keine ist falsch, aber sie können Ihre Fragen nicht gleich gut beantworten.",
    "q.m16#20.e" to "Der Kerndifferenz zwischen Geländedatensätzen ist nicht die Genauigkeit, sondern die Äquidistanz — denn sie bestimmt, wie fein Sie eine Neigungsänderung sehen. Intuition hat Wert, sie baut schnell einen Gesamteindruck, aber die Entscheidung, ob ein Stück steil oder passierbar ist, hängt weiter an der Höhenliniendichte, und die lässt sich beziffern und vergleichen.",
    "q.m16#20.s0.p" to "Schritt 1: Auf dieser Google-Karte lauten die Höhenlinien-Beschriftungen 6200, 6400, 6600, 6800… Wie groß ist die Äquidistanz?",
    "q.m16#20.s0.o0" to "50 m",
    "q.m16#20.s0.o1" to "100 m",
    "q.m16#20.s0.o2" to "200 m",
    "q.m16#20.s0.o3" to "500 m",
    "q.m16#20.s0.e" to "Benachbarte Beschriftungen unterscheiden sich um 200 m, dieses Liniensystem steigt also 200 m zwischen zwei Linien. 200 m Äquidistanz reicht für die Gesamtform, aber Geländedetail zwischen den Linien — etwa eine 40-m-Felsstufe — verschwindet schlicht aus der Karte.",
    "q.m16#20.s1.p" to "Schritt 2: Die SRTM-Karte nutzt 50 m Äquidistanz. Was ist gegenüber der Google-Karte mit 200 m ihr wesentlichster Vorteil?",
    "q.m16#20.s1.o0" to "Sie sieht schöner aus",
    "q.m16#20.s1.o1" to "Auf gleicher horizontaler Distanz liegen die Linien dichter und lösen Neigungsänderungen viermal feiner auf",
    "q.m16#20.s1.o2" to "Die Farben sind kräftiger",
    "q.m16#20.s1.o3" to "Die Beschriftungen sind größer",
    "q.m16#20.s1.e" to "Je kleiner die Äquidistanz, desto mehr Geländedetail können Sie auflösen. Die Frage, ob ein Hang passierbar ist, hängt genau an der Höhenliniendichte: Bei 200 m Abstand wird eine 150 m hohe Steilstufe zu einem flachen Hang geglättet, bei 50 m wird sie so gezeichnet, wie sie ist.\nDeshalb stützt sich die Geländebeurteilung auf technischen Routen auf hochauflösende Quellen wie SRTM.",
    "q.m16#20.s2.p" to "Schritt 3: Die Google-Version hat ausgeprägte Licht- und Schattenflächen und wirkt dreidimensional. Wie sollen Sie diese Schattierung beim Beurteilen der Steilheit behandeln?",
    "q.m16#20.s2.o0" to "Je dunkler der Schatten, desto steiler — direkt als Beleg verwenden",
    "q.m16#20.s2.o1" to "Die Schattierung spiegelt nur Beleuchtung und Exposition; sie taugt nicht direkt als Steilheitsmaß",
    "q.m16#20.s2.o2" to "Die Schattierung markiert schneebedeckte Flächen",
    "q.m16#20.s2.o3" to "Die Schattierung markiert Gelände über 7.000 m",
    "q.m16#20.s2.e" to "Reliefschattierung simuliert, wie ein Hang von Sonne aus einer bestimmten Richtung beleuchtet wird. Dunkel heißt: Der Hang liegt abgewandt vom Licht, nicht dass er steil ist. Ein flacher Nordhang kann dunkler sein als ein steiler Südhang.\nSchattierung als Ersatz für Steilheit zu lesen ist ein häufiger und wirklich gefährlicher Fehlschluss. Schattierung ist gut für den Gesamteindruck; zur Quantifizierung lesen Sie die Höhenliniendichte und gleichen im Idealfall mit hochauflösenden Daten mit Höhenbeschriftung ab.",

    "q.m16#21.p" to "Wie ist die Aussage 'Google Maps ist anschaulich, aber ungenau; SRTM ist genau, aber nicht anschaulich' richtig zu verstehen?",
    "q.m16#21.o0" to "SRTM ist genauer, Google Maps hat keinen Wert",
    "q.m16#21.o1" to "Sie sollten zusammen genutzt werden: Gesamteindruck aus der anschaulichen Karte, quantifizierte Beurteilung aus hochauflösenden Höhenlinien",
    "q.m16#21.o2" to "Google Maps ist anschaulicher, also bei der Hangbeurteilung zuerst darauf vertrauen",
    "q.m16#21.o3" to "Sie unterscheiden sich nur in der Farbe, die Information ist gleich",
    "q.m16#21.e" to "Die beiden Quellen lösen verschiedene Probleme. Reliefschattierung und Ortsbezeichnungen von Google bauen schnell ein Raumgefühl auf: wo der Berg ist, seine grobe Form, wohin die Route läuft. Die 50-m-Höhenlinien von SRTM tragen die quantifizierte Beurteilung: wie viele Grad dieser Hang hat, ob es irgendwo Platz für ein Lager gibt.\nMit der anschaulichen Karte überschauen, mit der hochauflösenden bestätigen — das ist die praktische Arbeitsteilung. Nur eine zu nutzen ist entweder langsam oder falsch.",

    "q.m16#22.p" to "Klicken Sie auf der Karte den ungefähren Bereich des Everest-Gipfels an.",
    "q.m16#22.e" to "Um einen Gipfel zu finden, suchen Sie die höchste beschriftete geschlossene Höhenlinie. Hier steigen die Beschriftungen in diesem Bereich auf 8600 und 8700 m, während sich die Ringe nach innen zusammenziehen; der innerste ist der Gipfel (8.848 m).\nAchten Sie darauf, hoch und steil zu trennen: Gipfelgelände ist oft nicht der steilste Teil des Berges — am steilsten ist es dort, wo die Höhenlinien am dichtesten liegen. Diese Unterscheidung ist für das Routenrisiko wichtig: Der Gipfel fordert Akklimatisierung und Kondition, das technische Risiko sitzt vor allem in einigen Hängen auf dem Weg hinauf und hinunter.",

    "q.m16#23.p" to "Zwischen den dichten geschlossenen Höhenlinien von Everest und Lhotse auf derselben Karte liegt eine Zone, in der die Linien deutlich dünner werden und das Gelände leicht absinkt. Was ist das geländekundlich?",
    "q.m16#23.o0" to "Der Ursprung eines Gletschers",
    "q.m16#23.o1" to "Der Sattel zwischen den beiden Gipfeln",
    "q.m16#23.o2" to "Der höchste Punkt des Grats",
    "q.m16#23.o3" to "Eine steile Felswand",
    "q.m16#23.e" to "Zwischen zwei dichten geschlossenen Hochpunkten, wo die Linien dünner werden und das Gelände absinkt, liegt ein Sattel. Der zwischen Everest und Lhotse ist der South Col auf etwa 7.900 m, wo das vierte Lager der Südroute liegt — der letzte Halt vor dem Gipfelanstieg.\nSättel auf der Höhenlinienkarte zu erkennen ist sehr praktisch. Sie bedeuten meist starken Wind und Exposition, aber verhältnismäßig flaches Gelände: gut für ein Lager, schlecht zum Verweilen — deshalb liegen Gipfellager meist auf einem Sattel und werden noch in derselben Nacht geräumt.",

    "q.m16#24.p" to "Klicken Sie auf der Karte den ungefähren Bereich des Muztagh-Ata-Gipfels an.",
    "q.m16#24.e" to "Die Gipfelform des Muztagh Ata ist typisch: eine Kuppel, oben breit und flach, bei der die höchste geschlossene Höhenlinie weit gespreizt ist statt eng geschachtelt wie bei einem spitzen Gipfel. Um einen solchen Gipfel zu finden, suchen Sie die höchste Höhenbeschriftung (hier 7.500 m) und den geschlossenen Ring, in dem sie liegt.\nDie Form wirkt direkt auf das Bergerlebnis. Eine Kuppel heißt: Der Gipfelabschnitt ist nicht steil, dauert aber lange; bei wenig Relief und ohne markante Orientierungspunkte verliert man im Schneefeld beim Abstieg leicht die Richtung. Genau dieses Risiko wird im Zusammenhang mit dem Muztagh Ata oft genannt.",

    // ---------- m17 Lagerführung in der Höhe ----------
    "q.m17#0.p" to "Was ist das Kernziel der Lagerführung in der Höhe?",
    "q.m17#0.o0" to "Das Lager bequem machen",
    "q.m17#0.o1" to "Die Handlungsfähigkeit mit dem geringsten Aufwand erhalten",
    "q.m17#0.o2" to "Brennstoff sparen",
    "q.m17#0.o3" to "Gute Fotos machen",
    "q.m17#0.e" to "In der Höhe ist jede Einheit Energie eine begrenzte Ressource, und das Lager ist der einzige Ort, der sie zurückgibt. Jede Lagerentscheidung sollte daher dieselbe Frage beantworten: Steht das Team morgen besser da?",

    "q.m17#1.p" to "Was ist die erste Überlegung bei der Wahl des Lagerplatzes?",
    "q.m17#1.o0" to "Die Aussicht",
    "q.m17#1.o1" to "Lawinenbahnen, Serac-Sturz-Zonen, Flächen unter Wechten und Spalten meiden",
    "q.m17#1.o2" to "Die Nähe zu Wasser",
    "q.m17#1.o3" to "Die Nähe zum Routenbeginn",
    "q.m17#1.e" to "Die erste Regel der Standortwahl ist, nicht von einer objektiven Gefahr getroffen zu werden — denn im Lager halten Sie sich stunden- oder tageweise auf und können sich kaum schnell bewegen. Aussicht und Bequemlichkeit sind nachrangige Variablen.",

    "q.m17#2.p" to "Warum darf man nicht unter einer Wechte zelten?",
    "q.m17#2.o0" to "Weil der Boden uneben ist",
    "q.m17#2.o1" to "Weil eine Wechte jederzeit abbrechen und eine Schnee- und Eismasse direkt auf das Lager schicken kann",
    "q.m17#2.o2" to "Weil es dort windig ist",
    "q.m17#2.o3" to "Weil man die Aussicht nicht sieht",
    "q.m17#2.e" to "Ein Wechtenabbruch kommt ohne vorhersehbare Warnung: Er kann in der Nachmittagswärme kommen oder in der kältesten Stunde vor der Dämmerung. Unter einer Wechte zu lagern heißt, eine andauernde Bedrohung zu akzeptieren, die Sie weder überwachen noch vorher beantworten können.",

    "q.m17#3.p" to "[Mehrfachauswahl] Welche Bereiche sollte ein Lagerplatz meiden?",
    "q.m17#3.o0" to "Unter einer Lawinenbahn",
    "q.m17#3.o1" to "Direkt unter oder über einer Wechte",
    "q.m17#3.o2" to "Offensichtliche Spaltenfelder",
    "q.m17#3.o3" to "In Reichweite von Serac-Sturz",
    "q.m17#3.o4" to "Eine offene Stelle mit gutem Panorama",
    "q.m17#3.e" to "Alle vier sind Fälle, in denen eine objektive Gefahr genau auf das Lager trifft. Ihnen gemeinsam ist, dass sie schwer zu überwachen sind und im Fall des Falles die Konsequenz die ganze Gruppe betrifft — deshalb müssen die Standortkriterien für ein Lager konservativer sein als für eine Route.",

    "q.m17#4.p" to "Wie sollten Brennstoff und Verpflegung eingeteilt werden?",
    "q.m17#4.o0" to "Alles bei einer Person",
    "q.m17#4.o1" to "Tageweise abgepackt, mit einer zurückgelegten Notreserve",
    "q.m17#4.o2" to "Alles am Zelteingang",
    "q.m17#4.o3" to "Gleichmäßig nach Kopfzahl ohne Reserve",
    "q.m17#4.e" to "Tageweise zu packen macht den Verbrauch nachvollziehbar, und die Reserve garantiert, dass immer genug Energie für einen sicheren Abstieg da ist. Am Berg ist Brennstoff nicht nur zum Kochen — er ist auch, wie Sie Schnee zu Wasser schmelzen, Kleidung trocknen und die Körpertemperatur halten.",

    "q.m17#5.p" to "Warum eine Notreserve zurücklegen?",
    "q.m17#5.o0" to "Weil Essen verdirbt",
    "q.m17#5.o1" to "Um unter allen Umständen Brennstoff und Verpflegung für einen sicheren Abstieg zu sichern",
    "q.m17#5.o2" to "Weil der Laden es verlangt",
    "q.m17#5.o3" to "Um den Rucksack am Rückweg zu erleichtern",
    "q.m17#5.e" to "Die Reserve zielt auf den schlimmsten Fall: Wetterumschwung, ein erzwungener zusätzlicher Tag, ein Verletzter mit langsamem Abstieg. Sind alle Ressourcen für einen Best-Case-Plan verplant, steht man bei jeder Verzögerung ohne Vorräte und ohne Bewegungsfähigkeit da.",

    "q.m17#6.p" to "Wie sind Elektronikgeräte (Telefon, Kamera, Stirnlampenbatterien) über Nacht zu behandeln?",
    "q.m17#6.o0" to "Draußen vor dem Zelt lassen",
    "q.m17#6.o1" to "Am Körper oder im Schlafsack warm halten",
    "q.m17#6.o2" to "In der äußersten Rucksacktasche",
    "q.m17#6.o3" to "Braucht keine Behandlung",
    "q.m17#6.e" to "Lithiumbatterien verlieren in der Kälte stark an Kapazität und können ganz abschalten. Sie warm zu halten schützt nicht das Gerät — es stellt sicher, dass die Stirnlampe morgen leuchtet und das GPS angeht. Das ist Sicherheitsausrüstung, kein persönlicher Gegenstand.",

    "q.m17#7.p" to "Was ist mit nasser Kleidung zu tun?",
    "q.m17#7.o0" to "Draußen aufhängen und gefriertrocknen",
    "q.m17#7.o1" to "Am Körper oder im Schlafsack halten, damit sie durch Körperwärme trocknet",
    "q.m17#7.o2" to "In eine Zeltecke werfen",
    "q.m17#7.o3" to "Direkt in den Rucksack stopfen",
    "q.m17#7.e" to "Die Nachttemperaturen in der Höhe sind extrem niedrig, nasse Kleidung draußen gefriert steinhart. Trocknen am Körper ist nicht vollständig, aber sie ist morgen wenigstens kein Eis — ein klassischer Fall davon, Körperwärme als Ressource zu behandeln.",

    "q.m17#8.p" to "Warum sollte das Lager immer in einem Zustand sein, in dem man sofort packen und gehen kann?",
    "q.m17#8.o0" to "Damit der Aufbruch bequem ist",
    "q.m17#8.o1" to "Weil Wetter oder der Zustand eines Gruppenmitglieds jederzeit eine Notfall-Evakuierung verlangen können",
    "q.m17#8.o2" to "Um Packzeit zu sparen",
    "q.m17#8.o3" to "Um Ordnung zu halten",
    "q.m17#8.e" to "Das Wetterfenster am Hochlager kann plötzlich schließen, und ein Gruppenmitglied kann plötzlich Höhensymptome entwickeln. Dann entscheidet, wie lange der Aufbruch dauert, wie viel Risiko Sie tragen — und über das ganze Zelt verteilte Ausrüstung kostet leicht eine halbe Stunde extra.",

    "q.m17#9.p" to "Was ist KEINE Hauptursache für schlechten Schlaf in der Höhe?",
    "q.m17#9.o0" to "Periodische Atmung mit wiederholtem kurzem Aufwachen",
    "q.m17#9.o1" to "Hypoxie und erhöhte Herzfrequenz",
    "q.m17#9.o2" to "Kälte und Unbehagen",
    "q.m17#9.o3" to "Eine zu helle Zeltfarbe",
    "q.m17#9.e" to "Die ersten drei sind echte physiologische Ursachen, und die periodische Atmung ist die typischste: In der Höhe wird die Atmung nachts unwillkürlich intermittierend und holt Sie wiederholt in den Leichtschlaf zurück. Die Schlafqualität wirkt direkt auf die Akklimatisierung — schlecht zu schlafen ist also keine Kleinigkeit.",

    "q.m17#10.p" to "[Reihenfolge] Wie lautet eine sinnvolle Reihenfolge beim Aufbau und Verlassen eines Lagers?",
    "q.m17#10.o0" to "Vor der Ankunft die Umgebung auf Lawinen-, Serac- und Wechtengefahr prüfen",
    "q.m17#10.o1" to "Zeltplatz festlegen, Boden einebnen und Zelt sichern",
    "q.m17#10.o2" to "Vorräte verteilen, Schnee zu Wasser schmelzen, den morgigen Ablauf und Schlaf planen",
    "q.m17#10.o3" to "Vor dem Verlassen Ausrüstung und Müll inventarisieren und den Platz wiederherstellen",
    "q.m17#10.e" to "Der erste Schritt wird am häufigsten übersprungen — besonders wenn man müde ist und jede ebene Fläche wie ein Zeltplatz wirkt. Aber ist ein Lager gebaut, ist ein Umzug extrem teuer; deshalb sollte Umschauen vor der Platzwahl feste Gewohnheit werden.",

    "q.m17#11.p" to "Warum ist ein Lager auch ein Wendepunkt für den Rückzug?",
    "q.m17#11.o0" to "Weil im Lager Vorräte liegen",
    "q.m17#11.o1" to "Weil Rückzug meist heißt, zuerst zum Lager zurückzukehren und dann zu entscheiden, ob weiter abgestiegen oder auf Wetter gewartet wird",
    "q.m17#11.o2" to "Weil im Lager Funkgeräte sind",
    "q.m17#11.o3" to "Weil der Bergführer im Lager ist",
    "q.m17#11.e" to "Der Abstieg von oben ist selten ein durchgehender Lauf; man kehrt zum nächsten Lager zurück, um sich zu erholen, zu beobachten und zu entscheiden. Das heißt: Das Lager selbst muss ein verlässliches Ziel sein — kein Ort, zu dem man Angst hat zurückzukehren.",

    "q.m17#12.p" to "Warum muss ein Zelt belüftet sein?",
    "q.m17#12.o0" to "Um kühl zu bleiben",
    "q.m17#12.o1" to "Um Kohlenmonoxid-Stau und Reifbildung innen zu vermeiden und Ersticken wie Vergiftung zu verhindern",
    "q.m17#12.o2" to "Um leichter rein- und rauszukommen",
    "q.m17#12.o3" to "Um den Windwiderstand zu senken",
    "q.m17#12.e" to "Kochen mit einem Kocher in der Höhe kann den Kohlenmonoxidspiegel in einem geschlossenen Zelt schnell steigen lassen, und diese Vergiftung passiert meist im Schlaf, mit Symptomen — Kopfschmerz, Müdigkeit — die sich von Höhenkrankheit kaum unterscheiden lassen. Zusammen macht das Lüftung zur harten Anforderung.",

    "q.m17#13.p" to "Was ist die größte Sorge beim Kocherbetrieb im Zelt?",
    "q.m17#13.o0" to "Brennstofflecks",
    "q.m17#13.o1" to "Kohlenmonoxidvergiftung",
    "q.m17#13.o2" to "Das Zelt anschmelzen",
    "q.m17#13.o3" to "Lärm",
    "q.m17#13.e" to "Kohlenmonoxid ist farblos und geruchlos, und seine Frühsymptome — Kopfschmerz, Benommenheit — überschneiden sich stark mit Höhenkrankheit. Genau das macht es gefährlich: Menschen schlafen ein im Glauben, es sei nur AMS. Kocherbetrieb verlangt immer Lüftung.",

    "q.m17#14.p" to "[Mehrfachauswahl] Welche Gesundheitspunkte sollten im Lager aktiv gepflegt werden?",
    "q.m17#14.o0" to "Genug trinken (Schnee schmelzen)",
    "q.m17#14.o1" to "Genug essen, auch ohne Appetit",
    "q.m17#14.o2" to "Kleidung trocken halten",
    "q.m17#14.o3" to "Den Zustand und das Gangbild der anderen beobachten",
    "q.m17#14.o4" to "Mahlzeiten durch Kaffee und Energydrinks ersetzen",
    "q.m17#14.e" to "Die ersten drei sind Selbstfürsorge, die vierte ist Fürsorge für andere — und sie ist oft wirksamer als die ersten drei: Frühe Zeichen der Höhenkrankheit (unsicherer Gang, verlangsamte Reaktionen) bemerkt man an sich selbst schwer, ein Partner sieht sie auf einen Blick.",

    "q.m17#15.p" to "Ergänzen Sie: Oberhalb des Hochlagers werden Brennstoff und Verpflegung meist nach ( ) abgepackt, mit einer zurückgelegten Notreserve.",
    "q.m17#15.a0" to "Tag",
    "q.m17#15.a1" to "Tage",
    "q.m17#15.a2" to "tagesweise",
    "q.m17#15.a3" to "pro Tag",
    "q.m17#15.e" to "Tageweise abgepackt. So ist der Verbrauch auf einen Blick sichtbar, und Sie erkennen sofort, 'wie viele Tage noch übrig sind', wenn der Zeitplan rutscht — statt es erst zu merken, wenn nichts mehr da ist.",

    // ---------- m18 7.000er-Ziele ----------
    "q.m18#0.p" to "Wie hoch ist der Muztagh Ata?",
    "q.m18#0.o0" to "6.812 m",
    "q.m18#0.o1" to "7.126 m",
    "q.m18#0.o2" to "7.134 m",
    "q.m18#0.o3" to "7.509 m",
    "q.m18#0.e" to "Der Muztagh Ata ist 7.509 m, im Kreis Akto, Xinjiang. Er ist die erste Wahl für ein chinesisches 7.000-m-Ziel und der höchste der vier Berge dieser Lektion.",

    "q.m18#1.p" to "Warum heißt der Muztagh Ata 'Vater der Eisberge'?",
    "q.m18#1.o0" to "Weil er der höchste Gipfel der Welt ist",
    "q.m18#1.o1" to "Weil seine Gletscher und Schneemassen enorm sind und er von Weitem wie eine riesige Eiskappe wirkt",
    "q.m18#1.o2" to "Weil er der erste bestiegene 7.000er war",
    "q.m18#1.o3" to "Weil er in lokalen Legenden ein heiliger Berg ist",
    "q.m18#1.e" to "Der Name kommt vom Aussehen: Der Oberteil ist von einer gewaltigen Eiskappe bedeckt, und die Schneehänge laufen sehr breit aus, sodass er aus der Ferne wie ein weißes Massiv wirkt. Dieses Bild erklärt auch seinen Charakter als Ziel — lange Schneehänge, mäßige Neigung, aber zeitaufwendig.",

    "q.m18#2.p" to "Was kennzeichnet die Besteigung des Muztagh Ata technisch?",
    "q.m18#2.o0" to "Überwiegend senkrechte Eiswände, extrem technisch",
    "q.m18#2.o1" to "Endlose Schneehänge bei mäßiger technischer Schwierigkeit, aber sehr fordernd für Akklimatisierung und Kondition",
    "q.m18#2.o2" to "Praktisch keine technische Ausrüstung nötig",
    "q.m18#2.o3" to "Überwiegend Klettergelände am Fels",
    "q.m18#2.e" to "Das ist ein klassisches 7.000er-Profil: Die Route selbst ist vielleicht nicht schwer, aber lange Lastentage in der Höhe vergrößern jedes kleine Problem. Der eigentliche Vorbereitungsschwerpunkt sind daher Akklimatisierung und Kondition, nicht hochtechnisches Können.",

    "q.m18#3.p" to "Wie hoch ist der Ama Dablam tatsächlich?",
    "q.m18#3.o0" to "6.812 m",
    "q.m18#3.o1" to "7.126 m",
    "q.m18#3.o2" to "7.509 m",
    "q.m18#3.o3" to "8.027 m",
    "q.m18#3.e" to "Der Ama Dablam ist 6.812 m, in der Khumbu-Region Nepals. Von der Höhe ist er ein 6.000er, steht aber in der 7.000er-Einheit, weil seine technische Schwierigkeit mit Gipfeln über 7.000 m vergleichbar ist.",

    "q.m18#4.p" to "Warum steht der Ama Dablam mit nur 6.812 m in der 7.000er-Einheit?",
    "q.m18#4.o0" to "Weil er verwaltungstechnisch als 7.000er eingestuft ist",
    "q.m18#4.o1" to "Weil sein steiles gemischtes Fels-Schnee-Gelände und die starke Exposition seine Schwierigkeit auf das Niveau von Gipfeln über 7.000 m heben",
    "q.m18#4.o2" to "Weil seine Gipfelquote sehr niedrig ist",
    "q.m18#4.o3" to "Weil er in einer 7.000er-Kette liegt",
    "q.m18#4.e" to "Das ist der wichtigste Punkt der Lektion: Die Schwierigkeit eines Berges ist nicht seine Höhe. Der Ama Dablam ist der klassische Beleg — niedriger als viele 7.000er, doch seine technische Schwelle und die psychische Belastung können größer sein. Einen Berg allein nach der Höhe zu wählen ist gefährlich.",

    "q.m18#5.p" to "Wie hoch ist der Lenin Peak und wo liegt er?",
    "q.m18#5.o0" to "7.126 m, Nepal",
    "q.m18#5.o1" to "7.134 m, Pamir-Plateau",
    "q.m18#5.o2" to "7.509 m, Xinjiang",
    "q.m18#5.o3" to "6.812 m, Khumbu, Nepal",
    "q.m18#5.e" to "Der Lenin Peak ist 7.134 m auf dem Pamir-Plateau. Er gehört zu den sanfteren 7.000ern und wird deshalb oft als erstes 7.000-m-Ziel genutzt.",

    "q.m18#6.p" to "Wie hoch ist der Himlung Himal?",
    "q.m18#6.o0" to "7.126 m",
    "q.m18#6.o1" to "7.134 m",
    "q.m18#6.o2" to "7.509 m",
    "q.m18#6.o3" to "6.812 m",
    "q.m18#6.e" to "Der Himlung Himal ist 7.126 m, in Nepal. Seine Route mischt Schneehänge und Eiswände, was ihn unter den nepalesischen 7.000ern beliebt macht.",

    "q.m18#7.p" to "[Reihenfolge] Ordnen Sie diese Berge von der niedrigsten zur höchsten Höhe.",
    "q.m18#7.o0" to "Ama Dablam (6.812 m)",
    "q.m18#7.o1" to "Himlung Himal (7.126 m)",
    "q.m18#7.o2" to "Lenin Peak (7.134 m)",
    "q.m18#7.o3" to "Muztagh Ata (7.509 m)",
    "q.m18#7.e" to "Diese Reihenfolge legt einen häufigen Fehler offen: Nach der Höhe sortiert kommt der Ama Dablam vor dem Muztagh Ata — die tatsächliche technische Schwierigkeit kann genau umgekehrt sein. Noch einmal: Höhe ist nur eine von vielen Variablen.",

    "q.m18#8.p" to "[Mehrfachauswahl] Was ändert sich bei 7.000 m gegenüber 6.000 m vor allem?",
    "q.m18#8.o0" to "Längere Akklimatisierung, mit mehr Hochlager-Rotationen",
    "q.m18#8.o1" to "Engere Wetterfenster, sodass das Timing wichtiger wird",
    "q.m18#8.o2" to "Schwierigerer Rückzug, wodurch Selbstrettung zur harten Anforderung wird",
    "q.m18#8.o3" to "Generell technischeres Gelände und mehr Exposition",
    "q.m18#8.o4" to "Zusätzlicher Sauerstoff wird zur Standardausrüstung",
    "q.m18#8.e" to "Diese vier multiplizieren sich statt sich zu addieren: Schlechte Akklimatisierung lässt Sie das Fenster verpassen, das verpasste Fenster erzwingt einen Rückzug unter schlechteren Bedingungen, und der Rückzug wird von Höhe und technischem Gelände verstärkt. Deshalb heißt 7.000 m Wasserscheide.",

    "q.m18#9.p" to "Warum heißt 7.000 m eine 'Wasserscheide'?",
    "q.m18#9.o0" to "Weil Eispickel erst über 7.000 m nötig sind",
    "q.m18#9.o1" to "Weil ab hier Technik, Urteilskraft, Kondition und Logistik gleichzeitig wirken und keine einzelne Stärke das ausgleichen kann",
    "q.m18#9.o2" to "Weil Gletscher erst über 7.000 m sichtbar sind",
    "q.m18#9.o3" to "Weil kommerzielle Teams nur über 7.000 m arbeiten",
    "q.m18#9.e" to "Scheitern bei 5.000 m hat meist eine Ursache (Akklimatisierung oder Kondition), bei 6.000 m stapeln sich die Ursachen, und bei 7.000 m muss alles sitzen. Deshalb fasst diese Einheit Technik, Urteil, Wetter, Selbstrettung und Lagerführung zusammen — sie waren immer ein System.",

    "q.m18#10.p" to "Was zählt bei der Wahl eines 7.000-m-Ziels am meisten?",
    "q.m18#10.o0" to "Die Höhe",
    "q.m18#10.o1" to "Eine gute Gesamtpassung aus Routentyp, Logistik, Akklimatisierungsplan und Rückzugsmöglichkeiten",
    "q.m18#10.o2" to "Die Kosten",
    "q.m18#10.o3" to "Die Gipfelquote",
    "q.m18#10.e" to "Kein einzelner Punkt genügt: höher ist nicht automatisch schwerer, eine hohe Gipfelquote nicht automatisch sicherer, billig nicht automatisch gut. Das eigentliche Urteil ist, ob die Kombination dieser vier etwas ist, das ich in meinem jetzigen Zustand tragen kann.",

    "q.m18#11.p" to "Warum sind am Muztagh Ata die 'endlosen Schneehänge' selbst ein Risiko?",
    "q.m18#11.o0" to "Weil die Hänge zu glatt sind",
    "q.m18#11.o1" to "Weil lange Exposition in der Höhe Kondition und Urteilskraft stetig aushöhlt und der Rückzugsweg weit ist",
    "q.m18#11.o2" to "Weil dort häufig Lawinen abgehen",
    "q.m18#11.o3" to "Weil man auf Schneehängen nicht anseilen kann",
    "q.m18#11.e" to "'Nicht schwer, aber sehr lang' ist das klassische 7.000er-Risikomodell: Es gibt keinen einzelnen Knackpunkt, aber es zehrt unablässig. Lange Exposition heißt, Kondition, Aufmerksamkeit und Entscheidungsqualität sinken langsam — und diese verlorene Reserve ist genau Ihre Sicherheitsreserve.",

    "q.m18#12.p" to "[Zuordnung] Ordnen Sie jedem Berg seinen typischen Charakter zu.",
    "q.m18#12.l0" to "Muztagh Ata",
    "q.m18#12.r0" to "Vater der Eisberge: endlose Schneehänge, ein Test für Akklimatisierung und Kondition",
    "q.m18#12.l1" to "Ama Dablam",
    "q.m18#12.r1" to "Steiler gemischter Fels und Schnee, starke Exposition, Prüfstein in Richtung 8.000 m",
    "q.m18#12.l2" to "Lenin Peak",
    "q.m18#12.r2" to "Pamir-Plateau; unter den 7.000ern verhältnismäßig sanft",
    "q.m18#12.l3" to "Himlung Himal",
    "q.m18#12.r3" to "In Nepal; eine Mischung aus Schneehängen und Eiswänden",
    "q.m18#12.e" to "Diese vier Profile entsprechen vier verschiedenen Vorbereitungsschwerpunkten: Muztagh Ata für Akklimatisierung, Ama Dablam für Technik und Psyche, Lenin Peak als Sprungbrett, Himlung als Allround-Prüfung. Zusammen gesehen können Sie nach Ihrem eigenen Schwachpunkt wählen.",

    "q.m18#13.p" to "Wenn das Ziel ein 8.000er ist — wie wählt man aus den 7.000ern am sinnvollsten?",
    "q.m18#13.o0" to "Den höchsten nehmen",
    "q.m18#13.o1" to "Den nehmen, der den eigenen Schwachpunkt abdeckt (Technik, Akklimatisierung oder Exposition)",
    "q.m18#13.o2" to "Den billigsten nehmen",
    "q.m18#13.o3" to "Den mit der höchsten Gipfelquote nehmen",
    "q.m18#13.e" to "Die 7.000er als Trainingsfeld für die eigenen Schwachpunkte zu behandeln bringt mehr, als sie als Stufenleiter zu sehen. Schwach in der Technik: Ama Dablam. Schlechter Akklimatisierer: Muztagh Ata mit seinen langen Hängen und etablierten Hochlager-Rotationen.",

    "q.m18#14.p" to "Wie ist die Vorbereitungszeit für einen 7.000er richtig einzuschätzen?",
    "q.m18#14.o0" to "Etwa wie für einen 6.000er",
    "q.m18#14.o1" to "Deutlich länger, mit genug Hochlager-Rotationen und Akklimatisierungszeit",
    "q.m18#14.o2" to "Nur Konditionstraining ist nötig",
    "q.m18#14.o3" to "Kann direkt nach der letzten Tour beginnen",
    "q.m18#14.e" to "Akklimatisierung ist kumulativ, und 7.000 m verlangt meist mehrere Hochlager-Rotationen. Einen engen Zeitplan ohne Akklimatisierungszeit zu bauen ist der direkte Grund, warum viele 7.000er-Teams den Gipfel nicht erreichen — oder Unfälle haben.",

    "q.m18#15.p" to "Warum stellt diese Einheit die Gefahrenbeurteilung hinter die Techniklektionen?",
    "q.m18#15.o0" to "Weil Urteilskraft leichter ist als Technik",
    "q.m18#15.o1" to "Weil technisches Können das Selbstvertrauen gibt, in schwierigeres Gelände zu gehen, was Urteilskraft umso nötiger macht, um es zu begrenzen",
    "q.m18#15.o2" to "Wegen Platzgrenzen im Lehrplan",
    "q.m18#15.o3" to "Weil Technik keine Rolle spielt",
    "q.m18#15.e" to "Das ist eine realistische Anordnung: Je besser Sie sind, desto schwerere Routen können Sie angehen, desto mehr steigt die Notwendigkeit, sich selbst zu begrenzen. Urteilskraft nach die Technik zu setzen spiegelt diese Reihenfolge in der Wirklichkeit — erst Können, dann Zurückhaltung.",

    // ---------- m19 8.000 m: Physiologie und Strategie ----------
    "q.m19#0.p" to "Die 'Todeszone' bezeichnet üblicherweise:",
    "q.m19#0.o0" to "Über 7.000 m",
    "q.m19#0.o1" to "Über 8.000 m",
    "q.m19#0.o2" to "Über 5.500 m",
    "q.m19#0.o3" to "Über 6.000 m",
    "q.m19#0.e" to "Über 8.000 m heißt Todeszone aus einem einfachen Grund: Der Sauerstoffpartialdruck ist so niedrig, dass keine Akklimatisierung den Körper länger im Gleichgewicht halten lässt. Das ist keine Rhetorik, sondern physiologische Tatsache — und die grundlegendste Trennlinie zwischen 8.000 m und 7.000 m.",

    "q.m19#1.p" to "Der Luftdruck auf 8.000 m beträgt ungefähr welchen Anteil des Meeresspiegelniveaus?",
    "q.m19#1.o0" to "Die Hälfte",
    "q.m19#1.o1" to "Zwei Drittel",
    "q.m19#1.o2" to "Ein Drittel",
    "q.m19#1.o3" to "Ein Fünftel",
    "q.m19#1.e" to "Etwa ein Drittel. Das heißt, jeder Atemzug liefert nur rund dreißig Prozent der Sauerstoffmoleküle, die auf Meereshöhe verfügbar sind — während Klettern ein Vielfaches des Ruhebedarfs verlangt. Aus dieser Lücke zwischen Angebot und Bedarf stammt jedes Risiko auf 8.000 m.",

    "q.m19#2.p" to "Warum kann der menschliche Körper sich nicht lange über 8.000 m aufhalten?",
    "q.m19#2.o0" to "Weil es zu kalt ist",
    "q.m19#2.o1" to "Weil der Sauerstoffpartialdruck unter der Schwelle für die Aufrechterhaltung des Stoffwechsels liegt, sodass der Körper stetig verfällt",
    "q.m19#2.o2" to "Weil es nicht genug Essen gibt",
    "q.m19#2.o3" to "Weil der Wind zu stark ist",
    "q.m19#2.e" to "Langes Bleiben heißt mehr verbrauchen als reparieren: Selbst in Ruhe verliert der Körper Muskelmasse und Gewicht, und die kognitive Leistung sinkt. Deshalb muss ein 8.000er-Zeitplan schnell hinein und schnell hinaus — die Option, auf bessere Bedingungen zu warten, gibt es nicht.",

    "q.m19#3.p" to "Welche Fähigkeit beeinträchtigt Hypoxie meist zuerst?",
    "q.m19#3.o0" to "Die Beinkraft",
    "q.m19#3.o1" to "Urteilskraft und Kognition",
    "q.m19#3.o2" to "Das Sehen",
    "q.m19#3.o3" to "Das Hören",
    "q.m19#3.e" to "Das ist der gefährlichste Mechanismus auf 8.000 m: Wer in seinem Urteil nachgelassen hat, kann nicht beurteilen, dass sein Urteil nachgelassen hat. Umgekehrt bemerken Sie schwache Beine sofort, während der Gedanke 'ich kann weiter' selbst schon ein Produkt der Hypoxie sein kann.",

    "q.m19#4.p" to "Warum ist nachlassende Urteilskraft auf 8.000 m besonders gefährlich?",
    "q.m19#4.o0" to "Weil man sich verlaufen kann",
    "q.m19#4.o1" to "Weil Sie mit bereits beeinträchtigtem Urteil entscheiden müssen, ob Sie weitergehen oder umkehren",
    "q.m19#4.o2" to "Weil es die Partner betrifft",
    "q.m19#4.o3" to "Weil es Sie langsamer macht",
    "q.m19#4.e" to "Es ist eine rekursive Falle: Genau wenn eine kritische Entscheidung nötig ist — weiter oder zurück — ist Ihre Entscheidungsfähigkeit am wenigsten verlässlich. 'Gehen wir noch ein bisschen weiter und schauen' mag auf 4.000 m vernünftig sein; auf 8.000 m kann es bereits ein hypoxiebedingter Fehler sein.",

    "q.m19#5.p" to "[Mehrfachauswahl] Welche sind typische Zeichen hypoxiebedingten kognitiven Abbaus?",
    "q.m19#5.o0" to "Verlangsamte Reaktionen, verwaschene Sprache",
    "q.m19#5.o1" to "Fehler beim Rechnen und Beurteilen",
    "q.m19#5.o2" to "Die Risikoeinschätzung wird übermäßig optimistisch",
    "q.m19#5.o3" to "Stimmungsschwankungen, Reizbarkeit oder Teilnahmslosigkeit",
    "q.m19#5.o4" to "Vermindertes Frostgefühl in Fingern und Zehen",
    "q.m19#5.e" to "Alle vier sind typisch, und sie teilen ein Merkmal: Der Betroffene bemerkt sie kaum. Deshalb ist der verlässliche Weg das Externalisieren — Checklisten statt Gedächtnis, feste Zeiten statt 'fühlt sich ungefähr richtig an', und Partner, die einander beobachten, statt Selbsteinschätzung.",

    "q.m19#6.p" to "Was ist das wirksamste Mittel gegen nachlassende Urteilskraft?",
    "q.m19#6.o0" to "Mit Willenskraft wachsam bleiben",
    "q.m19#6.o1" to "Entscheidungen in vorher geschriebene Checklisten und feste Regeln auslagern (Zeit, Rest-Sauerstoff, Wetterschwellen)",
    "q.m19#6.o2" to "Mehr heißes Wasser trinken",
    "q.m19#6.o3" to "Langsamer gehen",
    "q.m19#6.e" to "Willenskraft ist genau das, was Hypoxie zuerst aushöhlt. Die verlässliche Methode ist, die Regeln aufzuschreiben, solange Sie noch funktionieren: zu welcher Uhrzeit Sie umkehren müssen, bei welchem Rest-Sauerstoff der Abstieg beginnt — dann müssen Sie nur Fakten prüfen, nicht neu urteilen.",

    "q.m19#7.p" to "Warum betont ein 8.000er-Zeitplan 'früh starten, früh zurück'?",
    "q.m19#7.o0" to "Um Menschenmengen zu vermeiden",
    "q.m19#7.o1" to "Weil die Wahrscheinlichkeit einer Wetterverschlechterung am Nachmittag steigt und Kälte und Wind schnell Energie und Sauerstoff zehren",
    "q.m19#7.o2" to "Weil die Route morgens kürzer ist",
    "q.m19#7.o3" to "Wegen der Gewohnheiten der Bergführer",
    "q.m19#7.e" to "Auf 8.000 m wird der Preis von 'zu spät' vergrößert: Dieselbe Strecke kostet am Nachmittag doppelte Kraft, und sobald die Dunkelheit kommt, fallen Temperatur und Urteilskraft. 'Zu spät absteigen' ist fast immer der gemeinsame Ausgangspunkt dieser Unfallkette.",

    "q.m19#8.p" to "Warum verlangt 8.000 m 'vereinfachte Entscheidungsfindung'?",
    "q.m19#8.o0" to "Um Zeit zu sparen",
    "q.m19#8.o1" to "Weil kognitive Ressourcen begrenzt sind und für die wirklich wichtigen Entscheidungen aufgespart werden sollten",
    "q.m19#8.o2" to "Weil man in der Höhe nicht denken will",
    "q.m19#8.o3" to "Weil die Partner für Sie entscheiden",
    "q.m19#8.e" to "Praktisch heißt das: feste Plätze und Reihenfolge für Ausrüstung, Abläufe als Checklisten, der Zeitplan vorab fixiert. 'Was ziehe ich heute an, was mache ich zuerst' zum gedankenlosen Standard zu machen ist das, was Urteilskraft für Entscheidungen wie weiter oder umkehren bewahrt.",

    "q.m19#9.p" to "Warum brauchen selbst erfahrene Bergsteiger auf 8.000 m Checklisten?",
    "q.m19#9.o0" to "Weil das Gedächtnis unzuverlässig ist",
    "q.m19#9.o1" to "Weil Hypoxie zuerst das Arbeitsgedächtnis schädigt und eine Checkliste nicht vom Gedächtnis abhängt",
    "q.m19#9.o2" to "Weil Vorschriften es verlangen",
    "q.m19#9.o3" to "Um Anfängern das Lernen zu erleichtern",
    "q.m19#9.e" to "Die Logik ist dieselbe wie in der Luftfahrt: In Umgebungen mit hoher Belastung und schweren Folgen kann man sich nicht auf 'ich vergesse das wahrscheinlich nicht' verlassen. Eine Checkliste ist kein Lehrmittel für Anfänger, sondern eine Versicherung gegen Fehler, die auch Experten machen.",

    "q.m19#10.p" to "Was verursacht den kontinuierlichen Gewichtsverlust in der Höhe hauptsächlich?",
    "q.m19#10.o0" to "Weil Essen schlecht schmeckt",
    "q.m19#10.o1" to "Weil der Körper unter Hypoxie laufend eigenes Gewebe abbaut, während verminderter Appetit zu wenig Zufuhr bedeutet",
    "q.m19#10.o2" to "Wegen der Bewegungsmenge",
    "q.m19#10.o3" to "Wegen zu wenig Trinkwasser",
    "q.m19#10.e" to "Zwei Faktoren wirken zusammen: Hypoxie versetzt den Körper in einen Zustand, in dem Abbau die Synthese übersteigt, und die Höhenkrankheit selbst dämpft den Appetit. Deshalb ist Essenkönnen in der Höhe eine Fähigkeit, kein Vergnügen.",

    "q.m19#11.p" to "Warum ist der Schlaf auf 8.000 m schlecht?",
    "q.m19#11.o0" to "Weil das Zelt unbequem ist",
    "q.m19#11.o1" to "Weil niedriger Sauerstoff periodische Atmung verursacht, mit wiederholten Pausen, die Sie aus dem Schlaf holen",
    "q.m19#11.o2" to "Weil es windig ist",
    "q.m19#11.o3" to "Weil Sie tagsüber zu viel geschlafen haben",
    "q.m19#11.e" to "Periodische Atmung ist das klassische Höhenschlafphänomen: Ein instabiler Atemantrieb erzeugt wiederholt Apnoe-und-Aufschreck-Zyklen. Die Schlafqualität wirkt dann direkt auf Akklimatisierung und Energie des nächsten Tages — schlafen zu können ist eine Kernkompetenz im Hochlager.",

    "q.m19#12.p" to "[Reihenfolge] Bringen Sie die Wirkungen der Hypoxie auf den Körper in ihre übliche Reihenfolge des Auftretens.",
    "q.m19#12.o0" to "Schnellere Atmung und erhöhte Herzfrequenz (Kompensation)",
    "q.m19#12.o1" to "Nachlassende Ausdauer bei längerer Belastung",
    "q.m19#12.o2" to "Nachlassende Urteilskraft und Rechenfähigkeit",
    "q.m19#12.o3" to "Verändertes Bewusstsein, Ataxie",
    "q.m19#12.e" to "Die ersten beiden sind der Körper, der sich zu helfen versucht; die letzten beiden sind der Körper, der versagt. Gefährlich ist die dritte — sie erscheint vor jeder offensichtlichen Bewusstseinsänderung, deshalb heißt 'wirkt normal' nicht 'denkt klar'.",

    "q.m19#13.p" to "Was ist der direkteste und verlässlichste Weg gegen Hypoxie auf 8.000 m?",
    "q.m19#13.o0" to "Mehr essen",
    "q.m19#13.o1" to "Zusätzlichen Sauerstoff verwenden",
    "q.m19#13.o2" to "Mehr rasten",
    "q.m19#13.o3" to "Langsamer gehen",
    "q.m19#13.e" to "Die anderen wirken über geringeren Verbrauch oder schnellere Akklimatisierung, während zusätzlicher Sauerstoff direkt den eingeatmeten Sauerstoffpartialdruck hebt — er verändert die Wurzelvariable. Deshalb ist Sauerstoff auf 8.000 m Standard-Sicherheitsausrüstung.",

    "q.m19#14.p" to "Wie ist die 'Grenze der Akklimatisierung' richtig zu verstehen?",
    "q.m19#14.o0" to "Akklimatisierung kann unbegrenzt weitergehen",
    "q.m19#14.o1" to "Akklimatisierung hat eine Obergrenze; oberhalb einer bestimmten Höhe gleicht sie nichts mehr vollständig aus",
    "q.m19#14.o2" to "Akklimatisierung dauert einen Tag",
    "q.m19#14.o3" to "Akklimatisierung hat nichts mit der Höhe zu tun",
    "q.m19#14.e" to "Akklimatisierung ist ein Prozess mit Grenze, keine Kurve, die immer weiter steigt. Das ist der grundlegende Grund, warum 8.000 m von Sauerstoff und einer Schnell-rein-schnell-raus-Strategie abhängt — nicht wegen unzureichender Vorbereitung, sondern weil es physiologisch keine Option gibt, 'sich zu akklimatisieren und dann zu bleiben'.",

    "q.m19#15.p" to "Warum ist die Ursache von 8.000er-Unfällen selten ein einzelnes Ereignis?",
    "q.m19#15.o0" to "Wegen Pech",
    "q.m19#15.o1" to "Weil Hypoxie Urteilskraft, Energie und Koordination gleichzeitig schwächt und damit mehrere Glieder auf einmal brüchig macht",
    "q.m19#15.o2" to "Weil die Ausrüstung unzureichend ist",
    "q.m19#15.o3" to "Weil zu viele Leute unterwegs sind",
    "q.m19#15.e" to "Auf niedriger Höhe lässt ein Fehler meist Reserve zum Auffangen; auf 8.000 m sinken Urteilskraft, Energie und Motorik gemeinsam, sodass kleine Fehler direkt zu Unfällen verketten. Die Sicherheitsstrategie auf 8.000 m muss deshalb mehr Schutzschichten bedeuten, nicht einfach vorsichtiger zu sein.",

    "q.m19#16.p" to "[Mehrfachauswahl] Was sind die Haupttodesursachen auf 8.000 m?",
    "q.m19#16.o0" to "Lawine und Serac-Sturz",
    "q.m19#16.o1" to "Stürze",
    "q.m19#16.o2" to "Unterkühlung",
    "q.m19#16.o3" to "Höhenkrankheit und ihre Komplikationen",
    "q.m19#16.o4" to "Umgebungsschäden wie Schneeblindheit und Sonnenbrand",
    "q.m19#16.e" to "Alle vier sind verbreitet, und sie stapeln sich oft: Ein Sturz lässt Sie nicht mehr selbst retten, dann Warten in der Kälte, dann Unterkühlung, dann sich verschlechternde Höhenkrankheit. Deshalb darf sich Ausbildung für 8.000 m nicht nur auf Höhenkrankheit richten, sondern muss Technik, Urteil und Systeme einschließen.",

    "q.m19#17.p" to "Ergänzen Sie: Über 8.000 m heißt die '( )zone'.",
    "q.m19#17.a0" to "Todes",
    "q.m19#17.a1" to "todes",
    "q.m19#17.e" to "Die Todeszone. Der praktische Wert des Begriffs ist die harte Einschränkung, die er vermittelt: Hier gibt es keine Option zu warten oder es ruhiger angehen zu lassen. Jeder Plan, jede Vorratsrechnung und jede Entscheidung muss darauf ausgelegt sein, so schnell wie möglich durchzukommen.",

    "q.m19#18.p" to "Auf 8.000 m merken Sie, dass Sie 'unbedingt weiter zum Gipfel wollen'. Was tun Sie?",
    "q.m19#18.o0" to "Dem Instinkt vertrauen und weitersteigen",
    "q.m19#18.o1" to "Es als mögliches Zeichen hypoxiebedingter Risikounterschätzung behandeln und sofort die vorab festgelegten Umkehrbedingungen prüfen",
    "q.m19#18.o2" to "Schneller gehen und hochkommen",
    "q.m19#18.o3" to "Die Partner entscheiden lassen",
    "q.m19#18.e" to "Das ist eine sehr typische Lage: Ein starker Drang weiterzugehen kann auf niedriger Höhe bloßer Wunsch sein, auf 8.000 m aber ein Signal beeinträchtigter Urteilskraft. Die einzige verlässliche Referenz ist dann nicht Ihr Gefühl, sondern die objektiven Bedingungen, die Sie vor dem Aufbruch aufgeschrieben haben.",

    // ---------- m20 Sauerstoffsysteme ----------
    "q.m20#0.p" to "Was ist die Hauptaufgabe von zusätzlichem Sauerstoff auf 8.000 m?",
    "q.m20#0.o0" to "Konditionstraining ersetzen",
    "q.m20#0.o1" to "Den Blutsauerstoff heben, das Risiko der Höhenkrankheit senken und Beweglichkeit und Urteilskraft verbessern",
    "q.m20#0.o2" to "Sie warm halten",
    "q.m20#0.o3" to "Das Rucksackgewicht senken",
    "q.m20#0.e" to "Der am häufigsten übersehene und sicherheitsrelevanteste Punkt ist die verbesserte Urteilskraft, weil sie direkt gegen den gefährlichsten Faktor auf 8.000 m wirkt. Deshalb ist Sauerstoff in dieser Höhe Standard-Sicherheitsausrüstung und kein Arbeitserleichterer.",

    "q.m20#1.p" to "Aus welchen Teilen besteht ein Sauerstoffsystem?",
    "q.m20#1.o0" to "Flasche, Druckminderer, Flowmeter, Maske oder Nasenbrille",
    "q.m20#1.o1" to "Flasche und Rucksack",
    "q.m20#1.o2" to "Maske und Isolationsschicht",
    "q.m20#1.o3" to "Druckminderer und Helm",
    "q.m20#1.e" to "Jedes Teil hat seine Aufgabe: Die Flasche speichert, der Druckminderer senkt den Hochdruck auf einen sicheren Bereich, das Flowmeter stellt die Abgabe ein, und Maske oder Brille führen sie zu. Fällt irgendwo etwas aus, atmen Sie weniger ein, als Sie glauben — deshalb wird das System auf jedem Abschnitt geprüft.",

    "q.m20#2.p" to "Welche Flussrate ist beim Bergsteigen üblich?",
    "q.m20#2.o0" to "0,5–1 L/min",
    "q.m20#2.o1" to "2–4 L/min",
    "q.m20#2.o2" to "8–10 L/min",
    "q.m20#2.o3" to "Über 15 L/min",
    "q.m20#2.e" to "2–4 L/min ist der übliche Bereich beim Bergsteigen; der genaue Wert hängt von Höhe, Belastung und individueller Reaktion ab. Höherer Fluss ist angenehmer, verbraucht aber schneller — ein Kompromiss, der direkt bestimmt, wie lange Sie auf 8.000 m bleiben können.",

    "q.m20#3.p" to "Warum muss bei der Sauerstoffplanung eine Notreserve separat gerechnet werden?",
    "q.m20#3.o0" to "Um ein bisschen mehr mitzunehmen",
    "q.m20#3.o1" to "Weil Verzögerungen, Unterstützung eines Partners oder ein Systemausfall zusätzlichen Sauerstoff verbrauchen können",
    "q.m20#3.o2" to "Weil Flaschen undicht sind",
    "q.m20#3.o3" to "Weil Vorschriften es verlangen",
    "q.m20#3.e" to "Der klassische Sauerstoff-Planungsfehler ist 'gerade genug bis zum Gipfel'. Reale Zeitpläne sind fast immer langsamer als geplant, und Partner können zu wenig haben oder das System kann lecken. Ohne Reserve ist jede Abweichung ein Glücksspiel in der gefährlichsten Höhe.",

    "q.m20#4.p" to "Was kann passieren, wenn der Sauerstoff ausgeht?",
    "q.m20#4.o0" to "Gar nichts",
    "q.m20#4.o1" to "Der Zustand kann schnell verfallen, weil sich der Körper an eine höhere eingeatmete Sauerstoffkonzentration angepasst hat",
    "q.m20#4.o2" to "Höhenkrankheit tritt sofort ein",
    "q.m20#4.o3" to "Das System schaltet automatisch auf Umgebungsluft um",
    "q.m20#4.e" to "Plötzlich von angereichertem Sauerstoff auf den Umgebungspartialdruck zurückzufallen ist auf 8.000 m, als würde man mit einem Schlag ein Stück Höhe gewinnen. Wenn Sie weit vom Lager und schon erschöpft sind, kann das schnell gefährlich werden — deshalb muss die Sauerstoffreserve konservativ bleiben.",

    "q.m20#5.p" to "[Mehrfachauswahl] Welche Disziplin gilt beim Umgang mit dem Sauerstoffsystem?",
    "q.m20#5.o0" to "Auf jedem Abschnitt Fluss und Anschlüsse prüfen",
    "q.m20#5.o1" to "Die geplante Flussrate nutzen und nicht nach Belieben aufdrehen",
    "q.m20#5.o2" to "Restmenge und geschätzte Reichweite notieren",
    "q.m20#5.o3" to "Vorher vereinbaren, bei welcher Restmenge abgestiegen werden muss",
    "q.m20#5.o4" to "Bei Unwohlsein den Fluss auf Maximum drehen",
    "q.m20#5.e" to "Der vierte Punkt ist der wichtigste: 'bei dieser Restmenge absteigen' zu einer vorab fixierten Zahl machen statt zu einer Diskussion vor Ort. Wenn es darauf ankommt, kann die Person, die diese Regel braucht, vielleicht nicht mehr genau beurteilen.",

    "q.m20#6.p" to "Warum ist die Verwendung von Sauerstoff nicht 'Betrug'?",
    "q.m20#6.o0" to "Weil die Regeln es erlauben",
    "q.m20#6.o1" to "Weil der Körper oberhalb 8.000 m außerhalb des physiologischen Bereichs ist, den er langfristig kompensieren kann; Sauerstoff ist die Standardantwort darauf",
    "q.m20#6.o2" to "Weil es alle machen",
    "q.m20#6.o3" to "Weil es die Gipfelquote erhöht",
    "q.m20#6.e" to "Das Wort Betrug unterstellt, man könne sich mit etwas mehr Anstrengung an der Grenze vorbeimogeln — aber die Grenze auf 8.000 m ist Physik und Physiologie, keine Regel. Sauerstoff hebt die physiologische Obergrenze etwas an; er ändert nicht die Tatsache, dass Sie nicht lange bleiben können.",

    "q.m20#7.p" to "Worin liegt der Hauptunterschied zwischen Maske und Nasenbrille?",
    "q.m20#7.o0" to "Eine Maske liefert eine stabilere Konzentration, ist aber stickiger und schränkt beim Gehen die Sicht ein",
    "q.m20#7.o1" to "Eine Brille kann eine höhere Konzentration liefern",
    "q.m20#7.o2" to "Sie sind identisch",
    "q.m20#7.o3" to "Eine Maske ist leichter",
    "q.m20#7.e" to "Eine Maske dichtet besser ab und hält eine stabile Konzentration, erhöht aber den Atemwiderstand, beschlägt leicht und ist in Bewegung unangenehm; eine Brille ist bequem und lässt die Sicht frei, doch die tatsächlich eingeatmete Konzentration hängt stark von der Atemweise ab. Die Wahl richtet sich nach Gelände, Intensität und persönlicher Toleranz — nicht danach, was grundsätzlich besser ist.",

    "q.m20#8.p" to "Welcher Kompromiss entsteht beim Erhöhen bzw. Senken der Flussrate?",
    "q.m20#8.o0" to "Bequemlichkeit gegen Durchhaltezeit",
    "q.m20#8.o1" to "Gewicht gegen Preis",
    "q.m20#8.o2" to "Es gibt keinen Kompromiss",
    "q.m20#8.o3" to "Höhe gegen Temperatur",
    "q.m20#8.e" to "Höherer Fluss heißt bequemerer Körper und besser erhaltene Urteilskraft, aber weniger Zeit, bis es ausgeht. Ein Sauerstoffplan ist damit faktisch ein Budget dafür, wie lange Sie oben bleiben können — das legt das Gipfeltagsfenster und die Umkehrzeit direkt fest.",

    "q.m20#9.p" to "Warum wird das Flaschengewicht zum Logistikproblem?",
    "q.m20#9.o0" to "Weil sie sperrig sind",
    "q.m20#9.o1" to "Weil Flasche und Gas schwer sind und oberhalb des Hochlagers alles von Menschen getragen werden muss",
    "q.m20#9.o2" to "Weil man sie nicht aufgeben kann",
    "q.m20#9.o3" to "Weil sie leicht kaputtgehen",
    "q.m20#9.e" to "In der Höhe wird der Preis jedes Kilogramms vergrößert, und eine Flasche ist schwer und nicht komprimierbar. Deshalb muss die Sauerstoffplanung zusammen mit Lageraufbau und Mannschaft entworfen werden — sie ist keine isolierte Ausrüstungsfrage.",

    "q.m20#10.p" to "Warum muss Sauerstoff vorab im Hochlager deponiert werden?",
    "q.m20#10.o0" to "Um den Gipfeltag zu entlasten und zu garantieren, dass dann Sauerstoff verfügbar ist",
    "q.m20#10.o1" to "Um Diebstahl zu verhindern",
    "q.m20#10.o2" to "Weil es dort oben kälter ist",
    "q.m20#10.o3" to "Um Geld zu sparen",
    "q.m20#10.e" to "Am Gipfeltag sind Sie am meisten gefordert und am wenigsten leistungsfähig; Sie können nicht auch noch Sauerstoff hochtragen. Er muss also vorher Last für Last hochgeschafft werden — was Sauerstoffmenge, Mannschaft und Wetterfenster schon in der Planung aneinanderbindet.",

    "q.m20#11.p" to "Was tun Sie, wenn das Sauerstoffsystem unterwegs ausfällt?",
    "q.m20#11.o0" to "Weitersteigen und zu Hause reparieren",
    "q.m20#11.o1" to "Sofort Rest-Sauerstoff und eigene Höhe bewerten und dann nach Plan handeln: absteigen oder auf das Reservesystem wechseln",
    "q.m20#11.o2" to "Den Fluss aufdrehen und versuchen, es zu beheben",
    "q.m20#11.o3" to "Auseinandernehmen und reparieren",
    "q.m20#11.e" to "Ein Sauerstoffausfall heißt, Sie arbeiten plötzlich ungeschützt unter den Bedingungen einer höheren Höhe. Das zu behandeln hat Vorrang vor allem anderen: erst entscheiden, ob die Reserve weitergehen erlaubt, sonst absteigen. Auf 8.000 m ist Absteigen eine sinnvolle Wahl, kein Scheitern.",

    "q.m20#12.p" to "[Reihenfolge] Wie lautet die Prüfsequenz für das Sauerstoffsystem am Gipfeltag?",
    "q.m20#12.o0" to "Flaschendruck und geschätzte Reichweite bestätigen",
    "q.m20#12.o1" to "Druckminderer, Schlauch und Maske bzw. Brille auf Schäden prüfen",
    "q.m20#12.o2" to "Fluss öffnen und bestätigen, dass tatsächlich Gas kommt",
    "q.m20#12.o3" to "Restmenge notieren und Partner sowie die Menschen zu Hause informieren",
    "q.m20#12.e" to "Die ersten drei sind technische Prüfungen, die vierte ist Gruppenkommunikation — und letztere zählt in der Höhe besonders: Wenn Ihre Partner Ihre Sauerstoffreserve kennen, bemerken sie einen Abbau bei Ihnen vielleicht früher als Sie selbst.",

    "q.m20#13.p" to "Warum kann Sauerstoff die Akklimatisierung nicht ersetzen?",
    "q.m20#13.o0" to "Weil Sauerstoff zu teuer ist",
    "q.m20#13.o1" to "Weil Akklimatisierung die körpereigene physiologische Kompensation ist, während Sauerstoff nur die eingeatmete Konzentration erhöht",
    "q.m20#13.o2" to "Weil Sauerstoff aufhört zu wirken",
    "q.m20#13.o3" to "Weil Sauerstoff nur bei Höhenkrankheit hilft",
    "q.m20#13.e" to "Akklimatisierung verändert, wie der Körper Sauerstoff nutzt; Sauerstoff verändert, wie viel ankommt. Das eine bekommen Sie nicht durch das andere. Deshalb bleiben Abstieg, langsamer Aufstieg und ausreichende Akklimatisierungszeit auf 8.000 m nicht verhandelbare Voraussetzungen.",

    "q.m20#14.p" to "[Mehrfachauswahl] Was sind häufige Ausfälle im Sauerstoffsystem?",
    "q.m20#14.o0" to "Vereisung oder Verstopfung an der Verbindung",
    "q.m20#14.o1" to "Undichter Schlauch",
    "q.m20#14.o2" to "Fehler am Druckminderer mit ungenauem Fluss",
    "q.m20#14.o3" to "Schwierigkeiten, das Flaschenventil zu öffnen",
    "q.m20#14.o4" to "Die Flasche wiegt mehr als erwartet",
    "q.m20#14.e" to "Alle vier hängen mit Kälte, Vereisung und unbequemer Handhabung zusammen — und alle passieren in der Höhe, in Müdigkeit, wenn sie am schwersten zu bewältigen sind. Deshalb reicht ein Reservesystem allein nicht; Sie brauchen auch einen Entscheidungsplan für den Ausfall.",

    "q.m20#15.p" to "Warum muss der Sauerstoffplan in den Zeitplan geschrieben werden?",
    "q.m20#15.o0" to "Für die Optik",
    "q.m20#15.o1" to "Weil die Sauerstoffmenge die mögliche Umkehrzeit und die maximale Aufenthaltsdauer direkt bestimmt",
    "q.m20#15.o2" to "Um Ausgaben zu erfassen",
    "q.m20#15.o3" to "Für eine einfachere Abrechnung",
    "q.m20#15.e" to "Sauerstoff ist kein 'bring etwas mit, dann passt es', sondern ein beziffertes Budget: wie viele Flaschen, bei welchem Fluss, für wie viele Stunden. Diese Zahlen bestimmen wiederum die Umkehrzeit, deshalb müssen sie mit dem Zeitplan geplant werden und nicht auf einer separaten Liste stehen.",

    "q.m20#16.p" to "Ergänzen Sie: Die übliche Flussrate beim Bergsteigen liegt bei etwa 2 bis ( ) L/min.",
    "q.m20#16.a0" to "4",
    "q.m20#16.a1" to "vier",
    "q.m20#16.e" to "2–4 L/min. Der Bereich ist der Kompromiss zwischen ausreichendem Blutsauerstoff und sparsamem Gasverbrauch. Sauerstoffmanagement ist am Ende ein fortlaufendes Problem der Ressourcenverteilung.",

    "q.m20#17.p" to "Was tun Sie, wenn der Sauerstoff eines Partners knapp wird?",
    "q.m20#17.o0" to "Weiter zum Gipfel drücken; jeder für sich",
    "q.m20#17.o1" to "Die Information und die Restmengen sofort teilen und dann nach Plan gemeinsam absteigen oder Sauerstoff umverteilen",
    "q.m20#17.o2" to "Ihn das selbst regeln lassen",
    "q.m20#17.o3" to "Ihm den eigenen Sauerstoff ganz abgeben",
    "q.m20#17.e" to "Knappheit ist ein Ereignis der Gruppe, nicht des Einzelnen: Sie betrifft Abstiegsgeschwindigkeit und gegenseitige Deckung. Die schlechtesten Optionen sind die beiden Extreme — weiter zum Gipfel oder den eigenen Vorrat völlig abgeben. Vernünftig ist, Ressourcen umzuverteilen und alle nach unten zu bringen.",

    "q.m20#18.p" to "Eine nutzbare Flasche enthält 1.200 Liter. Bei einem Fluss von 3 L/min — wie viele Minuten reicht sie ungefähr?",
    "q.m20#18.a0" to "400",
    "q.m20#18.e" to "Etwa 400 Minuten (rund 6,7 Stunden): 1200 ÷ 3 = 400. Solche Rechnungen zählen am Gipfeltag direkt — sie bestimmen, wie lange Sie auf 8.000 m bleiben können, und damit, für welche Uhrzeit die Umkehr gesetzt werden muss.",

    "q.m20#19.p" to "Gipfelplan: 5 Stunden aufwärts, 3 Stunden abwärts, Fluss 2 L/min, plus 60 Minuten Notreserve. Welches Sauerstoffvolumen ist insgesamt nötig, in Litern?",
    "q.m20#19.a0" to "1080",
    "q.m20#19.e" to "1080 Liter: (5 + 3) Stunden × 60 min × 2 L/min = 960 Liter, plus 60 × 2 = 120 Liter Reserve, zusammen 1080. Aufstieg, Abstieg und Reserve als drei getrennte Teile zu rechnen ist die grundlegendste Disziplin der Sauerstoffplanung — nur zu zählen, ob es für den Aufstieg reicht, ist der häufigste Fehler.",

    // ---------- m21 Die vierzehn Achttausender: Himalaya ----------
    "q.m21#0.p" to "Wie viele Gipfel über 8.000 m gibt es weltweit?",
    "q.m21#0.o0" to "10",
    "q.m21#0.o1" to "12",
    "q.m21#0.o2" to "14",
    "q.m21#0.o3" to "18",
    "q.m21#0.e" to "Vierzehn, alle in Himalaya und Karakorum. Aus dieser Zahl entstand das bergsteigerische Ziel, das als 'die vierzehn Achttausender' bekannt ist.",

    "q.m21#1.p" to "In welchen Ländern liegen die vierzehn Achttausender?",
    "q.m21#1.o0" to "China, Nepal, Indien, Pakistan",
    "q.m21#1.o1" to "China, Nepal, Bhutan, Indien",
    "q.m21#1.o2" to "Nepal, Pakistan, Afghanistan, Tadschikistan",
    "q.m21#1.o3" to "China, Indien, Pakistan, Myanmar",
    "q.m21#1.e" to "Vier Länder: China, Nepal, Indien und Pakistan. Diese Verteilung zu kennen ist wichtig — sie bestimmt Permit, Logistik, Rettung und politisches Risiko, und all das gehört zur Planung auf 8.000 m.",

    "q.m21#2.p" to "Wie hoch ist der Everest?",
    "q.m21#2.o0" to "8.611 m",
    "q.m21#2.o1" to "8.848 m",
    "q.m21#2.o2" to "8.586 m",
    "q.m21#2.o3" to "8.516 m",
    "q.m21#2.e" to "8.848 m (die gemeinsame chinesisch-nepalesische Vermessung von 2020 ergab 8.848,86 m). Als höchster Berg der Welt hat er auch die am weitesten entwickelte kommerzielle Infrastruktur — aber ausgereift heißt ausgereifte Logistik und Routen, nicht geringes Risiko: Gedränge, Kosten und die Schwierigkeit guten Urteilens sind ebenfalls echte Gefahren.",

    "q.m21#3.p" to "Welchen Platz hat der Annapurna I in der Achttausender-Geschichte?",
    "q.m21#3.o0" to "Der zuletzt bestiegene",
    "q.m21#3.o1" to "Der erste je bestiegene Achttausender",
    "q.m21#3.o2" to "Die niedrigste Todesrate",
    "q.m21#3.o3" to "Der am leichtesten zu besteigende",
    "q.m21#3.e" to "Der Annapurna I ist 8.091 m und wurde 1950 erstbestiegen — der erste Achttausender der Menschheitsgeschichte. Seine Todesrate gehört seit jeher zu den höchsten. Zuerst bestiegen zu sein hat nichts damit zu tun, leicht zu sein.",

    "q.m21#4.p" to "Was zeichnet den Shishapangma aus?",
    "q.m21#4.o0" to "Er liegt in Nepal",
    "q.m21#4.o1" to "Er ist der einzige Achttausender vollständig in China und der zuletzt bestiegene der vierzehn",
    "q.m21#4.o2" to "Er ist der höchste",
    "q.m21#4.o3" to "Er ist der einfachste",
    "q.m21#4.e" to "Der Shishapangma ist 8.027 m in Tibet und der einzige Achttausender, der ganz in China liegt; er wurde 1964 von einem chinesischen Team erstbestiegen und ist der letzte der vierzehn, der bestiegen wurde.",

    "q.m21#5.p" to "Wie ist das Verhältnis von Lhotse und Everest?",
    "q.m21#5.o0" to "Sie liegen weit auseinander",
    "q.m21#5.o1" to "Der Lhotse grenzt an den Everest und teilt oft den gleichen Anmarschweg",
    "q.m21#5.o2" to "Der Lhotse ist höher als der Everest",
    "q.m21#5.o3" to "Sie liegen in verschiedenen Ketten",
    "q.m21#5.e" to "Der Lhotse ist 8.516 m, unmittelbar neben dem Everest, und von Süden teilen beide den größten Teil der Route und der Lager. Deshalb werden sie logistisch und akklimatisch oft in einem Zeitplan mitgedacht.",

    "q.m21#6.p" to "Wie wird der Cho Oyu üblicherweise eingeschätzt?",
    "q.m21#6.o0" to "Als technischster Achttausender",
    "q.m21#6.o1" to "Allgemein als einer der technisch weniger anspruchsvollen Achttausender",
    "q.m21#6.o2" to "Als Achttausender mit der höchsten Todesrate",
    "q.m21#6.o3" to "Kein kommerzielles Team besteigt ihn",
    "q.m21#6.e" to "Der Cho Oyu ist 8.188 m und gilt mit verhältnismäßig sanfter Route und ausgereifter Logistik als einer der technisch einfacheren Achttausender. Aber 'verhältnismäßig leicht' heißt weiterhin, sich tagelang in der Todeszone zu bewegen — die Größenordnung darf man nicht unterschätzen.",

    "q.m21#7.p" to "Wofür ist der Nanga Parbat bekannt?",
    "q.m21#7.o0" to "Für sanfte Routen",
    "q.m21#7.o1" to "Für enorme Reliefhöhe und schwere Lawinengefahr",
    "q.m21#7.o2" to "Für die billigsten Permits",
    "q.m21#7.o3" to "Für die beste Logistik",
    "q.m21#7.e" to "Der Nanga Parbat ist 8.126 m und heißt 'Nackter Berg' — er steigt aus dem Tal in gewaltiger Höhe direkt auf, mit ausgeprägter Lawinen- und Steinschlaggefahr. Seine historischen Besteigungskosten sind selbst für Achttausender hoch.",

    "q.m21#8.p" to "[Zuordnung] Ordnen Sie jedem Gipfel seine Höhe zu.",
    "q.m21#8.l0" to "Everest",
    "q.m21#8.r0" to "8.848 m",
    "q.m21#8.l1" to "Kangchenjunga",
    "q.m21#8.r1" to "8.586 m",
    "q.m21#8.l2" to "Lhotse",
    "q.m21#8.r2" to "8.516 m",
    "q.m21#8.l3" to "Makalu",
    "q.m21#8.r3" to "8.485 m",
    "q.m21#8.e" to "Das sind der erste, dritte, vierte und fünfte Gipfel der Welt. Lernen Sie nicht nur die Zahlen auswendig — merken Sie sich die Reihenfolge und die Kette, zu der jeder gehört. Zahlen kann man nachschlagen; das Gesamtbild muss im Kopf sitzen.",

    "q.m21#9.p" to "Warum sind 'die vierzehn' zu einem anerkannten bergsteigerischen Ziel geworden?",
    "q.m21#9.o0" to "Weil es eine runde Zahl ist",
    "q.m21#9.o1" to "Weil sie zufällig eine vollständige Grenze des Höhenbergsteigens bilden und die Zahl in einem Leben erreichbar ist",
    "q.m21#9.o2" to "Weil kommerzielle Anbieter es beworben haben",
    "q.m21#9.o3" to "Weil die UIAA es verlangt",
    "q.m21#9.e" to "Das Besondere an den vierzehn ist, dass sie eine objektive, eindeutige Grenze haben (über 8.000 m), eine endliche Anzahl, und sich einzeln auflisten lassen. Das macht das Ziel klar und zugleich lebenslang — deshalb wurde es zum Maßstab.",

    "q.m21#10.p" to "[Mehrfachauswahl] Was ist normalerweise nötig, um einen Achttausender zu besteigen?",
    "q.m21#10.o0" to "Ein vollständiger Akklimatisierungszyklus mit Hochlager-Rotationen",
    "q.m21#10.o1" to "Technisches Können und Gletschererfahrung",
    "q.m21#10.o2" to "Ein verlässliches Sauerstoff- und Logistiksystem",
    "q.m21#10.o3" to "Kondition und Urteilskraft, die auf 7.000 m nachgewiesen wurden",
    "q.m21#10.o4" to "Ein professionelles Filmteam",
    "q.m21#10.e" to "Die vier entsprechen vier Dimensionen: physiologisch (Akklimatisierung), technisch, logistisch und gesammelte Erfahrung. Auf 8.000 m wirken alle gleichzeitig — fehlt eine, wird sie zum schwachen Glied, und schwache Glieder werden in der Höhe schnell vergrößert.",

    "q.m21#11.p" to "Dhaulagiri, Manaslu und Annapurna liegen alle in welchem Land?",
    "q.m21#11.o0" to "China",
    "q.m21#11.o1" to "Nepal",
    "q.m21#11.o2" to "Pakistan",
    "q.m21#11.o3" to "Indien",
    "q.m21#11.e" to "Alle drei liegen in Nepal. Nepal hat die meisten Achttausender, deshalb ist seine Bergsteigerindustrie so entwickelt — und deshalb steht es unter dauerndem Druck bei Permits, Verwaltung und Umweltschutz.",

    "q.m21#12.p" to "Warum sind 'ausgereifte kommerzielle Routen' an Achttausendern weiterhin gefährlich?",
    "q.m21#12.o0" to "Weil sie teuer sind",
    "q.m21#12.o1" to "Weil die Höhe selbst nicht veränderbar ist und Gedränge, Warten und schwierige Rettung neue Risiken schaffen",
    "q.m21#12.o2" to "Weil die Bergführer unprofessionell sind",
    "q.m21#12.o3" to "Weil die Ausrüstung schlecht ist",
    "q.m21#12.e" to "Kommerzialisierung löst Logistik und Routenkenntnis, aber sie kann die Höhe nicht senken. Im Gegenteil: Viele Teams im selben Fenster erzeugen Warteschlangen — und Warten auf 8.000 m heißt zusätzlichen Sauerstoff und Körperwärme verbrennen.",

    "q.m21#13.p" to "[Reihenfolge] Ordnen Sie diese Gipfel vom höchsten zum niedrigsten.",
    "q.m21#13.o0" to "Everest (8.848)",
    "q.m21#13.o1" to "Kangchenjunga (8.586)",
    "q.m21#13.o2" to "Makalu (8.485)",
    "q.m21#13.o3" to "Annapurna I (8.091)",
    "q.m21#13.e" to "Hinter dieser Reihenfolge liegt die Spanne von Platz eins bis Platz zehn der Welt. Die Reihenfolge zu behalten ist nützlicher als exakte Zahlen — bei Diskussionen über Routen, Logistik und Schwierigkeit braucht man meist die relative Position.",

    "q.m21#14.p" to "Warum lohnt es, die Erstbesteigungsgeschichte eines Achttausenders zu lesen?",
    "q.m21#14.o0" to "Für Prüfungen",
    "q.m21#14.o1" to "Weil Erstbesteigungen meist die Kernschwierigkeiten und Risikotypen eines Berges offenlegen",
    "q.m21#14.o2" to "Um Namen auswendig zu lernen",
    "q.m21#14.o3" to "Es hat nichts mit Bergsteigen zu tun",
    "q.m21#14.e" to "Scheitern und Verluste früher Teams zeigen genau auf die Hauptschwierigkeiten eines Berges — wiederkehrende Lawinenpassagen, heftige Windstrecken, exponierte Routenabschnitte. Die Erstbesteigungsgeschichte als Risikoakte zu lesen ist weit nützlicher, als sie als Erzählung zu lesen.",

    "q.m21#15.p" to "[Mehrfachauswahl] Welche davon sind Himalaya-Achttausender?",
    "q.m21#15.o0" to "Everest",
    "q.m21#15.o1" to "Annapurna I",
    "q.m21#15.o2" to "Shishapangma",
    "q.m21#15.o3" to "K2",
    "q.m21#15.e" to "Die ersten drei liegen im Himalaya, der K2 im Karakorum. Die beiden Ketten sind geografisch benachbart, aber geologisch verschieden, und ihre Saisons und Wettermuster unterscheiden sich — deshalb werden die vierzehn oft nach Kette gruppiert besprochen.",

    "q.m21#16.p" to "Wie wirkt der Titel 'höchster Berg der Welt' auf die Strategie?",
    "q.m21#16.o0" to "Überhaupt nicht",
    "q.m21#16.o1" to "Er bedeutet die größte Medien- und Handelsaufmerksamkeit und damit die größte Teamdichte und Staugefahr",
    "q.m21#16.o2" to "Er bedeutet die leichteste Route",
    "q.m21#16.o3" to "Er bedeutet die einfachste Rettung",
    "q.m21#16.e" to "Aufmerksamkeit bringt Ressourcen und auch Menschenmengen. Wenn sich viele Teams in einem Fenster konzentrieren, werden Warten, Gedränge und der psychische Druck, den Platz in der Schlange nicht aufzugeben, zu zusätzlichen Risikoquellen — ein Strategieproblem, das es nur am höchsten Berg gibt.",

    "q.m21#17.p" to "Ergänzen Sie: Weltweit gibt es ( ) Gipfel über 8.000 m.",
    "q.m21#17.a0" to "14",
    "q.m21#17.a1" to "vierzehn",
    "q.m21#17.e" to "Vierzehn. Eine kleine Zahl, die dennoch die ganze Grenze des Höhenbergsteigens definiert — deshalb gilt 'die vierzehn' weiter als ein Ziel, für das sich ein Leben lohnt.",

    // ---------- m22 Die vierzehn Achttausender: Karakorum ----------
    "q.m22#0.p" to "Wie viele Achttausender liegen im Karakorum?",
    "q.m22#0.o0" to "2",
    "q.m22#0.o1" to "4",
    "q.m22#0.o2" to "6",
    "q.m22#0.o3" to "10",
    "q.m22#0.e" to "Vier: K2, Gasherbrum I, Gasherbrum II und Broad Peak. Sie sind auch als K2, K4, K5 und K3 bekannt — das K steht für Karakorum.",

    "q.m22#1.p" to "Wie hoch ist der K2 und welchen Rang hat er?",
    "q.m22#1.o0" to "8.611 m, zweithöchster der Welt und einer der technischsten und tödlichsten Achttausender",
    "q.m22#1.o1" to "8.848 m, höchster der Welt",
    "q.m22#1.o2" to "8.586 m, dritthöchster der Welt",
    "q.m22#1.o3" to "8.051 m, einer der einfacheren",
    "q.m22#1.e" to "Der K2 ist 8.611 m, der zweithöchste der Welt. Er gilt weithin als einer der schwierigsten und gefährlichsten Achttausender, deshalb heißt er 'der Berg der Bergsteiger' — hier wiegen Technik und Urteilskraft weit mehr als logistische Unterstützung.",

    "q.m22#2.p" to "Warum haben Karakorum und Himalaya oft unterschiedliche Saisons?",
    "q.m22#2.o0" to "Wegen unterschiedlicher Breiten- und Längengrade",
    "q.m22#2.o1" to "Weil sie von unterschiedlichen Klimasystemen geprägt sind: Der Karakorum steht stärker unter dem Einfluss der Westwindzone",
    "q.m22#2.o2" to "Wegen unterschiedlicher Höhen",
    "q.m22#2.o3" to "Wegen unterschiedlicher Vorschriften",
    "q.m22#2.e" to "Die beste Saison im Himalaya wird vor allem vom Monsunzyklus bestimmt, während der Karakorum stärker von der Westwindzone und orografischem Niederschlag geprägt ist. Das entscheidet, wann man geht — und mit der falschen Saison sieht selbst das beste Team nie ein Gipfelfenster.",

    "q.m22#3.p" to "Welchen zweiten Namen trägt der Broad Peak?",
    "q.m22#3.o0" to "K1",
    "q.m22#3.o1" to "K2",
    "q.m22#3.o2" to "K3",
    "q.m22#3.o3" to "K5",
    "q.m22#3.e" to "Der Broad Peak ist auch K3, mit 8.051 m. Sein Gelände ist verhältnismäßig offen, aber der Schneefall ist schwer und starker Wind häufig — historisch gab es mehrere Unfälle, nachdem er unterschätzt worden war.",

    "q.m22#4.p" to "Welche zweiten Namen tragen Gasherbrum I und II?",
    "q.m22#4.o0" to "K4 und K5",
    "q.m22#4.o1" to "K5 und K4",
    "q.m22#4.o2" to "K2 und K3",
    "q.m22#4.o3" to "K3 und K4",
    "q.m22#4.e" to "Gasherbrum I ist K5 (8.080 m) und Gasherbrum II ist K4 (8.035 m) — die Nummerierung folgt nicht der Höhe, und genau das macht sie verwirrend. Merken Sie sich, dass die K-Nummern nicht nach Höhe sortiert sind, und Sie verwechseln es nicht.",

    "q.m22#5.p" to "In welchen zwei Ketten liegen alle vierzehn Achttausender?",
    "q.m22#5.o0" to "Himalaya und Tian Shan",
    "q.m22#5.o1" to "Himalaya und Karakorum",
    "q.m22#5.o2" to "Karakorum und Alpen",
    "q.m22#5.o3" to "Nyainqêntanglha und Himalaya",
    "q.m22#5.e" to "Alle liegen in Himalaya und Karakorum — geografisch benachbarte Ketten, die von unterschiedlichen Klimasystemen geprägt sind. Das zeigt wieder: Auf 8.000 m ist die Geografie selbst Schlüsselinformation.",

    "q.m22#6.p" to "[Zuordnung] Ordnen Sie jedem Gipfel seine Höhe zu.",
    "q.m22#6.l0" to "K2",
    "q.m22#6.r0" to "8.611 m",
    "q.m22#6.l1" to "Nanga Parbat",
    "q.m22#6.r1" to "8.126 m",
    "q.m22#6.l2" to "Gasherbrum I",
    "q.m22#6.r2" to "8.080 m",
    "q.m22#6.l3" to "Shishapangma",
    "q.m22#6.r3" to "8.027 m",
    "q.m22#6.e" to "Das sind der zweite, neunte, elfte und vierzehnte Gipfel. Sie spannen eine weite Höhenspanne und haben doch denselben Status innerhalb von 'über 8.000 m' — genau das ist das Eigentümliche dieser Klasse: eine klare Grenze mit enormer interner Varianz.",

    "q.m22#7.p" to "Wie ist das Verhältnis von Rang und Schwierigkeit bei Achttausendern richtig zu sehen?",
    "q.m22#7.o0" to "Höher heißt immer schwieriger",
    "q.m22#7.o1" to "Die Schwierigkeit wird vor allem von technischem Gelände, Klima und Logistik bestimmt und bildet die Höhenrangfolge nicht direkt ab",
    "q.m22#7.o2" to "Niedriger heißt immer leichter",
    "q.m22#7.o3" to "Schwierigkeit lässt sich überhaupt nicht vergleichen",
    "q.m22#7.e" to "Das ist die wichtigste Einsicht aus der Gesamtschau der vierzehn: Der Cho Oyu mit 8.188 m gilt als verhältnismäßig leicht, während der K2 mit 8.611 m zu den schwierigsten gehört — unter 500 m Höhenunterschied, und doch liegen Welten dazwischen.",

    "q.m22#8.p" to "[Mehrfachauswahl] Was bestimmt die tatsächliche Schwierigkeit eines Achttausenders?",
    "q.m22#8.o0" to "Technisches Gelände und Exposition",
    "q.m22#8.o1" to "Klima und Wetterfenster",
    "q.m22#8.o2" to "Logistik und Anmarsch",
    "q.m22#8.o3" to "Die Machbarkeit von Rettung",
    "q.m22#8.o4" to "Der Höhenrang des Gipfels",
    "q.m22#8.e" to "Alle vier zählen. Besonders die Rettungsmöglichkeit wird oft ignoriert: Ein Berg, an dem Rettung fast unmöglich ist, hat ein völlig anderes Risikoniveau, auch wenn die Route nicht schwer ist — denn es gibt keinen Puffer, wenn etwas schiefgeht.",

    "q.m22#9.p" to "[Reihenfolge] Ordnen Sie diese Gipfel vom höchsten zum niedrigsten.",
    "q.m22#9.o0" to "K2 (8.611)",
    "q.m22#9.o1" to "Nanga Parbat (8.126)",
    "q.m22#9.o2" to "Gasherbrum I (8.080)",
    "q.m22#9.o3" to "Shishapangma (8.027)",
    "q.m22#9.e" to "Diese Reihenfolge deckt die zweite Hälfte der vierzehn ab. Zusammen mit der Reihenfolge aus der vorigen Lektion haben Sie nun die vollständige Höhenfolge — die Grundlage dafür, einzuschätzen, in welche Stufe ein Berg gehört.",

    "q.m22#10.p" to "Warum sind 'die vierzehn' ein so forderndes Ziel?",
    "q.m22#10.o0" to "Weil es extrem teuer ist",
    "q.m22#10.o1" to "Weil es verlangt, Technik, Kondition, Akklimatisierung und Urteilskraft über viele Jahre und über Logistiksysteme in mehreren Ländern hinweg zu halten",
    "q.m22#10.o2" to "Weil es zu lange dauert",
    "q.m22#10.o3" to "Weil Permits schwer zu bekommen sind",
    "q.m22#10.e" to "Die vierzehn dauern oft mehr als ein Jahrzehnt, in dem der Körper altert und sich die Lebensumstände ändern. Es prüft nicht nur das Klettern, sondern die Beständigkeit langfristiger Erhaltung und Risikosteuerung.",

    "q.m22#11.p" to "Warum hängt der Erfolg auf 8.000 m oft mehr am Wetterfenster als an der Technik?",
    "q.m22#11.o0" to "Weil Technik keine Rolle spielt",
    "q.m22#11.o1" to "Weil auch bei ausreichender Technik langes Warten in der Höhe die Sicherheitsreserve verbraucht",
    "q.m22#11.o2" to "Weil man Technik am Berg lernen kann",
    "q.m22#11.o3" to "Weil Bergführer alles regeln",
    "q.m22#11.e" to "Das ist die Realität auf 8.000 m: Technik ist nur die Eintrittskarte, während das Fenster entscheidet, ob Sie durchkommen, solange Sie noch Kapazität haben. Deshalb planen 8.000er-Zeitpläne meist großzügige Reservetage ein.",

    "q.m22#12.p" to "Wenn Sie nur einen Achttausender als ersten wählen könnten — was ist sinnvoller?",
    "q.m22#12.o0" to "Direkt den K2 und fertig",
    "q.m22#12.o1" to "Einen mit ausgereifter Route, verlässlicher Logistik und machbarer Rettung, und das 'erste Mal' zum Erfahrungssammeln nutzen",
    "q.m22#12.o2" to "Einfach den niedrigsten",
    "q.m22#12.o3" to "Egal welchen; sie sind alle gleich",
    "q.m22#12.e" to "Der Wert eines ersten Achttausenders ist, den eigenen realen Zustand in der Todeszone kennenzulernen: wie Sie Sauerstoff nutzen, wie stark das Urteil sinkt, wie Ihr Tempo ist. Ihn an einem schwierigeren Berg zu verbrauchen heißt, mehrere Unbekannte gleichzeitig zu testen.",

    "q.m22#13.p" to "[Mehrfachauswahl] Welche davon sind Karakorum-Achttausender?",
    "q.m22#13.o0" to "K2",
    "q.m22#13.o1" to "Gasherbrum I",
    "q.m22#13.o2" to "Gasherbrum II",
    "q.m22#13.o3" to "Broad Peak",
    "q.m22#13.o4" to "Manaslu",
    "q.m22#13.e" to "Alle vier liegen im Karakorum — tatsächlich sind sie alle Achttausender dieser Kette. 'Die vier Karakorum-Achttausender' ist deshalb eine feste Wendung, und zusammen mit den zehn im Himalaya ergibt das genau vierzehn.",

    "q.m22#14.p" to "Was ist der praktischste Nutzen, die vierzehn als Ganzes zu betrachten?",
    "q.m22#14.o0" to "Jede Höhe hersagen zu können",
    "q.m22#14.o1" to "Zu verstehen, warum Schwierigkeit und Höhe nicht dasselbe sind, und das zur Beurteilung eigener Ziele zu nutzen",
    "q.m22#14.o2" to "Andere führen zu können",
    "q.m22#14.o3" to "Routenbeschreibungen schreiben zu können",
    "q.m22#14.e" to "Der eigentliche Wert ist ein mehrdimensionales Bild von Schwierigkeit: technische, klimatische, logistische und Rettungs-Dimension bestimmen zusammen die echte Schwelle eines Berges. Derselbe Rahmen gilt auch bei der Wahl unter 5.000ern und 6.000ern.",

    "q.m22#15.p" to "Warum kann der Anmarsch zu einem Achttausender selbst ein Risikofaktor sein?",
    "q.m22#15.o0" to "Weil er lange dauert",
    "q.m22#15.o1" to "Weil der Anmarsch oft Gletscher und Lawinengelände quert, während das Team noch nicht voll akklimatisiert ist",
    "q.m22#15.o2" to "Weil die Landschaft karg ist",
    "q.m22#15.o3" to "Weil Permits nötig sind",
    "q.m22#15.e" to "Der Anmarsch findet meist in der Aufstiegsphase statt, wenn die Akklimatisierung am schlechtesten und das Urteil am instabilsten ist, während zugleich Spalten und Lawinengelände zu bewältigen sind. In dieser doppelt verletzlichen Phase passieren viele Unfälle.",

    "q.m22#16.p" to "Wenn Sie Ihre eigene Liste von Achttausender-Zielen aufbauen — was sollten Sie zuerst festlegen?",
    "q.m22#16.o0" to "Die Namen der Berge, die Sie wollen",
    "q.m22#16.o1" to "Ihre eigenen Schwachpunkte (Technik, Akklimatisierung, Urteil oder Logistikerfahrung) und dann passende Gipfel dazu suchen",
    "q.m22#16.o2" to "Das Budget",
    "q.m22#16.o3" to "Die Länge Ihres Urlaubs",
    "q.m22#16.e" to "Nach dem Schwachpunkt zu wählen behandelt 8.000 m als Wachstumsweg statt als Sammlung von Erfolgen. Derselbe Berg ist für verschiedene Menschen unterschiedlich viel wert — je nachdem, welche Ihrer Lücken er schließt.",

    // ---------- m23 Grundfähigkeiten: integrierte Prüfung ----------
    "q.m23#0.p" to "[Szenario] Ein Partner hat auf 4.500 m Kopfschmerz und Übelkeit und beharrt darauf, 'mit einem weiteren Tag Akklimatisierung kann ich aufsteigen'. Was ist aus Sicht der Umweltkunde das richtige Urteil?",
    "q.m23#0.o0" to "Ein Tag mehr löst es sicher — weiter aufsteigen, ermutigen",
    "q.m23#0.o1" to "Symptome bedeuten, dass die Kompensation nicht reicht; bei anhaltenden Symptomen nicht weiter aufsteigen",
    "q.m23#0.o2" to "Medikamente geben und weiter aufsteigen",
    "q.m23#0.o3" to "100 m absteigen genügt",
    "q.m23#0.e" to "Die Kette beginnt bei der grundlegendsten Kausalität: niedriger Druck → niedriger Sauerstoffpartialdruck → der Körper braucht Zeit. Symptome sind das Signal, dass die Zeit nicht reicht, und ein weiterer Tag garantiert keine Besserung — die richtige Handlung ist also, den Aufstieg zu stoppen, nicht auf morgen zu wetten.",

    "q.m23#1.p" to "[Mehrfachauswahl] Ein Gruppenmitglied geht auf 5.000 m zu einem harten Schneehang. Welche Punkte müssen bestätigt sein?",
    "q.m23#1.o0" to "Steigeisen strikt zum Schuh passend",
    "q.m23#1.o1" to "Ein Eispickel in passender Länge zur Körpergröße",
    "q.m23#1.o2" to "UV400-Gletscherbrille und Sonnencreme mit hohem Lichtschutzfaktor",
    "q.m23#1.o3" to "Isolations- und Wetterschutzschichten passend zum Schichtensystem",
    "q.m23#1.o4" to "Kamera und Ersatzbatterien für Gipfelfotos",
    "q.m23#1.e" to "Die vier entsprechen vier Risikotypen: Ausrutschen (Steigeisen), Bremsen (Pickel), UV (Brille und Creme), Unterkühlung (Schichten). Ausrüstung prüft man richtig, indem man die Liste aus den Risiken baut, nicht indem man aus Gewohnheit in den Rucksack greift.",

    "q.m23#2.p" to "[Zuordnung] Ordnen Sie jeder Schicht des Kleidungssystems ihre Aufgabe zu.",
    "q.m23#2.l0" to "Basisschicht",
    "q.m23#2.r0" to "Führt Schweiß von der Haut weg und hält trocken",
    "q.m23#2.l1" to "Mittelschicht",
    "q.m23#2.r1" to "Hält eine Luftschicht für Wärme (Fleece isoliert auch feucht)",
    "q.m23#2.l2" to "Hülle",
    "q.m23#2.r2" to "Wasserdicht, winddicht und atmungsaktiv; schirmt gegen das Wetter ab",
    "q.m23#2.l3" to "Daunenschicht (bei extremer Kälte)",
    "q.m23#2.r3" to "Die effizienteste Wärme in trockener Umgebung",
    "q.m23#2.e" to "Jede Schicht hat eine Aufgabe. Wer diese Aufteilung einmal sieht, versteht, warum 'mehr Schichten ist wärmer' falsch ist: Ohne Feuchtigkeitstransport tragen Sie Ihr eigenes feuchtes Mikroklima mit, und eine nicht atmungsaktive Hülle staut Schweißdampf innen.",

    "q.m23#3.p" to "[Szenario] Beim Aufstieg am Schneehang tritt die Person vor Ihnen ungleichmäßige Stufen. Was ist die wahrscheinlichste Folge?",
    "q.m23#3.o0" to "Die Gruppe kommt schneller voran",
    "q.m23#3.o1" to "Die Nachfolgenden müssen ihr Gleichgewicht ständig neu justieren, verbrauchen mehr Energie und verlieren Stabilität",
    "q.m23#3.o2" to "Der Hang wird einbrechen",
    "q.m23#3.o3" to "Keine Wirkung",
    "q.m23#3.e" to "Stufen sind das Fundament der Gruppe. Ungleichmäßige Stufen zwingen alle, immer wieder nach einem Tritt zu suchen — zusätzlich zu der Gleichgewichtsfähigkeit, die in der Höhe ohnehin knapp ist. Ein Lehrbuchfall dafür, wie kleine Probleme zu großem Risiko akkumulieren.",

    "q.m23#4.p" to "[Reihenfolge] Bringen Sie die Selbstbremsung mit dem Eispickel in die richtige Reihenfolge.",
    "q.m23#4.o0" to "Den Pickel fest greifen und den Griff korrekt bestätigen",
    "q.m23#4.o1" to "Auf den Bauch rollen, mit dem Gesicht zum Schnee",
    "q.m23#4.o2" to "Die Haue mit dem Körpergewicht in den Schnee treiben",
    "q.m23#4.o3" to "Die Füße anheben, damit die Steigeisen nicht greifen und Sie überschlagen",
    "q.m23#4.e" to "Diese Abfolge ist das Fundament des ganzen technischen Systems. Sie muss ohne Nachdenken laufen — bei einem echten Sturz haben Sie ein bis zwei Sekunden Denkfähigkeit, und diese zwei Sekunden sind vollständig vom Muskelgedächtnis belegt.",

    "q.m23#5.p" to "[Szenario] Ein Bergsteiger stürzt an einem harten Schneehang, und die Bremsung scheitert. Was ist bei der Auswertung die wahrscheinlichste Ursache?",
    "q.m23#5.o0" to "Der Pickel war zu kurz",
    "q.m23#5.o1" to "Die Haue konnte im harten Schnee nicht greifen — und ein harter Schneehang hätte mit Fixseil gesichert werden müssen",
    "q.m23#5.o2" to "Die Schuhe waren falsch",
    "q.m23#5.o3" to "Sie trugen keine Handschuhe",
    "q.m23#5.e" to "Der Bremserfolg sinkt auf hartem Schnee und Eis deutlich; das ist die Grenze der Technik selbst. Deshalb liegt die eigentliche Frage meist früher — warum waren wir überhaupt ohne Sicherungssystem an einem steilen harten Schneehang?",

    "q.m23#6.p" to "[Mehrfachauswahl] Welche Risiken werden beim Abstieg leicht übersehen?",
    "q.m23#6.o0" to "Nachlassende Kondition schwächt die Beinkontrolle",
    "q.m23#6.o1" to "Die Aufmerksamkeit sinkt, sobald das Ziel erreicht ist",
    "q.m23#6.o2" to "Die Schneeoberfläche gefriert oder wird weich, sodass die Bedingungen anders sind als beim Aufstieg",
    "q.m23#6.o3" to "Schwindendes Licht senkt Sicht und Urteilsfähigkeit",
    "q.m23#6.o4" to "Abstiegsrouten sind meist kürzer als Aufstiegsrouten",
    "q.m23#6.e" to "Diese vier zusammen erklären, warum so viele Unfälle beim Abstieg passieren. Der Abstieg ist nicht der Heimweg nach getaner Arbeit, sondern eine Strecke, die einen eigenen Plan braucht und vergleichbares Risiko trägt.",

    "q.m23#7.p" to "[Szenario] Das Mundstück Ihres Trinkschlauchs friert in der Kälte schnell ein. Was tun Sie?",
    "q.m23#7.o0" to "Auf eine isolierte Weithalsflasche wechseln und nach jedem Trinken das Wasser zurückblasen oder die Flasche umgedreht lagern",
    "q.m23#7.o1" to "Weiter benutzen und warten, bis es auftaut",
    "q.m23#7.o2" to "Den Beutel außen am Rucksack tragen",
    "q.m23#7.o3" to "Aufhören zu trinken",
    "q.m23#7.e" to "Eine kleine, aber kritische Technik: Dehydrierung in der Höhe heißt meist nicht 'kein Wasser mitgenommen', sondern 'das Wasser ist gefroren und ich konnte nicht trinken'. Ein Trinksystem zu bauen, das nicht einfrieren kann, ist das, was wirklich 'auf Trinken vorbereitet' bedeutet.",

    "q.m23#8.p" to "Ergänzen Sie: Die Temperatur fällt um etwa ( ) °C je 1.000 m Aufstieg.",
    "q.m23#8.a0" to "6.5",
    "q.m23#8.a1" to "sechs Komma fünf",
    "q.m23#8.e" to "6,5 °C. Diese Zahl zieht sich durch den ganzen Kurs: Sie erklärt die Schneegrenze, bestimmt, wie dick Ihre Isolation sein muss, und treibt, wie sich Lawinen- und Eisverhältnisse ändern. Sie zu verstehen heißt, mit ihr argumentieren zu können.",

    "q.m23#9.p" to "[Szenario] Auf 5.000 m beschlägt Ihre Brille stark und Sie können das Gelände nicht mehr lesen. Was ist das wichtigste Risiko?",
    "q.m23#9.o0" to "Es ist nur unbequem",
    "q.m23#9.o1" to "Sie verlieren die Grundlage der Geländebeurteilung und können auf einen Steilhang, eine Wechte oder ein Spaltenfeld geraten",
    "q.m23#9.o2" to "Sie bekommen Schneeblindheit",
    "q.m23#9.o3" to "Die Partner beschweren sich",
    "q.m23#9.e" to "'Nichts sehen' heißt in Wahrheit, die Belege zu verlieren, nach denen Sie urteilen. In komplexem Schneegelände können ein oder zwei falsche Tritte sehr teuer sein. 'Sehe ich klar' sollte deshalb ein hartes Kriterium für die Zuverlässigkeit der Ausrüstung sein.",

    "q.m23#10.p" to "[Mehrfachauswahl] Ein Gruppenmitglied hat in der Höhe starken Appetitverlust. Was ist zu tun?",
    "q.m23#10.o0" to "Aktiv in kleinen Mengen und häufig essen, kohlenhydratreich und leicht verdaulich",
    "q.m23#10.o1" to "Gleichmäßige, ausreichende Flüssigkeitszufuhr sichern",
    "q.m23#10.o2" to "Den Appetitverlust als mögliches Akklimatisierungssignal behandeln und beobachten",
    "q.m23#10.o3" to "Mahlzeiten durch viel Kaffee und Energydrinks ersetzen",
    "q.m23#10.e" to "Die ersten drei sind richtig; der vierte ist auf sehr typische Weise falsch: Koffein gibt ein vorübergehendes Gefühl, ersetzt aber keine Energie. In der Höhe schwächt zu wenig Energiezufuhr direkt die Akklimatisierung — ein Teufelskreis.",

    "q.m23#11.p" to "[Szenario] Auf 5.000 m springt Ihr Telefon von 40 % direkt auf Aus. Was ist die vernünftigste Reaktion?",
    "q.m23#11.o0" to "Am Körper wärmen und dann erneut einschalten",
    "q.m23#11.o1" to "Immer wieder einschalten",
    "q.m23#11.o2" to "Auf Elektronik verzichten",
    "q.m23#11.o3" to "Den Restakku für einen Notruf verwenden",
    "q.m23#11.e" to "Das ist typisches Lithiumbatterie-Verhalten in der Kälte: Die Kapazität bricht zusammen, ohne dass die Ladung weg ist. Am Körper gewärmt kommt die Leistung meist zurück. Die Lehre: Elektronik als Sicherheitsausrüstung behandeln, die ohne Vorwarnung ausfallen kann.",

    "q.m23#12.p" to "[Reihenfolge] Bringen Sie eine vollständige Ausrüstungskontrolle in eine sinnvolle Ordnung.",
    "q.m23#12.o0" to "Die Liste aus den Risiken bauen (was Gelände, Wetter und Höhe jeweils verlangen)",
    "q.m23#12.o1" to "Jeden Punkt auf Vollständigkeit und Funktion prüfen",
    "q.m23#12.o2" to "Die kritischen Teile anlegen und im Betrieb testen (Steigeisen, Gurt, Helm, Stirnlampe)",
    "q.m23#12.o3" to "Den Ausrüstungszustand und den Rückfallplan notieren und den Partnern mitteilen",
    "q.m23#12.e" to "Der Schlüssel ist Schritt drei, die Testbenutzung: Vollständig heißt nicht funktionsfähig. Ein nicht ganz eingerasteter Steigeisenbügel oder eine alte Batterie in der Stirnlampe zeigt sich erst, wenn Sie es anlegen und benutzen.",

    "q.m23#13.p" to "[Szenario] Die Gruppe entscheidet wetterbedingt abzusteigen, doch ein Mitglied besteht darauf weiterzugehen und argumentiert 'wir sind doch so weit gekommen'. Was ist die beste Handhabung?",
    "q.m23#13.o0" to "Die Entscheidung respektieren und allein weitergehen lassen",
    "q.m23#13.o1" to "Darauf bestehen, dass die ganze Gruppe gemeinsam absteigt — Alleingehen ist in der Höhe nicht zulässig, und Sturheit dort kann selbst Hypoxie sein",
    "q.m23#13.o2" to "Abstimmen lassen",
    "q.m23#13.o3" to "Eine Stunde warten lassen und dann entscheiden",
    "q.m23#13.e" to "Zwei Gründe: Alleingehen in der Höhe ist extrem riskant, und 'wir sind doch so weit gekommen' ist die Lehrbuchformulierung versunkener Kosten — in der Höhe verschmelzen diese Emotion und nachlassendes Urteil meist, deshalb taugt sie nicht als verlässlicher Input.",

    "q.m23#14.p" to "Wie ist es richtig: Sind fittere Menschen anfälliger für Höhenkrankheit?",
    "q.m23#14.o0" to "Je fitter, desto unwahrscheinlicher",
    "q.m23#14.o1" to "Höhenkrankheit hat keinen direkten Zusammenhang mit Fitness; sie hängt von Aufstiegsgeschwindigkeit, Schlafhöhe und individueller Reaktion ab",
    "q.m23#14.o2" to "Je fitter, desto wahrscheinlicher",
    "q.m23#14.o3" to "Nur Untrainierte bekommen sie",
    "q.m23#14.e" to "Fitness mit Akklimatisierung zu verwechseln ist der häufigste Anfängerfehler. Tatsächlich können Fittere mehr Probleme bekommen, gerade weil sie schneller gehen und höher steigen — eine sehr reale Falle.",

    "q.m23#15.p" to "[Mehrfachauswahl] Welche Praktiken senken das Sturzrisiko wirksam?",
    "q.m23#15.o0" to "Den Pickel in der Bewegung laufend zur Selbstsicherung nutzen",
    "q.m23#15.o1" to "Ein nachhaltiges gleichmäßiges Tempo ohne plötzliche Krafteinsätze halten",
    "q.m23#15.o2" to "Im Tempo des langsamsten Gruppenmitglieds gehen",
    "q.m23#15.o3" to "Fixseile an harten Schnee- und Eishängen einrichten",
    "q.m23#15.o4" to "Beim Abstieg weniger bremsen und schneller gehen",
    "q.m23#15.e" to "Die vier entsprechen persönlicher Technik, Tempokontrolle, Gruppenabstimmung und Systemischerung. Sturzprävention ist nie eine einzelne Handlung, sondern eine ganze Schicht Versicherung auf Versicherung.",

    "q.m23#16.p" to "[Szenario] In einer Pause am Schneehang lässt ein Gruppenmitglied den Pickel im Schnee stecken und geht weg. Welches Risiko entsteht?",
    "q.m23#16.o0" to "Der Pickel kann verloren gehen",
    "q.m23#16.o1" to "Bei einem Sturz hat die Person überhaupt kein Bremsmittel",
    "q.m23#16.o2" to "Jemand kann darauf treten",
    "q.m23#16.o3" to "Kein Risiko",
    "q.m23#16.e" to "Stürze passieren extrem schnell, und der Pickel ist das einzige Bremsmittel. Ihn im Schnee zu lassen heißt, diese Fähigkeit vorübergehend aufzugeben — und am Schneehang ist 'vorübergehend' genau das gefährlichste Intervall.",

    "q.m23#17.p" to "Welche Kernfähigkeit prüft diese Lektion?",
    "q.m23#17.o0" to "Alle Zahlen auswendig zu können",
    "q.m23#17.o1" to "Wissen zu Umwelt, Ausrüstung, Kleidung und Bewegung zu verbinden und eine konkrete Lage richtig zu beurteilen",
    "q.m23#17.o2" to "Alle Fachbegriffe hersagen zu können",
    "q.m23#17.o3" to "Ausrüstungsmarken gut zu kennen",
    "q.m23#17.e" to "Das ist die Konstruktionslogik des ganzen Kurses: Einzelne Fakten sind leicht zu merken, aber am Berg stehen Sie vor Kombinationsproblemen. Mehrere Wissensstücke in einer konkreten Situation zu verbinden ist, was echte Beherrschung bedeutet.",

    // ---------- m24 Abschlussprüfung ----------
    "q.m24#0.p" to "[Szenario] Ein Partner ist in eine Spalte gestürzt, und Ihr Körper hält sein Gewicht allein. Was kommt zuerst?",
    "q.m24#0.o0" to "Sofort mit dem Ziehen beginnen",
    "q.m24#0.o1" to "Erst einen Standplatz bauen und die Last übertragen, dann ans Ziehen denken",
    "q.m24#0.o2" to "Zuerst Hilfe rufen",
    "q.m24#0.o3" to "Ein Foto für die Dokumentation machen",
    "q.m24#0.e" to "Solange das Gewicht an Ihnen hängt, haben Sie keine Kapazität, das System zu bedienen. Also: Standplatz, dann Übertragen, dann Ziehen — die Reihenfolge ist nicht umkehrbar. Es ist die praktischste Regel des ganzen Rettungssystems und der Schritt, der unter Stress am häufigsten übersprungen wird.",

    "q.m24#1.p" to "[Zuordnung] Ordnen Sie jedem Knoten seinen Einsatz zu.",
    "q.m24#1.l0" to "Achterknoten",
    "q.m24#1.r0" to "Gurt mit einem Anschlagpunkt verbinden",
    "q.m24#1.l1" to "Doppelter Fischerknoten",
    "q.m24#1.r1" to "Zwei Seile verbinden oder eine Kordelettenschlinge bauen",
    "q.m24#1.l2" to "Prusik",
    "q.m24#1.r2" to "Klemmknoten, greift in eine Richtung",
    "q.m24#1.l3" to "Palstek",
    "q.m24#1.r3" to "Verbindung zu einem Anschlagpunkt; auch im Bootssport üblich",
    "q.m24#1.e" to "Diese vier decken den größten Teil von Gletscherbegehung und Grundsicherung ab. Der Sinn der Prüfung: Sie müssen sie im Dunkeln und mit Handschuhen knüpfen können.",

    "q.m24#2.p" to "[Szenario] Der Schlingenwinkel zwischen zwei Anschlagpunkten liegt nahe 100°. Was bedeutet das?",
    "q.m24#2.o0" to "Die Last verteilt sich gleichmäßiger",
    "q.m24#2.o1" to "Die Last an jedem Anschlagpunkt steigt deutlich (je größer der Winkel, desto größer die Last pro Punkt)",
    "q.m24#2.o2" to "Keine Wirkung",
    "q.m24#2.o3" to "Das Seil gleicht sich automatisch aus",
    "q.m24#2.e" to "Die Zahlen sind anschaulich: etwa 50 % pro Punkt bei 0°, etwa 58 % bei 60°, etwa 71 % bei 90°. Bei 100° trägt jeder Punkt sehr viel — deshalb hält die Praxis den Winkel innerhalb von 60°.",

    "q.m24#3.p" to "[Mehrfachauswahl] Was sollte ein ausreichendes Standplatzsystem haben?",
    "q.m24#3.o0" to "Jede einzelne Platzierung solide",
    "q.m24#3.o1" to "Unabhängiges Versagen zwischen den Platzierungen (keine Scheinredundanz)",
    "q.m24#3.o2" to "Sinnvolle Lastverteilung, vorgespannt",
    "q.m24#3.o3" to "Schnell zu bauen, um die Exposition zu verkürzen",
    "q.m24#3.o4" to "So wenige Platzierungen wie möglich, um Material zu sparen",
    "q.m24#3.e" to "Die ersten drei sind Sicherheitsanforderungen, der vierte ist eine Effizienzanforderung — und Effizienz ist auch Sicherheit, weil der Bau selbst Zeit in der Gefährdung ist.",

    "q.m24#4.p" to "[Szenario] Ein Partner wird unsicher auf den Beinen und verwirrt. Was hat Vorrang?",
    "q.m24#4.o0" to "Sauerstoff geben und beobachten",
    "q.m24#4.o1" to "Sofort absteigen und Dexamethason unter medizinischer Aufsicht geben",
    "q.m24#4.o2" to "Weiter aufsteigen, um schneller im Lager zu sein",
    "q.m24#4.o3" to "Schmerzmittel geben und rasten",
    "q.m24#4.e" to "Ataxie und verändertes Bewusstsein sind die Kernsymptome von HACE, einem medizinischen Notfall. Der Abstieg ist die einzige definitive Behandlung; Dexamethason kauft nur Zeit für den Abstieg — die beiden sind keine Alternativen.",

    "q.m24#5.p" to "[Mehrfachauswahl] Welche Aussagen zu Höhenmedikamenten sind richtig?",
    "q.m24#5.o0" to "Dexamethason beeinflusst die Akklimatisierung nicht und behandelt kein Lungenödem",
    "q.m24#5.o1" to "Acetazolamid beschleunigt die Akklimatisierung; einen Tag vor dem Aufstieg beginnen und etwa zwei Tage danach absetzen",
    "q.m24#5.o2" to "Nifedipin kann einen schnellen Blutdruckabfall verursachen",
    "q.m24#5.o3" to "Medikamente können den Abstieg nicht ersetzen",
    "q.m24#5.o4" to "Acetazolamid kann den körpereigenen Akklimatisierungsprozess ersetzen",
    "q.m24#5.e" to "Alle vier sind Kernpunkte, und ihre gemeinsame Schlussfolgerung ist, dass Medikamente den Abstieg nicht ersetzen: Was auch immer gegeben wird, der Abstieg bleibt die grundlegende Behandlung. Medikamente schaffen nur die Bedingungen dafür.",

    "q.m24#6.p" to "[Szenario] Ein Gruppenmitglied hört in der Kälte auf zu zittern und spricht verwaschen. Was sollten Sie NICHT tun?",
    "q.m24#6.o0" to "Nasse Kleidung wechseln und isolieren",
    "q.m24#6.o1" to "Die Person umhergehen lassen, um Wärme zu erzeugen",
    "q.m24#6.o2" to "Zuerst den Rumpf wiedererwärmen",
    "q.m24#6.o3" to "Raue Behandlung vermeiden",
    "q.m24#6.e" to "Zittern aufgehört heißt mittelgradige Unterkühlung oder schlimmer, und ein kaltes Herz ist sehr anfällig für Rhythmusstörungen. Den Patienten gehen zu lassen oder grob zu behandeln kann das direkt auslösen — die kontraintuitivste Regel der Unterkühlungs-Ersten-Hilfe.",

    "q.m24#7.p" to "[Reihenfolge] Bringen Sie die vier Schritte einer Seilschaftsrettung in die richtige Reihenfolge.",
    "q.m24#7.o0" to "Selbst bremsen und sich stabilisieren",
    "q.m24#7.o1" to "Einen unabhängigen Standplatz bauen",
    "q.m24#7.o2" to "Die Last auf den Standplatz übertragen",
    "q.m24#7.o3" to "Mit einem 3:1-System ziehen",
    "q.m24#7.e" to "Diese vier sind nicht umsortierbar. In einer Prüfung können Sie sie vielleicht hersagen; in der Wirklichkeit müssen die ersten drei in Sekunden sitzen — das ist die echte Schwelle dieses Wissenspunkts.",

    "q.m24#8.p" to "[Szenario] Die Vorhersage sagt 'bewölkt', aber Sie sehen Quellwolken schnell vertikal wachsen. Was tun Sie?",
    "q.m24#8.o0" to "Der Vorhersage vertrauen und dem Plan folgen",
    "q.m24#8.o1" to "Unter der Annahme entscheiden, dass es schlechter wird, und einen frühen Abstieg erwägen",
    "q.m24#8.o2" to "Eine Stunde warten und noch mal schauen",
    "q.m24#8.o3" to "Weiter aufsteigen, aber schneller",
    "q.m24#8.e" to "Eine Vorhersage liefert regionalen Hintergrund; die Wolke vor Ihnen ist Beleg von hier und jetzt. Wenn sie sich widersprechen, gewinnt der Boden. Umso mehr, als die Quellwolkenentwicklung in der Höhe oft in Minuten gemessen wird.",

    "q.m24#9.p" to "[Mehrfachauswahl] Welche Praktiken sind beim Queren von Lawinengelände richtig?",
    "q.m24#9.o0" to "Eine nach der anderen mit Abstand queren",
    "q.m24#9.o1" to "Einen Beobachter an einer sicheren Stelle postieren",
    "q.m24#9.o2" to "Fluchtroute und Sammelpunkt vorher festlegen",
    "q.m24#9.o3" to "Die ganze Gruppe schnell gemeinsam hinüber schicken, um die Exposition zu verkürzen",
    "q.m24#9.e" to "Die ersten drei begrenzen das Risiko auf eine Person; 'alle gleichzeitig hinüber' vergrößert es auf Gruppenebene — von vielleicht einer verschütteten Person zu vielleicht allen, deshalb ist es die am wenigsten akzeptable Option.",

    "q.m24#10.p" to "[Szenario] Die Gruppe ist eine Stunde vom Gipfel entfernt, aber über der Umkehrzeit. Was ist richtig?",
    "q.m24#10.o0" to "Weiter zum Gipfel, es ist ja nur eine Stunde",
    "q.m24#10.o1" to "Sofort umkehren — der ganze Sinn einer Umkehrzeit ist, dass sie genau bei 'nur noch ein Stück' wirkt",
    "q.m24#10.o2" to "Um eine halbe Stunde verlängern",
    "q.m24#10.o3" to "Das fitteste Mitglied weitergehen lassen",
    "q.m24#10.e" to "Diese Frage prüft eigentlich, wozu eine Umkehrzeit da ist. Wenn sie nur befolgt wird, wenn es leicht ist, und bei 'nur noch ein Stück' aufgeweicht werden darf, hat sie nie existiert — und genau dort passieren Unfälle.",

    "q.m24#11.p" to "[Mehrfachauswahl] Welche sind richtige Praktiken der Gruppenentscheidung in Risikoumgebungen?",
    "q.m24#11.o0" to "Rückzugssignale vor dem Aufbruch beziffern",
    "q.m24#11.o1" to "Die konservativste Meinung setzt sich durch",
    "q.m24#11.o2" to "Widerspruch absichtlich einladen (etwa reihum jede Person fragen)",
    "q.m24#11.o3" to "Mehrheitsentscheid",
    "q.m24#11.e" to "Die ersten drei bilden zusammen den Mechanismus gegen kollektive Fehleinschätzung; Mehrheitsentscheid tut das Gegenteil — er unterdrückt die berechtigte Sorge der Minderheit, und oft ist es genau diese Minderheit, die das Gefahrensignal zuerst bemerkt hat.",

    "q.m24#12.p" to "[Szenario] Die Kommunikation ist ausgefallen, und die Meldung an die Menschen zu Hause war vor einer Stunde fällig. Was tun Sie?",
    "q.m24#12.o0" to "Wie geplant weitermachen und auf Empfang warten",
    "q.m24#12.o1" to "Dem vor dem Aufbruch vereinbarten Plan für Kontaktverlust folgen (etwa am Sammelpunkt warten)",
    "q.m24#12.o2" to "Aufteilen und nach Empfang suchen",
    "q.m24#12.o3" to "Alle sofort absteigen lassen",
    "q.m24#12.e" to "Kommunikationsausfall im Gebirge ist normal, kein Unfall — er muss also vor dem Aufbruch einen Plan haben. Mit Plan ist Kontaktverlust ein bekannter Zweig; ohne Plan wird daraus Verwirrung zu Hause.",

    "q.m24#13.p" to "[Reihenfolge] Bringen Sie den vollständigen Ablauf bei einer schwer verletzten Person in Ordnung.",
    "q.m24#13.o0" to "Die Unfallstelle sichern und einen zweiten Unfall vermeiden",
    "q.m24#13.o1" to "Bewusstsein, Atmung und Kreislauf prüfen; Lebensgefahr behandeln",
    "q.m24#13.o2" to "Hilfe rufen und genaue Lage und Verletzungen melden",
    "q.m24#13.o3" to "Isolieren, ruhigstellen und weiter beobachten, während auf Transport oder professionelle Rettung gewartet wird",
    "q.m24#13.e" to "Die Reihenfolge verkörpert Sicherheit zuerst, dann Behandlung, mit dem Hilferuf parallel und der Erhaltung danach. Der häufigste Fehler in der Praxis ist, Schritt eins zu überspringen und direkt zum Verletzten zu laufen — der klassische Weg zum zweiten Verletzten.",

    "q.m24#14.p" to "[Mehrfachauswahl] Welche Fähigkeiten im technischen Bergsteigen müssen im Gelände geübt werden?",
    "q.m24#14.o0" to "Selbstbremsung mit dem Eispickel",
    "q.m24#14.o1" to "Prusik- und Seilschaftssysteme",
    "q.m24#14.o2" to "Standplatzbau",
    "q.m24#14.o3" to "Der Ablauf der Spaltenrettung",
    "q.m24#14.o4" to "Die Namen und Höhen der vierzehn Achttausender auswendig zu können",
    "q.m24#14.e" to "Keine der vier ist durch Lesen zu erwerben. Ihnen gemeinsam: Sie müssen unter Druck ausgeführt werden, erlauben fast keinen Fehlerspielraum und hängen am Muskelgedächtnis. Deshalb markiert diese App sie wiederholt als prüfungspflichtig durch eine ausbildende Person.",

    "q.m24#15.p" to "[Szenario] Sie haben alle Theorieprüfungen bestanden. Wie sollen Sie Ihre Fähigkeit jetzt einschätzen?",
    "q.m24#15.o0" to "Sie können jetzt selbstständig Achttausender besteigen",
    "q.m24#15.o1" to "Sie haben eine theoretische Grundlage und ein Urteilsgerüst, aber jede technische Fertigkeit braucht vor der Anwendung eine Geländeprüfung durch eine ausbildende Person",
    "q.m24#15.o2" to "Sie können als Bergführer arbeiten",
    "q.m24#15.o3" to "Bestandene Theorie heißt, die Fähigkeit ist da",
    "q.m24#15.e" to "Das ist die wichtigste Aussage des ganzen Kurses: Theoretisches Verständnis ist keine Geländefähigkeit. Diese App baut ein kognitives und urteilendes Gerüst; was Sie an einer Eiswand tatsächlich rettet, ist die Bewegung, die Sie auf sicherem Grund mehrere hundert Mal wiederholt haben.",

    "q.m24#16.p" to "Welches Kernvermögen haben Sie nach dem gesamten Kurs aufgebaut?",
    "q.m24#16.o0" to "Eine Ausrüstungsliste",
    "q.m24#16.o1" to "Ein Denkgerüst aus Risiko erkennen, Risiko beurteilen, entscheiden — einschließlich der Fähigkeit zu erkennen, wann man nicht weitergeht",
    "q.m24#16.o2" to "Ein Bergsteigerzertifikat",
    "q.m24#16.o3" to "Einen Haufen Fakten",
    "q.m24#16.e" to "Von den 5.000-m-Grundlagen bis zur 8.000-m-Abschlussprüfung wiederholt der Kurs eine Sache: Sicherheit ist kein Produkt der Technik, sondern des Urteils — und Technik existiert, um dem Urteil Raum zu geben.",

    "q.m24#17.p" to "Ergänzen Sie: Bei Entscheidungen unter Unsicherheit sollte zuerst die ( ) Meinung übernommen werden.",
    "q.m24#17.a0" to "konservativste",
    "q.m24#17.e" to "Konservativ zuerst ist der Schlussgedanke des ganzen Kurses: einfach genug, um vor Ort zu greifen, stark genug, um den meisten kognitiven Verzerrungen zu widerstehen. Der Berg ist immer da; Sie nicht.",

    // ---------- m25 Die erste Hochtour: Kommunikation und Urteil ----------
    "q.m25#0.p" to "Nach dem Aufstieg spüren Sie Kopfdruck und Atemnot, während die Gruppe wie geplant weiter aufsteigt. Was tun Sie?",
    "q.m25#0.o0" to "Durchbeißen — Sie sind doch so weit gekommen",
    "q.m25#0.o1" to "Anhalten, der Führung oder den Partnern ehrlich sagen, wie es Ihnen geht, dann rasten und beobachten",
    "q.m25#0.o2" to "Selbst etwas einnehmen und mit der Gruppe mithalten",
    "q.m25#0.o3" to "Schneller gehen; früher im Lager sein löst es",
    "q.m25#0.e" to "Zwei Dinge dürfen Sie mit Körpersignalen in der Höhe nie tun: verstecken und selbst medikamentieren. Der richtige erste Schritt ist, ehrlich zu sagen, wie es Ihnen geht, dann anzuhalten, zu rasten und zu beobachten.\nDas ist keine Schwäche — die Führung kann nur beurteilen, wenn sie es weiß, und Sie brauchen selbst eine Beobachtungszeit, um zu erkennen, ob es nachlässt oder schlimmer wird.",

    "q.m25#1.p" to "Warum ist der Satz 'wir sind doch so weit gekommen' auf einer Höhentour gefährlich?",
    "q.m25#1.o0" to "Weil er Zeit verschwendet",
    "q.m25#1.o1" to "Weil er bereits investierte Zeit in einen Grund verwandelt, weiter Risiko zu tragen",
    "q.m25#1.o2" to "Weil er die Gruppenstimmung belastet",
    "q.m25#1.o3" to "Weil er unprofessionell klingt",
    "q.m25#1.e" to "Das ist Lehrbuchdenken in versunkenen Kosten: Wir sind so weit gelaufen, haben so viel ausgegeben, so viel Urlaub genommen — das kann doch nicht umsonst gewesen sein.\nAber das Risiko sinkt nicht dadurch, wie viel Sie investiert haben. Was ausgegeben ist, lässt sich nicht zurückholen, während der Preis des Weitergehens mehr Dinge sein können, die sich nicht zurückholen lassen.",

    "q.m25#2.p" to "Sie merken, dass Sie das Tempo der Gruppe deutlich nicht halten können und es bisher erzwungen haben. Was ist das beste Vorgehen?",
    "q.m25#2.o0" to "Zähne zusammenbeißen und mithalten, um niemanden aufzuhalten",
    "q.m25#2.o1" to "Es ehrlich sagen und die Gruppe bitten, im Tempo der langsamsten Person zu gehen",
    "q.m25#2.o2" to "Unauffällig langsamer werden und so tun, als sei alles in Ordnung",
    "q.m25#2.o3" to "Niemandem etwas sagen und allein absteigen",
    "q.m25#2.e" to "Das Tempo in der Höhe zu erzwingen ist eine versteckte Überziehung: Der unmittelbare Preis ist nur Müdigkeit, aber er akkumuliert zum Zusammenbruch am nächsten Tag. Und eine Gruppe im Tempo der schnellsten Person zieht alle an die Grenze.\nRichtig ist, das Tempo so zu setzen, dass es die langsamste Person dauerhaft tragen kann — das schützt sowohl den Einzelnen als auch die Gruppe.",

    "q.m25#3.p" to "Ein Partner sagt, er fühle sich etwas daneben, beharrt aber auf 'es ist okay, ich kann gehen'. Was tun Sie?",
    "q.m25#3.o0" to "Seinem Urteil vertrauen und weitergehen",
    "q.m25#3.o1" to "Es ernst nehmen und der Führung sagen",
    "q.m25#3.o2" to "Sich nicht einmischen; ihn selbst entscheiden lassen",
    "q.m25#3.o3" to "Nicht ernst nehmen — das sagen viele",
    "q.m25#3.e" to "Unwohlsein in der Höhe hat eine grausame Eigenschaft: Das Urteil ist zuerst betroffen, deshalb ist 'ich glaube, mir geht es gut' dort oben entwertet.\nDen Zustand Ihres Partners der Führung zu melden ist das Verantwortliche — ist es wirklich nichts, kostet es einen zusätzlichen Check; ist es etwas, sind Sie vielleicht der Einzige, der es rechtzeitig bemerkt hat.",

    "q.m25#4.p" to "Vor dem Aufbruch sagt die Führung, die morgige Route müsse angeseilt gequert werden. Jemand meint, 'ein so flacher Hang braucht das nicht'. Wie ist das richtig zu verstehen?",
    "q.m25#4.o0" to "Ein flacher Hang braucht wirklich kein Seil",
    "q.m25#4.o1" to "Ob angeseilt wird, entscheidet die Führung; sie hat die Informationen zu Gelände und Schneedecke",
    "q.m25#4.o2" to "Anseilen dient vor allem der Ordnung",
    "q.m25#4.o3" to "Die fitteste Person sollte entscheiden",
    "q.m25#4.e" to "'Von Weitem flach' zu sehen und dort zu stehen und die Verteilung von Spalten, Schneebrücken und verdeckten Rissen zu betrachten sind zwei verschiedene Dinge. Die Führung hat Informationen, die Sie nicht haben — genau darin liegt ihr Wert.\nBei technischen Entscheidungen die Person mit den meisten Informationen urteilen zu lassen ist die Grundregel für Effizienz und Sicherheit zugleich.",

    "q.m25#5.p" to "Mitten in der Gruppe gehen Sie und stellen fest, dass Ihr Wasser leer ist, der nächste Nachschubpunkt aber zwei Stunden entfernt ist. Was tun Sie?",
    "q.m25#5.o0" to "Schweigen und niemanden belästigen",
    "q.m25#5.o1" to "Sofort dem Gruppenleiter sagen und prüfen, ob es koordiniert werden kann",
    "q.m25#5.o2" to "Den nächsten Partner um Wasser bitten, aber dem Leiter nichts sagen",
    "q.m25#5.o3" to "Weniger trinken und weitergehen",
    "q.m25#5.e" to "Wassermangel ist Information der Gruppe, keine persönliche Kleinigkeit — sie prägt das Urteil der Leitung über Tempo und Nachversorgung.\nEinen Partner privat zu fragen wirkt rücksichtsvoll, schneidet aber die Information ab: Die Leitung glaubt weiter, die Gruppe sei in gutem Zustand, und drückt womöglich wie geplant weiter.",

    "q.m25#6.p" to "Was bedeutet 'langsam ist schnell' in der Höhe tatsächlich?",
    "q.m25#6.o0" to "Langsam gehen garantiert den Gipfel",
    "q.m25#6.o1" to "Ein nachhaltiges gleichmäßiges Tempo spart mehr Zeit und ist sicherer als wiederholte Krafteinsätze",
    "q.m25#6.o2" to "Langsam ist Rücksicht auf die Schwächeren",
    "q.m25#6.o3" to "Geschwindigkeit ist in der Höhe egal",
    "q.m25#6.e" to "Die Sauerstoffversorgung ist in der Höhe begrenzt, und wiederholte explosive Anstrengungen häufen schnell Laktat an und verschlechtern die Hypoxie.\nEin gleichmäßiges Tempo ist tatsächlich schneller: Es erspart häufige Erholungspausen und senkt die Chance, durch Überverausgabung zum Umkehren gezwungen zu sein. Der Satz beschreibt den Energiestoffwechsel, nicht einen Trost.",

    "q.m25#7.p" to "Sie erreichen das Lager zwei Stunden später als geplant, es ist bereits dunkel. Was tun Sie?",
    "q.m25#7.o0" to "Die Nacht durch zum nächsten Lager weitergehen",
    "q.m25#7.o1" to "An Ort und Stelle lagern und den Menschen zu Hause die Position mitteilen",
    "q.m25#7.o2" to "Allein zurückgehen und nach Vermissten suchen",
    "q.m25#7.o3" to "Weitergehen, bis Sie die Gruppe vor sich eingeholt haben",
    "q.m25#7.e" to "Nachts in der Höhe zu marschieren kombiniert die schlechtesten Faktoren: Dunkelheit, Müdigkeit, Kälte und keine Möglichkeit, das Gelände zu lesen. Dort zu lagern, wo Sie sind, ist die vernünftige Wahl.\nAber eines gehört dazu: der Außenwelt Ihre Position mitteilen. Dann weiß im Ernstfall wenigstens jemand, wo gesucht werden muss. Allein loszugehen kostet die Gruppe dagegen zwei Leute auf einmal.",

    "q.m25#8.p" to "Ein Partner wird unterwegs deutlich unwohl und wird immer langsamer. Die Gruppe ist uneinig, ob warten oder jemand vorausgehen soll. Was ist sinnvoller?",
    "q.m25#8.o0" to "Die ganze Gruppe geht im ursprünglichen Tempo weiter",
    "q.m25#8.o1" to "Niemals teilen; die ganze Gruppe wird langsamer",
    "q.m25#8.o2" to "Eine erfahrene Person begleitet ihn, die Übrigen gehen weiter und halten Kontakt",
    "q.m25#8.o3" to "Ihn langsam allein gehen lassen und im Lager treffen",
    "q.m25#8.e" to "Teilen birgt in der Höhe eigenes Risiko, aber mit genug Leuten ist es oft vernünftiger, die erfahrenste Person zur Begleitung des Langsameren abzustellen, während der Rest weitergeht — statt alle zu bremsen oder alle zu zwingen.\nDrei Dinge sind wesentlich: Jemand bleibt bei ihm, der Kontakt bleibt bestehen, und die Gruppe voraus erfährt die Lage und die erwartete Ankunftszeit. Völlig allein ist die schlechteste Option.",

    "q.m25#9.p" to "Wie ist der Platz des Gipfels in der gesamten Tour richtig zu verstehen?",
    "q.m25#9.o0" to "Der Gipfel ist das Ende der Tour",
    "q.m25#9.o1" to "Der Gipfel ist nur die Hälfte der Tour; der Abstieg ist, wo sich das Risiko konzentriert",
    "q.m25#9.o2" to "Nur der Gipfel zählt",
    "q.m25#9.o3" to "Kein Gipfel heißt, die Tour ist gescheitert",
    "q.m25#9.e" to "Viele Unfälle passieren beim Abstieg, weil die Aufmerksamkeit nach erreichtem Ziel sinkt, während die Kondition schon am Limit ist.\nDen Gipfel als 'Hälfte' zu behandeln heißt, im Plan gleiche Zeit, Energie und Sicherung für den Abstieg einzuplanen — statt alles für den Aufstieg zu verbrauchen.",

    "q.m25#10.p" to "Szenario: die ersten 24 Stunden in der Höhe",
    "q.m25#10.c" to "Es ist Ihr erster 5.000-m-Trekkinggipfel. Nach dem Erreichen eines Lagers auf 4.300 m passieren über die nächsten 24 Stunden mehrere Dinge.",
    "q.m25#10.e" to "Der Sinn dieser vier Schritte ist kein medizinisches Wissen, sondern zwei Gewohnheiten: ehrlich sagen und neu beurteilen. Was Menschen auf einer Höhentour tatsächlich in Gefahr bringt, ist nicht ein einzelnes schlechtes Urteil, sondern eine Kette kleiner Entscheidungen — durchbeißen, nicht stören — die sich stapeln.",
    "q.m25#10.s0.p" to "Schritt 1: Am Abend bekommen Sie Kopfschmerz und verlieren den Appetit. Ein Partner sagt 'das ist normal, schlaf es weg'. Was tun Sie?",
    "q.m25#10.s0.o0" to "Wie gesagt handeln und ausschlafen",
    "q.m25#10.s0.o1" to "Der Führung ehrlich sagen, wie es Ihnen geht, dann nach Anweisung rasten sowie in kleinen Mengen essen und trinken",
    "q.m25#10.s0.o2" to "Selbst ein Medikament suchen und niemandem etwas sagen",
    "q.m25#10.s0.o3" to "Etwas trinken, damit Sie besser schlafen",
    "q.m25#10.s0.e" to "Kopfschmerz und Appetitlosigkeit sind in der Höhe häufig, aber häufig heißt nicht ignorierbar. Ehrliche Meldung plus Basismaßnahmen — Ruhe, Flüssigkeit, kleine Mengen Essen — ist die Standardantwort.\nEntscheidend ist, dass die Führung im Moment der Veränderung davon erfährt und nicht erst am nächsten Morgen.",
    "q.m25#10.s1.p" to "Schritt 2: Sie schlafen die ganze Nacht kaum. Am Morgen rüstet sich die Gruppe zum Weitergehen. Was wählen Sie?",
    "q.m25#10.s1.o0" to "Nichts sagen und einfach mitgehen",
    "q.m25#10.s1.o1" to "Berichten, wie Sie geschlafen haben, und die Führung beurteilen lassen, ob es weitergeht",
    "q.m25#10.s1.o2" to "Selbst entscheiden, zurückzubleiben, ohne es der Gruppe zu sagen",
    "q.m25#10.s1.o3" to "Die ganze Gruppe bitten, zu warten, bis Sie sich erholt haben",
    "q.m25#10.s1.e" to "Schlechter Schlaf ist eine der häufigsten Höhenbeschwerden; für sich genommen rechtfertigt er meist keinen Aufstiegsstopp — aber er muss in die Beurteilung eingehen, statt still getragen zu werden.\nDie Führung wägt ihn zusammen mit Kopfschmerz, Appetit und Ihrer Bewegungsart. Darin liegt der Wert ihrer Erfahrung.",
    "q.m25#10.s2.p" to "Schritt 3: Die Gruppe geht weiter, Sie fühlen sich etwas besser als gestern, gehen aber langsam. Welche Haltung sollten Sie jetzt am meisten fürchten?",
    "q.m25#10.s2.o0" to "Sorge, ausgelacht zu werden",
    "q.m25#10.s2.o1" to "Das Gefühl 'das kann doch nicht umsonst gewesen sein' — es macht Ihnen schwer, aufzuhören, wenn Sie es müssten",
    "q.m25#10.s2.o2" to "Der Drang, Fotos zu machen",
    "q.m25#10.s2.o3" to "Sorge ums Wetter",
    "q.m25#10.s2.e" to "Versunkene Kosten lodern am zweiten Tag am stärksten: Sie haben die ganze Nacht gelitten, ein Aufgeben jetzt würde dieses Leiden sinnlos machen.\nDiese Logik verwandelt bereits bezahlte Kosten in einen Grund weiterzumachen, statt in ein Signal zur Neubeurteilung.",
    "q.m25#10.s3.p" to "Schritt 4: Am Ende erreichen Sie den Gipfel nicht — Sie kehren eine Stunde vorher um. Wie sollen Sie diese Tour sehen?",
    "q.m25#10.s3.o0" to "Ein Scheitern; kommen Sie nicht wieder",
    "q.m25#10.s3.o1" to "Eine nützliche Akklimatisierungserfahrung; das Umkehren war Urteilskraft, kein Scheitern",
    "q.m25#10.s3.o2" to "Die Partner waren schuld, weil sie Sie gebremst haben",
    "q.m25#10.s3.o3" to "Nächstes Mal unter allen Umständen auf den Gipfel",
    "q.m25#10.s3.e" to "Akklimatisierung entsteht durch wiederholte Exposition; eine erste Tour auf 4.000–5.000 m hatte nie den Gipfel als einziges Ziel.\nUnd rechtzeitig umkehren zu können ist die am höchsten geschätzte Fähigkeit in diesem Sport. Sie bringt Sie weiter als ein glücklicher Gipfel es je könnte.",

    "q.m25#11.p" to "Szenario: Gruppendruck",
    "q.m25#11.c" to "Vierter Tag der Tour; das Wetter beginnt zu drehen und die Gruppe ist gespalten. Ihr eigenes Urteil weicht etwas von dem der Gruppe ab.",
    "q.m25#11.e" to "In diesem Szenario geht es um das Vorbringen eines Vorbehalts. Es ist in der Praxis schwer, weil der Preis sozial aussieht — Stimmung verderben, nicht dazugehören — während der Nutzen unsichtbar ist: ein Unfall, der nicht passiert ist. Merken Sie sich diese drei Punkte, und Sie werden nächstes Mal früher etwas sagen.",
    "q.m25#11.s0.p" to "Schritt 1: Einige argumentieren 'drücken wir weiter, morgen ist das Wetter vielleicht besser'; andere wollen absteigen. Sie neigen zum Abstieg, wollen aber nicht derjenige sein, der es verdirbt. Was tun Sie?",
    "q.m25#11.s0.o0" to "Schweigen und mitgehen",
    "q.m25#11.s0.o1" to "Ihr Urteil und die Begründung dazu vortragen",
    "q.m25#11.s0.o2" to "Privat klagen und es dabei belassen",
    "q.m25#11.s0.o3" to "Zustimmung zum Weitergehen vortäuschen und die Zweifel behalten",
    "q.m25#11.s0.e" to "Die schweigende Minderheit ist ein Stammgast in Unfallauswertungen. Einen Vorbehalt zu haben und ihn nicht zu äußern heißt, dass die Gruppe mit unvollständiger Information entscheidet.\nDer Preis, etwas zu sagen, ist klein, vielleicht null; der Preis des Schweigens kann sehr groß sein.",
    "q.m25#11.s1.p" to "Schritt 2: Nach der Diskussion entscheidet die Gruppe weiterzugehen, aber Sie fühlen sich damit weiter unwohl. Wie weiter?",
    "q.m25#11.s1.o0" to "Passiv mitmachen und nur das Minimum tun",
    "q.m25#11.s1.o1" to "Ihren Vorbehalt klar festhalten und die Umkehrbedingungen und den Rückzugsplan der Gruppe bestätigen",
    "q.m25#11.s1.o2" to "Sofort allein absteigen",
    "q.m25#11.s1.o3" to "Nichts mehr sagen, aber Groll hegen",
    "q.m25#11.s1.e" to "Ist die Entscheidung gefallen, bleiben drei Dinge: einen klaren Vermerk hinterlassen (ich war dagegen, weil …), bestätigen, dass die Rückzugsbedingungen ausdrücklich sind, und sicherstellen, dass Sie weiterhin willens und fähig sind, sie auszuführen.\nEin Vorbehalt ist keine passive Fügung — nachdem Sie Ihre Sicht gesagt haben, machen Sie Ihren Teil trotzdem ordentlich.",
    "q.m25#11.s2.p" to "Schritt 3: Es zeigt sich, dass Ihre Sorge richtig war, und die Gruppe steigt früh ab. Was ist der Wert dieser Erfahrung?",
    "q.m25#11.s2.o0" to "Es beweist, dass Sie besser sind als die anderen",
    "q.m25#11.s2.o1" to "Es bestätigt, dass ein vorher geäußerter Vorbehalt wirkt und die Beziehung nicht beschädigt",
    "q.m25#11.s2.o2" to "Es zeigt, dass Sie künftig allein handeln sollten",
    "q.m25#11.s2.o3" to "Nicht viel, weil Sie den Gipfel nicht erreicht haben",
    "q.m25#11.s2.e" to "Viele fürchten beim ersten Mal, einen Vorbehalt zu äußern, sie würden als nicht dazugehörend gesehen. Tatsächlich vertraut eine gute Gruppe danach einander mehr, weil es beweist, dass jemand bereit ist, die Wahrheit zu sagen.\nHalten Sie diese Erfahrung fest; nächstes Mal sagen Sie früher etwas."
)
